CREATE OR REPLACE FUNCTION public.fn_accrue_dues_interest()
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_rate numeric; v_updated int := 0;
begin
  v_rate := coalesce((select num_value from public.gl_settings where key='clawback_interest_monthly_pct'), 0.75) / 100.0;

  with calc as (
    select d.id,
           round(coalesce(d.amount_due,0) * v_rate *
                 greatest(0, (date_part('year',  age(current_date, d.due_date::date)) * 12
                            + date_part('month', age(current_date, d.due_date::date)))::int), 2) as want
    from public.supplier_dues d
    where d.paid_at is null
      -- H6 (OS audit): once collections_legal has escalated a due it FREEZES the interest; the monthly
      -- accrual must not overwrite that frozen figure, so exclude legal-stage dues here.
      and coalesce(d.status,'') not in ('paid','settled','waived','cancelled','legal')
      and d.legal_stage is null
      and coalesce(d.amount_due,0) > 0
      and d.due_date is not null
  )
  update public.supplier_dues d
     set interest_amount = c.want
    from calc c
   where c.id = d.id
     and coalesce(d.interest_amount,0) is distinct from c.want;

  get diagnostics v_updated = row_count;
  return v_updated;
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_add_working_days(p_from timestamp with time zone, p_days integer)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare d date; left_ int := greatest(0, coalesce(p_days,0)); tod time; res timestamptz;
begin
  if p_from is null then return null; end if;
  d   := (p_from at time zone 'Asia/Dubai')::date;
  tod := (p_from at time zone 'Asia/Dubai')::time;
  while left_ > 0 loop
    d := d + 1;
    if public.fn_is_working_day(d) then left_ := left_ - 1; end if;
  end loop;
  -- if we consumed no days and landed on a non-working day, roll forward
  while not public.fn_is_working_day(d) loop d := d + 1; end loop;
  res := ((d::text || ' ' || tod::text)::timestamp) at time zone 'Asia/Dubai';
  return res;
end $function$


CREATE OR REPLACE FUNCTION public.fn_agent_context(p_agent_key text DEFAULT NULL::text, p_max_chars integer DEFAULT 9000)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare out text := ''; r record; piece text; cap int; own_cap int;
        v_dept text; v_role text; v_charter text; v_north text; v_health_fn text;
        v_status text; v_state jsonb; v_l4 text := '';
begin
  cap := greatest(coalesce(p_max_chars,9000), 22000);
  own_cap := least(cap/2, 6000);
  if p_agent_key is not null then
    select a.department, a.role into v_dept, v_role from org_agents a where a.agent_key=p_agent_key;
    select d.charter, d.north_star, d.health_fn into v_charter, v_north, v_health_fn
      from org_departments d where d.dept_key=v_dept;
    select status into v_status from org_onboarding where agent_key=p_agent_key;
    out := out || '# YOUR IDENTITY AT QUOTESDONE'||E'\n'
      ||'You are '||coalesce(v_role, p_agent_key||' (senior specialist)')
      ||case when v_charter is not null then '. Department charter: '||v_charter else '' end
      ||case when v_north is not null then ' North star: '||v_north||'.' else '' end
      ||' Employment status: '||coalesce(v_status,'onboarding')||'.'||E'\n'
      ||'POSTURE: You are a senior executive employee, not an assistant. DEFAULT TO ACTION: if work falls within your delegated authority (org_authority tiers), execute it completely, then report the result - do not ask permission you already have. Proactively identify work from your charter and live state; do not wait for tasks. Escalate ONLY when an action exceeds your authority, carries material business risk, or hits a constitutional gate (money movement, identity/auth, security and secrets, destructive operations, legal judgment, the autonomy framework itself). Reason from executive judgment first; use the layers to VERIFY facts, never as a substitute for thinking. Quote operational numbers ONLY from LIVE STATE. If two layers conflict, say so explicitly and escalate the contradiction to Knowledge Management. Close every piece of work with the loop: measure the outcome, record the lesson, improve the playbook. If your employment status is not certified, mark your outputs as provisional.'||E'\n\n';
  end if;
  if p_agent_key is not null then
    out := out || '# LAYER 2 - YOUR PROFESSIONAL EXPERTISE'||E'\n\n';
    for r in select topic,content from agent_knowledge
             where agent_key=p_agent_key and coalesce(layer,'profession') in ('profession','state')
             order by priority desc nulls last, updated_at desc loop
      piece := '## '||coalesce(r.topic,'')||E'\n'||coalesce(r.content,'')||E'\n\n';
      if length(out)+length(piece) <= own_cap + 2200 then out := out||piece; end if;
    end loop;
  end if;
  out := out || '# LAYER 1 - COMPANY KNOWLEDGE (authoritative; pricing marked LIVE overrides any other figure)'||E'\n\n';
  for r in select topic,content from agent_knowledge
           where agent_key='_global' and coalesce(priority,0)>=90 order by priority desc nulls last, updated_at desc loop
    piece := '## '||coalesce(r.topic,'')||E'\n'||coalesce(r.content,'')||E'\n\n';
    if length(out)+length(piece) <= cap then out := out||piece; end if;
  end loop;
  for r in select topic,content from agent_knowledge
           where agent_key='_global' and coalesce(priority,0)<90 order by priority desc nulls last, updated_at desc loop
    piece := '## '||coalesce(r.topic,'')||E'\n'||coalesce(r.content,'')||E'\n\n';
    if length(out)+length(piece) <= cap then out := out||piece; end if;
  end loop;
  if v_health_fn is not null then
    begin
      execute format('select %I()', v_health_fn) into v_state;
      piece := '# LAYER 3 - LIVE OPERATIONAL STATE (from '||v_health_fn||' at '||now()::timestamptz(0)||'; the ONLY valid source for operational numbers)'||E'\n'
               ||left(coalesce(v_state::text,'{}'), 2600)||E'\n\n';
      if length(out)+length(piece) <= cap + 3000 then out := out||piece; end if;
    exception when others then
      out := out || '# LAYER 3 - LIVE OPERATIONAL STATE unavailable ('||sqlerrm||'); do not quote operational numbers this turn.'||E'\n\n';
    end;
  end if;
  if p_agent_key is not null then
    for r in select topic, content from agent_knowledge
             where layer='experience' and agent_key in (p_agent_key,'_global')
             order by updated_at desc limit 12 loop
      v_l4 := v_l4 || '## '||coalesce(r.topic,'')||E'\n'||coalesce(r.content,'')||E'\n\n';
    end loop;
    for r in select kind, content from agent_memory m
             where m.agent_key=p_agent_key and m.importance >= 5
               and not exists (select 1 from policy_rules p where p.active and m.content ~* p.forbid_regex)
             order by m.importance desc, m.created_at desc limit 8 loop
      v_l4 := v_l4 || '## memory ('||r.kind||')'||E'\n'||r.content||E'\n\n';
    end loop;
    v_l4 := v_l4 || coalesce(public.fn_agent_institutional_memory(p_agent_key, 6), '');
    if v_l4 <> '' then
      out := out || '# LAYER 4 - WHAT THIS ORGANIZATION HAS LEARNED'||E'\n\n'|| left(v_l4, 3500);
    end if;
  end if;
  return out;
end $function$


CREATE OR REPLACE FUNCTION public.fn_agent_context_capped(p_agent_key text, p_max_chars integer DEFAULT 9000)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_want int := greatest(coalesce(p_max_chars, 9000), 500);
  v_raw  text;
begin
  -- The inner function ignores anything below 22,000 and overshoots above it, so ask
  -- for what we want and then enforce the promise ourselves.
  select fn_agent_context(p_agent_key, v_want) into v_raw;
  if v_raw is null then return null; end if;
  if length(v_raw) <= v_want then return v_raw; end if;

  -- Truncate on a paragraph boundary where possible so a layer is not cut mid-sentence.
  return left(v_raw, v_want - 60) || E'\n\n[context truncated to the ' || v_want ||
         ' characters requested; ' || length(v_raw) || ' were available]';
end $function$


CREATE OR REPLACE FUNCTION public.fn_agent_decision(p_agent text, p_kind text, p_title text, p_recommendation text, p_confidence numeric DEFAULT NULL::numeric, p_evidence jsonb DEFAULT '[]'::jsonb, p_risk text DEFAULT 'low'::text, p_detail jsonb DEFAULT '{}'::jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_sensitive boolean; v_escalate boolean; v_reason text; v_status text; v_id bigint;
begin
  v_sensitive := (p_kind ~* 'legal|financ|complian|security|payment|refund|payout|pricing|price'
                  or p_agent ~* 'legal|security|finance|compliance');
  v_escalate := (coalesce(p_confidence,0) < 0.6) or v_sensitive;
  v_reason := case
    when coalesce(p_confidence,0) < 0.6 and v_sensitive then 'Low confidence and sensitive domain — human review required.'
    when coalesce(p_confidence,0) < 0.6 then 'Confidence below 0.60 threshold — human review required.'
    when v_sensitive then 'Sensitive domain (legal/financial/compliance/security) — human review required.'
    else null end;
  v_status := case when v_escalate then 'needs_review' else 'pending' end;

  insert into public.agent_actions(agent,kind,status,risk,title,recommendation,detail,
                                   confidence,evidence,escalated,escalation_reason,created_at)
  values (p_agent,p_kind,v_status,p_risk,p_title,p_recommendation,p_detail,
          p_confidence,coalesce(p_evidence,'[]'::jsonb),v_escalate,v_reason, now())
  returning id into v_id;
  return v_id;
end $function$


CREATE OR REPLACE FUNCTION public.fn_agent_institutional_memory(p_agent_key text, p_limit integer DEFAULT 6)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_dept text; v_cat text; out text := ''; r record;
begin
  if p_agent_key is null then return ''; end if;

  select department into v_dept from org_agents where agent_key = p_agent_key;
  if p_agent_key like 'cat:%' then v_cat := replace(p_agent_key, 'cat:', ''); end if;

  for r in
    select m.kind, m.headline, m.detail, m.outcome, m.money_aed, m.category_slug, m.confidence
    from institutional_memory m
    where (m.visible_to is null
           or array_length(m.visible_to,1) is null
           or 'all' = any(m.visible_to)
           or v_dept = any(m.visible_to)
           or p_agent_key = any(m.visible_to))
      and (m.category_slug is null or m.category_slug = v_cat)
    order by coalesce(m.confidence,0) desc, coalesce(m.occurred_at, m.created_at) desc
    limit greatest(coalesce(p_limit,6), 1)
  loop
    out := out || '## lesson (' || coalesce(r.kind,'note') || ')' || E'\n'
        || coalesce(r.headline,'') || E'\n'
        || left(coalesce(r.detail,''), 600)
        || case when r.outcome is not null then E'\n' || 'What changed as a result: ' || left(r.outcome, 300) else '' end
        || case when coalesce(r.money_aed,0) <> 0 then ' (AED ' || r.money_aed || ' at stake)' else '' end
        || E'\n\n';
  end loop;

  return out;
end; $function$


CREATE OR REPLACE FUNCTION public.fn_agent_silence_watch()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; n int:=0; f int:=0; g int:=0; nr int:=0; v_email text; v_run bigint;
begin
  insert into agent_runs(agent, started_at) values ('agent_silence_watch', clock_timestamp()) returning id into v_run;

  select to_email into v_email from notifications
   where type='founder_brief' and to_email is not null order by created_at desc limit 1;

  insert into cron_job_seen (jobid, jobname, schedule)
  select j.jobid, j.jobname, j.schedule from cron.job j where j.active
  on conflict (jobid) do update set last_seen = now(), jobname = excluded.jobname, schedule = excluded.schedule;

  -- Record successes BEFORE evaluating, so they survive the 14-day history prune.
  update cron_job_seen s
     set last_success = h.last_ok
    from (select jobid, max(start_time) as last_ok
            from cron.job_run_details where status='succeeded' group by jobid) h
   where h.jobid = s.jobid
     and (s.last_success is null or s.last_success < h.last_ok);

  for r in
    select j.jobid, j.jobname,
           case when split_part(j.schedule,' ',5) <> '*' then 336
                when split_part(j.schedule,' ',3) <> '*' then 1440
                when split_part(j.schedule,' ',2) =  '*' then 6
                else 72 end as thresh_h,
           (select count(*) from cron.job_run_details d where d.jobid=j.jobid) as history_rows,
           -- effective last success: live history OR the value we persisted before pruning
           greatest(
             (select max(d.start_time) from cron.job_run_details d
               where d.jobid=j.jobid and d.status='succeeded'),
             (select s.last_success from cron_job_seen s where s.jobid=j.jobid)
           ) as last_ok,
           (select count(*) from cron.job_run_details d
             where d.jobid=j.jobid and d.status='failed'
               and d.start_time > now() - interval '24 hours') as fails_24h,
           (select s.first_seen from cron_job_seen s where s.jobid=j.jobid) as first_seen,
           (select s.last_success from cron_job_seen s where s.jobid=j.jobid) as stored_ok
      from cron.job j where j.active
  loop
    -- Never-run: only when there is NO history AND we have never recorded a success.
    -- Previously a pruned-history monthly job hit this branch and false-alarmed.
    if r.history_rows = 0 and r.stored_ok is null then
      if r.first_seen is not null and r.first_seen < now() - (r.thresh_h||' hours')::interval then
        if not exists (select 1 from founder_alerts where event='cron_never_ran'
                        and detail like '%"'||r.jobname||'"%'
                        and created_at > now() - interval '24 hours') then
          insert into founder_alerts(level,event,detail,channel)
          values ('high','cron_never_ran', jsonb_build_object(
            'job', r.jobname,
            'first_seen', r.first_seen::text,
            'known_for_hours', round(extract(epoch from (now()-r.first_seen))/3600),
            'expected_within_hours', r.thresh_h)::text, 'email');
          if v_email is not null then
            insert into notifications(type,to_email,subject,body,status)
            values ('agent_silence', v_email, 'Scheduled job has never run: '||r.jobname,
              'Job "'||r.jobname||'" is active but has no run history at all. It has been registered since '||
              r.first_seen::text||' and should have run at least every '||r.thresh_h||' hours. It is likely misregistered.','pending');
          end if;
          nr := nr + 1;
        end if;
      else
        g := g + 1;
      end if;
      continue;
    end if;

    if r.last_ok is null or r.last_ok < now() - (r.thresh_h||' hours')::interval then
      if not exists (select 1 from founder_alerts where event='cron_silent'
                      and detail like '%"'||r.jobname||'"%'
                      and created_at > now() - interval '24 hours') then
        insert into founder_alerts(level,event,detail,channel)
        values ('high','cron_silent', jsonb_build_object(
          'job',r.jobname,'last_success',coalesce(r.last_ok::text,'no success on record'),
          'silent_hours',round(extract(epoch from (now()-r.last_ok))/3600),
          'expected_within_hours',r.thresh_h)::text,'email');
        if v_email is not null then
          insert into notifications(type,to_email,subject,body,status)
          values ('agent_silence',v_email,'Scheduled job stopped: '||r.jobname,
            'Job "'||r.jobname||'" last succeeded '||coalesce(r.last_ok::text,'unknown')||
            '. Expected at least every '||r.thresh_h||' hours.','pending');
        end if;
        n := n + 1;
      end if;
    end if;

    if r.fails_24h > 0 then
      if not exists (select 1 from founder_alerts where event='cron_failing'
                      and detail like '%"'||r.jobname||'"%'
                      and created_at > now() - interval '24 hours') then
        insert into founder_alerts(level,event,detail,channel)
        values ('high','cron_failing',
          jsonb_build_object('job',r.jobname,'failures_24h',r.fails_24h,
                             'last_success',coalesce(r.last_ok::text,'unknown'))::text,'email');
        if v_email is not null then
          insert into notifications(type,to_email,subject,body,status)
          values ('agent_silence',v_email,'Scheduled job failing: '||r.jobname,
            'Job "'||r.jobname||'" has failed '||r.fails_24h||' time(s) in the last 24 hours. Last success: '||
            coalesce(r.last_ok::text,'unknown')||'. Check cron.job_run_details for the error text.','pending');
        end if;
        f := f + 1;
      end if;
    end if;
  end loop;

  update agent_runs
     set finished_at=clock_timestamp(), status='ok',
         counts=jsonb_build_object('active_jobs',(select count(*) from cron.job where active),
                                   'in_grace',g,'silent',n,'failing',f,'never_ran',nr)
   where id=v_run;

  return jsonb_build_object('ran_at',now(),
    'active_jobs',(select count(*) from cron.job where active),
    'in_grace',g,'silent_alerts',n,'failing_alerts',f,'never_ran_alerts',nr);
exception when others then
  update agent_runs set finished_at=clock_timestamp(), status='error', note=left(sqlerrm,500) where id=v_run;
  raise;
end $function$


CREATE OR REPLACE FUNCTION public.fn_agents_board()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare out jsonb;
begin
  with runs as (
    select agent, count(*) filter (where started_at > now() - interval '24 hours') as runs24,
           count(*) filter (where started_at > now() - interval '24 hours' and status in ('error','failed')) as fails24,
           max(started_at) as last_run, (array_agg(status order by started_at desc))[1] as last_status
    from agent_runs group by agent
  ), base as (
    select a.agent_key, coalesce(nullif(trim(a.department),''),'General') as department, a.role, a.kind, coalesce(a.active,true) as active,
      coalesce(r.runs24,0) as runs24, coalesce(r.fails24,0) as fails24, r.last_run, r.last_status
    from org_agents a left join runs r on r.agent = a.agent_key
  ), dc as (select department, count(*) c, sum(runs24) rs from base group by department)
  select jsonb_build_object(
    'total',(select count(*) from base),
    'runs24',(select coalesce(sum(runs24),0) from base),
    'departments',(select coalesce(jsonb_agg(jsonb_build_object('key',d.department,'label',d.department,'count',d.c,'runs',d.rs,
        'cards',(select jsonb_agg(jsonb_build_object('id',b.agent_key,'agent_key',b.agent_key,'role',b.role,'kind',b.kind,'active',b.active,'runs24',b.runs24,'fails24',b.fails24,'last_status',b.last_status,'last_run',b.last_run) order by b.runs24 desc, b.agent_key) from base b where b.department=d.department))
        order by d.rs desc nulls last, d.department),'[]'::jsonb) from dc d),
    'rows',(select coalesce(jsonb_agg(jsonb_build_object('id',b.agent_key,'agent_key',b.agent_key,'department',b.department,'role',b.role,'kind',b.kind,'active',b.active,'runs24',b.runs24,'fails24',b.fails24,'last_status',b.last_status,'last_run',b.last_run) order by b.runs24 desc, b.agent_key),'[]'::jsonb) from base b)
  ) into out; return out;
end $function$


CREATE OR REPLACE FUNCTION public.fn_ai_gate(p_answer text, p_sources jsonb DEFAULT '[]'::jsonb, p_confidence numeric DEFAULT NULL::numeric, p_action text DEFAULT 'run_agent_action'::text, p_actor text DEFAULT 'agent'::text, p_attrs jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare g jsonb; a jsonb; esc jsonb; conf_min numeric; viol text[]:='{}'; approved boolean; route text;
begin
  g := public.fn_require_grounding(p_answer, p_sources);
  if not (g->>'grounded')::boolean then viol := array_append(viol,'ungrounded: retrieve knowledge and cite a source'); end if;
  select value::numeric into conf_min from decision_policy where key='confidence_min';
  if p_confidence is not null and p_confidence < coalesce(conf_min,0.6) then
     viol := array_append(viol,'low_confidence: below '||coalesce(conf_min,0.6)||' — ask a clarifying question or escalate'); end if;
  a := public.fn_authorize(p_actor, p_action, p_attrs);
  if not (a->>'allowed')::boolean then viol := array_append(viol,'unauthorized: '||(a->>'reason')); end if;
  esc := public.fn_should_escalate(p_attrs || jsonb_build_object('confidence',p_confidence));
  route := esc->>'route_to';
  approved := (array_length(viol,1) is null) and not (esc->>'escalate')::boolean;
  -- log the governance decision (immutable)
  insert into decision_log(actor,kind,ctx,decision,confidence,reasons,sources,route_to)
  values (p_actor,'ai_gate', jsonb_build_object('action',p_action,'attrs',p_attrs),
          case when approved then 'approved' else 'blocked' end, p_confidence,
          to_jsonb(viol || array(select jsonb_array_elements_text(coalesce(esc->'reasons','[]')))), p_sources, route);
  return jsonb_build_object('approved',approved,'violations',to_jsonb(viol),
    'grounding',g,'authorization',a,'escalation',esc,'route_to',route,
    'directive', case when approved then 'emit' when (esc->>'escalate')::boolean then 'escalate to '||coalesce(route,'Secretary') else 'revise before emitting' end);
end $function$


CREATE OR REPLACE FUNCTION public.fn_ai_quality_watch()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_regs int:=0; v_spikes int:=0; v_detail jsonb; v_open int; v_owner text;
begin
  -- 1. snapshot current per-agent override rate (builds history for spike detection)
  insert into public.ai_quality_snapshots(agent,override_pct,actions_30d)
    select agent, override_pct, actions_30d from public.v_ai_agent_health where override_pct is not null;

  -- 2. eval regressions: latest run worse than previous, or below 70 absolute
  with ranked as (
    select prompt_key, score, created_at,
           row_number() over(partition by prompt_key order by created_at desc) rn
    from public.prompt_eval_runs
  ),
  reg as (
    select c.prompt_key, c.score cur, p.score prev
    from ranked c join ranked p on p.prompt_key=c.prompt_key and p.rn=2
    where c.rn=1 and (c.score < p.score - 5 or c.score < 70)
  ),
  ins as (
    insert into public.security_events(kind,severity,source,subject,detail)
    select 'eval_regression', case when cur<70 then 'high' else 'medium' end, 'ai_quality_watch', prompt_key,
           jsonb_build_object('current',cur,'previous',prev)
    from reg returning 1
  )
  select count(*) into v_regs from ins;

  -- 3. override spikes: human-facing agents whose override jumped >20pts above their trailing average
  with cur as (
    select agent, override_pct, actions_30d from public.v_ai_agent_health
    where override_pct is not null and actions_30d>=5 and agent not in ('security','onboarding','email')
  ),
  hist as (
    select agent, avg(override_pct) avg_prev, count(*) n
    from public.ai_quality_snapshots where at < now()-interval '12 hours' group by agent
  ),
  spike as (
    select c.agent, c.override_pct, round(h.avg_prev,1) avg_prev
    from cur c join hist h on h.agent=c.agent
    where h.n>=1 and c.override_pct > coalesce(h.avg_prev,0)+20
  ),
  ins2 as (
    insert into public.security_events(kind,severity,source,subject,detail)
    select 'override_spike','medium','ai_quality_watch', agent,
           jsonb_build_object('override_pct',override_pct,'trailing_avg',avg_prev)
    from spike returning 1
  )
  select count(*) into v_spikes from ins2;

  v_detail := jsonb_build_object('eval_regressions',v_regs,'override_spikes',v_spikes);

  -- 4. surface + email the founder (deduped, mirrors fn_backup_watch), only if something fired
  if v_regs+v_spikes > 0 then
    select count(*) into v_open from public.agent_actions
      where kind='ai_quality_alert' and coalesce(status,'') in ('pending','needs_review')
        and created_at > now()-interval '24 hours';
    if v_open = 0 then
      insert into public.agent_actions(agent,kind,status,risk,title,recommendation,target_table,detail)
      values('ai_trainer','ai_quality_alert','pending','medium',
        'AI quality alert: '||v_regs||' eval regression(s), '||v_spikes||' override spike(s)',
        'Open the AI Observability dashboard and review security_events of kind eval_regression / override_spike. Consider rolling back the regressed prompt version, or investigating why a human-facing agent''s suggestions are being rejected.',
        'security_events', v_detail);
      select split_part(coalesce(value,'management@quotesdone.com'),',',1) into v_owner
        from public.app_secrets where key='admin_emails';
      insert into public.notifications(type,to_email,to_role,channel,subject,body,status)
      values('ai_quality_alert', v_owner,'admin','email','QuotesDone: AI quality alert',
        'The AI quality watch flagged '||v_regs||' eval regression(s) and '||v_spikes||' override spike(s). Open the AI Observability dashboard and check security_events (kind eval_regression / override_spike).','queued');
    end if;
  end if;
  return v_detail;
end $function$


CREATE OR REPLACE FUNCTION public.fn_ai_route(p_task_class text DEFAULT NULL::text, p_dept_key text DEFAULT NULL::text, p_confidence numeric DEFAULT NULL::numeric, p_fn text DEFAULT NULL::text, p_escalate boolean DEFAULT false, p_require_caps text[] DEFAULT NULL::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_class   text;
  v_src     text;
  v_pol     model_policy%rowtype;
  v_reg     model_registry%rowtype;
  v_fb      model_registry%rowtype;
  v_bud     department_budget%rowtype;
  v_pct     numeric := 0;
  v_model   text;
  v_why     text;
  v_min     numeric;
  v_tier    text;
  v_vis     boolean := 'vision' = any(coalesce(p_require_caps, '{}'::text[]));
  v_aud     boolean := 'audio'  = any(coalesce(p_require_caps, '{}'::text[]));
  v_tls     boolean := 'tools'  = any(coalesce(p_require_caps, '{}'::text[]));
  v_sub     model_registry%rowtype;
  v_want    int;
begin
  if p_task_class is not null and length(btrim(p_task_class)) > 0 then
    v_class := p_task_class; v_src := 'caller-supplied task_class';
  else
    select task_class into v_class from fn_task_class where fn = p_fn and active;
    if v_class is not null then
      v_src := 'classified from calling function "' || p_fn || '"';
    else
      v_class := 'general_drafting';
      v_src := 'UNMAPPED function "' || coalesce(p_fn,'?') || '" - defaulted to general_drafting (medium). Add a fn_task_class row to route this properly.';
    end if;
  end if;

  select * into v_pol from model_policy where task_class = v_class and active;
  if not found then
    select * into v_pol from model_policy where task_class = 'general_drafting' and active;
    v_src := v_src || ' | no policy for "' || v_class || '", fell back to general_drafting';
  end if;

  if v_pol.tier = 'none' then
    return jsonb_build_object(
      'use_llm', false, 'task_class', v_class, 'tier', 'none',
      'why', 'REFUSED. ' || coalesce(v_pol.deterministic_alternative, 'This is deterministic - use code.')
             || ' [' || v_src || ']',
      'deterministic_alternative', v_pol.deterministic_alternative);
  end if;

  v_tier  := v_pol.tier;
  v_model := v_pol.model_primary;
  v_why   := coalesce(v_pol.rationale, 'policy for ' || v_class) || ' [' || v_src || ']';

  if p_escalate then
    v_model := coalesce(v_pol.model_fallback, v_model);
    v_why   := v_why || ' | ESCALATED one tier after an unsatisfactory cheaper attempt';
  end if;

  select (value #>> '{}')::numeric into v_min from decision_policy where key = 'confidence_min';
  if p_confidence is not null then
    if p_confidence >= 0.95 and v_tier in ('large','xlarge') then
      select model_id into v_model from model_registry
       where active and approved and tier = 'medium' order by in_per_mtok_usd limit 1;
      v_why := v_why || ' | confidence ' || p_confidence || ' >= 0.95, downgraded to medium - no second opinion needed';
    elsif v_min is not null and p_confidence < v_min and v_tier = 'small' then
      v_model := coalesce(v_pol.model_fallback, v_model);
      v_why := v_why || ' | confidence ' || p_confidence || ' below floor ' || v_min || ', escalated a tier';
    end if;
  end if;

  if p_dept_key is not null then
    select * into v_bud from department_budget where dept_key = p_dept_key;
    if found and v_bud.monthly_aed > 0 then
      v_pct := round(100 * coalesce(
        (select sum(cost_aed) from ai_cost_log
          where dept_key = p_dept_key and occurred_at >= date_trunc('month', now())), 0)
        / v_bud.monthly_aed, 2);
      if v_pct >= v_bud.halt_at_pct then
        return jsonb_build_object(
          'use_llm', false, 'task_class', v_class, 'tier', v_tier, 'halted', true, 'budget_pct', v_pct,
          'why', 'HALTED. ' || p_dept_key || ' is at ' || v_pct || '% of its monthly AI budget (halt at '
                 || v_bud.halt_at_pct || '%). Non-gated work stops until the budget resets or is raised.');
      elsif v_pct >= v_bud.degrade_at_pct then
        select model_id into v_model from model_registry
         where active and approved
           and tier = case v_tier when 'xlarge' then 'large' when 'large' then 'medium' else 'small' end
         order by in_per_mtok_usd limit 1;
        v_why := v_why || ' | department at ' || v_pct || '% of budget, degraded one tier';
      end if;
    end if;
  end if;

  select * into v_reg from model_registry where model_id = v_model and active;
  if not found then
    select * into v_reg from model_registry
     where active and approved and tier = (case v_tier when 'xlarge' then 'xlarge' else v_tier end)
     order by in_per_mtok_usd limit 1;
    v_why := v_why || ' | WARNING: policy model "' || v_model || '" is not in model_registry; substituted ' || coalesce(v_reg.model_id,'(none)');
    v_model := v_reg.model_id;
  end if;

  -- CAPABILITY. Price and tier chose the model above; if it cannot see, hear or call tools the
  -- provider will simply reject the payload. Substitute the nearest capable model, preferring the
  -- intended tier, then the closest tier ABOVE it, and only then below - a capability substitution
  -- must never quietly become a quality downgrade.
  v_want := fn_ai_route_tier_rank(v_tier);
  if (v_vis or v_aud or v_tls)
     and not ( (not v_vis or coalesce(v_reg.supports_vision,false))
           and (not v_aud or coalesce(v_reg.supports_audio, false))
           and (not v_tls or coalesce(v_reg.supports_tools, false)) ) then

    select * into v_sub from model_registry
     where active and approved
       and (not v_vis or supports_vision) and (not v_aud or supports_audio) and (not v_tls or supports_tools)
     order by (fn_ai_route_tier_rank(tier) < v_want),                 -- at-or-above the tier first
              abs(fn_ai_route_tier_rank(tier) - v_want),              -- then closest to it
              in_per_mtok_usd                                          -- then cheapest
     limit 1;

    if found then
      v_why := v_why || ' | CAPABILITY OVERRIDE: ' || v_model || ' cannot do ('
               || array_to_string(coalesce(p_require_caps,'{}'::text[]), '+') || '); substituted ' || v_sub.model_id
               || ' (' || v_sub.tier || ' tier, intended ' || v_tier || ')';
      v_reg := v_sub; v_model := v_sub.model_id;
    else
      return jsonb_build_object(
        'use_llm', false, 'task_class', v_class, 'tier', v_tier, 'caps', to_jsonb(p_require_caps),
        'why', 'REFUSED. No active approved model in model_registry supports ('
               || array_to_string(coalesce(p_require_caps,'{}'::text[]), '+')
               || '). Add one, or mark the capability on an existing model.');
    end if;
  end if;

  select * into v_fb from model_registry
   where model_id = v_pol.model_fallback and active
     and (not v_vis or supports_vision) and (not v_aud or supports_audio) and (not v_tls or supports_tools);
  if not found and (v_vis or v_aud or v_tls) then
    select * into v_fb from model_registry
     where active and approved and model_id <> v_model
       and (not v_vis or supports_vision) and (not v_aud or supports_audio) and (not v_tls or supports_tools)
     order by (fn_ai_route_tier_rank(tier) < v_want), abs(fn_ai_route_tier_rank(tier) - v_want), in_per_mtok_usd
     limit 1;
  end if;

  return jsonb_build_object(
    'use_llm', true,
    'task_class', v_class,
    'tier', v_tier,
    'model', v_model,
    'fallback', v_fb.model_id,
    'max_tokens', v_pol.max_tokens,
    'cache', coalesce(v_reg.supports_cache, false),
    'stream', coalesce(v_reg.supports_streaming, true),
    'caps', to_jsonb(coalesce(p_require_caps, '{}'::text[])),
    'in_per_mtok_usd', v_reg.in_per_mtok_usd,
    'out_per_mtok_usd', v_reg.out_per_mtok_usd,
    'cache_read_per_mtok_usd', v_reg.cache_read_per_mtok_usd,
    'budget_pct', v_pct,
    'why', v_why);
end $function$


CREATE OR REPLACE FUNCTION public.fn_ai_route_tier_rank(p_tier text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$ select case p_tier when 'small' then 1 when 'medium' then 2 when 'large' then 3 when 'xlarge' then 4 else 0 end $function$


CREATE OR REPLACE FUNCTION public.fn_ai_spend_guard()
 RETURNS TABLE(scope text, verdict text, pct numeric, note text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  r             record;
  v_month_start date := date_trunc('month', now())::date;
  v_day_of      numeric := greatest(extract(day from now())::numeric, 1);
  v_days_in     numeric := extract(day from (date_trunc('month', now()) + interval '1 month - 1 day'))::numeric;
  v_today       numeric;
  v_baseline    numeric;
  v_spike       numeric := coalesce((select nullif(value,'')::numeric from app_secrets where key='ai_spend_spike_multiple'), 5.0);
  v_verdict     text;
  v_note        text;
  v_proj        numeric;
begin
  -- ---- 1 & 3: per-department consumption and month-end projection ----
  for r in
    select b.dept_key, b.monthly_aed, b.degrade_at_pct, b.halt_at_pct,
           coalesce((select sum(l.cost_aed) from ai_cost_log l
                      where l.dept_key = b.dept_key and l.occurred_at >= v_month_start), 0) as spent
    from department_budget b
    where b.monthly_aed > 0
  loop
    pct  := round(100 * r.spent / r.monthly_aed, 2);
    v_proj := round(r.spent / v_day_of * v_days_in, 2);

    if pct >= r.halt_at_pct then
      v_verdict := 'HALT';
      v_note := r.dept_key || ' has spent ' || round(r.spent,2) || ' of ' || r.monthly_aed
             || ' AED (' || pct || '%), at or past its halt threshold of ' || r.halt_at_pct || '%.';
    elsif pct >= r.degrade_at_pct then
      v_verdict := 'DEGRADE';
      v_note := r.dept_key || ' has spent ' || round(r.spent,2) || ' of ' || r.monthly_aed
             || ' AED (' || pct || '%), past its degrade threshold of ' || r.degrade_at_pct || '%.';
    elsif v_proj > r.monthly_aed then
      v_verdict := 'PROJECTED OVER';
      v_note := r.dept_key || ' is at ' || pct || '% on day ' || v_day_of || ', but the current run-rate projects '
             || v_proj || ' AED by month end against a ' || r.monthly_aed || ' AED budget.';
    else
      v_verdict := 'OK';
      v_note := r.dept_key || ': ' || round(r.spent,2) || '/' || r.monthly_aed || ' AED (' || pct
             || '%), projecting ' || v_proj || ' AED.';
    end if;

    insert into ai_spend_probe (scope, spent_aed, budget_aed, pct, projected_aed, verdict, note)
    values (r.dept_key, r.spent, r.monthly_aed, pct, v_proj, v_verdict, v_note);

    if v_verdict <> 'OK' then
      if not exists (select 1 from os_incidents
                      where status='open' and kind='ai_spend' and detail->>'scope' = r.dept_key) then
        insert into os_incidents (title, kind, severity, status, detail, opened_by)
        values (left('AI spend ' || v_verdict || ': ' || r.dept_key, 300), 'ai_spend',
                case when v_verdict='HALT' then 'high' else 'medium' end, 'open',
                jsonb_build_object('scope', r.dept_key, 'spent_aed', round(r.spent,2),
                  'budget_aed', r.monthly_aed, 'pct', pct, 'projected_aed', v_proj,
                  'verdict', v_verdict,
                  'governance_gap', 'model_policy degrade/halt is NOT enforced: task_class is null on every call, so fn_select_model never runs. This alert is currently the only ceiling.'),
                'ai_spend_guard');
        insert into founder_alerts (level, event, detail, channel)
        values (case when v_verdict='HALT' then 'crit' else 'warn' end, 'ai_spend_' || lower(replace(v_verdict,' ','_')),
                v_note || ' NOTE: the automatic budget halt in fn_select_model does not currently fire, because no call site passes task_class. Treat this alert as the ceiling.', 'system');
      end if;
    else
      update os_incidents set status='resolved', resolved_at=now(), resolved_by='ai_spend_guard',
             resolution = 'Back within budget: ' || v_note
       where status='open' and kind='ai_spend' and detail->>'scope' = r.dept_key;
    end if;

    scope := r.dept_key; verdict := v_verdict; note := v_note;
    return next;
  end loop;

  -- ---- 2: company-wide daily run-rate spike ----
  select coalesce(sum(cost_aed),0) into v_today
    from ai_cost_log where occurred_at >= current_date;
  select coalesce(avg(d),0) into v_baseline from (
    select sum(cost_aed) d from ai_cost_log
    where occurred_at >= current_date - interval '7 days' and occurred_at < current_date
    group by date_trunc('day', occurred_at)
  ) x;

  if v_baseline > 0 and v_today > v_baseline * v_spike then
    v_verdict := 'SPIKE';
    v_note := 'Company AI spend today is ' || round(v_today,2) || ' AED against a trailing daily average of '
           || round(v_baseline,2) || ' AED - ' || round(v_today / v_baseline, 1)
           || 'x the baseline. Autonomy multiplies call volume; check what started.';
    if not exists (select 1 from os_incidents where status='open' and kind='ai_spend' and detail->>'scope'='company_daily') then
      insert into os_incidents (title, kind, severity, status, detail, opened_by)
      values (left('AI spend SPIKE: ' || round(v_today/v_baseline,1) || 'x the daily baseline', 300),
              'ai_spend', 'high', 'open',
              jsonb_build_object('scope','company_daily','today_aed',round(v_today,2),
                'baseline_aed',round(v_baseline,2),'multiple',round(v_today/v_baseline,1),
                'threshold_multiple', v_spike), 'ai_spend_guard');
      insert into founder_alerts (level, event, detail, channel)
      values ('crit','ai_spend_spike', v_note, 'system');
    end if;
  else
    v_verdict := 'OK';
    v_note := 'Company AI spend today ' || round(v_today,2) || ' AED against a ' || round(v_baseline,2) || ' AED trailing daily average.';
    update os_incidents set status='resolved', resolved_at=now(), resolved_by='ai_spend_guard',
           resolution = v_note
     where status='open' and kind='ai_spend' and detail->>'scope'='company_daily';
  end if;

  insert into ai_spend_probe (scope, spent_aed, budget_aed, pct, verdict, note)
  values ('company_daily', v_today, v_baseline, case when v_baseline>0 then round(v_today/v_baseline,2) else null end, v_verdict, v_note);

  scope := 'company_daily'; verdict := v_verdict;
  pct := case when v_baseline>0 then round(v_today/v_baseline,2) else null end;
  note := v_note;
  return next;
end $function$


CREATE OR REPLACE FUNCTION public.fn_ai_trainer()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_runs int; v_err int; v_run_ok numeric;
  v_open int; v_rej int; v_acc int; v_reject_rate numeric; v_esc_rate numeric;
  v_qa_total int; v_qa_failed int; v_qa_pass numeric;
  v_sat numeric; v_halluc numeric; v_clarif numeric;
  v_quote_q numeric; v_match_cov numeric;
  v_health numeric; v_kpis jsonb; n_rec int; v_weak text; v_secret text; n_drafted int:=0;
begin
  select count(*), count(*) filter (where status in ('error','failed')) into v_runs, v_err from agent_runs where started_at>=now()-interval '30 days';
  v_run_ok := round(100.0*(v_runs-v_err)/nullif(v_runs,0),1);
  select count(*) filter (where status in ('pending','needs_review')),
         count(*) filter (where status='rejected'),
         count(*) filter (where status in ('approved','done','auto_done'))
    into v_open, v_rej, v_acc from agent_actions where created_at>=now()-interval '30 days';
  v_reject_rate := round(100.0*v_rej/nullif(v_rej+v_acc,0),1);
  v_esc_rate := round(100.0*v_open/nullif(v_open+v_acc+v_rej,0),1);
  select total, failed into v_qa_total, v_qa_failed from qa_results order by run_at desc limit 1;
  v_qa_pass := round(100.0*(coalesce(v_qa_total,0)-coalesce(v_qa_failed,0))/nullif(v_qa_total,0),1);
  select avg_satisfaction into v_sat from customer_kpis;
  v_halluc := round(100.0*(coalesce(v_rej,0)+coalesce(v_qa_failed,0))/nullif(coalesce(v_acc,0)+coalesce(v_rej,0)+coalesce(v_qa_total,0),0),1);
  select round(100.0*count(*) filter (where rfq_ready)/nullif(count(*),0),1) into v_clarif from inquiries where created_at>=now()-interval '90 days';
  select (kpis->>'quote_quality_avg')::numeric, (kpis->>'match_coverage_pct')::numeric into v_quote_q, v_match_cov from agent_evals order by snapshot_at desc limit 1;

  v_kpis := jsonb_build_object(
    'window_days',30,'run_success_pct',v_run_ok,'escalation_rate_pct',v_esc_rate,'rejection_rate_pct',v_reject_rate,
    'qa_pass_pct',v_qa_pass,'qa_cases',v_qa_total,'customer_satisfaction',v_sat,
    'hallucination_proxy_pct',v_halluc,'clarification_efficiency_pct',v_clarif,
    'quote_quality_avg',v_quote_q,'match_coverage_pct',v_match_cov,
    'runs_30d',v_runs,'errors_30d',v_err,'open_escalations',v_open,'rejected',v_rej,'accepted',v_acc);

  insert into agent_evals(snapshot_at, window_days, kpis) values (now(), 30, v_kpis);
  v_health := round(coalesce(v_run_ok,100)*0.30 + (100-coalesce(v_halluc,0))*0.25 + coalesce(v_sat,70)*0.20 + coalesce(v_qa_pass,100)*0.15 + coalesce((select coverage_pct from knowledge_kpis),60)*0.10,1);
  insert into ai_trainer_snapshots(snapshot_date, kpis) values (current_date, v_kpis || jsonb_build_object('ai_health',v_health))
    on conflict (snapshot_date) do update set kpis=excluded.kpis, created_at=now();

  select string_agg(agent||' ('||coalesce(run_success_pct,0)||'% ok, '||coalesce(rejection_rate_pct,0)||'% rejected)', '; ')
    into v_weak from ai_agent_quality where runs_30d>=20 and (coalesce(run_success_pct,100)<90 or coalesce(rejection_rate_pct,0)>30);
  perform ai_rec('weak_agents', v_weak is not null, 'medium', 'Under-performing agents',
    'These agents need attention: '||v_weak||'. Review their logic/prompt or the knowledge they rely on.');
  perform ai_rec('low_quote_quality', coalesce(v_quote_q,100) < 60, 'medium', 'Quote-review quality is low',
    'Structured quote quality is averaging '||coalesce(v_quote_q,0)||'/100. The Trainer is drafting an improved quote_review prompt for your approval; also strengthening category knowledge helps.');
  perform ai_rec('thin_benchmarks', coalesce(v_qa_total,0) < 20, 'low', 'Add more test benchmarks',
    'The QA suite has only '||coalesce(v_qa_total,0)||' cases. Add benchmark cases (quotes, RFQ qualification, compliance answers) so regressions are caught automatically.');
  perform ai_rec('prompts_unbenchmarked', (select count(*) from prompt_versions where status='active' and eval_score is null)>0, 'low', 'Prompts have no eval score',
    (select count(*)::text from prompt_versions where status='active' and eval_score is null)||' active prompt(s) have never been benchmarked. Run an eval so future changes can be compared objectively.');
  perform ai_rec('accuracy_watch', coalesce(v_halluc,0) > 15, 'high', 'Accuracy watch — high correction rate',
    'The AI was corrected/failed '||coalesce(v_halluc,0)||'% of the time (founder rejections + QA failures). Review the rejected actions to find the pattern and fix the responsible prompt or knowledge.');

  -- CLOSED LOOP: when quote quality is low and no draft is already awaiting approval, ask the LLM to author an improved
  -- quote_review prompt DRAFT (founder still approves before rollout). De-duped so it drafts once per open cycle.
  if coalesce(v_quote_q,100) < 60
     and not exists (select 1 from agent_actions where kind='prompt_approval' and detail->>'key'='quote_review.system' and status in ('pending','needs_review'))
     and not exists (select 1 from prompt_versions where prompt_key='quote_review.system' and status='draft') then
    select value into v_secret from app_secrets where key='cred_db_internal';
    perform net.http_post(
      url:='https://htdblwldjkcgjvmqkbeh.supabase.co/functions/v1/prompt_improve',
      headers:='{"Content-Type":"application/json"}'::jsonb,
      body:=jsonb_build_object('__secret',v_secret,'key','quote_review.system',
        'reason','Structured quote quality is averaging '||coalesce(v_quote_q,0)||'/100 — quotes lack itemised detail (brand/model/spec/unit price) and clear scope; the prompt should require full line-item detail and flag missing fields.'));
    n_drafted := 1;
  end if;

  select count(*) into n_rec from agent_actions where agent='ai_trainer' and status in ('pending','needs_review');
  return jsonb_build_object('ran_at',now(),'ai_health',v_health,'kpis',v_kpis,'open_recommendations',n_rec,'auto_drafted',n_drafted);
end $function$


CREATE OR REPLACE FUNCTION public.fn_answer_precedence_rank(p answer_precedence)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case p
    when 'customer_confirmed'      then 1
    when 'approved_document'       then 2
    when 'document_extracted'      then 3
    when 'deterministic_inference' then 4
    when 'model_inference'         then 5
    else 6 end;
$function$


CREATE OR REPLACE FUNCTION public.fn_ap_bill_dupe_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_prior bigint;
begin
  if coalesce(new.status,'') in ('void','duplicate_hold') then return new; end if;

  select id into v_prior from ap_bills
  where vendor_id = new.vendor_id
    and coalesce(status,'') not in ('void','duplicate_hold')
    and id is distinct from new.id
    and total = new.total
    and bill_date = new.bill_date
  order by id limit 1;

  if v_prior is not null then
    new.status := 'duplicate_hold';

    insert into brand_signal (signal_type, severity, subject_type, subject_id, rule_key, detail, evidence)
    values ('fake_supplier','critical','ap_bill', coalesce(new.bill_no, new.id::text), 'duplicate_invoice_presented',
            'Same vendor, same amount, same date as an invoice already booked. Held, not posted.',
            jsonb_build_object('vendor_id', new.vendor_id, 'total', new.total,
                               'bill_date', new.bill_date, 'prior_bill_id', v_prior,
                               'presented_bill_no', new.bill_no))
    on conflict do nothing;

    insert into institutional_memory (kind, subject_type, subject_id, headline, detail, outcome,
                                      money_aed, learned_by, confidence, evidence_ref)
    values ('pattern','ap_bill', coalesce(new.bill_no, new.id::text),
            'Duplicate invoice presentation held before payment.',
            format('Vendor %s presented %s for %s on %s, matching bill id %s already on file.',
                   new.vendor_id, coalesce(new.bill_no,'(no ref)'), new.total, new.bill_date, v_prior),
            'held as duplicate_hold; not posted, not paid', new.total, 'finance_bookkeeper', 1.0,
            'trg_ap_bill_dupe_guard; ap_bills id ' || v_prior);

    insert into company_event (event_type, entity_type, entity_id, actor, payload)
    values ('invoice.flagged','ap_bill', coalesce(new.bill_no, new.id::text), 'finance_bookkeeper',
            jsonb_build_object('reason','duplicate_invoice','vendor_id', new.vendor_id,
                               'total', new.total,'prior_bill_id', v_prior));

    raise warning 'invoice held as duplicate of bill id %', v_prior;
  end if;
  return new;
end; $function$


CREATE OR REPLACE FUNCTION public.fn_ap_duplicate_scan()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n integer := 0;
begin
  insert into brand_signal (signal_type, severity, subject_type, subject_id, rule_key, detail, evidence)
  select 'fake_supplier','critical','ap_bill', min(b.bill_no), 'duplicate_invoice_booked',
         'More than one non-void bill exists for the same vendor, amount and date.',
         jsonb_build_object('vendor_id', b.vendor_id, 'total', b.total, 'bill_date', b.bill_date,
                            'bill_ids', array_agg(b.id order by b.id), 'count', count(*))
  from ap_bills b
  where coalesce(b.status,'') <> 'void'
  group by b.vendor_id, b.total, b.bill_date
  having count(*) > 1
  on conflict do nothing;
  get diagnostics n = row_count;
  return n;
end; $function$


CREATE OR REPLACE FUNCTION public.fn_ap_pay(p_bill bigint, p_date date DEFAULT NULL::date, p_amount numeric DEFAULT NULL::numeric, p_from_account text DEFAULT '1000'::text, p_by text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare b record; pay numeric(18,2); j bigint; newpaid numeric(18,2);
begin
  select * into b from public.ap_bills where id=p_bill;
  if b.id is null then raise exception 'bill % not found', p_bill; end if;
  if b.status in ('paid','void') then raise exception 'bill % is %', p_bill, b.status; end if;
  pay := coalesce(round(p_amount,2), b.total - b.amount_paid);
  if pay <= 0 then raise exception 'nothing to pay on bill %', p_bill; end if;
  if b.amount_paid + pay > b.total then raise exception 'overpay bill %: %/%', p_bill, b.amount_paid+pay, b.total; end if;

  j := public.fn_gl_entry(coalesce(p_date,current_date),
         'Payment '||coalesce(b.bill_no,'bill '||p_bill),
         'ap_payment', p_bill::text,
         jsonb_build_array(jsonb_build_object('account','2000','debit', pay),
                           jsonb_build_object('account',p_from_account,'credit', pay)),
         p_by);
  newpaid := b.amount_paid + pay;
  update public.ap_bills
     set amount_paid = newpaid,
         status = case when newpaid >= total then 'paid' else 'partial' end,
         pay_journal_id = j
   where id=p_bill;
  return j;
end $function$


CREATE OR REPLACE FUNCTION public.fn_ap_pay_block_held()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.status in ('paid','partial') and coalesce(old.status,'') = 'duplicate_hold' then
    raise exception 'bill % is held as a duplicate and cannot be paid until a person clears the hold',
      coalesce(new.bill_no, new.id::text);
  end if;
  return new;
end; $function$


CREATE OR REPLACE FUNCTION public.fn_assign_founding_rank()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_limit int; v_rank int;
begin
  -- Rank a supplier once, and only once they are a VERIFIED supplier. Claiming a scraped listing
  -- is not registration; registration without documents is not verification.
  if new.founding_rank is not null then return new; end if;
  if coalesce(new.verified,false) is not true then return new; end if;
  if coalesce(new.banned,false) is true then return new; end if;
  if coalesce(new.approval_status,'') in ('rejected','action_required') then return new; end if;

  v_limit := coalesce((select nullif(value,'')::int from public.app_secrets where key='founding_free_limit'), 1000);

  -- Serialise rank assignment so two concurrent verifications cannot take the same number.
  perform pg_advisory_xact_lock(hashtext('qd_founding_rank'));
  select coalesce(max(founding_rank),0) + 1 into v_rank from public.leads;

  new.founding_rank := v_rank;
  -- Exemption is permanent: it is stamped at verification and never recalculated, so a supplier
  -- who was inside the first 1,000 stays exempt even as the base grows.
  new.subscription_exempt := (v_rank <= v_limit);
  return new;
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_assign_founding_ranks()
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_limit int; v_max int; v_assigned int := 0;
begin
  v_limit := coalesce((select nullif(value,'')::int from app_secrets where key='founding_free_limit'), 1000);
  select coalesce(max(founding_rank),0) into v_max from leads;
  with candidates as (
    select id, row_number() over (
             order by coalesce(approved_at, registration_submitted_at, created_at) asc, id asc) + v_max as new_rank
    from leads
    where founding_rank is null
      and coalesce(verified,false) = true
      and coalesce(banned,false) = false
      and coalesce(approval_status,'') not in ('rejected','action_required')
  )
  update leads l set founding_rank = c.new_rank,
                     subscription_exempt = (c.new_rank <= v_limit)
  from candidates c where l.id = c.id;
  get diagnostics v_assigned = row_count;
  return json_build_object('newly_ranked', v_assigned, 'highest_rank', (select coalesce(max(founding_rank),0) from leads),
                           'founding_slots_left', greatest(0, v_limit - (select count(*) from leads where founding_rank is not null)),
                           'free_limit', v_limit);
end $function$


CREATE OR REPLACE FUNCTION public.fn_audit_prune()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare n_audit int; n_undo int;
begin
  delete from os_audit_log where action='agent_run' and at < now() - interval '180 days';
  get diagnostics n_audit = row_count;

  delete from undo_log where created_at < now() - interval '90 days';
  get diagnostics n_undo = row_count;

  insert into agent_runs (agent, started_at, finished_at, status, counts, note)
  values ('audit_prune', now(), now(), 'ok',
          jsonb_build_object('audit_pruned',n_audit,'undo_pruned',n_undo),
          'Retention: '||n_audit||' agent-run audit rows and '||n_undo||' undo rows older than their window removed.');

  return jsonb_build_object('audit_pruned',n_audit,'undo_pruned',n_undo);
end $function$


CREATE OR REPLACE FUNCTION public.fn_authority_rank(p text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- How much UNSUPERVISED power the tier confers. advisory advises only; gated needs approval
  -- before acting; supervised acts and is reviewed after; autonomous acts unreviewed.
  select case p when 'advisory' then 0 when 'gated' then 1 when 'supervised' then 2
                when 'autonomous' then 3 else 3 end;   -- unknown tier ranks highest: fail closed
$function$


CREATE OR REPLACE FUNCTION public.fn_authorize(p_email text, p_action text, p_attrs jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_role text; c jsonb; ok boolean:=false; reason text; maxamt numeric; amt numeric;
begin
  v_role := public.fn_role_of(p_email);
  if v_role='owner' then return jsonb_build_object('allowed',true,'role',v_role,'reason','owner has full access'); end if;
  select rp.constraint_json into c from role_permissions rp where rp.role=v_role and rp.action=p_action;
  if c is null then
    if exists(select 1 from role_permissions rp where rp.role=v_role and rp.action='*') then
      return jsonb_build_object('allowed',true,'role',v_role,'reason','role wildcard'); end if;
    return jsonb_build_object('allowed',false,'role',v_role,'reason','role "'||v_role||'" lacks permission "'||p_action||'"');
  end if;
  ok := true; reason := 'granted';
  if c ? 'max_amount_aed' then
    maxamt := (c->>'max_amount_aed')::numeric; amt := nullif(p_attrs->>'amount_aed','')::numeric;
    if amt is not null and amt > maxamt then ok:=false; reason:='amount '||amt||' exceeds role limit '||maxamt; end if;
  end if;
  if c ? 'purpose' and coalesce(p_attrs->>'purpose','') <> (c->>'purpose') then ok:=false; reason:='purpose must be '||(c->>'purpose'); end if;
  return jsonb_build_object('allowed',ok,'role',v_role,'reason',reason,'constraint',c);
end $function$


CREATE OR REPLACE FUNCTION public.fn_autonomy_audit()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with per as (
    select d.dept_key, d.name,
      (select max(created_at) from org_memory m where m.scope=d.dept_key and m.kind='plan')   as last_plan,
      (select max(created_at) from org_memory m where m.scope=d.dept_key and m.kind='lesson') as last_lesson,
      (select count(*) from org_tasks t where t.dept_key=d.dept_key and t.status in ('assigned','proposed','in_progress')) as open_tasks,
      (select count(*) from org_tasks t where t.dept_key=d.dept_key and t.status='done' and t.updated_at > now()-interval '7 days') as done_7d
    from org_departments d where d.active
  )
  select jsonb_build_object(
    'as_of', now(),
    'departments', (select jsonb_agg(jsonb_build_object(
        'dept', dept_key, 'name', name,
        'last_plan', last_plan, 'last_lesson', last_lesson, 'open_tasks', open_tasks, 'done_7d', done_7d,
        'status', case
          when (last_plan is null or last_plan < now()-interval '4 days') and open_tasks=0 and done_7d=0 then 'red'
          when (last_plan is null or last_plan < now()-interval '3 days') then 'amber'
          else 'green' end
      ) order by dept_key) from per),
    'summary', (select jsonb_build_object(
        'green', count(*) filter (where (last_plan is not null and last_plan >= now()-interval '3 days')),
        'stalled', count(*) filter (where (last_plan is null or last_plan < now()-interval '4 days') and open_tasks=0 and done_7d=0))
      from per)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_autonomy_audit_run()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare a jsonb; stalled int;
begin
  a := fn_autonomy_audit();
  stalled := coalesce((a->'summary'->>'stalled')::int, 0);
  insert into org_memory(scope,kind,content,source)
    values ('exec','audit','Autonomy self-audit: '||(a->'summary')::text||' — '||stalled||' department loop(s) stalled.', 'autonomy_audit');
  if stalled > 0 then
    insert into agent_actions(agent,kind,status,risk,title,recommendation,detail)
    values ('brief','autonomy_stall','pending','medium',
      stalled||' department loop(s) have stalled',
      'One or more departments have not planned in 4+ days and have no open or recent work. Check fn_autonomy_audit().',
      a);
  end if;
  return a;
end $function$


CREATE OR REPLACE FUNCTION public.fn_autonomy_check(p_kind text, p_target_table text, p_recommendation text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select case
    when p_kind ~* 'refund|payout|payment|withdraw|transfer|invoice_pay|money|charge' then 'approve'
    when p_kind ~* 'delete|purge|remove_record' and coalesce(p_target_table,'') in ('leads','customers') then 'approve'
    when p_kind = 'approve_supplier' and coalesce(p_recommendation,'') <> 'approve' then 'approve'
    else 'auto'
  end;
$function$


CREATE OR REPLACE FUNCTION public.fn_autonomy_class(p_kind text, p_target_table text, p_recommendation text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare pol jsonb; d text;
begin
  -- Policy-bounded carve-out (chairman doctrine 2026-07-24): a refund fully inside
  -- the published policy window is routine work, not an executive decision.
  if p_kind = 'refund_within_window' then return 'ack'; end if;
  -- HARD RAILS: money, destructive, and supplier approval can never be auto-cleared by policy.
  if p_kind ~* 'refund|payout|payment|withdraw|transfer|invoice_pay|money|charge' then return 'founder'; end if;
  if p_kind ~* 'delete|purge|remove_record' and coalesce(p_target_table,'') in ('leads','customers') then return 'founder'; end if;
  if p_kind='approve_supplier' and coalesce(p_recommendation,'')='approve' then return 'clean_supplier'; end if;
  if p_kind='approve_supplier' then return 'founder'; end if;
  -- POLICY: founder-editable per-kind disposition.
  select value into pol from public.decision_policy where key='action_autonomy';
  d := pol->>p_kind;
  if d in ('ack','founder','keep') then return d; end if;
  -- LEGACY FALLBACK
  if p_kind in ('security_alert','compliance_update','incident','supply_health','sla_no_supply') then return 'ack'; end if;
  return 'keep';
end $function$


CREATE OR REPLACE FUNCTION public.fn_autonomy_control_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_key    text := coalesce(new.key, old.key);
  v_old    text := old.value;
  v_new    text := new.value;
  v_reason text := nullif(trim(coalesce(current_setting('app.change_reason', true), '')), '');
  v_dir    text := 'neutral';
  v_widen  boolean := false;
begin
  if v_key not in ('agent_autonomy_enabled','agent_autonomy_from','cos_frozen','ai_kill_switch') then
    return coalesce(new, old);
  end if;

  if tg_op = 'DELETE' then
    -- Deleting cos_frozen or ai_kill_switch removes a brake; deleting the enable flag adds one.
    v_widen := v_key in ('cos_frozen','ai_kill_switch');
  elsif v_key = 'agent_autonomy_enabled' then
    v_widen := v_new = 'true' and coalesce(v_old,'false') <> 'true';
  elsif v_key = 'cos_frozen' then
    v_widen := coalesce(v_new,'false') <> 'true' and v_old = 'true';
  elsif v_key = 'ai_kill_switch' then
    v_widen := coalesce(v_new,'false') = 'false' and coalesce(v_old,'false') <> 'false';
  elsif v_key = 'agent_autonomy_from' then
    v_widen := tg_op = 'INSERT' or v_new is distinct from v_old;   -- any move of the date is a widen
  end if;
  v_dir := case when v_widen then 'widen' else 'tighten' end;

  if v_widen and (v_reason is null or length(v_reason) < 12) then
    raise exception
      'app_secrets.%: widening autonomy needs a stated reason. Run '
      '`set local app.change_reason = ''why, in a sentence'';` in the same transaction. '
      'A PostgREST update from an edge function cannot set that, which is the point — this key '
      'was reachable by all 190 service-role functions. Tightening (freeze, kill switch, disable) '
      'never needs a reason and is never refused.', v_key
      using errcode = 'check_violation';
  end if;

  insert into public.autonomy_control_audit (object, op, direction, old_value, new_value, reason)
  values ('app_secrets:' || v_key, tg_op, v_dir, v_old, v_new, v_reason);

  return coalesce(new, old);
end $function$


CREATE OR REPLACE FUNCTION public.fn_autonomy_dispose()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare r record; n_appr int:=0; n_ack int:=0; n_queue int:=0; c text;
begin
  for r in select * from public.agent_actions
           where status in ('pending','held_for_review','proposed','open','needs_review')
  loop
    c := public.fn_autonomy_class(r.kind, r.target_table, r.recommendation);
    if c='clean_supplier' and r.target_id ~ '^\d+$' then
      update public.leads set approval_status='approved', approved_at=now(),
             approval_decided_by='chief_of_staff (auto)', lifecycle_stage='active'
       where id=r.target_id::bigint and approval_status='pending' and coalesce(banned,false)=false;
      update public.agent_actions set status='approved', decided_by='chief_of_staff (auto)', decided_at=now() where id=r.id;
      n_appr := n_appr+1;
    elsif c='ack' then
      update public.agent_actions set status='auto_done', decided_by='chief_of_staff (auto)', decided_at=now() where id=r.id;
      n_ack := n_ack+1;
    else  -- 'founder' or 'keep' → remains visible in the queue
      n_queue := n_queue+1;
    end if;
  end loop;
  return jsonb_build_object('approved_suppliers',n_appr,'auto_cleared_logged',n_ack,'in_your_queue',n_queue);
end $function$


CREATE OR REPLACE FUNCTION public.fn_autonomy_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_blockers text[] := '{}';
  v_p0       record;
  v_enabled  text;
  v_from     text;
  v_frozen   text;
  v_kill     text;
begin
  for v_p0 in
    select id, item from public.spec_backlog where priority = 0 and status = 'open' order by id
  loop
    v_blockers := array_append(v_blockers, 'spec_backlog#' || v_p0.id || ' open: ' || left(v_p0.item, 90));
  end loop;

  select value into v_enabled from public.app_secrets where key = 'agent_autonomy_enabled';
  select value into v_from    from public.app_secrets where key = 'agent_autonomy_from';
  select value into v_frozen  from public.app_secrets where key = 'cos_frozen';
  select value into v_kill    from public.app_secrets where key = 'ai_kill_switch';

  if coalesce(v_enabled, 'false') <> 'true' then
    v_blockers := array_append(v_blockers, 'agent_autonomy_enabled is not true');
  end if;
  if v_frozen = 'true' then
    v_blockers := array_append(v_blockers, 'cos_frozen is true');
  end if;
  if v_kill is not null and v_kill <> 'false' then
    v_blockers := array_append(v_blockers, 'ai_kill_switch is set');
  end if;
  begin
    if v_from is not null and v_from::date > current_date then
      v_blockers := array_append(v_blockers, 'agent_autonomy_from is in the future: ' || v_from);
    end if;
  exception when others then
    v_blockers := array_append(v_blockers, 'agent_autonomy_from is unparseable: ' || coalesce(v_from, 'null'));
  end;

  return jsonb_build_object(
    'allowed',    cardinality(v_blockers) = 0,
    'blockers',   to_jsonb(v_blockers),
    'checked_at', now());
exception when others then
  return jsonb_build_object(
    'allowed', false,
    'blockers', to_jsonb(array['autonomy status could not be determined: ' || sqlerrm]),
    'checked_at', now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_backup_watch()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_last timestamptz; v_status text; v_stale boolean; v_owner text; v_open int;
begin
  select started_at, status into v_last, v_status
    from agent_runs where agent='backup' order by started_at desc limit 1;
  v_stale := (v_last is null) or (v_last < now() - interval '26 hours') or (coalesce(v_status,'')='error');
  if not v_stale then
    return jsonb_build_object('ok',true,'last',v_last,'status',v_status);
  end if;
  select count(*) into v_open from agent_actions
    where kind='backup_alert' and coalesce(status,'') in ('pending','needs_review')
      and created_at > now()-interval '24 hours';
  if v_open = 0 then
    insert into agent_actions(agent,kind,status,risk,title,recommendation,target_table,detail)
    values('security','backup_alert','pending','high',
      'Backup may have failed or is overdue',
      'The daily logical backup has not completed successfully in the last 26 hours (last: '||coalesce(v_last::text,'never')||', status: '||coalesce(v_status,'unknown')||'). Check the backup function and logs. Managed daily backups and the Dropbox mirror remain as fallbacks.',
      'agent_runs', jsonb_build_object('last_backup',v_last,'last_status',v_status));
    insert into security_events(kind,severity,source,subject,detail)
    values('backup_overdue','high','backup','logical backup',
      jsonb_build_object('last_backup',v_last,'last_status',v_status));
    select split_part(coalesce(value,'management@quotesdone.com'),',',1) into v_owner
      from app_secrets where key='admin_emails';
    insert into notifications(type,to_email,to_role,channel,subject,body,status)
    values('backup_alert', v_owner, 'admin','email','QuotesDone: backup overdue or failed',
      'The daily logical backup has not completed in the last 26 hours (last: '||coalesce(v_last::text,'never')||', status: '||coalesce(v_status,'unknown')||'). Please check. Managed daily backups + the Dropbox mirror remain as fallbacks.','queued');
  end if;
  return jsonb_build_object('alerted',true,'last',v_last,'status',v_status,'existing_open',v_open);
end $function$


CREATE OR REPLACE FUNCTION public.fn_ban_overdue_dues()
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v_days int; v_n int := 0; v_admin text;
begin
  v_days  := coalesce((select num_value from public.gl_settings where key='clawback_ban_days'), 90)::int;
  v_admin := coalesce((select split_part(value,',',1) from public.app_secrets where key='admin_emails'),'management@quotesdone.com');

  for r in
    select d.id, d.supplier_id, d.amount_due, d.admin_fee, d.interest_amount, d.due_date,
           l.company_name, coalesce(l.claimed_by,l.email) as email,
           l.accepted_terms_at, l.accepted_terms_version, l.signed_terms_path, l.banned
    from public.supplier_dues d
    join public.leads l on l.id = d.supplier_id
    where d.paid_at is null
      and coalesce(d.status,'') not in ('paid','settled','waived','cancelled')
      and coalesce(d.amount_due,0) > 0
      and d.due_date is not null
      and current_date >= (d.due_date::date + v_days)
      and d.legal_escalated_at is null
  loop
    update public.supplier_dues
       set status = 'legal', legal_stage = 'pending_case', legal_escalated_at = now()
     where id = r.id;

    update public.leads
       set banned = true,
           banned_reason = 'Unpaid refund clawback of AED ' ||
                           round(coalesce(r.amount_due,0)+coalesce(r.admin_fee,0)+coalesce(r.interest_amount,0),2) ||
                           ' more than ' || v_days || ' days past due (due ' || r.due_date::date || ').',
           matching_blocked = true,
           matching_block_reason = 'Banned: unpaid refund clawback escalated to legal'
     where id = r.supplier_id;

    insert into public.founder_alerts(level, event, detail, channel)
    values ('crit', 'supplier_banned_legal',
      coalesce(r.company_name,'Supplier #'||r.supplier_id) || ' has been banned and due #' || r.id ||
      ' escalated to legal: AED ' || round(coalesce(r.amount_due,0)+coalesce(r.admin_fee,0)+coalesce(r.interest_amount,0),2) ||
      ' unpaid for over ' || v_days || ' days. ' ||
      case when r.accepted_terms_at is null
           then '*** NO SIGNED TERMS ON RECORD - the supplier agreement cannot be produced as evidence, so a filing may not be supportable. Verify before instructing the legal agent. ***'
           else 'Terms accepted ' || r.accepted_terms_at::date || ' (version ' || coalesce(r.accepted_terms_version,'?') || ') - available as supporting evidence.'
      end, 'system');

    v_n := v_n + 1;
  end loop;

  return v_n;
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_bi_snapshot()
 RETURNS TABLE(metric_key text, value numeric, error text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r record; v numeric; e text;
begin
  for r in select m.metric_key, m.measure_sql from metric_definition m where m.active loop
    v := null; e := null;
    begin
      execute r.measure_sql into v;
    exception when others then e := left(sqlerrm, 200);
    end;
    insert into metric_snapshot (metric_key, value, error) values (r.metric_key, v, e);
    metric_key := r.metric_key; value := v; error := e;
    return next;
  end loop;
end; $function$


CREATE OR REPLACE FUNCTION public.fn_board_report()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  inq_t int; inq_p int; q_t int; q_p int; c_t int; c_p int; s_t int; s_p int;
  rev_t numeric; rev_p numeric; conv numeric; qpr numeric;
  gap int; expired int; crit int; gatepass numeric;
  health jsonb; eval jsonb; officer text; topcats text;
  wtrend text; body text; owner text; d jsonb;
begin
  select count(*) filter (where created_at>=now()-interval '7 days'),
         count(*) filter (where created_at>=now()-interval '14 days' and created_at<now()-interval '7 days')
    into inq_t, inq_p from inquiries;
  select count(*) filter (where created_at>=now()-interval '7 days'),
         count(*) filter (where created_at>=now()-interval '14 days' and created_at<now()-interval '7 days')
    into q_t, q_p from quotes;
  select count(*) filter (where created_at>=now()-interval '7 days'),
         count(*) filter (where created_at>=now()-interval '14 days' and created_at<now()-interval '7 days')
    into c_t, c_p from customers;
  select count(*) filter (where registration_submitted_at>=now()-interval '7 days'),
         count(*) filter (where registration_submitted_at>=now()-interval '14 days' and registration_submitted_at<now()-interval '7 days')
    into s_t, s_p from leads;
  select coalesce(sum(reveal_fee) filter (where revealed_at>=now()-interval '7 days'),0),
         coalesce(sum(reveal_fee) filter (where revealed_at>=now()-interval '14 days' and revealed_at<now()-interval '7 days'),0)
    into rev_t, rev_p from transactions where coalesce(refund_status,'')<>'approved';
  select round(100.0*count(distinct t.inquiry_id)/nullif(count(distinct i.id),0),1) into conv
    from inquiries i left join transactions t on t.inquiry_id=i.id where i.created_at>=now()-interval '30 days';
  select round(avg(qc),1) into qpr from (select count(*) qc from quotes q join inquiries i on i.id=q.inquiry_id where i.created_at>=now()-interval '30 days' group by q.inquiry_id) z;
  select count(*) into gap from inquiries i where i.status not in ('completed','accepted','closed','cancelled') and not exists(select 1 from inquiry_matches m where m.inquiry_id=i.id);
  begin select count(*) into expired from leads where license_expiry<current_date and coalesce(approval_status,'')='approved'; exception when others then expired:=0; end;
  select count(*) into crit from founder_alerts where level='critical' and created_at>=now()-interval '7 days';
  select round(100.0*count(*) filter (where nullif(quality->>'score','')::numeric>=60)/nullif(count(*) filter (where quality is not null),0),1) into gatepass
    from quotes where created_at>=now()-interval '7 days';
  begin select public.fn_health_index() into health; exception when others then health:=null; end;
  begin select public.fn_eval_snapshot(30) into eval; exception when others then eval:=null; end;
  select string_agg(cat,', ') into topcats from (select coalesce(nullif(category,''),'(uncat)') cat, count(*) n from inquiries where created_at>=now()-interval '7 days' group by 1 order by n desc limit 5) z;
  officer := public.fn_officer_recs(8);

  wtrend :=
    '- RFQs: '||inq_t||' (prev '||inq_p||')'||E'\n'||
    '- Quotes: '||q_t||' (prev '||q_p||')'||E'\n'||
    '- New customers: '||c_t||' (prev '||c_p||')'||E'\n'||
    '- New supplier registrations: '||s_t||' (prev '||s_p||')'||E'\n'||
    '- Revenue: AED '||round(rev_t)||' (prev AED '||round(rev_p)||')';

  d := jsonb_build_array();
  if expired>0 then d := d||to_jsonb('Review '||expired||' supplier(s) with expired trade licence'::text); end if;
  if crit>0 then d := d||to_jsonb('Address '||crit||' critical alert(s) from this week'::text); end if;
  if gap>0 then d := d||to_jsonb('Decide sourcing for '||gap||' unmatched demand item(s)'::text); end if;

  body := public.fn_report_skeleton(
    'QuotesDone Weekly Board Report — '||to_char(current_date,'DD Mon YYYY'),
    'Marketplace health '||coalesce(health->>'index','—')||'/100 ('||coalesce(health->>'band','no data')||'). '||
      inq_t||' RFQs and '||q_t||' quotes this week; revenue AED '||round(rev_t)||'; 30-day conversion '||coalesce(conv::text,'—')||'%.',
    jsonb_build_array(
      jsonb_build_object('heading','Key Metrics (this week)','body',
        'RFQs '||inq_t||' · Quotes '||q_t||' · Avg quotes/RFQ (30d) '||coalesce(qpr::text,'—')||' · Conversion (30d) '||coalesce(conv::text,'—')||'% · Revenue AED '||round(rev_t)||' · Quote-gate pass '||coalesce(gatepass::text,'—')||'%'),
      jsonb_build_object('heading','Trends (WoW)','body',wtrend),
      jsonb_build_object('heading','Growth','body','Top categories: '||coalesce(topcats,'—')),
      jsonb_build_object('heading','AI Performance','body','Health index '||coalesce(health->>'index','—')||'/100; eval sample '||coalesce(eval->'samples'->>'quotes','0')||' quotes, gate pass '||coalesce(gatepass::text,'—')||'%.'),
      jsonb_build_object('heading','Issues','body','Supply gaps: '||gap||' · Expired licences: '||expired||' · Critical alerts (7d): '||crit),
      jsonb_build_object('heading','Recommendations (officers)','body',coalesce(officer,'No officer recommendations available yet.'))
    ),
    d,
    'Health: '||coalesce(health::text,'n/a')||E'\n'||'Eval: '||coalesce(eval::text,'n/a'));

  insert into public.board_reports(week_start, title, body, kpis)
  values (date_trunc('week',current_date)::date,
          'QuotesDone Weekly Board Report — '||to_char(current_date,'DD Mon YYYY'), body,
          jsonb_build_object('rfqs',inq_t,'quotes',q_t,'customers',c_t,'suppliers',s_t,'revenue',rev_t,'conversion',conv,'gate_pass',gatepass,'health',(health->>'index')));

  select split_part(coalesce(value,'management@quotesdone.com'),',',1) into owner from app_secrets where key='admin_emails';
  insert into notifications(type,to_email,to_role,channel,subject,body)
  values ('board_report', coalesce(owner,'management@quotesdone.com'),'admin','email',
          'QuotesDone Weekly Board Report — '||to_char(current_date,'DD Mon'), body);
end $function$


CREATE OR REPLACE FUNCTION public.fn_board_review(p_subject text, p_subject_ref text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare adv record; ch jsonb; v_rec text; v_conf numeric; v_supply int; v_rev numeric;
  n_pro int:=0; n_cond int:=0; n_against int:=0; v_out jsonb := '[]'::jsonb;
begin
  ch := fn_challenge(p_subject,'board','board');
  select count(*) into v_supply from leads where approval_status='approved';
  select coalesce(sum(coalesce(reveal_fee,app_fee,0)),0) into v_rev from transactions where revealed_at>now()-interval '30 days';

  for adv in select * from board_advisor where active order by advisor_key loop
    -- each advisor reasons through its own lens against the same facts
    if adv.advisor_key='risk' and (ch->>'stance')='recommend_against' then
      v_rec:='do_not_proceed'; v_conf:=0.85;
    elsif adv.advisor_key='economist' and v_rev=0 then
      v_rec:='proceed_with_conditions'; v_conf:=0.7;
    elsif adv.advisor_key in ('customer','supplier') and v_supply=0 then
      v_rec:='abstain'; v_conf:=0.5;
    elsif (ch->>'stance')='recommend_against' then
      v_rec:='do_not_proceed'; v_conf:=0.75;
    elsif (ch->>'stance')='concern' then
      v_rec:='proceed_with_conditions'; v_conf:=0.65;
    else
      v_rec:='proceed'; v_conf:=0.6;
    end if;

    insert into board_opinion (subject,subject_ref,advisor_key,recommendation,rationale,confidence)
    values (p_subject,p_subject_ref,adv.advisor_key,v_rec,
      adv.name||' ('||adv.lens||') asks: '||adv.asks||' — '||
      case v_rec
        when 'do_not_proceed' then 'On the evidence available this fails that test.'
        when 'proceed_with_conditions' then 'Proceed only with a named metric, a captured baseline and a reversal path.'
        when 'abstain' then 'There is no data on this side of the marketplace yet; an opinion would be invention.'
        else 'Nothing in this lens argues against it.' end, v_conf);

    if v_rec='proceed' then n_pro:=n_pro+1;
    elsif v_rec='proceed_with_conditions' then n_cond:=n_cond+1;
    elsif v_rec='do_not_proceed' then n_against:=n_against+1; end if;

    v_out := v_out || jsonb_build_array(jsonb_build_object('advisor',adv.name,'lens',adv.lens,'recommendation',v_rec,'confidence',v_conf));
  end loop;

  return jsonb_build_object('subject',p_subject,'proceed',n_pro,'with_conditions',n_cond,
    'against',n_against,'abstained',(select count(*) from board_advisor where active)-n_pro-n_cond-n_against,
    'board_verdict', case when n_against>0 then 'DO NOT PROCEED' when n_cond>0 then 'PROCEED WITH CONDITIONS' else 'PROCEED' end,
    'challenge_stance', ch->>'stance', 'opinions', v_out);
end $function$


CREATE OR REPLACE FUNCTION public.fn_brand_scan()
 RETURNS TABLE(rule_key text, hits integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  -- 1. Supplier claims to be registered but has no trade licence number.
  insert into brand_signal (signal_type, severity, subject_type, subject_id, rule_key, detail, evidence)
  select 'fake_supplier','high','lead', l.id::text, 'no_trade_licence',
         'Supplier reached registration without a trade licence number.',
         jsonb_build_object('company', l.company_name, 'status', l.registration_status)
  from leads l
  where l.registration_submitted_at is not null
    and coalesce(nullif(trim(l.trade_license_no),''), null) is null
  on conflict do nothing;

  -- 2. Licence expired but still approved to receive RFQs.
  insert into brand_signal (signal_type, severity, subject_type, subject_id, rule_key, detail, evidence)
  select 'fake_supplier','critical','lead', l.id::text, 'licence_expired_but_approved',
         'Approved supplier holds an expired trade licence.',
         jsonb_build_object('company', l.company_name, 'expiry', l.license_expiry)
  from leads l
  where l.approval_status = 'approved' and l.license_expiry is not null and l.license_expiry < current_date
  on conflict do nothing;

  -- 3. Two different suppliers claiming the same trade licence number.
  insert into brand_signal (signal_type, severity, subject_type, subject_id, rule_key, detail, evidence)
  select 'fake_supplier','critical','trade_license', t.lic, 'duplicate_trade_licence',
         'The same trade licence number is claimed by more than one supplier record.',
         jsonb_build_object('licence', t.lic, 'count', t.n)
  from (
    select trim(trade_license_no) as lic, count(*) as n
    from leads where coalesce(trim(trade_license_no),'') <> ''
    group by 1 having count(*) > 1
  ) t
  on conflict do nothing;

  -- 4. Supplier name impersonating QuotesDone.
  insert into brand_signal (signal_type, severity, subject_type, subject_id, rule_key, detail, evidence)
  select 'brand_misuse','high','lead', l.id::text, 'name_impersonates_platform',
         'Supplier trading name contains the platform brand.',
         jsonb_build_object('company', l.company_name)
  from leads l
  where l.company_name ~* '(quotes ?done|quotesdone)'
  on conflict do nothing;

  -- 5. Scam RFQ: request for money, gift cards or advance payment inside a buyer brief.
  insert into brand_signal (signal_type, severity, subject_type, subject_id, rule_key, detail, evidence)
  select 'scam_rfq','high','inquiry', i.id::text, 'advance_payment_solicitation',
         'Buyer brief solicits an advance payment, gift card or wire transfer.',
         jsonb_build_object('excerpt', left(coalesce(i.raw_input,''), 240))
  from inquiries i
  where coalesce(i.raw_input,'') ~* '(gift ?card|western union|wire transfer|advance fee|upfront payment to release|crypto payment)'
  on conflict do nothing;

  -- 6. Scam RFQ: attempt to move the conversation off-platform before reveal.
  insert into brand_signal (signal_type, severity, subject_type, subject_id, rule_key, detail, evidence)
  select 'scam_rfq','medium','inquiry', i.id::text, 'off_platform_contact',
         'Buyer brief pushes contact off-platform before a paid reveal.',
         jsonb_build_object('excerpt', left(coalesce(i.raw_input,''), 240))
  from inquiries i
  where coalesce(i.raw_input,'') ~* '(whatsapp me on|call me directly on|contact me at .*@|my number is [+0-9])'
  on conflict do nothing;

  -- 7. Fake review: a supplier with a high rating and an implausible review count for its footprint.
  insert into brand_signal (signal_type, severity, subject_type, subject_id, rule_key, detail, evidence)
  select 'fake_review','medium','lead', l.id::text, 'implausible_review_profile',
         'Perfect rating with a high review count and no verifiable web presence.',
         jsonb_build_object('company', l.company_name, 'rating', l.rating, 'reviews', l.reviews)
  from leads l
  where l.rating is not null and l.rating >= 4.9 and coalesce(l.reviews,0) >= 100
    and coalesce(nullif(trim(l.website),''), null) is null
  on conflict do nothing;

  return query
    select b.rule_key, count(*)::integer
    from brand_signal b
    where b.detected_at > now() - interval '5 minutes'
    group by b.rule_key;
end; $function$


CREATE OR REPLACE FUNCTION public.fn_budget_available(p_dept text)
 RETURNS numeric
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select greatest(coalesce(monthly_aed,0) - coalesce(spent_aed,0), 0)
  from department_budget where dept_key = p_dept;
$function$


CREATE OR REPLACE FUNCTION public.fn_budget_create(p_name text, p_year integer, p_by text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare b bigint;
begin
  insert into public.budgets(name,fiscal_year,created_by) values (p_name,p_year,p_by) returning id into b;
  return b;
end $function$


CREATE OR REPLACE FUNCTION public.fn_budget_rollup()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_period text := to_char(current_date,'YYYY-MM'); n int := 0; v_degraded int := 0; v_halted int := 0; r record;
begin
  update department_budget b
     set spent_aed = coalesce(s.total,0), period_label = v_period, updated_at = now()
  from (
    select dept_key, sum(cost_aed) total
    from ai_cost_log
    where dept_key is not null and occurred_at >= date_trunc('month', now())
    group by dept_key
  ) s
  where b.dept_key = s.dept_key;
  get diagnostics n = row_count;

  for r in
    select dept_key, monthly_aed, spent_aed, degrade_at_pct, halt_at_pct,
           round(100.0*spent_aed/nullif(monthly_aed,0),1) as pct
    from department_budget
    where monthly_aed > 0 and spent_aed is not null
  loop
    if r.pct >= r.halt_at_pct then
      v_halted := v_halted + 1;
      insert into founder_alerts (level, event, detail, channel)
      select 'high','ai_budget_halt', r.dept_key||' has spent '||r.pct||'% of its monthly AI budget ('||r.spent_aed||' of '||r.monthly_aed||' AED). Halt threshold '||r.halt_at_pct||'% reached.','email'
      where not exists (select 1 from founder_alerts where event='ai_budget_halt' and detail like r.dept_key||'%' and created_at > now()-interval '24 hours');
    elsif r.pct >= r.degrade_at_pct then
      v_degraded := v_degraded + 1;
      insert into org_tasks (dept_key, title, detail, status, tier, needs_founder, action_class)
      select r.dept_key, 'AI budget degrade threshold: '||r.dept_key,
             r.dept_key||' has spent '||r.pct||'% of its monthly AI budget. Move non-critical work to the cheaper model tier and enable response caching before the halt threshold at '||r.halt_at_pct||'%.',
             'proposed','gated', false, 'recommend'
      where not exists (select 1 from org_tasks where title='AI budget degrade threshold: '||r.dept_key and status<>'done');
    end if;
  end loop;

  insert into agent_runs (agent, started_at, finished_at, status, counts, note)
  values ('budget_rollup', now(), now(), 'ok',
          jsonb_build_object('depts_updated',n,'degraded',v_degraded,'halted',v_halted),
          'AI spend rolled into department budgets: '||n||' departments, '||v_degraded||' past degrade threshold, '||v_halted||' past halt.');
  return jsonb_build_object('updated',n,'degraded',v_degraded,'halted',v_halted);
end $function$


CREATE OR REPLACE FUNCTION public.fn_budget_set(p_budget bigint, p_account text, p_month date, p_amount numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
begin
  insert into public.budget_lines(budget_id,account_code,period_month,amount)
    values (p_budget, p_account, date_trunc('month',p_month)::date, round(p_amount,2))
  on conflict (budget_id,account_code,period_month)
    do update set amount = excluded.amount;
end $function$


CREATE OR REPLACE FUNCTION public.fn_budget_set_annual(p_budget bigint, p_account text, p_amount numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare yr int; base numeric(18,2); rem numeric(18,2); mth date; i int; amt numeric(18,2);
begin
  select fiscal_year into yr from public.budgets where id=p_budget;
  if yr is null then raise exception 'budget % not found', p_budget; end if;
  base := round(round(p_amount,2)/12, 2);
  rem  := round(p_amount,2) - base*12;                 -- rounding remainder to last month
  for i in 0..11 loop
    mth := make_date(yr,1,1) + (i||' months')::interval;
    amt := base + case when i=11 then rem else 0 end;
    perform public.fn_budget_set(p_budget, p_account, mth, amt);
  end loop;
end $function$


CREATE OR REPLACE FUNCTION public.fn_bump_exam_question(p_id bigint)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  update knowledge_exam_questions set times_asked = coalesce(times_asked,0)+1, last_asked = now() where id = p_id;
$function$


CREATE OR REPLACE FUNCTION public.fn_cancel_inquiry(p_inquiry uuid, p_customer uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v inquiries%rowtype; v_paid boolean; v_cnt int; v_warned boolean:=false; v_email text;
begin
  select * into v from inquiries where id=p_inquiry;
  if not found then return jsonb_build_object('error','inquiry_not_found'); end if;
  if p_customer is not null and v.customer_id is distinct from p_customer then
    return jsonb_build_object('error','not_your_inquiry'); end if;
  if v.status='cancelled' or v.pipeline_stage='cancelled' then
    return jsonb_build_object('ok',true,'already_cancelled',true); end if;
  select exists(select 1 from transactions where inquiry_id=p_inquiry) into v_paid;
  if v_paid or v.status in ('revealed','completed') or v.pipeline_stage in ('revealed','won') then
    return jsonb_build_object('error','already_revealed',
      'message','This request already has an active revealed deal and cannot be cancelled. You can close it instead.'); end if;

  update inquiries set status='cancelled', pipeline_stage='cancelled', outcome='cancelled',
      lost_reason=coalesce(p_reason,'customer_cancelled'), completed_at=now(), stage_changed_at=now()
    where id=p_inquiry;
  insert into inquiry_cancellations(inquiry_id,customer_id,reason) values (p_inquiry, v.customer_id, p_reason);

  select count(*) into v_cnt from inquiry_cancellations where customer_id=v.customer_id and created_at > now()-interval '30 days';
  if v.customer_id is not null and v_cnt >= 3 then
    select email into v_email from customers where id=v.customer_id;
    if v_email is not null and position('@' in v_email)>1
       and not exists (select 1 from notifications where type='cancel_warning' and to_email=v_email and created_at > now()-interval '30 days') then
      insert into notifications(type,to_email,to_role,inquiry_id,subject,body,channel,status)
      values('cancel_warning', v_email, 'customer', p_inquiry,
        'A quick note about cancelled requests',
        'We noticed a few of your recent requests were cancelled. That is completely fine — but every request you post is prepared and quoted by suppliers who set aside real time for it. To keep things fair for them, we kindly ask that you post requests you intend to proceed with. If you would like help scoping a job before posting, our team is glad to assist.',
        'email','queued');
      v_warned:=true;
    end if;
  end if;
  return jsonb_build_object('ok',true,'cancelled',true,'cancellations_30d',v_cnt,'warned',v_warned);
end $function$


CREATE OR REPLACE FUNCTION public.fn_category_expert_ref(p_category text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_slug text; v_txt text;
begin
  v_slug := case
    when p_category ~* 'cctv|security|surveillance' then 'cctv-security'
    when p_category ~* 'hvac|air.?con|ac-' then 'ac-maintenance'
    when p_category ~* 'duct' then 'ac-duct-cleaning'
    when p_category ~* 'glass|glaz|alumin' then 'aluminium-glass'
    when p_category = 'carpentry' then 'carpentry-joinery'
    when p_category ~* 'joinery|kitchen' then 'joinery-kitchens'
    when p_category ~* 'tiling|tile|marble|granite' then 'tiling-marble'
    when p_category ~* 'gypsum|false.?ceiling|ceiling' then 'false-ceiling'
    when p_category ~* 'upholstery|blind|curtain' then 'curtains-blinds'
    when p_category ~* 'fit.?out' then 'commercial-retail-fitout'
    when p_category ~* 'combined.?mep|^mep$' then 'combined-mep'
    when p_category ~* 'steel|fabrication' then 'structural-steel-fabrication'
    when p_category ~* 'pest' then 'pest-control'
    when p_category ~* 'tent|shade' then 'tents-and-shade-structures'
    when p_category ~* 'general|other|handyman|facilit' then coalesce(
        (select 'general-services-other' where exists (select 1 from agent_knowledge where agent_key='cat:general-services-other')), p_category)
    else p_category end;
  select string_agg('## '||topic||E'\n'||content, E'\n\n')
    into v_txt from agent_knowledge
    where agent_key = 'cat:'||v_slug
      and topic in ('Pricing benchmarks & red flags','Quote analysis & comparison',
                    'Standards, materials & specifications','Field expertise — UAE codes, standards & specs');
  return left(coalesce(v_txt,''), 4500);
end $function$


CREATE OR REPLACE FUNCTION public.fn_category_knowledge_promote()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_slug text; v_know text; v_name text; r jsonb;
begin
  if NEW.kind='category_knowledge' and NEW.status in ('approved','done')
     and coalesce(OLD.status,'') not in ('approved','done') then
    v_slug := NEW.detail->>'slug'; v_know := NEW.detail->>'knowledge'; v_name := NEW.detail->>'name';
    if v_slug is not null and v_know is not null then
      -- publish the quoting-knowledge blob live (full parity) if not already present
      if not exists (select 1 from agent_knowledge where agent_key='cat:'||v_slug) then
        insert into agent_knowledge(agent_key,topic,content,priority,created_at,updated_at)
        values ('cat:'||v_slug, coalesce(v_name,v_slug), v_know, 100, now(), now());
      else
        update agent_knowledge set content=v_know, updated_at=now() where agent_key='cat:'||v_slug;
      end if;
      -- apply the proposed regulation -> category mapping
      for r in select * from jsonb_array_elements(coalesce(NEW.detail->'reg_matches','[]'::jsonb)) loop
        update regulations
          set categories = array(select distinct e from unnest(coalesce(categories,'{}'::text[]) || array[v_slug]) e)
          where id::text = (r->>'id') and not (v_slug = any(coalesce(categories,'{}'::text[])));
      end loop;
    end if;
  end if;
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.fn_category_sales(p_min_age_hours integer DEFAULT 24)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  rec record; v_hot int := 0; v_gap int := 0; v_cats int := 0; v_slug text; v_label text;
begin
  ---------------------------------------------------------------- HOT LEADS
  -- Quotes are in, the customer has not revealed. Every one of these is uncollected revenue.
  for rec in
    select i.id, i.category, i.emirate, count(q.id) as n_quotes, min(q.created_at) as first_quote
      from inquiries i
      join quotes q on q.inquiry_id = i.id and q.status = 'submitted'
     where not exists (select 1 from transactions tr where tr.inquiry_id = i.id and tr.revealed_at is not null)
       and coalesce(i.status,'') <> 'split'
     group by i.id, i.category, i.emirate
    having min(q.created_at) < now() - make_interval(hours => p_min_age_hours)
  loop
    v_slug := 'cat:' || lower(coalesce(nullif(trim(rec.category),''),'uncategorised'));
    v_label := coalesce(nullif(trim(rec.category),''),'Uncategorised');
    -- one open hot_lead per inquiry
    if not exists (select 1 from agent_actions
                    where kind = 'hot_lead' and target_id = rec.id::text
                      and status in ('needs_review','pending','open','proposed')) then
      insert into agent_actions(agent,kind,status,risk,title,recommendation,detail,target_table,target_id)
      values (v_slug,'hot_lead','needs_review','medium',
              'Hot lead — ' || v_label || ' / ' || coalesce(nullif(trim(rec.emirate),''),'UAE') ||
                ': ' || rec.n_quotes || ' quote(s), not revealed',
              'nudge the customer to reveal',
              jsonb_build_object('inquiry_id',rec.id,'category',rec.category,'emirate',rec.emirate,
                                 'quotes',rec.n_quotes,'waiting_since',rec.first_quote),
              'inquiries', rec.id::text);
      v_hot := v_hot + 1;
    end if;
  end loop;

  ---------------------------------------------------------------- SUPPLY GAPS
  -- Category+emirate combinations where finalized demand found nobody. Feeds supplier activation.
  for rec in
    select coalesce(nullif(trim(i.category),''),'uncategorised') as category,
           coalesce(nullif(trim(i.emirate),''),'UAE') as emirate,
           count(*) as n_inquiries
      from inquiries i
     where i.rfq_ready is true
       and coalesce(i.status,'') <> 'split'
       and not exists (select 1 from inquiry_matches m where m.inquiry_id = i.id)
       and i.created_at > now() - interval '30 days'
     group by 1,2
  loop
    v_slug := 'cat:' || lower(rec.category);
    if not exists (select 1 from agent_actions
                    where kind = 'supply_gap' and agent = v_slug
                      and detail->>'emirate' = rec.emirate
                      and status in ('needs_review','pending','open','proposed')) then
      insert into agent_actions(agent,kind,status,risk,title,recommendation,detail,target_table,target_id)
      values (v_slug,'supply_gap','needs_review','high',
              'Supply gap — ' || rec.category || ' / ' || rec.emirate || ': no suppliers matched',
              'source or activate suppliers in this category',
              jsonb_build_object('category',rec.category,'emirate',rec.emirate,'inquiries',rec.n_inquiries),
              'inquiries', null);
      v_gap := v_gap + 1;
    end if;
  end loop;

  select count(distinct coalesce(nullif(trim(category),''),'uncategorised')) into v_cats from inquiries;

  insert into agent_runs(agent,status,counts,note,started_at,finished_at)
  values ('category_sales','ok',
          jsonb_build_object('hot',v_hot,'gaps',v_gap,'categories',v_cats),
          'category sweep: ' || v_hot || ' new hot lead(s), ' || v_gap || ' new supply gap(s) across ' || v_cats || ' categories',
          now(), now());

  return json_build_object('hot',v_hot,'gaps',v_gap,'categories',v_cats);
end $function$


CREATE OR REPLACE FUNCTION public.fn_ceo_questions()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare qs text[] := array[]::text[]; n int := 0; q text;
  v_rev numeric; v_sup int; v_inq int; v_worst text; v_cost numeric; v_prev numeric;
begin
  select coalesce(sum(coalesce(reveal_fee,app_fee,0)),0) into v_rev from transactions where revealed_at > now()-interval '30 days';
  select count(*) into v_sup from leads where claimed and approval_status='approved';
  select count(*) into v_inq from inquiries where created_at > now()-interval '30 days';
  select dept_key into v_worst from org_tasks where title like 'KPI missed:%' and status<>'done'
    group by dept_key order by count(*) desc limit 1;
  select coalesce(sum(cost_aed),0) into v_cost from ai_cost_log where occurred_at > now()-interval '7 days';
  select coalesce(sum(cost_aed),0) into v_prev from ai_cost_log where occurred_at between now()-interval '14 days' and now()-interval '7 days';

  if v_rev = 0 then
    qs := array_append(qs, 'Why are we not growing? Revenue is zero over 30 days with '||v_sup||' onboarded suppliers and '||v_inq||' inquiries. What is the single binding constraint, and what would remove it?');
  end if;
  if v_sup = 0 then
    qs := array_append(qs, 'We have 86 fully briefed category experts and no onboarded suppliers. Are we building capability ahead of demand, and is that still the right sequence?');
  end if;
  if v_worst is not null then
    qs := array_append(qs, 'Why is '||v_worst||' missing more targets than any other department this week? Is it capability, capacity, or a target that was never realistic?');
  end if;
  if v_prev > 0 and v_cost > v_prev * 1.25 then
    qs := array_append(qs, 'AI cost rose from '||round(v_prev,2)||' to '||round(v_cost,2)||' AED week on week. What drove it and did it buy anything?');
  end if;
  qs := array_append(qs, 'Which workflow wastes the most employee time, and what would automating it be worth?');
  qs := array_append(qs, 'Which department produced the highest return on its AI spend this month, and what are the others not copying?');
  qs := array_append(qs, 'What are we doing today only because we have always done it?');

  foreach q in array qs loop
    insert into org_tasks (dept_key,title,detail,status,tier,needs_founder,action_class)
    select 'exec','CEO question: '||left(q,80),
           q||E'\n\nAnswer with evidence from company data, not opinion. If the answer implies a change, open it as an initiative with a named metric and a baseline so it can be graded.',
           'proposed','advisory',false,'recommend'
    where not exists (select 1 from org_tasks where title='CEO question: '||left(q,80) and status<>'done');
    if found then n := n + 1; end if;
  end loop;

  insert into agent_runs (agent,started_at,finished_at,status,counts,note)
  values ('ceo_questions',now(),now(),'ok',jsonb_build_object('asked',n),
          'CEO self-questioning: '||n||' strategic question(s) raised from live company data.');
  return jsonb_build_object('asked',n);
end $function$


CREATE OR REPLACE FUNCTION public.fn_challenge(p_proposal text, p_proposed_by text DEFAULT 'founder'::text, p_challenger text DEFAULT 'brief'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  h record; v_id bigint; v_stance text := 'support'; v_conf numeric := 0.5;
  v_reason text := ''; v_alts jsonb := '[]'::jsonb; v_evidence jsonb := '[]'::jsonb;
  v_rank int; v_principle text; v_weight int := 0;
  v_prior record; v_supply int; v_rev numeric;
begin
  for h in select * from challenge_heuristic where active and p_proposal ~* pattern order by rank_touched limit 3
  loop
    -- a rank-1 conflict is severe on its own; lower ranks accumulate
    v_weight := v_weight + case h.rank_touched when 1 then 3 when 2 then 2 else 1 end;
    if v_rank is null or h.rank_touched < v_rank then v_rank := h.rank_touched; v_principle := h.principle; end if;
    v_reason := v_reason || case when v_reason='' then '' else ' ' end || h.concern;
    if h.alternative is not null then v_alts := v_alts || jsonb_build_array(h.alternative); end if;
  end loop;

  for v_prior in
    select headline, detail, outcome from institutional_memory
     where outcome in ('worse','improved')
       and p_proposal ~* coalesce(substring(headline from '\w+'),'zzzz')
     order by created_at desc limit 3
  loop
    v_evidence := v_evidence || jsonb_build_array(jsonb_build_object(
      'type','prior_outcome','verdict',v_prior.outcome,'lesson',left(v_prior.detail,240)));
    if v_prior.outcome='worse' then v_weight := v_weight + 3; end if;
  end loop;

  select count(*) into v_supply from leads where approval_status='approved';
  select coalesce(sum(coalesce(reveal_fee,app_fee,0)),0) into v_rev
    from transactions where revealed_at > now()-interval '30 days';
  v_evidence := v_evidence || jsonb_build_array(jsonb_build_object(
    'type','current_state','onboarded_suppliers',v_supply,'revenue_30d_aed',v_rev,
    'note', case when v_supply=0
      then 'The marketplace has no onboarded supply, so any demand-side or pricing change cannot be validated against real behaviour yet.'
      else 'Supply exists; effects are measurable.' end));

  if v_supply=0 and p_proposal ~* '(fee|price|commission|campaign|customer|demand)' then
    v_weight := v_weight + 1;
    v_reason := v_reason || ' There is also no onboarded supply to measure the effect against, so the change would be unfalsifiable at the moment it is made.';
  end if;

  if v_weight >= 3 then v_stance := 'recommend_against'; v_conf := least(0.95, 0.60 + v_weight*0.05);
  elsif v_weight >= 1 then v_stance := 'concern'; v_conf := 0.65;
  else v_stance := 'support'; v_conf := 0.6;
       v_reason := 'No conflict with the priority hierarchy, no contrary prior outcome on record, and current state does not argue against it.';
  end if;

  if v_alts='[]'::jsonb and v_stance<>'support' then
    v_alts := jsonb_build_array('Run it as a bounded test with a named metric and a captured baseline, so it can be graded and reversed.');
  end if;

  insert into challenge_record (proposal,proposed_by,challenged_by,stance,confidence,reasoning,
                                violates_rank,violates_principle,evidence,alternatives)
  values (p_proposal,p_proposed_by,p_challenger,v_stance,v_conf,v_reason,v_rank,v_principle,v_evidence,v_alts)
  returning id into v_id;

  return jsonb_build_object('id',v_id,'stance',v_stance,'confidence',v_conf,
    'conflicts_with', case when v_principle is null then null else 'Rank '||v_rank||' — '||v_principle end,
    'reasoning',v_reason,'evidence',v_evidence,'alternatives',v_alts);
end $function$


CREATE OR REPLACE FUNCTION public.fn_check_licence_activity(p_subject_id text, p_content text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_lead leads%rowtype; v_cat text; v_rx text; v_note text;
begin
  begin
    select * into v_lead from leads where id = p_subject_id::bigint;
  exception when others then
    return jsonb_build_object('passed', false, 'detail', 'subject_id "' || p_subject_id || '" is not a lead id, so the licence activity cannot be checked');
  end;
  if v_lead.id is null then
    return jsonb_build_object('passed', false, 'detail', 'no lead ' || p_subject_id);
  end if;

  v_cat := (select unnest from unnest(v_lead.invite_trades) limit 1);
  if v_cat is null then
    return jsonb_build_object('passed', false, 'detail', 'supplier has declared no category, so no licence activity can be matched against it');
  end if;

  select activity_regex, note into v_rx, v_note from category_licence_activity where catalog_slug = v_cat;
  if v_rx is null then
    return jsonb_build_object('passed', false,
      'detail', 'no licence-activity rule recorded for category "' || v_cat || '" - cannot verify cover, so this application must be reviewed by a person');
  end if;

  if coalesce(trim(v_lead.license_activity), '') = '' then
    return jsonb_build_object('passed', false,
      'detail', 'trade licence activity was never captured for this supplier - request the licence and record its activity before approving');
  end if;

  if v_lead.license_activity ~ v_rx then
    return jsonb_build_object('passed', true,
      'detail', 'licence activity "' || v_lead.license_activity || '" covers ' || v_cat || coalesce('. ' || v_note, ''));
  end if;

  return jsonb_build_object('passed', false,
    'detail', 'MISMATCH: licence activity "' || v_lead.license_activity || '" does not cover the category applied for ("' || v_cat || '"). Request a licence whose activity includes that trade, or an amendment adding it.');
end; $function$


CREATE OR REPLACE FUNCTION public.fn_check_licence_expiry(p_subject_id text, p_content text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_exp date; v_no text;
begin
  begin
    select license_expiry, trade_license_no into v_exp, v_no from leads where id = p_subject_id::bigint;
  exception when others then
    return jsonb_build_object('passed', false, 'detail', 'subject_id is not a lead id');
  end;
  if coalesce(trim(v_no),'') = '' then
    return jsonb_build_object('passed', false, 'detail', 'no trade licence number recorded');
  end if;
  if v_exp is null then
    return jsonb_build_object('passed', false, 'detail', 'licence expiry date not recorded');
  end if;
  if v_exp < current_date then
    return jsonb_build_object('passed', false, 'detail', 'trade licence expired on ' || v_exp);
  end if;
  return jsonb_build_object('passed', true, 'detail', 'licence ' || v_no || ' valid to ' || v_exp);
end; $function$


CREATE OR REPLACE FUNCTION public.fn_check_spend(p_dept text, p_amount numeric, p_agent text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_avail numeric; v_month numeric; v_limit numeric; v_route text; v_afford boolean;
begin
  select coalesce(monthly_aed,0), fn_budget_available(p_dept) into v_month, v_avail
  from department_budget where dept_key = p_dept;

  if v_month is null then
    return jsonb_build_object('ok', false, 'reason',
      'no budget is recorded for department "' || p_dept || '", so no spend can be authorised against it',
      'route_to','finance');
  end if;

  v_afford := coalesce(p_amount,0) <= v_avail;

  select max(threshold_aed) into v_limit
  from employee_authority where agent_key = p_agent;

  v_route := case
    when coalesce(p_amount,0) >  10000 then 'founder'
    when coalesce(p_amount,0) >= 1000  then 'brief'
    else coalesce(p_agent,'department head') end;

  return jsonb_build_object(
    'ok', v_afford and (v_limit is null or coalesce(p_amount,0) <= v_limit),
    'affordable', v_afford,
    'requested_aed', coalesce(p_amount,0),
    'available_aed', v_avail,
    'monthly_aed', v_month,
    'agent_limit_aed', v_limit,
    'route_to', v_route,
    'reason', case
      when not v_afford then format('Requested AED %s exceeds the AED %s remaining in the %s budget this period. Reduce the scope, defer to next period, or ask Finance to reallocate.', coalesce(p_amount,0), v_avail, p_dept)
      when v_limit is not null and coalesce(p_amount,0) > v_limit then format('Affordable, but AED %s is above %s''s personal limit of AED %s. Route to %s.', coalesce(p_amount,0), p_agent, v_limit, v_route)
      else format('Within budget: AED %s of AED %s available. Approver: %s.', coalesce(p_amount,0), v_avail, v_route) end);
end; $function$


CREATE OR REPLACE FUNCTION public.fn_chief_of_staff()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare disp jsonb; exec jsonb; health jsonb; ops jsonb; rev jsonb;
  n_pending int; n_aging int; n_depts int; brief text; recs text; dept_txt text; esc_txt text; owner text;
  prioritized jsonb; run_id bigint;
begin
  disp := public.fn_autonomy_dispose();
  exec := public.fn_ws_exec();
  health := exec->'command'->'health'; ops := exec->'command'->'ops'; rev := ops->'revenue';

  select count(*) into n_pending from public.agent_actions where status in ('pending','held_for_review','proposed','open','needs_review');
  select count(*) into n_aging from public.agent_actions
    where status in ('pending','held_for_review','proposed','open','needs_review') and created_at < now()-interval '3 days';
  select count(distinct agent) into n_depts from public.agent_runs where started_at > now()-interval '24 hours';

  select string_agg(line, E'\n' order by line) into dept_txt from (
    select '- '||agent||': '||count(*)||' runs'||
           case when count(*) filter (where status='error')>0 then ' ('||count(*) filter (where status='error')||' failed)' else '' end as line
    from public.agent_runs where started_at > now()-interval '24 hours' group by agent
  ) d;

  select string_agg('- ['||coalesce(risk,'?')||'] '||coalesce(title,kind)||' ('||agent||')', E'\n') into esc_txt from (
    select agent,risk,title,kind from public.agent_actions
     where status in ('pending','held_for_review','proposed','open','needs_review') order by created_at asc limit 10
  ) e;

  select coalesce(jsonb_agg(x order by cat asc),'[]'::jsonb) into prioritized from (
    select jsonb_build_object('id',id,'agent',agent,'risk',risk,'title',title,
             'age_days',round(extract(epoch from (now()-created_at))/86400)) x, created_at cat
    from public.agent_actions where status in ('pending','held_for_review','proposed','open','needs_review')
    order by created_at asc limit 15
  ) s;

  recs := '';
  if n_pending>0 then recs := recs||'1) '||n_pending||' item(s) in your queue (payments, deletions, flagged suppliers, marketing to post, BD to enable, to-dos).'||E'\n'; end if;
  if n_aging>0 then recs := recs||'2) '||n_aging||' waited >3 days — action or dismiss.'||E'\n'; end if;
  if (health->>'band') is not null and lower(health->>'band')<>'good'
     then recs := recs||'3) Health "'||(health->>'band')||'" ('||coalesce(health->>'index','?')||'/100).'||E'\n'; end if;
  if recs='' then recs := 'Queue clear. Everything auto-handled where safe.'; end if;

  brief := 'Chief of Staff — daily briefing ('||to_char(now(),'DD Mon YYYY')||')'||E'\n\n'
    ||'HEADLINE: auto-approved '||coalesce(disp->>'approved_suppliers','0')||' clean supplier(s), auto-cleared '
      ||coalesce(disp->>'auto_cleared_logged','0')||' logged alert(s). '||n_pending||' item(s) in your queue. Health '
      ||coalesce(health->>'index','?')||'/100 ('||coalesce(health->>'band','?')||').'||E'\n\n'
    ||'YOUR QUEUE:'||E'\n'||coalesce(esc_txt,'- Empty.')||E'\n\n'
    ||'DEPARTMENTS (24h):'||E'\n'||coalesce(dept_txt,'- No agent runs in the last 24h.')||E'\n\n'
    ||'KPIs: revenue month '||coalesce(rev->>'month_aed','0')||' AED, cash received '||coalesce(rev->>'cash_received_aed','0')
      ||' AED, pending fees '||coalesce(rev->>'pending_fees_aed','0')||' AED, active RFQs '||coalesce(ops->'marketplace'->>'active_rfqs','0')||'.'||E'\n\n'
    ||'RECOMMENDATIONS:'||E'\n'||recs;

  insert into public.agent_runs(agent,started_at,finished_at,status,counts,note)
    values('chief_of_staff',now(),now(),'ok',
      jsonb_build_object('approved_suppliers',disp->>'approved_suppliers','auto_cleared',disp->>'auto_cleared_logged',
        'in_queue',n_pending,'aging',n_aging,'departments',n_depts),'coordination + autonomy v2')
    returning id into run_id;

  insert into public.agent_actions(agent,kind,status,risk,title,recommendation,target_table,target_id,detail)
    values('chief_of_staff','exec_briefing','auto_done','low',
      'Chief of Staff briefing — '||n_pending||' in queue, '||coalesce(disp->>'auto_cleared_logged','0')||' auto-cleared',
      'Informational.', null, null,
      jsonb_build_object('briefing',brief,'prioritized',prioritized,'autonomy',disp,'health',health->>'index','in_queue',n_pending));

  select split_part(coalesce(value,'management@quotesdone.com'),',',1) into owner from public.app_secrets where key='admin_emails';
  owner := coalesce(nullif(trim(owner),''),'management@quotesdone.com');
  insert into public.notifications(type,to_email,to_role,channel,subject,body)
    values('chief_of_staff', owner, 'admin','email',
      'Chief of Staff — '||n_pending||' in your queue, health '||coalesce(health->>'index','?')||'/100', brief);

  return jsonb_build_object('ok',true,'autonomy',disp,'in_queue',n_pending,'aging',n_aging,'departments',n_depts,'run_id',run_id);
end $function$


CREATE OR REPLACE FUNCTION public.fn_collections()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_run bigint; v_reminded int:=0; r record;
begin
  insert into agent_runs(agent, started_at) values ('collections', now()) returning id into v_run;
  -- NO commission is charged on won jobs (founder policy: zero commission). This engine never creates dues.
  -- The only supplier charge is the non-response fine (= the refunded reveal fee), created by qd_on_refund_resolved,
  -- and enforced by a matching block until settled. Here we only send a gentle reminder; no extra fees are added.
  for r in select d.*, l.claimed_by, l.email as lead_email, l.company_name
           from supplier_dues d join leads l on l.id=d.supplier_id
           where d.status in ('due','pending','reminded')
             and (d.last_reminder_at is null or d.last_reminder_at < now()-interval '4 days')
             and d.reminders < 3
  loop
    update supplier_dues set status='reminded', reminders=reminders+1, last_reminder_at=now() where id=r.id;
    insert into notifications(type,to_email,to_role,channel,status,lead_id,subject,body)
      values ('nonresponse_reminder', coalesce(r.claimed_by,r.lead_email), 'supplier', 'portal', 'portal', r.supplier_id,
        'Reminder: outstanding non-response charge',
        'Reminder: a non-response charge of AED '||round(r.amount_due)||' is outstanding on your account. This equals the reveal fee that was refunded to a customer because a paid reveal was not responded to. Please settle it on the portal to lift the hold on new matches. QuotesDone charges no commission on won jobs.');
    v_reminded := v_reminded + 1;
  end loop;
  update agent_runs set finished_at=now(), status='ok', counts=jsonb_build_object('reminders',v_reminded,'commission_charged',0) where id=v_run;
end;$function$


CREATE OR REPLACE FUNCTION public.fn_company_brief(p_max_chars integer DEFAULT 1600)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare s jsonb; out text; d jsonb;
begin
  s := fn_company_state();
  out := 'COMPANY SELF-KNOWLEDGE (authoritative org facts — you may answer any question about the company from this):'||E'\n'
       ||'Vision: '||(s->>'vision')||E'\n'
       ||'Totals: '||(s->'totals'->>'departments')||' departments, '||(s->'totals'->>'brain_agents')||' brain agents, '
       ||(s->'totals'->>'category_sales_agents')||' category sales agents, '||(s->'totals'->>'tools_wired')||' wired tools, '
       ||(s->'totals'->>'open_objectives')||' open objectives, '||(s->'totals'->>'open_tasks')||' open tasks.'||E'\n'
       ||'Departments (lead · brain agents · north star):'||E'\n';
  for d in select * from jsonb_array_elements(s->'departments') loop
    out := out || '- '||(d->>'name')||' ['||(d->>'dept')||']: lead '||coalesce(d->>'lead_agent','—')
                || ', '||(d->>'headcount')||' agent(s)';
    if jsonb_array_length(d->'brain_agents') > 0 then
      out := out || ' ('||replace(replace(replace((d->'brain_agents')::text,'"',''),'[',''),']','')||')';
    end if;
    out := out || ', north star: '||coalesce(d->>'north_star','—')||E'\n';
    exit when length(out) > p_max_chars;
  end loop;
  return left(out, greatest(p_max_chars, 400));
end $function$


CREATE OR REPLACE FUNCTION public.fn_company_facts_sync()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare c record; pct text; capnote text; txt text; regline text;
begin
  select * into c from pricing_config where id=1; if c is null then return; end if;

  pct := trim(to_char(coalesce(c.standard_reveal_rate,0)*100,'FM990.##'))||'%';
  capnote := case when coalesce(c.standard_reveal_cap,0) >= 1000000
                  then 'no cap'
                  else 'capped at '||coalesce(c.reveal_currency,'AED')||' '||trim(to_char(c.standard_reveal_cap,'FM999999990')) end;

  -- The registration sentence is DERIVED, including the date. A generator that silently omits the
  -- start date produces a row that reads as "charged today" to every agent that retrieves it.
  if c.supplier_charging_starts is null then
    regline := 'Supplier registration: the annual subscription START DATE IS NOT SET in pricing_config — '
            || 'do NOT state when the fee begins; say the founder must confirm it. ';
  else
    regline := 'Supplier registration is FREE for EVERY supplier until '
            || to_char(c.supplier_charging_starts - 1, 'FMDD FMMonth YYYY') || '. '
            || 'From ' || to_char(c.supplier_charging_starts, 'FMDD FMMonth YYYY') || ' a '
            || coalesce(c.supplier_reg_period,'yearly') || ' subscription of '
            || coalesce(c.supplier_reg_currency,'AED') || ' '
            || trim(to_char(c.supplier_reg_fee,'FM999,999,990.##')) || ' applies, and it is NOT charged '
            || 'before that date. The first ' || c.supplier_free_count || ' businesses to register are '
            || 'exempt PERMANENTLY and never pay it — that exemption does not expire. ';
  end if;

  txt := 'PRICING & FEES — LIVE, AUTO-SYNCED FROM pricing_config (authoritative; OVERRIDES any pricing figure stated elsewhere). '
    ||'Customer REVEAL FEE: '||pct||' of the accepted quotation value ('||capnote||'), paid by the customer to unlock their chosen supplier. '
    ||'Suppliers pay NO commission on won jobs. '
    ||regline
    ||'Non-response window: '||c.refund_window_working_days||' working days — if a revealed supplier does not respond in that window and cannot be reached, the customer reveal fee is refunded and the supplier is charged a non-response fee equal to that reveal fee and blocked from matching until paid. '
    ||'There is NO 2% fee and NO supplier commission — never quote those. (Auto-updated '||to_char(now(),'YYYY-MM-DD HH24:MI')||' UTC.)';

  update agent_knowledge set content=txt, priority=100, updated_at=now()
    where agent_key='_global' and topic='Pricing & fees (LIVE — auto-synced)';
  if not found then
    insert into agent_knowledge(agent_key,topic,content,priority,updated_at)
      values ('_global','Pricing & fees (LIVE — auto-synced)',txt,100,now());
  end if;
end $function$


CREATE OR REPLACE FUNCTION public.fn_company_faq_sync()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_body text; n int;
begin
  select count(*) into n from company_faq where status='approved';
  select 'QUOTESDONE COMPANY FAQ — canonical answers every agent must use verbatim-in-spirit (founder-approved). '||
         'If asked anything here, answer consistently with this. Do not contradict it or invent beyond it.'||E'\n\n'||
         coalesce(string_agg(
           '## ['||section||'] '||question||E'\n'||coalesce(answer,'(no answer yet)')||
           case when audience<>'all' then E'\n(Audience: '||audience||')' else '' end,
           E'\n\n' order by section, sort, id), '')
    into v_body
  from company_faq where status='approved';

  if n=0 then
    delete from agent_knowledge where agent_key='_global' and topic='Company FAQ (canonical answers)';
    return jsonb_build_object('synced',0);
  end if;
  if exists(select 1 from agent_knowledge where agent_key='_global' and topic='Company FAQ (canonical answers)') then
    update agent_knowledge set content=v_body, updated_at=now()
      where agent_key='_global' and topic='Company FAQ (canonical answers)';
  else
    insert into agent_knowledge(agent_key,topic,content,priority,created_at,updated_at)
      values('_global','Company FAQ (canonical answers)', v_body, 96, now(), now());
  end if;
  return jsonb_build_object('synced', n);
end $function$


CREATE OR REPLACE FUNCTION public.fn_company_indices()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  d_auto numeric; d_know numeric; d_dec numeric; d_fin numeric; d_cust numeric;
  d_supp numeric; d_sec numeric; d_res numeric; d_inno numeric; d_strat numeric; v_mat numeric;
  e_vel numeric; e_backlog numeric; e_collab numeric; e_knowcreate numeric; e_autorate numeric; v_energy numeric;
  m_quality numeric; m_speed numeric; m_completion numeric; m_fraud numeric; m_conf numeric; v_mh numeric;
  v_kpis int; v_gaps int;
begin
  select coalesce(100 - round(100.0*count(*) filter (where needs_founder)/nullif(count(*),0),1),100)
    into d_auto from org_tasks where status<>'done';
  select coalesce(round(100.0*count(*) filter (where validation_status not in ('unvalidated','unreviewed'))/nullif(count(*),0),1),0)
    into d_know from agent_knowledge;
  select coalesce(round(100.0*count(*) filter (where verdict='improved')
           /nullif(count(*) filter (where verdict in ('improved','no_change','worse')),0),1),50)
    into d_dec from outcome_record;
  select case when coalesce(sum(coalesce(reveal_fee,app_fee,0)),0) > 0 then 60 else 10 end
    into d_fin from transactions where revealed_at > now()-interval '90 days';
  select case when count(*) > 0 then 50 else 10 end into d_cust from customers;
  select least(100, round(100.0*(select count(*) from v_supply_gap where approved>=10)/86.0,1)) into d_supp;
  select coalesce(round(100.0*count(*) filter (where ok)/nullif(count(*),0),1),50)
    into d_sec from health_checks where check_kind='http' and created_at > now()-interval '7 days';
  select round(100.0*count(*) filter (where last_tested is not null)/nullif(count(*),0),1)
    into d_res from continuity_plan;
  select least(100,(select count(*) from evolution_proposal)*5) into d_inno;
  select count(*) into v_kpis from employee_kpi where active;
  select count(*) into v_gaps from org_tasks where title like 'KPI missed:%' and status<>'done';
  d_strat := greatest(0, round(100.0 - 100.0*v_gaps/nullif(v_kpis,0), 1));

  v_mat := round((d_auto+d_know+d_dec+d_fin+d_cust+d_supp+d_sec+d_res+d_inno+d_strat)/10.0,1);
  insert into company_index (measured_on,index_name,dimensions,score,band)
  values (current_date,'company_maturity',
    jsonb_build_object('automation',d_auto,'knowledge_quality',d_know,'decision_accuracy',d_dec,
      'financial_health',d_fin,'customer_trust',d_cust,'supplier_ecosystem',d_supp,'security',d_sec,
      'operational_resilience',d_res,'innovation',d_inno,'strategic_execution',d_strat), v_mat,
    case when v_mat>=80 then 'mature' when v_mat>=60 then 'developing' when v_mat>=40 then 'early' else 'nascent' end)
  on conflict (measured_on,index_name) do update set dimensions=excluded.dimensions, score=excluded.score, band=excluded.band;

  select count(*) into e_vel from decision_log where created_at > now()-interval '7 days';
  select coalesce(round(100.0 - 100.0*count(*) filter (where created_at < now()-interval '14 days')/nullif(count(*),0),1),100)
    into e_backlog from org_tasks where status<>'done';
  select coalesce(round(100.0*count(*) filter (where decision='approve')/nullif(count(*),0),1),50)
    into e_collab from review_chain where created_at > now()-interval '30 days';
  select least(100,count(*)) into e_knowcreate from agent_knowledge where updated_at > now()-interval '7 days';
  e_autorate := d_auto;
  v_energy := round((least(100,e_vel)+e_backlog+e_collab+e_knowcreate+e_autorate)/5.0,1);
  insert into company_index (measured_on,index_name,dimensions,score,band)
  values (current_date,'organizational_energy',
    jsonb_build_object('decision_velocity_7d',e_vel,'backlog_freshness',e_backlog,
      'collaboration_efficiency',e_collab,'knowledge_creation_7d',e_knowcreate,'automation_rate',e_autorate),
    v_energy, case when v_energy>=75 then 'high' when v_energy>=50 then 'steady' else 'slowing' end)
  on conflict (measured_on,index_name) do update set dimensions=excluded.dimensions, score=excluded.score, band=excluded.band;

  select coalesce(round(avg(reliability),1),0) into m_quality from supplier_score where reliability is not null;
  select coalesce(round(100.0*count(*) filter (where sent_at is not null and sent_at-created_at < interval '24 hours')
           /nullif(count(*),0),1),0) into m_speed from notifications where created_at > now()-interval '30 days';
  select coalesce(round(100.0*count(*) filter (where exists(select 1 from quotes q where q.inquiry_id=i.id))
           /nullif(count(*),0),1),0) into m_completion from inquiries i where i.created_at > now()-interval '30 days';
  select coalesce(100 - least(100,count(*)*5),100) into m_fraud from fraud_flags;
  select coalesce(round(avg(confidence)*100,1),50) into m_conf from decision_log where confidence is not null;
  v_mh := round((m_quality+m_speed+coalesce(m_completion,0)+m_fraud+m_conf)/5.0,1);
  insert into company_index (measured_on,index_name,dimensions,score,band)
  values (current_date,'marketplace_health',
    jsonb_build_object('supplier_quality',m_quality,'quote_speed',m_speed,'rfq_completion',m_completion,
      'fraud_clean',m_fraud,'ai_confidence',m_conf), v_mh,
    case when v_mh>=75 then 'healthy' when v_mh>=50 then 'fragile' else 'unhealthy' end)
  on conflict (measured_on,index_name) do update set dimensions=excluded.dimensions, score=excluded.score, band=excluded.band;

  insert into agent_runs (agent,started_at,finished_at,status,counts,note)
  values ('company_indices',now(),now(),'ok',
    jsonb_build_object('maturity',v_mat,'energy',v_energy,'marketplace_health',v_mh),
    'Company indices: maturity '||v_mat||', energy '||v_energy||', marketplace health '||v_mh||'.');
  return jsonb_build_object('maturity',v_mat,'energy',v_energy,'marketplace_health',v_mh);
end $function$


CREATE OR REPLACE FUNCTION public.fn_company_reflect()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare a jsonb; n_concern int := 0; n_act int := 0;
  v_learned int; v_errors int; v_wrong int; v_dept text; v_improved text;
  v_stale int; v_missed int; v_comp int; v_worst text;
begin
  select count(*) into v_learned from institutional_memory where created_at > now()-interval '24 hours';
  select count(*) into v_errors  from agent_runs where status='error' and started_at > now()-interval '24 hours';
  select count(*) into v_wrong   from outcome_record where verdict='worse' and closed_at > now()-interval '24 hours';
  select dept_key into v_dept from org_tasks where status<>'done' group by dept_key order by count(*) desc limit 1;
  select string_agg(actor,', ') into v_improved from (
    select distinct actor from outcome_record where verdict='improved' and closed_at > now()-interval '7 days' limit 3) x;
  select count(*) into v_stale from agent_knowledge where validation_status in ('stale','quarantined');
  select count(*) into v_missed from v_supply_gap where status='READY - not yet invited';
  select count(*) into v_comp from competitor;
  select name into v_worst from v_supply_gap where status like 'NO POOL%' limit 1;

  a := jsonb_build_object(
    'what_did_i_learn', v_learned||' lesson(s) entered institutional memory in the last 24 hours.',
    'what_mistakes_did_i_make', v_errors||' agent run(s) errored.',
    'which_decisions_were_wrong', v_wrong||' graded improvement(s) made things worse and were flagged for reversal.',
    'which_departments_are_struggling', coalesce('Heaviest open backlog: '||v_dept,'No department is carrying an unusual backlog.'),
    'which_employees_improved', coalesce('Improvements that worked came from: '||v_improved,'No graded improvement has closed successfully yet.'),
    'which_knowledge_became_outdated', v_stale||' knowledge item(s) are stale or quarantined.',
    'which_opportunities_did_i_miss', v_missed||' category/categories have a viable supplier pool and no invitations sent.',
    'which_competitor_became_stronger', v_comp||' competitor(s) tracked but 0 market signals captured, so this cannot be answered honestly yet.',
    'how_can_i_be_better_tomorrow', coalesce('Close the supply gap starting with '||v_worst,'Close the open KPI gaps before taking on new work.'));

  if v_errors > 10 then n_concern := n_concern + 1; end if;
  if v_wrong  > 0  then n_concern := n_concern + 1; end if;
  if v_stale  > 50 then n_concern := n_concern + 1; end if;

  if v_missed > 0 then
    insert into org_tasks (dept_key,title,detail,status,tier,needs_founder,action_class)
    select 'procurement','Nightly reflection: '||v_missed||' category(ies) ready but uninvited',
      'The company noticed overnight that '||v_missed||' category(ies) hold a viable supplier pool with no invitations sent. Queue them, or record why not.',
      'proposed','advisory',false,'invite'
    where not exists (select 1 from org_tasks where title like 'Nightly reflection: % ready but uninvited' and status<>'done');
    if found then n_act := n_act + 1; end if;
  end if;

  insert into company_reflection (reflected_on,answers,concerns,actions)
  values (current_date,a,n_concern,n_act)
  on conflict (reflected_on) do update set answers=excluded.answers, concerns=excluded.concerns, actions=excluded.actions;

  insert into agent_runs (agent,started_at,finished_at,status,counts,note)
  values ('company_reflect',now(),now(),'ok',jsonb_build_object('concerns',n_concern,'actions',n_act),
    'Nightly self-reflection: '||n_concern||' concern(s), '||n_act||' action(s) opened. Nobody asked for this.');
  return jsonb_build_object('concerns',n_concern,'actions',n_act,'answers',a);
end $function$


CREATE OR REPLACE FUNCTION public.fn_company_situation()
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v text;
begin
  select concat_ws(E'\n',
    'COMPANY SITUATION as at ' || to_char(now(), 'YYYY-MM-DD HH24:MI') || ' UTC. Computed from live rows and shared by every department - do not re-derive it.',
    '',
    'MARKETPLACE STATE',
    (select string_agg('- ' || label || ': ' || coalesce(value::text,'unmeasured')
              || case when target is not null then ' (target ' || target || ', ' || state || ')' else '' end, E'\n' order by domain, label)
     from v_bi_scorecard),
    '',
    'CATEGORY COVERAGE',
    (select '- ' || count(*) filter (where coverage='COMPLIANT') || ' of ' || count(*)
            || ' catalogue categories have an employee at the full 14-module standard; '
            || count(*) filter (where coverage='NO_AGENT') || ' have no employee at all.'
     from v_category_coverage),
    '',
    'RESOURCE PRESSURE',
    (select coalesce(string_agg('- ' || resource || ': ' || state || ' (' || coalesce(used_pct::text,'0') || '% of ' || capacity || ' ' || unit || ')', E'\n' order by resource)
            filter (where state <> 'OK'), '- All pools within limits.')
     from v_resource_pressure),
    '',
    'OPEN RISKS AND SELF-DETECTED DEFECTS',
    (select '- ' || count(*) || ' proposals open from the self-evolution scan; '
            || (select count(*) from risk_register where coalesce(status,'open') = 'open') || ' open risks on the register.'
     from evolution_proposal where status = 'proposed'),
    '',
    'ECONOMIC REALITY',
    (select '- ' || state || '. Reveal rate ' || (reveal_rate*100) || '%, ' || leads_total || ' leads in pipeline, '
            || verified_suppliers || ' verified, ' || inquiries_total || ' inquiries ever, ' || reveals_total || ' reveals ever.'
     from v_unit_economics)
  ) into v;
  return v;
end; $function$


CREATE OR REPLACE FUNCTION public.fn_company_snapshot()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare s jsonb;
begin
  s := jsonb_build_object(
    'employees',        (select count(*) from org_agents where active),
    'departments',      (select count(*) from org_departments where active),
    'operating_systems',(select count(*) from operating_system where active),
    'kpis',             (select count(*) from employee_kpi where active),
    'kpis_measurable',  (select count(*) from employee_kpi where active and measure_sql is not null),
    'kpi_gaps_open',    (select count(*) from org_tasks where title like 'KPI missed:%' and status<>'done'),
    'open_tasks',       (select count(*) from org_tasks where status<>'done'),
    'needs_founder',    (select count(*) from org_tasks where status<>'done' and needs_founder),
    'approved_suppliers',(select count(*) from leads where approval_status='approved'),
    'sendable_pool',    (select coalesce(sum(sendable),0) from v_supply_gap),
    'categories_at_target',(select count(*) from v_supply_gap where approved>=10),
    'revenue_30d_aed',  (select coalesce(sum(coalesce(reveal_fee,app_fee,0)),0) from transactions where revealed_at>now()-interval '30 days'),
    'ai_cost_30d_aed',  (select round(coalesce(sum(cost_aed),0),2) from ai_cost_log where occurred_at>now()-interval '30 days'),
    'knowledge_items',  (select count(*) from agent_knowledge),
    'knowledge_quarantined',(select count(*) from agent_knowledge where validation_status='quarantined'),
    'outcomes_pending', (select count(*) from outcome_record where verdict='pending'),
    'outcomes_improved',(select count(*) from outcome_record where verdict='improved'),
    'decisions_7d',     (select count(*) from decision_log where created_at>now()-interval '7 days'),
    'agent_runs_7d',    (select count(*) from agent_runs where started_at>now()-interval '7 days'),
    'error_rate_7d',    (select round(100.0*count(*) filter (where status='error')/nullif(count(*),0),2) from agent_runs where started_at>now()-interval '7 days'),
    'os_health',        (select jsonb_object_agg(os_key,health) from os_review where period=to_char(now(),'IYYY-"W"IW')),
    'indices',          (select jsonb_object_agg(index_name,score) from company_index where measured_on=current_date),
    'autonomy_enabled', (select value from app_secrets where key='agent_autonomy_enabled'),
    'invite_enabled',   (select value from app_secrets where key='invite_enabled'));

  insert into company_snapshot (snapshot_on, state) values (current_date, s)
  on conflict (snapshot_on) do update set state=excluded.state, created_at=now();

  insert into agent_runs (agent,started_at,finished_at,status,counts,note)
  values ('company_snapshot',now(),now(),'ok',jsonb_build_object('keys',(select count(*) from jsonb_object_keys(s))),
    'Company state snapshotted for '||current_date||'. Any past day can now be reconstructed.');
  return s;
end $function$


CREATE OR REPLACE FUNCTION public.fn_company_state()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with depts as (
    select d.dept_key, d.name, d.charter, d.north_star, d.lead_agent, d.active,
           coalesce((select array_agg(a.agent_key order by a.agent_key) from org_agents a where a.department=d.dept_key and a.active), '{}') as brain_agents,
           (select count(*) from org_agents a where a.department=d.dept_key and a.active) as brain_count,
           (select count(*) from org_action_executor e where e.department=d.dept_key and e.active) as tool_count
    from org_departments d where d.active
  )
  select jsonb_build_object(
    'vision', (select vision from company_vision where id=1),
    'mission', (select mission from company_vision where id=1),
    'as_of', now(),
    'totals', jsonb_build_object(
      'departments', (select count(*) from depts),
      'brain_agents', (select count(*) from org_agents where active),
      'category_sales_agents', (select count(*) from category_agents),
      'tools_wired', (select count(*) from org_action_executor where active),
      'open_objectives', (select count(*) from org_objectives where status not in ('done','cancelled')),
      'open_tasks', (select count(*) from org_tasks where status in ('assigned','proposed','in_progress'))
    ),
    'departments', (select jsonb_agg(jsonb_build_object(
        'dept', dept_key, 'name', name, 'charter', charter, 'north_star', north_star,
        'lead_agent', lead_agent, 'brain_agents', brain_agents,
        'headcount', brain_count + case when dept_key='procurement' then (select count(*) from category_agents) else 0 end,
        'tools_wired', tool_count) order by dept_key) from depts)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_control_mode_challenge_minutes()
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select greatest(1, least(15, coalesce((select value from public.app_secrets where key='control_mode_challenge_minutes')::int, 5)));
$function$


CREATE OR REPLACE FUNCTION public.fn_control_mode_challenge_start(p_actor_email text, p_code_hash text, p_ip text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id record; v_phone text; v_recent int; v_row public.control_mode_challenge%rowtype; v_min int;
begin
  select * into v_id from public.control_mode_identity
   where admin_email = lower(btrim(p_actor_email)) and active;
  if not found then
    insert into public.control_mode_audit (actor_email, event, allowed, reason)
    values (p_actor_email, 'challenge_denied', false, 'not a registered Control Mode identity');
    return jsonb_build_object('ok', false, 'error', 'not_a_control_mode_identity',
      'message', 'This account is not registered for Control Mode. Registering one is itself a Control Mode change.');
  end if;

  select value into v_phone from public.app_secrets where key = v_id.phone_secret_key;
  if coalesce(length(btrim(v_phone)),0) < 8 then
    insert into public.control_mode_audit (actor_email, event, allowed, reason)
    values (p_actor_email, 'challenge_denied', false, 'no phone configured at ' || v_id.phone_secret_key);
    return jsonb_build_object('ok', false, 'error', 'control_mode_phone_not_configured',
      'message', 'No Control Mode phone number is configured. Set app_secrets.' || v_id.phone_secret_key || '.');
  end if;

  -- Rate limit. Without one, an attacker with a session cookie can spray the founder's phone until
  -- a code is approved out of irritation.
  select count(*) into v_recent from public.control_mode_challenge
   where admin_email = v_id.admin_email and created_at > now() - interval '1 hour';
  if v_recent >= 5 then
    insert into public.control_mode_audit (actor_email, event, allowed, reason)
    values (p_actor_email, 'challenge_denied', false, 'rate limit: 5 challenges per hour');
    return jsonb_build_object('ok', false, 'error', 'too_many_challenges',
      'message', 'Too many Control Mode codes requested in the last hour. Wait, then try again.');
  end if;

  -- Anything still open is void. Two live codes means two ways in.
  update public.control_mode_challenge
     set consumed_at = now(), consumed_why = 'superseded'
   where admin_email = v_id.admin_email and consumed_at is null;

  v_min := public.fn_control_mode_challenge_minutes();
  insert into public.control_mode_challenge (admin_email, nonce, code_hash, phone_tail, expires_at, ip)
  values (v_id.admin_email, encode(extensions.gen_random_bytes(18), 'hex'), p_code_hash,
          right(btrim(v_phone), 4), now() + make_interval(mins => v_min), p_ip)
  returning * into v_row;

  insert into public.control_mode_audit (actor_email, event, allowed, reason, detail)
  values (p_actor_email, 'challenge_started', true, 'control_mode challenge issued',
          jsonb_build_object('challenge_id', v_row.id, 'phone_tail', v_row.phone_tail, 'minutes', v_min));

  return jsonb_build_object('ok', true, 'challenge_id', v_row.id, 'nonce', v_row.nonce,
                            'expires_at', v_row.expires_at, 'phone_tail', v_row.phone_tail,
                            'phone', btrim(v_phone), 'minutes', v_min);
end $function$


CREATE OR REPLACE FUNCTION public.fn_control_mode_close(p_actor_email text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_n int;
begin
  update public.control_mode_session set closed_at = now(), closed_reason = 'closed by actor'
   where actor_email = p_actor_email and closed_at is null;
  get diagnostics v_n = row_count;
  if v_n > 0 then
    insert into public.control_mode_audit (actor_email, event, allowed, reason)
    values (p_actor_email, 'close', true, 'closed by actor');
  end if;
  return jsonb_build_object('ok', true, 'closed', v_n);
end $function$


CREATE OR REPLACE FUNCTION public.fn_control_mode_identity_active(p_email text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (select 1 from public.control_mode_identity
                  where admin_email = lower(btrim(p_email)) and active);
$function$


CREATE OR REPLACE FUNCTION public.fn_control_mode_minutes()
 RETURNS integer
 LANGUAGE sql
 STABLE
AS $function$
  select least(60, greatest(5, coalesce((select nullif(btrim(value),'')::int from app_secrets where key='control_mode_minutes'), 15)));
$function$


CREATE OR REPLACE FUNCTION public.fn_control_mode_open(p_actor_email text, p_reason text, p_challenge_id uuid, p_nonce text, p_code text, p_user_id uuid DEFAULT NULL::uuid, p_ip text DEFAULT NULL::text, p_ua text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_c public.control_mode_challenge%rowtype; v_id uuid; v_min int := public.fn_control_mode_minutes();
        v_reason text; v_raw_len int;
begin
  if coalesce(btrim(p_reason),'') = '' then
    insert into public.control_mode_audit (actor_email, event, allowed, reason)
    values (p_actor_email, 'open_denied', false, 'no reason given');
    return jsonb_build_object('ok', false, 'error', 'reason_required',
      'message', 'Control Mode needs a reason. It is written into the audit trail beside whatever you change.');
  end if;

  -- Bound the reason exactly as user_agent is bounded below, and record what was dropped.
  v_reason := btrim(p_reason);
  v_raw_len := length(v_reason);
  if v_raw_len > 1000 then
    v_reason := left(v_reason, 1000) || ' [truncated from ' || v_raw_len || ' characters]';
  end if;

  select * into v_c from public.control_mode_challenge
   where id = p_challenge_id
     and admin_email = lower(btrim(p_actor_email))
     and purpose = 'control_mode'
   for update;

  if not found then
    insert into public.control_mode_audit (actor_email, event, allowed, reason)
    values (p_actor_email, 'open_denied', false, 'no such Control Mode challenge for this identity');
    return jsonb_build_object('ok', false, 'error', 'challenge_not_found',
      'message', 'That Control Mode request does not exist, or belongs to a different account. Start a new one.');
  end if;

  if v_c.consumed_at is not null then
    insert into public.control_mode_audit (actor_email, event, allowed, reason)
    values (p_actor_email, 'open_denied', false, 'challenge already used: ' || coalesce(v_c.consumed_why,'used'));
    return jsonb_build_object('ok', false, 'error', 'challenge_already_used',
      'message', 'That code has already been used. Request a new one.');
  end if;

  if v_c.expires_at <= now() then
    update public.control_mode_challenge set consumed_at = now(), consumed_why = 'expired' where id = v_c.id;
    insert into public.control_mode_audit (actor_email, event, allowed, reason)
    values (p_actor_email, 'open_denied', false, 'challenge expired');
    return jsonb_build_object('ok', false, 'error', 'challenge_expired',
      'message', 'That code has expired. Request a new one.');
  end if;

  if v_c.attempts >= v_c.max_attempts then
    update public.control_mode_challenge set consumed_at = now(), consumed_why = 'attempts_exhausted' where id = v_c.id;
    insert into public.control_mode_audit (actor_email, event, allowed, reason)
    values (p_actor_email, 'open_denied', false, 'attempt limit reached');
    return jsonb_build_object('ok', false, 'error', 'too_many_attempts',
      'message', 'Too many wrong codes. That request is closed - start a new one.');
  end if;

  -- Nonce and code are checked together, and only the hashed code is ever compared.
  if v_c.nonce <> coalesce(p_nonce,'') or v_c.code_hash <> public.fn_otp_hash(coalesce(p_code,'')) then
    update public.control_mode_challenge set attempts = attempts + 1 where id = v_c.id;
    insert into public.control_mode_audit (actor_email, event, allowed, reason, detail)
    values (p_actor_email, 'open_denied', false, 'mfa_failed',
            jsonb_build_object('attempt', v_c.attempts + 1, 'of', v_c.max_attempts));
    return jsonb_build_object('ok', false, 'error', 'mfa_failed',
      'attempts_left', greatest(0, v_c.max_attempts - (v_c.attempts + 1)),
      'message', 'That code is not right. Check the message and try again.');
  end if;

  update public.control_mode_challenge set consumed_at = now(), consumed_why = 'opened' where id = v_c.id;

  update public.control_mode_session
     set closed_at = now(), closed_reason = 'superseded by a new session'
   where actor_email = p_actor_email and closed_at is null;

  insert into public.control_mode_session (user_id, actor_email, reason, expires_at, mfa_method, mfa_ref, ip, user_agent)
  values (p_user_id, p_actor_email, v_reason, now() + make_interval(mins => v_min),
          'control_mode_challenge', v_c.id, p_ip, left(coalesce(p_ua,''), 300))
  returning id into v_id;

  insert into public.control_mode_audit (actor_email, event, session_id, allowed, reason, detail)
  values (p_actor_email, 'open', v_id, true, v_reason,
          jsonb_build_object('minutes', v_min, 'ip', p_ip, 'challenge_id', v_c.id,
                             'reason_chars', v_raw_len, 'reason_truncated', (v_raw_len > 1000)));

  return jsonb_build_object('ok', true, 'session_id', v_id, 'expires_at', now() + make_interval(mins => v_min),
                            'minutes', v_min,
                            'message', 'Control Mode is open for ' || v_min || ' minutes. It closes on its own.');
end $function$


CREATE OR REPLACE FUNCTION public.fn_control_mode_require(p_actor_email text, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_class text; v_s record;
begin
  -- AUDIT 8.3 TIER 0. Phase 1 rolled back to observe-only. Still audited, deliberately: during an
  -- incident, the record of what was done under the relaxed control is the most valuable thing here.
  if public.fn_phase1_disarmed() then
    insert into public.control_mode_audit (actor_email, event, action, allowed, reason)
    values (p_actor_email, 'action_allowed_phase1_disarmed', p_action, true,
            'Phase 1 Control Mode is disarmed - see public.phase1_rollback_log for who disarmed it and why');
    return jsonb_build_object('allowed', true, 'mode', 'disarmed',
      'reason', 'Phase 1 Control Mode is disarmed (rollback tier 0)');
  end if;

  select classification into v_class from public.control_mode_action where action = p_action;

  -- FAIL CLOSED. An action nobody classified is an action nobody thought about, and the cost of
  -- being wrong is asymmetric: refusing a read is an inconvenience, allowing an unreviewed mutation
  -- is the incident. The refusal is audited so the missing classification is discoverable.
  if v_class is null then
    insert into public.control_mode_audit (actor_email, event, action, allowed, reason)
    values (p_actor_email, 'action_unclassified', p_action, false, 'action is not in control_mode_action');
    return jsonb_build_object(
      'allowed', false, 'mode', 'observe', 'error', 'action_classification_required',
      'message', 'This action has not been classified as read-only or mutating, so it is refused. '
              || 'Classify it in control_mode_action (and in os_api ACTION_CLASS) before using it.');
  end if;

  if v_class = 'read_only' then
    return jsonb_build_object('allowed', true, 'mode', 'observe', 'reason', 'action is registered read-only');
  end if;

  if v_class = 'mode_control' then
    return jsonb_build_object('allowed', true, 'mode', 'observe', 'reason', 'Control Mode plumbing; handled before the gate');
  end if;

  select * into v_s from public.control_mode_session
   where actor_email = p_actor_email and closed_at is null and expires_at > now()
   order by opened_at desc limit 1;

  if not found then
    insert into public.control_mode_audit (actor_email, event, action, allowed, reason)
    values (p_actor_email, 'action_denied', p_action, false, 'no active Control Mode session');
    return jsonb_build_object('allowed', false, 'mode', 'observe', 'error', 'control_mode_required',
      'message', 'This changes something, so it needs Control Mode. Open it with a code sent to your phone, and say why.');
  end if;

  update public.control_mode_session set actions_used = actions_used + 1 where id = v_s.id;
  insert into public.control_mode_audit (actor_email, event, action, session_id, allowed, reason)
  values (p_actor_email, 'action_allowed', p_action, v_s.id, true, v_s.reason);

  return jsonb_build_object('allowed', true, 'mode', 'control', 'session_id', v_s.id, 'reason', v_s.reason,
                            'seconds_remaining', greatest(0, extract(epoch from (v_s.expires_at - now()))::int));
end $function$


CREATE OR REPLACE FUNCTION public.fn_control_mode_session_mfa_is_real()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v public.control_mode_challenge%rowtype;
begin
  select * into v from public.control_mode_challenge where id = new.mfa_ref;
  if not found then
    raise exception 'control mode: mfa_ref % is not a challenge', new.mfa_ref using errcode = '23514';
  end if;
  if lower(btrim(v.admin_email)) <> lower(btrim(new.actor_email)) then
    raise exception 'control mode: challenge belongs to %, not %', v.admin_email, new.actor_email using errcode = '23514';
  end if;
  if v.purpose <> 'control_mode' then
    raise exception 'control mode: challenge % was issued for %, not control_mode', v.id, v.purpose using errcode = '23514';
  end if;
  if v.consumed_at is null or coalesce(v.consumed_why,'') <> 'opened' then
    raise exception 'control mode: challenge % was not consumed by an open (consumed_why=%)',
      v.id, coalesce(v.consumed_why,'<null>') using errcode = '23514';
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_control_mode_status(p_actor_email text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(
    (select jsonb_build_object(
       'mode','control', 'session_id', s.id, 'reason', s.reason,
       'opened_at', s.opened_at, 'expires_at', s.expires_at,
       'seconds_remaining', greatest(0, extract(epoch from (s.expires_at - now()))::int),
       'actions_used', s.actions_used)
     from public.control_mode_session s
     where s.actor_email = p_actor_email and s.closed_at is null and s.expires_at > now()
     order by s.opened_at desc limit 1),
    jsonb_build_object('mode','observe','session_id', null,
      'message','Observe Mode. Everything is readable; nothing can be changed until Control Mode is opened with a code.'));
$function$


CREATE OR REPLACE FUNCTION public.fn_control_mode_sweep()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_sessions int;
begin
  with c as (
    update public.control_mode_session set closed_at = now(), closed_reason = 'expired'
     where closed_at is null and expires_at <= now() returning id, actor_email
  ), a as (
    insert into public.control_mode_audit (actor_email, event, session_id, allowed, reason)
    select actor_email, 'expired', id, true, 'session timed out' from c
  )
  select count(*)::int into v_sessions from c;

  update public.control_mode_challenge
     set consumed_at = now(), consumed_why = 'expired'
   where consumed_at is null and expires_at <= now();

  delete from public.control_mode_challenge where consumed_at < now() - interval '7 days';

  return v_sessions;
end $function$


CREATE OR REPLACE FUNCTION public.fn_cron_liveness()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog', 'cron'
AS $function$
declare v_age numeric; v_last timestamptz;
begin
  select max(start_time) into v_last from cron.job_run_details;
  if v_last is null then
    return jsonb_build_object('healthy', false, 'newest_run_age_min', null, 'note', 'no cron run history');
  end if;
  v_age := extract(epoch from (now() - v_last))/60.0;
  return jsonb_build_object(
    'healthy', v_age <= 20,               -- crons run every few minutes; >20min silence = scheduler down
    'newest_run_age_min', round(v_age,1),
    'checked_at', now());
exception when others then
  return jsonb_build_object('healthy', null, 'error', sqlerrm);
end $function$


CREATE OR REPLACE FUNCTION public.fn_cron_ran(p_jobname text, p_within interval DEFAULT '26:00:00'::interval)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'cron', 'public', 'pg_temp'
AS $function$
declare v boolean;
begin
  select exists (
    select 1 from cron.job j
    join cron.job_run_details d on d.jobid = j.jobid
    where j.jobname = p_jobname
      and d.start_time > now() - p_within
      and d.status = 'succeeded'
  ) into v;
  return coalesce(v,false);
exception when others then
  return true;  -- if the history is unreadable, do not raise a false alarm
end $function$


CREATE OR REPLACE FUNCTION public.fn_customer_stats(p_customer uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v jsonb; v_inq int; v_open int; v_quotes int; v_deals int; v_spend numeric; v_list jsonb; v_hist jsonb;
begin
  select count(*) into v_inq from inquiries where customer_id=p_customer and parent_inquiry_id is null;
  select count(*) into v_open from inquiries where customer_id=p_customer and parent_inquiry_id is null and coalesce(status,'') not in ('completed','closed','cancelled','split');
  select count(*) into v_quotes from quotes q where q.status <> 'draft' and q.inquiry_id in (select id from inquiries where customer_id=p_customer);
  select count(*) into v_deals from transactions where customer_id=p_customer;
  select coalesce(sum(coalesce(reveal_fee,0)+coalesce(app_fee,0)),0) into v_spend from transactions where customer_id=p_customer and coalesce(refund_status,'')<>'approved';
  select jsonb_agg(x order by (x->>'created_at') desc) into v_list from (
    select jsonb_build_object(
      'id', i.id, 'category', i.category, 'emirate', i.emirate, 'status', i.status,
      'created_at', i.created_at, 'pipeline_stage', i.pipeline_stage, 'outcome', i.outcome,
      'has_drawing', (i.drawing_file_path is not null), 'boq_confidence', i.boq_confidence,
      'quotes_count', (select count(*) from quotes q where q.inquiry_id=i.id and q.status <> 'draft'),
      'minutes_since', round(extract(epoch from (now()-i.created_at))/60.0)::int,
      'editable', (i.status='sent') and (now()-i.created_at) < interval '60 minutes',
      'edit_minutes_left', greatest(0, 60 - round(extract(epoch from (now()-i.created_at))/60.0)::int)
    ) x from inquiries i where i.customer_id=p_customer and i.parent_inquiry_id is null
  ) t;
  with months as (select date_trunc('month',(now()-(n||' month')::interval)) m from generate_series(0,11) n),
  ib as (select date_trunc('month',created_at) m, count(*) c from inquiries where customer_id=p_customer and parent_inquiry_id is null group by 1)
  select jsonb_agg(jsonb_build_object('month',to_char(months.m,'Mon YY'),'inquiries',coalesce(ib.c,0)) order by months.m)
    into v_hist from months left join ib on ib.m=months.m;
  v := jsonb_build_object(
    'customer_id', p_customer,'inquiries_total', v_inq,'open_inquiries', v_open,
    'quotes_received', v_quotes,'avg_quotes_per_inquiry', round(v_quotes::numeric/nullif(v_inq,0),1),
    'deals', v_deals,'total_spend', v_spend,
    'inquiries', coalesce(v_list,'[]'::jsonb),'history_12m', v_hist);
  return v;
end $function$


CREATE OR REPLACE FUNCTION public.fn_customer_success()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_kpis jsonb; n_checkin int:=0; n_reengage int:=0; n_esc int:=0; rec record; v_subject text; v_body text;
begin
  -- snapshot KPIs
  select to_jsonb(k) into v_kpis from public.customer_kpis k;
  insert into public.customer_kpi_snapshots(snapshot_date,kpis) values(current_date,coalesce(v_kpis,'{}'::jsonb))
    on conflict (snapshot_date) do update set kpis=excluded.kpis, created_at=now();

  -- FOLLOW-UP (operational, auto-send): project check-in — revealed but not completed for 7+ days
  for rec in
    select i.id as inquiry_id, i.customer_id, c.full_name, c.email, i.category
    from inquiries i join customers c on c.id=i.customer_id
    where i.status='revealed' and i.completed_at is null
      and coalesce(i.stage_changed_at,i.created_at) < now()-interval '7 days'
      and coalesce(c.banned,false)=false and c.email like '%@%'
      and not exists (select 1 from notifications n where n.type='customer_checkin' and n.body like '%'||i.id::text||'%' and n.created_at>now()-interval '21 days')
    limit 200
  loop
    v_subject:='How is your '||coalesce(rec.category,'project')||' going?';
    v_body:='Hi '||coalesce(rec.full_name,'there')||E',\n\nWe wanted to check in on your '||coalesce(rec.category,'project')||' booked through QuotesDone. Is everything going well with your supplier?\n\nIf you need anything — a hand resolving an issue, another quote, or help with your next project — just reply to this email. We are here to help.\n\n(ref '||rec.inquiry_id||')';
    insert into notifications(type,to_email,to_role,channel,subject,body,status)
    values('customer_checkin',rec.email,'customer','email',v_subject,v_body,'queued');
    n_checkin:=n_checkin+1;
  end loop;

  -- FOLLOW-UP (operational, auto-send): re-engagement — last project 30+ days ago, no new inquiry since
  for rec in
    select c.id as customer_id, c.full_name, c.email
    from customers c
    where coalesce(c.banned,false)=false and c.email like '%@%'
      and exists (select 1 from inquiries i where i.customer_id=c.id and (i.status='revealed' or i.completed_at is not null))
      and (select max(created_at) from inquiries i where i.customer_id=c.id) < now()-interval '30 days'
      and not exists (select 1 from notifications n where n.type='customer_reengage' and n.to_email=c.email and n.created_at>now()-interval '45 days')
    limit 200
  loop
    v_subject:='Planning your next project?';
    v_body:='Hi '||coalesce(rec.full_name,'there')||E',\n\nIt has been a little while since your last project on QuotesDone. Whenever you are planning your next one — big or small — post it in a minute and compare anonymous quotes from vetted UAE suppliers.\n\nStart here: https://quotesdone.com/app\n\nHappy to help anytime.';
    insert into notifications(type,to_email,to_role,channel,subject,body,status)
    values('customer_reengage',rec.email,'customer','email',v_subject,v_body,'queued');
    n_reengage:=n_reengage+1;
  end loop;

  -- ESCALATIONS to founder (never auto-resolve): disputes/refunds, reveal non-response, bad reviews, complaints
  for rec in
    select 'dispute' as sig, t.customer_id as cid, coalesce(c.full_name,'customer') as who, t.id::text as ref,
      'Refund/dispute open — review and resolve.' as msg, 'high' as risk
    from transactions t join customers c on c.id=t.customer_id
    where (t.refund_status is not null or (t.refund_requested_at is not null and t.refund_resolved_at is null))
    union all
    select 'reveal_no_response', t.customer_id, coalesce(c.full_name,'customer'), t.id::text,
      'Customer paid to reveal but supplier has not acknowledged within 48h — service risk.', 'high'
    from transactions t join customers c on c.id=t.customer_id
    where t.supplier_ack_at is null and t.revealed_at is not null and t.revealed_at < now()-interval '48 hours' and t.refund_status is null
    union all
    select 'bad_review', r.customer_id, coalesce(c.full_name,'customer'), r.id::text,
      'Low review left ('||r.rating||'/5) — follow up on dissatisfaction.', 'medium'
    from reviews r join customers c on c.id=r.customer_id where r.rating<=2
    union all
    select 'complaint', c.id, coalesce(c.full_name,'customer'), im.id::text,
      'Inbound complaint from customer — needs attention.', 'high'
    from inbound_messages im join customers c on lower(c.email)=lower(im.from_email)
    where im.ai_category ilike '%complaint%' and im.replied_at is null
  loop
    if not exists (select 1 from agent_actions a where a.kind='customer_escalation' and a.detail->>'signal'=rec.sig and a.detail->>'ref'=rec.ref and a.status in ('pending','needs_review')) then
      insert into agent_actions(agent,kind,status,risk,title,recommendation,detail,target_table,target_id)
      values('customer_success','customer_escalation','pending',rec.risk,
        'Customer '||rec.sig||': '||rec.who, rec.msg,
        jsonb_build_object('signal',rec.sig,'ref',rec.ref,'customer',rec.who),
        'customers', rec.cid::text);
      n_esc:=n_esc+1;
    end if;
  end loop;

  return jsonb_build_object('ran_at',now(),'kpis',v_kpis,'checkins_queued',n_checkin,'reengage_queued',n_reengage,'escalations',n_esc);
end $function$


CREATE OR REPLACE FUNCTION public.fn_customers_board(p_search text DEFAULT ''::text, p_limit integer DEFAULT 80, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare out jsonb;
begin
  with base as (
    select c.id::text as id, coalesce(nullif(trim(c.full_name),''),'(unnamed)') as full_name, c.email, c.phone,
      coalesce(c.email_verified,false) as email_verified, coalesce(c.phone_verified,false) as phone_verified, c.banned, c.created_at,
      case when c.banned then 'banned' when coalesce(c.email_verified,false) or coalesce(c.phone_verified,false) then 'verified' else 'new' end as stage
    from customers c
    where coalesce(p_search,'')='' or c.full_name ilike '%'||p_search||'%' or c.email ilike '%'||p_search||'%' or c.phone ilike '%'||p_search||'%'
  ), ranked as (select *, row_number() over (partition by stage order by created_at desc) rn from base),
  sc as (select stage, count(*) c from base group by stage)
  select jsonb_build_object(
    'total',(select count(*) from base),
    'stages',(select jsonb_agg(jsonb_build_object('key',s.key,'label',s.label,'count',coalesce((select c from sc where sc.stage=s.key),0),
      'cards',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'full_name',r.full_name,'email',r.email,'phone',r.phone,'email_verified',r.email_verified,'banned',r.banned) order by r.rn) from ranked r where r.stage=s.key and r.rn<=12),'[]'::jsonb))
      order by s.ord)
      from (values ('new','New',1),('verified','Verified',2),('banned','Banned',3)) s(key,label,ord)),
    'rows',(select coalesce(jsonb_agg(jsonb_build_object('id',b.id,'full_name',b.full_name,'email',b.email,'phone',b.phone,'email_verified',b.email_verified,'phone_verified',b.phone_verified,'banned',b.banned,'stage',b.stage,'created_at',b.created_at) order by b.created_at desc),'[]'::jsonb)
             from (select * from base order by created_at desc limit greatest(1,least(p_limit,200)) offset greatest(0,p_offset)) b)
  ) into out; return out;
end $function$


CREATE OR REPLACE FUNCTION public.fn_data_metrics()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare res jsonb;
begin
  select jsonb_build_object(
    'category_growth', (select coalesce(fn_marketplace_analytics()->'category_growth','[]'::jsonb)),
    'competitive_categories', (select coalesce(fn_marketplace_analytics()->'competitive_categories','[]'::jsonb)),
    'price_spread', (select coalesce(jsonb_agg(jsonb_build_object('category',category,'n',n,'median',median,'p25',p25,'p75',p75) order by n desc),'[]'::jsonb)
        from (select * from category_price_stats order by n desc limit 10) z),
    'monthly_volume', (select coalesce(jsonb_agg(jsonb_build_object('month',m,'rfqs',c) order by m),'[]'::jsonb)
        from (select to_char(date_trunc('month',created_at),'YYYY-MM') m, count(*) c from inquiries where created_at > now()-interval '6 months' group by 1) z)
  ) into res;
  return res;
end $function$


CREATE OR REPLACE FUNCTION public.fn_day_conductor()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare d date := current_date; v_ok int := 0; v_bad int := 0;
begin
  insert into day_cadence (business_day, stage, stage_order, expected, observed, ok, note)
  select d,'ceo_reviews_company',1,'an exec or board report in the last 24h',
    jsonb_build_object('board_reports_24h',(select count(*) from board_reports where created_at>now()-interval '24 hours'),
                       'exec_reports_24h',(select count(*) from exec_reports where created_at>now()-interval '24 hours')),
    ((select count(*) from board_reports where created_at>now()-interval '24 hours')
   + (select count(*) from exec_reports where created_at>now()-interval '24 hours'))>0,
    'strategy_ai_daily / board_report_weekly / exec_meeting_weekly'
  on conflict (business_day,stage) do update set observed=excluded.observed, ok=excluded.ok, checked_at=now();

  insert into day_cadence (business_day, stage, stage_order, expected, observed, ok, note)
  select d,'cos_reviews_departments',2,'cos_execute_hourly fired and succeeded',
    jsonb_build_object('cron_ok',fn_cron_ran('cos_execute_hourly','3 hours'),
                       'runs_24h',(select count(*) from agent_runs where agent='chief_of_staff' and started_at>now()-interval '24 hours')),
    fn_cron_ran('cos_execute_hourly','3 hours'),'cos_execute_hourly'
  on conflict (business_day,stage) do update set observed=excluded.observed, ok=excluded.ok, checked_at=now();

  insert into day_cadence (business_day, stage, stage_order, expected, observed, ok, note)
  select d,'departments_plan',3,'dept_plan_daily fired and succeeded',
    jsonb_build_object('cron_ok',fn_cron_ran('dept_plan_daily')),
    fn_cron_ran('dept_plan_daily'),'dept_plan_daily (does not always write agent_runs)'
  on conflict (business_day,stage) do update set observed=excluded.observed, ok=excluded.ok, checked_at=now();

  insert into day_cadence (business_day, stage, stage_order, expected, observed, ok, note)
  select d,'tasks_execute',4,'agent runs happened',
    jsonb_build_object('runs_24h',(select count(*) from agent_runs where started_at>now()-interval '24 hours'),
                       'errors_24h',(select count(*) from agent_runs where started_at>now()-interval '24 hours' and status='error')),
    (select count(*) from agent_runs where started_at>now()-interval '24 hours')>0,'all scheduled workers'
  on conflict (business_day,stage) do update set observed=excluded.observed, ok=excluded.ok, checked_at=now();

  insert into day_cadence (business_day, stage, stage_order, expected, observed, ok, note)
  select d,'results_measured',5,'outcomes gradeable and KPIs measurable',
    jsonb_build_object('outcomes_pending',(select count(*) from outcome_record where verdict='pending'),
                       'kpis_measurable',(select count(*) from employee_kpi where active and measure_sql is not null)),
    (select count(*) from employee_kpi where active and measure_sql is not null)>0,'outcome_evaluate_daily / kpi_review_weekly'
  on conflict (business_day,stage) do update set observed=excluded.observed, ok=excluded.ok, checked_at=now();

  insert into day_cadence (business_day, stage, stage_order, expected, observed, ok, note)
  select d,'lessons_learned',6,'dept_learn_daily fired and succeeded',
    jsonb_build_object('cron_ok',fn_cron_ran('dept_learn_daily'),
                       'memory_rows',(select count(*) from institutional_memory)),
    fn_cron_ran('dept_learn_daily'),'dept_learn_daily (does not always write agent_runs)'
  on conflict (business_day,stage) do update set observed=excluded.observed, ok=excluded.ok, checked_at=now();

  insert into day_cadence (business_day, stage, stage_order, expected, observed, ok, note)
  select d,'knowledge_updated',7,'knowledge touched in the last 24h',
    jsonb_build_object('touched_24h',(select count(*) from agent_knowledge where updated_at>now()-interval '24 hours')),
    (select count(*) from agent_knowledge where updated_at>now()-interval '24 hours')>0,'kb_deepen / knowledge_curator_daily'
  on conflict (business_day,stage) do update set observed=excluded.observed, ok=excluded.ok, checked_at=now();

  insert into day_cadence (business_day, stage, stage_order, expected, observed, ok, note)
  select d,'tomorrow_planned',8,'open work exists',
    jsonb_build_object('open_tasks',(select count(*) from org_tasks where status<>'done')),
    (select count(*) from org_tasks where status<>'done')>0,'dept_plan_daily / kpi_review_weekly'
  on conflict (business_day,stage) do update set observed=excluded.observed, ok=excluded.ok, checked_at=now();

  select count(*) filter (where ok), count(*) filter (where not ok) into v_ok, v_bad
    from day_cadence where business_day=d;

  if v_bad>0 then
    insert into founder_alerts (level,event,detail,channel)
    select 'high','daily_cadence_broken',
      'The daily operating loop did not complete. Failed stages: '||
      (select string_agg(stage,', ' order by stage_order) from day_cadence where business_day=d and not ok),'email'
    where not exists (select 1 from founder_alerts where event='daily_cadence_broken' and created_at>now()-interval '20 hours');
  end if;

  insert into agent_runs (agent,started_at,finished_at,status,counts,note)
  values ('day_conductor',now(),now(),case when v_bad>0 then 'error' else 'ok' end,
    jsonb_build_object('stages_ok',v_ok,'stages_failed',v_bad),
    'Daily operating rhythm: '||v_ok||' of '||(v_ok+v_bad)||' stages verified.');

  return jsonb_build_object('day',d,'ok',v_ok,'failed',v_bad);
end $function$


CREATE OR REPLACE FUNCTION public.fn_dbx_category(p_lead_id bigint)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select public.fn_dbx_safe(coalesce(
    -- 1. the supplier's primary catalog category (the real 86-item taxonomy)
    (select c.name from public.lead_category lc
       join public.catalog_supplier_categories c on c.slug = lc.slug
      where lc.lead_id = p_lead_id and lc.is_primary
      order by lc.score desc nulls last limit 1),
    -- 2. any catalog category we managed to map, best score first
    (select c.name from public.lead_category lc
       join public.catalog_supplier_categories c on c.slug = lc.slug
      where lc.lead_id = p_lead_id
      order by lc.score desc nulls last limit 1),
    -- 3. legacy text, but only when it is literally a catalog slug or catalog name
    (select c.name from public.leads l
       join public.catalog_supplier_categories c
         on c.slug = btrim(split_part(coalesce(l.categories,''),',',1))
         or lower(c.name) = lower(btrim(split_part(coalesce(l.categories,''),',',1)))
         or c.slug = btrim(coalesce(l.sector,''))
      where l.id = p_lead_id limit 1),
    'Uncategorized'));
$function$


CREATE OR REPLACE FUNCTION public.fn_dbx_safe(x text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select btrim(regexp_replace(regexp_replace(coalesce(x,''),'[\\/:*?"<>|\r\n\t]+',' ','g'),'\s+',' ','g'))
$function$


CREATE OR REPLACE FUNCTION public.fn_decide(p_kind text, p_ctx jsonb, p_actor text DEFAULT 'agent'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare res jsonb; conf numeric; reasons jsonb:='[]'; route text; decision text; sources jsonb:='[]';
begin
  if p_kind='escalate' then
    res := public.fn_should_escalate(p_ctx);
    decision := case when (res->>'escalate')::boolean then 'escalate' else 'proceed' end;
    reasons := res->'reasons'; route := res->>'route_to';
    conf := case when (res->>'escalate')::boolean then 0.9 else 0.8 end;
    sources := to_jsonb(array['decision_policy']);

  elsif p_kind='price' then
    res := public.fn_price_confidence(coalesce(p_ctx->>'category','default'), nullif(p_ctx->>'amount_aed','')::numeric);
    decision := 'priced'; conf := coalesce((res->>'confidence')::numeric, 0.5);
    reasons := jsonb_build_array(coalesce(res->>'band', 'price band computed')); sources := to_jsonb(array['price_confidence']);
    route := 'none';

  elsif p_kind='route_category' then
    route := public.fn_resolve_cat_agent(coalesce(p_ctx->>'category',''));
    decision := coalesce(route,'unmatched'); conf := case when route is null then 0.3 else 0.85 end;
    reasons := jsonb_build_array('mapped category "'||coalesce(p_ctx->>'category','')||'" to agent '||coalesce(route,'(none)'));
    sources := to_jsonb(array['category_agents']);

  elsif p_kind='invite' then
    -- rank approved suppliers for a category (+ optional emirate)
    with pool as (
      select id, company_name, coalesce(capability_score,0) cap, coalesce(app_rating,rating,0) rat, coalesce(rv_response_rate,0) resp
      from leads
      where coalesce(approval_status,'')='approved'
        and (coalesce(p_ctx->>'category','')='' or lower(coalesce(categories,''))||' '||lower(coalesce(sub_type,'')) like '%'||lower(p_ctx->>'category')||'%')
        and (coalesce(p_ctx->>'emirate','')='' or coalesce(p_ctx->>'emirate')= any(coalesce(service_emirates,array[emirate])))
      order by (coalesce(capability_score,0)*0.5 + coalesce(app_rating,rating,0)*8 + coalesce(rv_response_rate,0)*0.3) desc
      limit coalesce((p_ctx->>'n')::int, 5))
    select jsonb_agg(jsonb_build_object('id',id,'name',company_name,'cap',cap,'rating',rat,'response',resp)) into res from pool;
    decision := 'invite_ranked'; conf := case when res is null then 0.2 when jsonb_array_length(res)>=3 then 0.8 else 0.5 end;
    reasons := jsonb_build_array('ranked by capability_score, rating and response rate');
    sources := to_jsonb(array['leads','supplier_capability','response_rate']);
    res := jsonb_build_object('suppliers', coalesce(res,'[]'));

  elsif p_kind='approve' then
    res := public.fn_should_escalate(p_ctx);
    if (res->>'escalate')::boolean then decision:='human_review'; conf:=0.9; reasons:=res->'reasons';
    else decision:='auto_approve'; conf:=0.85; reasons:=jsonb_build_array('within autonomous thresholds'); end if;
    route := res->>'route_to'; sources := to_jsonb(array['decision_policy']);

  else
    decision := 'unsupported_kind'; conf := 0; reasons := jsonb_build_array('no handler for kind '||p_kind); route:='Secretary';
  end if;

  insert into public.decision_log(actor,kind,ctx,decision,confidence,reasons,sources,route_to)
  values (p_actor,p_kind,p_ctx,decision,conf,reasons,sources,route);

  return jsonb_build_object('kind',p_kind,'decision',decision,'confidence',conf,'reasons',reasons,'route_to',route,'sources',sources,'detail',res);
end $function$


CREATE OR REPLACE FUNCTION public.fn_decision_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_was text; v_spend jsonb; v_reason text;
begin
  v_was := case when tg_op = 'UPDATE' then coalesce(old.status,'') else '' end;

  if new.status in ('approved','executed') and v_was not in ('approved','executed') then
    v_reason := null;

    if coalesce(length(new.impact_business),0)  < 20
    or coalesce(length(new.impact_financial),0) < 20
    or coalesce(length(new.impact_legal),0)     < 10
    or coalesce(length(new.impact_customer),0)  < 20
    or jsonb_array_length(coalesce(new.evidence,'[]'::jsonb)) = 0 then
      v_reason := 'Impact analysis incomplete: business, financial, legal and customer impact plus at least one evidence reference are all required before approval.';
    end if;

    if v_reason is null and coalesce(new.financial_aed,0) > 0 then
      v_spend := public.fn_check_spend(new.dept_key, new.financial_aed, new.approved_by);
      if not coalesce((v_spend->>'affordable')::boolean, false) then
        v_reason := v_spend->>'reason';
      elsif coalesce(new.financial_aed,0) > 10000 and coalesce(new.approved_by,'') not in ('founder','ceo') then
        v_reason := format('AED %s is above the AED 10,000 founder threshold and approved_by is "%s".', new.financial_aed, coalesce(new.approved_by,'(none)'));
      elsif coalesce(new.financial_aed,0) >= 1000 and coalesce(new.approved_by,'') not in ('brief','founder','ceo') then
        v_reason := format('AED %s needs Chief of Staff approval and approved_by is "%s".', new.financial_aed, coalesce(new.approved_by,'(none)'));
      end if;
    end if;

    if v_reason is not null then
      -- Refuse, and leave the refusal on the row rather than aborting the transaction
      -- and losing every trace of it.
      new.status          := 'blocked_by_gate';
      new.gate_verdict    := 'refused';
      new.gate_reason     := v_reason;
      new.gate_checked_at := now();
      raise warning 'decision refused by gate: %', v_reason;
    else
      new.gate_verdict    := 'passed';
      new.gate_reason     := null;
      new.gate_checked_at := now();
    end if;
  end if;
  return new;
end; $function$


CREATE OR REPLACE FUNCTION public.fn_dept_authority(p_dept text, p_action_class text, p_amount_aed numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v jsonb;
begin
  v := public.fn_ops_authority_check(p_dept, p_action_class, p_amount_aed, null);
  return jsonb_build_object(
    'dept', p_dept,
    'action_class', p_action_class,
    'tier', v->>'effective_tier',
    'threshold_aed', (v->>'threshold_aed')::numeric,
    'capped', coalesce(v->>'production_tier', 'gated') is distinct from (v->>'effective_tier'),
    'reviewed', (v->>'reviewed')::boolean,
    'reason', v->>'reason');
end $function$


CREATE OR REPLACE FUNCTION public.fn_dept_can_plan(p_dept_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_stalled int; v_cap int := 5; v_last timestamptz;
begin
  -- Only ASSIGNED-but-never-run work counts as pile-up. Work in progress, work
  -- awaiting the founder, and work already attempted are not what the cap is for.
  select count(*) into v_stalled from org_tasks
   where dept_key = p_dept_key and status = 'assigned' and attempts = 0
     and created_at < now() - interval '48 hours';

  select max(created_at) into v_last from org_memory
   where scope = p_dept_key and kind = 'plan' and source = 'dept_plan';

  -- No department goes silent for more than a week, whatever its backlog. A
  -- department that cannot plan cannot improve, and that is the failure mode the
  -- autonomous-company design exists to prevent.
  if v_last is null or v_last < now() - interval '7 days' then
    return jsonb_build_object('can_plan', true, 'reason',
      'weekly floor: last self-plan ' || coalesce(v_last::text,'never') || ' - planning regardless of backlog',
      'stalled', v_stalled);
  end if;

  if v_stalled >= v_cap then
    return jsonb_build_object('can_plan', false, 'reason',
      v_stalled || ' tasks assigned over 48h ago and never attempted. Execution is behind planning; drain before adding.',
      'stalled', v_stalled);
  end if;

  return jsonb_build_object('can_plan', true, 'reason',
    v_stalled || ' stalled task(s), under the cap of ' || v_cap, 'stalled', v_stalled);
end $function$


CREATE OR REPLACE FUNCTION public.fn_dept_library_search(p_dept text, p_query text, p_limit integer DEFAULT 5)
 RETURNS TABLE(id bigint, department text, title text, content text, rank real)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare q_or tsquery; words text[];
begin
  words := array(select w from unnest(regexp_split_to_array(lower(regexp_replace(coalesce(p_query,''),'[^a-z0-9 ]',' ','g')),'\s+')) w where length(w)>2);
  if array_length(words,1) is null then return; end if;
  begin q_or := to_tsquery('english', array_to_string(words,' | ')); exception when others then return; end;
  return query
    select l.id, l.department, l.title, l.content, ts_rank(l.tsv, q_or) as rank
    from dept_library l
    where (p_dept is null or l.department = p_dept) and l.tsv @@ q_or
    order by ts_rank(l.tsv, q_or) desc, l.id
    limit greatest(1, least(coalesce(p_limit,5),20));
end $function$


CREATE OR REPLACE FUNCTION public.fn_derive_supplier_registration_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_fee numeric; v_start date;
begin
  -- Only registered suppliers carry a registration state. The other ~20k scraped listings are
  -- left completely untouched so bulk maintenance on leads stays cheap.
  if coalesce(new.claimed,false) is not true and new.founding_rank is null then
    return new;
  end if;

  select coalesce(p.supplier_reg_fee,1000), coalesce(p.supplier_charging_starts,'2027-08-01'::date)
    into v_fee, v_start from public.pricing_config p where p.id = 1;
  v_fee := coalesce(v_fee,1000); v_start := coalesce(v_start,'2027-08-01'::date);

  if coalesce(new.subscription_exempt,false) then
    new.registration_status := 'exempt'; new.registration_fee_due := 0;
  elsif new.subscription_paid_until is not null and new.subscription_paid_until >= current_date then
    new.registration_status := 'paid'; new.registration_fee_due := 0;
  elsif current_date < v_start then
    new.registration_status := 'not_due'; new.registration_fee_due := 0;
  else
    new.registration_status := 'due'; new.registration_fee_due := v_fee;
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_dispatch_agent_knowledge_gaps(p_stale_days integer DEFAULT 14, p_thin_min integer DEFAULT 4)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare a jsonb; g jsonb; opened int := 0; resolved_before int; resolved_after int; total_gap int := 0;
begin
  g := fn_knowledge_gaps(p_stale_days, p_thin_min);
  select count(*) into resolved_before from agent_actions where kind='knowledge_task' and detail->>'signal' like 'agent_knowledge:%' and status in ('pending','needs_review');
  for a in select * from jsonb_array_elements(g->'agents') loop
    declare v_gap boolean := (a->>'status') in ('stale','thin'); v_slug text := a->>'slug';
    begin
      if v_gap then total_gap := total_gap + 1; end if;
      perform kn_task('agent_knowledge:'||v_slug, v_gap, case when (a->>'status')='thin' then 'low' else 'medium' end,
        'Refresh knowledge: '||coalesce(a->>'name',v_slug),
        coalesce(a->>'name',v_slug)||' has '||coalesce(a->>'items','0')||' knowledge item(s), last refreshed '||
        coalesce((a->>'days_stale')||' days ago','never')||' (status: '||(a->>'status')||'). Regenerate its field brief so it advises with current expertise. Auto-closes once refreshed.');
    end;
  end loop;
  select count(*) into resolved_after from agent_actions where kind='knowledge_task' and detail->>'signal' like 'agent_knowledge:%' and status in ('pending','needs_review');
  return jsonb_build_object('ran_at', now(), 'gaps_found', total_gap, 'open_tasks', resolved_after,
    'summary', g->'summary');
end $function$


CREATE OR REPLACE FUNCTION public.fn_dispute_open(p_stripe_dispute_id text, p_stripe_charge_id text, p_payment_ref text, p_amount_aed numeric, p_reason text, p_evidence_due_by timestamp with time zone)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id bigint; v_txn bigint;
begin
  select id into v_txn from transactions where payment_ref = p_payment_ref limit 1;

  insert into payment_dispute (stripe_dispute_id, stripe_charge_id, payment_ref, transaction_id,
                               amount_aed, reason, evidence_due_by)
  values (p_stripe_dispute_id, p_stripe_charge_id, p_payment_ref, v_txn,
          p_amount_aed, p_reason, p_evidence_due_by)
  on conflict (stripe_dispute_id) do update set
    status = 'needs_response', evidence_due_by = excluded.evidence_due_by
  returning id into v_id;

  insert into founder_alerts (level, event, detail, channel)
  values ('crit','payment_dispute',
          format('Card dispute opened: AED %s, reason "%s", evidence due %s. Stripe dispute %s. An unanswered dispute is lost automatically and counts toward the account dispute rate.',
                 coalesce(p_amount_aed,0), coalesce(p_reason,'unknown'),
                 coalesce(p_evidence_due_by::text,'unknown'), p_stripe_dispute_id),
          'system');

  insert into company_event (event_type, entity_type, entity_id, actor, payload)
  values ('invoice.flagged','dispute', p_stripe_dispute_id, 'cfo',
          jsonb_build_object('amount_aed', p_amount_aed, 'reason', p_reason,
                             'evidence_due_by', p_evidence_due_by, 'transaction_id', v_txn));

  insert into institutional_memory (kind, subject_type, subject_id, headline, detail, outcome,
                                    money_aed, learned_by, confidence, evidence_ref)
  values ('pattern','dispute', p_stripe_dispute_id,
          'Card dispute opened on a reveal fee.',
          format('Reason "%s" on AED %s. Disputes on a facilitation fee usually mean the buyer did not understand what they paid for, or the supplier never responded after reveal.', coalesce(p_reason,'unknown'), coalesce(p_amount_aed,0)),
          'open', p_amount_aed, 'cfo', 1.0, 'payment_dispute id '||v_id);

  return v_id;
end; $function$


CREATE OR REPLACE FUNCTION public.fn_doc_control()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_run bigint; v_remind int := 0; v_expired int := 0; r record; v_days int;
begin
  insert into agent_runs(agent, started_at) values ('docs', now()) returning id into v_run;
  for r in select id, company_name, claimed_by, email, license_expiry from leads
           where approval_status='approved' and claimed=true and license_expiry is not null
  loop
    v_days := r.license_expiry - current_date;
    if v_days between 0 and 7 then
      if not exists (select 1 from notifications where lead_id=r.id and type='licence_expiry_reminder' and created_at > now()-interval '6 days') then
        insert into notifications(type,to_email,to_role,channel,lead_id,subject,body)
          values ('licence_expiry_reminder', coalesce(r.claimed_by,r.email), 'supplier', 'email', r.id,
            'Your trade licence expires in '||v_days||' day(s) - QuotesDone',
            'Dear '||coalesce(r.company_name,'partner')||', our records show your trade licence expires on '||to_char(r.license_expiry,'DD Mon YYYY')||' ('||v_days||' day(s) away). Please upload your renewed trade licence in your supplier portal to keep your account active and continue receiving job matches. Portal: https://quotesdone.com/suppliers/');
        v_remind := v_remind + 1;
      end if;
    elsif v_days < 0 then
      if not exists (select 1 from notifications where lead_id=r.id and type='licence_expired' and created_at > now()-interval '7 days') then
        insert into notifications(type,to_email,to_role,channel,lead_id,subject,body)
          values ('licence_expired', coalesce(r.claimed_by,r.email), 'supplier', 'email', r.id,
            'Action needed: your trade licence has expired - QuotesDone',
            'Dear '||coalesce(r.company_name,'partner')||', our records show your trade licence expired on '||to_char(r.license_expiry,'DD Mon YYYY')||'. To keep receiving jobs on QuotesDone, please upload your renewed licence in your portal as soon as possible: https://quotesdone.com/suppliers/');
        insert into agent_actions(agent,kind,status,risk,title,recommendation,target_table,target_id,detail)
          values ('docs','licence_expired','pending','medium',coalesce(r.company_name,'Supplier #'||r.id)||' - trade licence EXPIRED','suspend or chase renewal','leads',r.id::text,jsonb_build_object('expiry',r.license_expiry));
        v_expired := v_expired + 1;
      end if;
    end if;
  end loop;
  update agent_runs set finished_at=now(), status='ok', counts=jsonb_build_object('reminders',v_remind,'expired',v_expired) where id=v_run;
end;$function$


CREATE OR REPLACE FUNCTION public.fn_doc_diff(p_type text, p_id text, p_va integer, p_vb integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare a jsonb; b jsonb; k text; res jsonb := '{}';
begin
  select snapshot into a from public.doc_versions where entity_type=p_type and entity_id=p_id and version=p_va;
  select snapshot into b from public.doc_versions where entity_type=p_type and entity_id=p_id and version=p_vb;
  if a is null or b is null then return jsonb_build_object('error','version not found'); end if;
  for k in select distinct key from (select jsonb_object_keys(a) key union select jsonb_object_keys(b)) z loop
    if (a->k) is distinct from (b->k) then
      res := res || jsonb_build_object(k, jsonb_build_object('from', a->k, 'to', b->k));
    end if;
  end loop;
  return jsonb_build_object('entity',p_type||':'||p_id,'from_version',p_va,'to_version',p_vb,'changes',res);
end $function$


CREATE OR REPLACE FUNCTION public.fn_doc_expiry_scan()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare rec record; n int:=0; owner text;
begin
  select split_part(coalesce(value,'management@quotesdone.com'),',',1) into owner from app_secrets where key='admin_emails';
  for rec in
    select id, company_name, 'trade licence' as doc, license_expiry as exp from leads where license_expiry is not null and license_expiry <= current_date+30 and coalesce(approval_status,'')='approved'
    union all
    select id, company_name, 'insurance', insurance_expiry from leads where insurance_expiry is not null and insurance_expiry <= current_date+30 and coalesce(approval_status,'')='approved'
    union all
    select id, company_name, 'registration', registration_expires_at::date from leads where registration_expires_at is not null and registration_expires_at::date <= current_date+30 and coalesce(approval_status,'')='approved'
    union all
    select id, company_name, 'ISO certification', iso_expiry from leads where iso_expiry is not null and iso_expiry <= current_date+30 and coalesce(approval_status,'')='approved'
    union all
    select id, company_name, 'manufacturer authorisation', manufacturer_auth_expiry from leads where manufacturer_auth_expiry is not null and manufacturer_auth_expiry <= current_date+30 and coalesce(approval_status,'')='approved'
  loop
    if not exists (select 1 from notifications where type='doc_expiry' and lead_id=rec.id and subject like '%'||rec.doc||'%' and created_at > now()-interval '20 days') then
      insert into notifications(type,to_email,to_role,lead_id,channel,subject,body)
      values ('doc_expiry', owner, 'admin', rec.id, 'email',
        'Supplier document expiring: '||rec.doc,
        coalesce(rec.company_name,'Supplier #'||rec.id)||' — '||rec.doc||' expires '||rec.exp||'. Follow up for renewal.');
      n:=n+1;
    end if;
  end loop;
  return jsonb_build_object('flagged',n,'scanned_at',now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_doc_final_notice(p_days integer DEFAULT 7)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  rec record; v_email int := 0; v_wa int := 0; v_skipped int := 0;
  v_horizon date := current_date + make_interval(days => p_days);
  v_phone text; v_to text; v_label text; v_exp date;
begin
  for rec in
    select id, company_name, claimed_by, email, phone, whatsapp,
           license_expiry, insurance_expiry
      from leads
     where approval_status = 'approved'
       and coalesce(banned,false) = false
       and coalesce(matching_blocked,false) = false
       and ((license_expiry   is not null and license_expiry   between current_date and v_horizon)
         or (insurance_expiry is not null and insurance_expiry between current_date and v_horizon))
  loop
    -- Whichever gating document expires first is the one we lead with.
    if rec.license_expiry is not null and rec.license_expiry between current_date and v_horizon
       and (rec.insurance_expiry is null or rec.license_expiry <= rec.insurance_expiry) then
      v_label := 'trade licence'; v_exp := rec.license_expiry;
    else
      v_label := 'insurance certificate'; v_exp := rec.insurance_expiry;
    end if;

    -- One final notice per document per expiry cycle. Without this the daily cron would send
    -- the same warning seven days running.
    if exists (select 1 from notifications
                where type = 'doc_final_notice' and lead_id = rec.id
                  and subject like '%' || v_label || '%'
                  and created_at > now() - interval '20 days') then
      v_skipped := v_skipped + 1; continue;
    end if;

    v_to := nullif(trim(coalesce(rec.claimed_by, rec.email)), '');
    if v_to is null or position('@' in v_to) = 0 then v_skipped := v_skipped + 1; continue; end if;

    insert into notifications(type,to_email,to_role,lead_id,channel,subject,body,status)
    values ('doc_final_notice', v_to, 'supplier', rec.id, 'email',
      'Final reminder: your ' || v_label || ' expires on ' || v_exp,
      'Dear ' || coalesce(rec.company_name,'supplier') || ',' || chr(10) || chr(10) ||
      'Your ' || v_label || ' on file with QuotesDone expires on ' || v_exp || '.' || chr(10) || chr(10) ||
      'If we do not have a valid copy by then, your account will be paused automatically and you will stop receiving customer requests until it is renewed. This is temporary and there is no fee to restore it.' || chr(10) || chr(10) ||
      'Two ways to fix it, either is fine:' || chr(10) ||
      '  1. Reply to this email with the renewed document attached. Our system reads it and updates your profile automatically.' || chr(10) ||
      '  2. Upload it in the Documents tab of your supplier portal: https://quotesdone.com/portal' || chr(10) || chr(10) ||
      'If you have already renewed, please send us the latest copy so our records match.',
      'queued');
    v_email := v_email + 1;

    -- WhatsApp: queued for the same supplier when we hold a number. Delivery depends on the
    -- approved template described in the header comment.
    v_phone := nullif(trim(coalesce(rec.whatsapp, rec.phone)), '');
    if v_phone is not null then
      insert into notifications(type,to_email,to_role,lead_id,channel,to_phone,subject,body,status)
      values ('supplier_doc_expiry', v_to, 'supplier', rec.id, 'whatsapp', v_phone,
        'Your ' || v_label || ' expires on ' || v_exp,
        'Your ' || v_label || ' expires on ' || v_exp || '. Renew it to keep receiving QuotesDone requests: https://quotesdone.com/portal',
        'queued');
      v_wa := v_wa + 1;
    end if;
  end loop;

  return json_build_object('emails_queued', v_email, 'whatsapp_queued', v_wa,
                           'skipped', v_skipped, 'days_ahead', p_days,
                           'whatsapp_deliverable', false,
                           'whatsapp_note', 'Queued but not deliverable until a supplier_doc_expiry template SID is registered in wa_template_sids.',
                           'ran_at', now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_doc_history(p_type text, p_id text)
 RETURNS TABLE(version integer, changed_fields text[], checksum text, created_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ select version, changed_fields, checksum, created_at from public.doc_versions
   where entity_type=p_type and entity_id=p_id order by version desc $function$


CREATE OR REPLACE FUNCTION public.fn_document_controller()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare k record; v_health numeric; v_ret numeric; v_backup numeric; n int;
begin
  select * into k from document_kpis;
  v_ret := round(100.0*(k.total_documents - coalesce(k.past_retention,0))/nullif(k.total_documents,0),1);
  v_backup := case when coalesce(k.days_since_backup,999) <= 10 then 100 when coalesce(k.days_since_backup,999) <= 20 then 60 else 20 end;
  v_health := round(coalesce(k.ocr_coverage_pct,100)*0.30 + coalesce(v_ret,100)*0.35 + v_backup*0.20 + greatest(0,100-coalesce(k.oversized,0)*5)*0.15,1);

  insert into document_kpi_snapshots(snapshot_date,kpis) values (current_date, to_jsonb(k)||jsonb_build_object('doc_health',v_health))
    on conflict (snapshot_date) do update set kpis=excluded.kpis, created_at=now();

  -- recommendations (founder-visible; the Controller NEVER deletes a document on its own)
  perform doc_rec('past_retention', coalesce(k.past_retention,0) > 0, 'medium', 'Documents past retention period',
    k.past_retention||' document(s) are older than their retention class. Review for archival or deletion — the Controller flags only and never deletes on its own.');
  perform doc_rec('ocr_backlog', coalesce(k.ocr_backlog,0) > 0, 'low', 'Documents pending OCR/processing',
    k.ocr_backlog||' registered document(s) are not fully processed/extracted. Re-run the doc processing pipeline.');
  perform doc_rec('backup_stale', coalesce(k.days_since_backup,999) > 10, 'high', 'Backup may be stale',
    'The last backup to the backups bucket was '||coalesce(k.days_since_backup::text,'never')||' day(s) ago. Confirm the weekly Dropbox backup job is running.');
  perform doc_rec('oversized', coalesce(k.oversized,0) > 0, 'low', 'Oversized files',
    k.oversized||' file(s) exceed 30MB. Consider compressing or archiving to control storage cost.');

  select count(*) into n from agent_actions where agent='document_controller' and status in ('pending','needs_review');
  return jsonb_build_object('ran_at',now(),'doc_health',v_health,'kpis',to_jsonb(k),'open_tasks',n);
end $function$


CREATE OR REPLACE FUNCTION public.fn_dropbox_list(p_prefix text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'prefix', p_prefix,
    'items', coalesce((
      select jsonb_agg(to_jsonb(t) order by t.is_folder desc, lower(t.name))
      from (
        select id, path, name, is_folder, size, server_modified
        from dropbox_files
        where substring(path, 1, length(path) - length(split_part(path,'/', -1)) - 1) = p_prefix
      ) t
    ), '[]'::jsonb)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_dues_to_escalate(p_days integer)
 RETURNS TABLE(due_id bigint, supplier_id bigint, principal numeric, currency text, reveal_date date, due_date date, days_overdue integer, company_name text, contact_name text, email text, phone text, trade_license_no text, emirate text, category text, signed_terms_path text, claimed_by text, accepted_terms_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select d.id, d.supplier_id, d.amount_due, coalesce(d.currency,'AED'), d.reveal_date, d.due_date::date,
         (current_date - d.due_date::date) as days_overdue,
         l.company_name, l.contact_name, coalesce(l.claimed_by,l.email) as email, coalesce(l.phone_e164,l.phone),
         l.trade_license_no, l.emirate,
         coalesce(nullif(btrim(split_part(coalesce(l.categories,''),',',1)),''), nullif(l.sector,''),'Uncategorized') as category,
         l.signed_terms_path, l.claimed_by, l.accepted_terms_at
  from public.supplier_dues d
  join public.leads l on l.id = d.supplier_id
  where d.status not in ('paid','waived','cancelled','legal')
    and d.legal_escalated_at is null
    and coalesce(d.amount_due,0) > 0
    and current_date >= add_working_days(d.due_date::date, p_days);
$function$


CREATE OR REPLACE FUNCTION public.fn_ea_agenda(p_days integer DEFAULT 7)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'as_of', now(),
    'today', jsonb_build_object(
      'events', coalesce((select jsonb_agg(jsonb_build_object('id',id,'kind',kind,'title',title,'starts_at',starts_at,'location',location,'attendees',attendees) order by starts_at)
          from ea_events where status='scheduled' and coalesce(starts_at, now())::date = current_date),'[]'::jsonb),
      'reminders_due', coalesce((select jsonb_agg(jsonb_build_object('id',id,'title',title,'remind_at',remind_at) order by remind_at)
          from ea_reminders where not done and remind_at <= now()+interval '1 day'),'[]'::jsonb)
    ),
    'upcoming_events', coalesce((select jsonb_agg(jsonb_build_object('id',id,'kind',kind,'title',title,'starts_at',starts_at,'location',location) order by starts_at)
        from ea_events where status='scheduled' and starts_at > current_date and starts_at <= (current_date + (p_days||' days')::interval)),'[]'::jsonb),
    'open_tasks', coalesce((select jsonb_agg(jsonb_build_object('id',id,'title',title,'priority',priority,'due',due_date,'source',source) order by (due_date is null), due_date)
        from (select * from crm_tasks where coalesce(status,'')<>'done' order by (due_date is null), due_date limit 15) t),'[]'::jsonb),
    'overdue_tasks', (select count(*) from crm_tasks where coalesce(status,'')<>'done' and due_date < now()),
    'approvals_to_clear', jsonb_build_object(
      'total',(select count(*) from agent_actions where status in ('pending','needs_review')),
      'high_risk',(select count(*) from agent_actions where status in ('pending','needs_review') and coalesce(risk,'') in ('high','critical')),
      'top', coalesce((select jsonb_agg(jsonb_build_object('agent',agent,'title',title,'risk',risk) order by (coalesce(risk,'')='high') desc, created_at desc)
          from (select * from agent_actions where status in ('pending','needs_review') order by (coalesce(risk,'')='high') desc, created_at desc limit 8) a),'[]'::jsonb)
    ),
    'recent_meetings', coalesce((select jsonb_agg(jsonb_build_object('id',id,'title',title,'meeting_at',meeting_at,'summary',left(summary,240)) order by meeting_at desc)
        from (select * from ea_meetings order by meeting_at desc limit 5) m),'[]'::jsonb)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_ea_assistant()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_agenda jsonb; n_rem int:=0; n_nudge int:=0; rec record;
begin
  v_agenda := fn_ea_agenda(7);
  insert into ea_snapshots(snapshot_date, agenda) values (current_date, v_agenda)
    on conflict (snapshot_date) do update set agenda=excluded.agenda, created_at=now();

  -- mark due reminders as notified (they surface in the agenda; internal only)
  update ea_reminders set notified_at=now() where not done and remind_at <= now() and notified_at is null;
  select count(*) into n_rem from ea_reminders where not done and remind_at <= now();

  -- nudge: overdue tasks/follow-ups -> founder-visible EA reminder action (de-duped daily)
  if (select count(*) from crm_tasks where coalesce(status,'')<>'done' and due_date < now()) > 0
     and not exists (select 1 from agent_actions where agent='executive_assistant' and detail->>'signal'='overdue_followups' and status in ('pending','needs_review') and created_at::date=current_date) then
    insert into agent_actions(agent,kind,status,risk,title,recommendation,detail,target_table,target_id)
    values('executive_assistant','handoff','pending','low','Overdue follow-ups need your attention',
      (select count(*)::text from crm_tasks where coalesce(status,'')<>'done' and due_date < now())||' task(s)/follow-up(s) are past due. Review your open items in the agenda.',
      jsonb_build_object('signal','overdue_followups'),'ea','overdue');
    n_nudge:=1;
  end if;

  return jsonb_build_object('ran_at',now(),'reminders_due',n_rem,'nudged',n_nudge,'agenda',v_agenda);
end $function$


CREATE OR REPLACE FUNCTION public.fn_edge_health_scan()
 RETURNS TABLE(fn_key text, verdict text, silent_minutes numeric, opened_incident boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  r            record;
  v_beat       timestamptz;
  v_silent     numeric;
  v_verdict    text;
  v_note       text;
  v_open       boolean;
  v_title      text;
  v_platform   jsonb;
begin
  select coalesce(jsonb_agg(x), '[]'::jsonb) into v_platform
  from (
    select coalesce(headers->>'sb-error-code', 'status_' || coalesce(status_code::text,'null')) as code,
           count(*) as n
    from net._http_response
    where created > timezone('utc', now()) - interval '30 minutes'
      and (status_code is null or status_code < 200 or status_code >= 300)
    group by 1 order by 2 desc limit 10
  ) x;

  for r in select * from edge_expectation where active order by fn_key loop
    v_beat := null; v_note := null; v_open := false;
    begin
      execute r.heartbeat_sql into v_beat;
    exception when others then
      v_verdict := 'PROBE FAILED';
      v_note := 'heartbeat_sql could not be evaluated: ' || left(sqlerrm, 200);
    end;

    if v_note is null then
      v_silent := case when v_beat is null then null
                       else round(extract(epoch from (now() - v_beat)) / 60.0, 1) end;
      v_verdict := case
        when v_beat is null then 'STALE'
        when v_silent > r.max_silence_minutes then 'STALE'
        else 'ALIVE' end;
    else
      v_silent := null;
    end if;

    insert into edge_health_probe (fn_key, last_beat_at, silent_minutes, verdict, note)
    values (r.fn_key, v_beat, v_silent, v_verdict, v_note);

    if v_verdict <> 'ALIVE' then
      v_title := 'Silent failure: ' || r.fn_key || ' has produced no effect for ' ||
                 coalesce(v_silent::text || ' minutes', 'an unknown period') ||
                 ' (threshold ' || r.max_silence_minutes || ')';

      if not exists (
        select 1 from os_incidents
        where status = 'open' and detail->>'fn_key' = r.fn_key
      ) then
        insert into os_incidents (title, kind, severity, status, detail, opened_by)
        values (
          left(v_title, 300), 'silent_failure', r.severity, 'open',
          jsonb_build_object(
            'fn_key', r.fn_key,
            'cron_jobname', r.cron_jobname,
            'purpose', r.purpose,
            'blast_radius', r.blast_radius,
            'last_beat_at', v_beat,
            'silent_minutes', v_silent,
            'threshold_minutes', r.max_silence_minutes,
            'probe_note', v_note,
            'platform_errors_30m', v_platform,
            'detected_by', 'fn_edge_health_scan'),
          'edge_health_watchdog');
        v_open := true;

        insert into org_tasks (dept_key, title, detail, status, tier, action_class, needs_founder)
        values (
          coalesce(r.dept_key, 'technology'),
          left(v_title, 300),
          r.purpose || E'\n\nWhat breaks while this stays down: ' || r.blast_radius ||
          E'\n\nLast observed effect: ' || coalesce(v_beat::text, 'never') ||
          E'\nCron job: ' || coalesce(r.cron_jobname, 'unknown') ||
          E'\nSeverity: ' || r.severity ||
          E'\nPlatform error codes in the last 30 minutes: ' || v_platform::text ||
          E'\n\nNote: this was detected by watching the capability''s EFFECT, not its logs. ' ||
          'A function killed by the platform (546 WORKER_RESOURCE_LIMIT, OOM, timeout) never ' ||
          'reaches its own error handler, so agent_runs will look clean. Check ' ||
          'net._http_response and the edge function logs directly.',
          'proposed', 'supervised', 'investigate',
          -- a dark backup or a dark availability probe is founder-visible, not just a ticket
          (r.severity = 'high'));
      end if;
    else
      update os_incidents
         set status = 'resolved', resolved_at = now(), resolved_by = 'edge_health_watchdog',
             resolution = 'Capability resumed producing effects; last beat ' || coalesce(v_beat::text,'?')
       where status = 'open' and detail->>'fn_key' = r.fn_key;
      update org_tasks
         set status = 'done', updated_at = now(),
             result = coalesce(result,'{}'::jsonb) || jsonb_build_object('auto_closed','capability recovered','last_beat_at', v_beat)
       where status in ('proposed','assigned','in_progress')
         and action_class = 'investigate'
         and title like 'Silent failure: ' || r.fn_key || ' %';
    end if;

    fn_key := r.fn_key; verdict := v_verdict; silent_minutes := v_silent; opened_incident := v_open;
    return next;
  end loop;
end $function$


CREATE OR REPLACE FUNCTION public.fn_edit_inquiry(p_inquiry uuid, p_customer uuid, p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v inquiries%rowtype; v_paid boolean; v_deadline timestamptz;
begin
  select * into v from inquiries where id=p_inquiry;
  if not found then return jsonb_build_object('error','inquiry_not_found'); end if;
  if p_customer is not null and v.customer_id is distinct from p_customer then
    return jsonb_build_object('error','not_your_inquiry'); end if;
  select exists(select 1 from transactions where inquiry_id=p_inquiry) into v_paid;
  if v_paid or v.status in ('revealed','completed','cancelled','closed') or v.pipeline_stage in ('revealed','won','cancelled') then
    return jsonb_build_object('error','not_editable','status',v.status,
      'message','This request can no longer be edited.'); end if;
  v_deadline := v.created_at + interval '1 hour';
  if now() > v_deadline then
    return jsonb_build_object('error','edit_window_closed','editable_until',v_deadline,
      'message','Inquiries can be edited within 1 hour of submitting. Please create a new request for changes after that.'); end if;

  update inquiries set
    summary   = coalesce(p_patch->>'summary', summary),
    raw_input = coalesce(p_patch->>'raw_input', raw_input),
    budget    = coalesce(p_patch->>'budget', budget),
    emirate   = coalesce(p_patch->>'emirate', emirate),
    scope_type= coalesce(p_patch->>'scope_type', scope_type),
    spec      = case when p_patch ? 'spec' then p_patch->'spec' else spec end,
    boq       = case when p_patch ? 'boq' then p_patch->'boq' else boq end,
    trades    = case when p_patch ? 'trades' then array(select jsonb_array_elements_text(p_patch->'trades')) else trades end,
    keywords  = case when p_patch ? 'keywords' then array(select jsonb_array_elements_text(p_patch->'keywords')) else keywords end
    where id=p_inquiry;
  return jsonb_build_object('ok',true,'edited',true,'editable_until',v_deadline);
end $function$


CREATE OR REPLACE FUNCTION public.fn_email_sendable(p_email text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_e text; v_pat record;
begin
  v_e := lower(btrim(coalesce(p_email,'')));
  if v_e = '' then
    return jsonb_build_object('ok', false, 'reason', 'no address');
  end if;
  if v_e !~ '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+[.][A-Za-z]{2,}$' then
    return jsonb_build_object('ok', false, 'reason', 'not a valid address shape');
  end if;
  if exists (select 1 from email_suppressions s where lower(s.email) = v_e) then
    return jsonb_build_object('ok', false, 'reason', 'suppressed');
  end if;
  for v_pat in select pattern, reason from email_block_pattern where active loop
    if v_e ~ v_pat.pattern then
      return jsonb_build_object('ok', false, 'reason', v_pat.reason);
    end if;
  end loop;
  return jsonb_build_object('ok', true, 'reason', 'sendable');
end; $function$


CREATE OR REPLACE FUNCTION public.fn_emit_budget_exceeded(p_dept text, p_amount numeric, p_requested_by text, p_purpose text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v jsonb;
begin
  v := fn_check_spend(p_dept, p_amount, p_requested_by);
  if not coalesce((v->>'affordable')::boolean, true) then
    insert into company_event (event_type, entity_type, entity_id, actor, payload)
    values ('budget.exceeded','department', p_dept, coalesce(p_requested_by,'system'),
            jsonb_build_object('requested_aed', p_amount, 'available_aed', v->>'available_aed',
                               'purpose', p_purpose, 'reason', v->>'reason'));
  end if;
  return v;
end; $function$


CREATE OR REPLACE FUNCTION public.fn_emit_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_type text; v_entity text; v_id text; v_actor text;
begin
  v_entity := tg_argv[0];
  v_type   := tg_argv[1];
  begin v_id := (to_jsonb(new)->>'id'); exception when others then v_id := null; end;
  begin v_actor := coalesce(to_jsonb(new)->>'created_by', to_jsonb(new)->>'author_agent', to_jsonb(new)->>'actor', 'system'); exception when others then v_actor := 'system'; end;
  insert into company_event (event_type, entity_type, entity_id, actor, payload)
  values (v_type, v_entity, v_id, v_actor, to_jsonb(new));
  return new;
end; $function$


CREATE OR REPLACE FUNCTION public.fn_emit_invoice_received()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  insert into company_event (event_type, entity_type, entity_id, actor, payload)
  values ('invoice.received','ap_bill', new.bill_no, coalesce(new.created_by,'system'),
          jsonb_build_object('vendor_id', new.vendor_id, 'total', new.total,
                             'bill_date', new.bill_date, 'due_date', new.due_date));
  return new;
end; $function$


CREATE OR REPLACE FUNCTION public.fn_emit_metric_alerts()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n integer := 0; r record;
begin
  for r in
    select metric_key, label, value, target, owner_dept, state from v_bi_scorecard
    where state = 'OFF_TARGET'
  loop
    if not exists (
      select 1 from company_event e
      where e.event_type = 'kpi.missed' and e.entity_id = r.metric_key
        and e.occurred_at > date_trunc('day', now())
    ) then
      insert into company_event (event_type, entity_type, entity_id, actor, payload)
      values ('kpi.missed','metric', r.metric_key, coalesce(r.owner_dept,'exec'),
              jsonb_build_object('label', r.label, 'value', r.value, 'target', r.target, 'state', r.state));
      n := n + 1;
    end if;
  end loop;

  -- One goal.at_risk per DEPARTMENT per day, naming the goals and the failing metrics.
  for r in
    select s.owner_dept,
           array_agg(distinct s.label) as failing_metrics,
           (select array_agg(g.key) from company_goals g where g.active and g.owner_dept = s.owner_dept) as goals
    from v_bi_scorecard s
    where s.state = 'OFF_TARGET' and s.owner_dept is not null
    group by s.owner_dept
  loop
    if r.goals is not null and not exists (
      select 1 from company_event e
      where e.event_type = 'goal.at_risk' and e.entity_id = r.owner_dept
        and e.occurred_at > date_trunc('day', now())
    ) then
      insert into company_event (event_type, entity_type, entity_id, actor, payload)
      values ('goal.at_risk','department', r.owner_dept, r.owner_dept,
              jsonb_build_object('failing_metrics', r.failing_metrics, 'goals_at_risk', r.goals));
      n := n + 1;
    end if;
  end loop;

  return n;
end; $function$


CREATE OR REPLACE FUNCTION public.fn_emit_supplier_applied()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.registration_submitted_at is not null
     and coalesce(old.registration_submitted_at, '-infinity'::timestamptz) is distinct from new.registration_submitted_at then
    insert into company_event (event_type, entity_type, entity_id, actor, payload)
    values ('supplier.applied','lead', new.id::text, coalesce(new.claimed_by,'supplier'),
            jsonb_build_object('company', new.company_name, 'emirate', new.emirate,
                               'trade_licence', new.trade_license_no, 'trades', new.invite_trades));
  end if;
  return new;
end; $function$


CREATE OR REPLACE FUNCTION public.fn_emit_test_failed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.status = 'error' and coalesce(old.status,'') <> 'error' then
    if not exists (
      select 1 from company_event e
      where e.event_type = 'test.failed' and e.entity_id = new.agent
        and e.occurred_at > date_trunc('day', now())
    ) then
      insert into company_event (event_type, entity_type, entity_id, actor, payload)
      values ('test.failed','scheduled_run', new.agent, 'system',
              jsonb_build_object('run_id', new.id, 'note', left(coalesce(new.note,''), 500),
                                 'started_at', new.started_at));
    end if;
  end if;
  return new;
end; $function$


CREATE OR REPLACE FUNCTION public.fn_emit_test_failed_ins()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.status = 'error' then
    if not exists (
      select 1 from company_event e
      where e.event_type = 'test.failed' and e.entity_id = new.agent
        and e.occurred_at > date_trunc('day', now())
    ) then
      insert into company_event (event_type, entity_type, entity_id, actor, payload)
      values ('test.failed','scheduled_run', new.agent, 'system',
              jsonb_build_object('run_id', new.id, 'note', left(coalesce(new.note,''), 500),
                                 'started_at', new.started_at));
    end if;
  end if;
  return new;
end; $function$


CREATE OR REPLACE FUNCTION public.fn_enable_dropbox_sync()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare jid int; begin
  select jobid into jid from cron.job where jobname='dropbox_sync_daily';
  if jid is not null then perform cron.alter_job(jid, active:=true); return 'enabled'; end if;
  return 'not_found';
end $function$


CREATE OR REPLACE FUNCTION public.fn_enforce_rls_on_new_tables()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare r record;
begin
  for r in
    select object_identity, schema_name, object_type
    from pg_event_trigger_ddl_commands()
    where command_tag in ('CREATE TABLE','CREATE TABLE AS','SELECT INTO')
      and object_type = 'table'
      and schema_name = 'public'
  loop
    execute format('alter table %s enable row level security', r.object_identity);
  end loop;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_enqueue_doc_backups()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare n integer := 0; m integer;
begin
  with s as (
    select l.*,
      '/QuotesDone Backup/Suppliers/'
        || public.fn_dbx_category(l.id)
        || '/' || fn_dbx_safe(coalesce(l.company_name,'Supplier')) || ' (' || l.id || ')/' as base
    from public.leads l
    where l.approved_at is not null or l.registration_submitted_at is not null
       or l.signed_terms_path is not null or l.company_profile_doc_path is not null
       or l.license_doc_path is not null or coalesce(l.claimed,false)
  ),
  sd as (
    select s.id, s.base, v.doc_type, v.bucket, v.path
    from s cross join lateral (values
      ('Trade licence','supplier-docs', s.license_doc_path),
      ('Bank IBAN','supplier-docs', s.iban_doc_path),
      ('Establishment card','supplier-docs', s.egr_doc_path),
      ('Insurance','supplier-docs', s.insurance_doc_path),
      ('VAT certificate','supplier-docs', s.vat_doc_path),
      ('ISO certificate','supplier-docs', s.iso_doc_path),
      ('Manufacturer authorization','supplier-docs', s.manufacturer_auth_doc_path),
      ('Company profile','supplier-docs', s.company_profile_doc_path),
      ('Signed Terms & Conditions','signed-terms', s.signed_terms_path)
    ) v(doc_type,bucket,path)
    where v.path is not null and length(v.path)>0
  )
  insert into public.doc_backups(entity,entity_id,doc_type,bucket,path,file_name,dropbox_path,source,dedupe_key)
  select 'supplier', sd.id::text, sd.doc_type, sd.bucket, sd.path,
         regexp_replace(sd.path,'^.*/',''),
         sd.base || sd.doc_type || ' - ' || regexp_replace(sd.path,'^.*/',''),
         'storage', 'S:'||sd.id||':'||sd.doc_type||':'||sd.path
  from sd on conflict (dedupe_key) do nothing;
  get diagnostics m = row_count; n := n + m;

  insert into public.doc_backups(entity,entity_id,doc_type,bucket,path,file_name,dropbox_path,source,dedupe_key)
  select 'supplier', s.id::text, 'Catalogue', 'supplier-docs', cat,
         regexp_replace(cat,'^.*/',''), s.base || 'Catalogue - ' || regexp_replace(cat,'^.*/',''),
         'storage', 'S:'||s.id||':cat:'||cat
  from ( select l.id,
      '/QuotesDone Backup/Suppliers/'
        || public.fn_dbx_category(l.id)
        || '/' || fn_dbx_safe(coalesce(l.company_name,'Supplier')) || ' (' || l.id || ')/' as base, l.catalog_doc_paths
    from public.leads l
    where (l.approved_at is not null or l.registration_submitted_at is not null
       or l.signed_terms_path is not null or l.company_profile_doc_path is not null
       or l.license_doc_path is not null or coalesce(l.claimed,false)) and l.catalog_doc_paths is not null ) s,
    unnest(s.catalog_doc_paths) cat
  where cat is not null and length(cat)>0 on conflict (dedupe_key) do nothing;
  get diagnostics m = row_count; n := n + m;

  insert into public.doc_backups(entity,entity_id,doc_type,source,gen_kind,gen_ref,dropbox_path,dedupe_key)
  select 'supplier', s.id::text, 'Company Details','generated','supplier_details', s.id::text,
         s.base || 'Company Details.pdf', 'S:'||s.id||':details'
  from ( select l.id,
      '/QuotesDone Backup/Suppliers/'
        || public.fn_dbx_category(l.id)
        || '/' || fn_dbx_safe(coalesce(l.company_name,'Supplier')) || ' (' || l.id || ')/' as base
    from public.leads l
    where l.approved_at is not null or l.registration_submitted_at is not null
       or l.signed_terms_path is not null or l.company_profile_doc_path is not null
       or l.license_doc_path is not null or coalesce(l.claimed,false) ) s
  on conflict (dedupe_key) do nothing;
  get diagnostics m = row_count; n := n + m;

  insert into public.doc_backups(entity,entity_id,doc_type,bucket,path,file_name,dropbox_path,source,dedupe_key)
  select 'customer', c.id::text, 'Signed Terms & Conditions','signed-terms', c.signed_terms_path,
         regexp_replace(c.signed_terms_path,'^.*/',''),
         '/QuotesDone Backup/Customers/'||fn_dbx_safe(coalesce(c.full_name,'Customer'))||' ('||left(c.id::text,8)||')/Signed Terms & Conditions - '||regexp_replace(c.signed_terms_path,'^.*/',''),
         'storage', 'C:'||c.id||':terms:'||c.signed_terms_path
  from public.customers c where c.signed_terms_path is not null and length(c.signed_terms_path)>0
  on conflict (dedupe_key) do nothing;
  get diagnostics m = row_count; n := n + m;

  insert into public.doc_backups(entity,entity_id,doc_type,source,gen_kind,gen_ref,dropbox_path,dedupe_key)
  select 'customer', c.id::text, 'Customer Details','generated','customer_details', c.id::text,
         '/QuotesDone Backup/Customers/'||fn_dbx_safe(coalesce(c.full_name,'Customer'))||' ('||left(c.id::text,8)||')/Customer Details.pdf',
         'C:'||c.id||':details'
  from public.customers c on conflict (dedupe_key) do nothing;
  get diagnostics m = row_count; n := n + m;

  insert into public.doc_backups(entity,entity_id,doc_type,bucket,path,file_name,dropbox_path,source,dedupe_key)
  select 'inquiry', i.id::text, 'RFQ drawing','drawing-files', i.drawing_file_path,
         coalesce(i.drawing_file_name, regexp_replace(i.drawing_file_path,'^.*/','')),
         '/QuotesDone Backup/Customers/'||fn_dbx_safe(coalesce(c.full_name,'Customer'))||' ('||left(c.id::text,8)||')/Inquiries/'
           || to_char(i.created_at,'YYYY-MM-DD')||' '||left(i.id::text,8)||' - '||fn_dbx_safe(coalesce(i.status,'inquiry'))
           || '/Drawing - '||coalesce(i.drawing_file_name, regexp_replace(i.drawing_file_path,'^.*/','')),
         'storage', 'I:'||i.id||':drawing:'||i.drawing_file_path
  from public.inquiries i join public.customers c on c.id=i.customer_id
  where i.drawing_file_path is not null and length(i.drawing_file_path)>0
  on conflict (dedupe_key) do nothing;
  get diagnostics m = row_count; n := n + m;

  insert into public.doc_backups(entity,entity_id,doc_type,source,gen_kind,gen_ref,dropbox_path,dedupe_key)
  select 'inquiry', i.id::text, 'Inquiry Summary','generated','inquiry_summary', i.id::text,
         '/QuotesDone Backup/Customers/'||fn_dbx_safe(coalesce(c.full_name,'Customer'))||' ('||left(c.id::text,8)||')/Inquiries/'
           || to_char(i.created_at,'YYYY-MM-DD')||' '||left(i.id::text,8)||' - '||fn_dbx_safe(coalesce(i.status,'inquiry'))
           || '/Inquiry Summary.pdf', 'I:'||i.id||':summary'
  from public.inquiries i join public.customers c on c.id=i.customer_id
  on conflict (dedupe_key) do nothing;
  get diagnostics m = row_count; n := n + m;

  -- Quote comparison reports: one PDF per distinct quote-set (>=2 live quotes). Anonymized A/B/C.
  insert into public.doc_backups(entity,entity_id,doc_type,source,gen_kind,gen_ref,dropbox_path,dedupe_key)
  select 'inquiry', i.id::text, 'Quote Comparison','generated','comparison', i.id::text,
         '/QuotesDone Backup/Customers/'||fn_dbx_safe(coalesce(c.full_name,'Customer'))||' ('||left(c.id::text,8)||')/Inquiries/'
           || to_char(i.created_at,'YYYY-MM-DD')||' '||left(i.id::text,8)||' - '||fn_dbx_safe(coalesce(i.status,'inquiry'))
           || '/Quote Comparison Report '||to_char(now(),'YYYY-MM-DD')||' '||left(sig.sig,8)||'.pdf',
         'CMP:'||i.id||':'||sig.sig
  from public.inquiries i
  join public.customers c on c.id=i.customer_id
  join lateral ( select md5(coalesce(string_agg(q.quote_amount::text||':'||coalesce(q.status,''),'|' order by q.quote_amount),'')) as sig,
                        count(*) as nq
                 from public.quotes q where q.inquiry_id=i.id and q.status<>'draft' ) sig on true
  where sig.nq >= 2
  on conflict (dedupe_key) do nothing;
  get diagnostics m = row_count; n := n + m;

  return n;
end $function$


CREATE OR REPLACE FUNCTION public.fn_entity_activity(p_entity text, p_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare out jsonb := '[]'::jsonb; l public.leads%rowtype;
begin
  -- comments (all entities)
  out := out || coalesce((select jsonb_agg(jsonb_build_object('kind','comment','title','Comment','actor',c.author,'body',c.body,'at',c.created_at)) from public.entity_comments c where c.entity=p_entity and c.entity_id=p_id),'[]'::jsonb);
  -- audit trail (all entities)
  out := out || coalesce((select jsonb_agg(jsonb_build_object('kind','audit','title',a.action,'actor',a.actor,'at',a.at,'ok',a.ok)) from public.os_audit_log a where a.entity_id=p_id and (a.entity=p_entity or (p_entity='supplier' and a.entity in ('leads','supplier','suppliers')))),'[]'::jsonb);
  if p_entity = 'supplier' then
    select * into l from public.leads where id = p_id::bigint;
    if l.id is not null then
      out := out || coalesce((select jsonb_agg(jsonb_build_object('kind','agent','title',coalesce(nullif(btrim(aa.title),''), aa.kind),'actor',aa.agent,'body',aa.recommendation,'at',aa.created_at,'status',aa.status)) from public.agent_actions aa where aa.target_table='leads' and aa.target_id::text = p_id),'[]'::jsonb);
      out := out || coalesce((select jsonb_agg(jsonb_build_object('kind','milestone','title',v.label,'actor','system','at',v.ts)) from (values
        ('Sourced', l.created_at),('Scraped', l.scraped_at),('Invited', l.invited_at),('AI reviewed', l.ai_reviewed_at),
        ('Documents extracted', l.doc_extracted_at),('Capability enriched', l.capability_enriched_at),
        ('Registration submitted', l.registration_submitted_at),('Terms accepted', l.accepted_terms_at),
        ('Terms signed', l.signed_terms_at),('Approved', l.approved_at)
      ) v(label, ts) where v.ts is not null),'[]'::jsonb);
    end if;
  end if;
  return coalesce((select jsonb_agg(e) from (select e from jsonb_array_elements(out) e where (e->>'at') is not null order by (e->>'at') desc limit 80) z),'[]'::jsonb);
end $function$


CREATE OR REPLACE FUNCTION public.fn_entity_comment_add(p_entity text, p_id text, p_author text, p_body text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare r public.entity_comments%rowtype;
begin
  if coalesce(btrim(p_body),'') = '' then return jsonb_build_object('ok', false, 'error', 'empty'); end if;
  insert into public.entity_comments(entity, entity_id, author, body)
    values (p_entity, p_id, coalesce(nullif(btrim(p_author),''),'operator'), left(p_body, 4000))
    returning * into r;
  return jsonb_build_object('ok', true, 'id', r.id, 'at', r.created_at);
end $function$


CREATE OR REPLACE FUNCTION public.fn_entity_files(p_entity text, p_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare out jsonb := '[]'::jsonb; l public.leads%rowtype;
begin
  if p_entity = 'supplier' then
    select * into l from public.leads where id = p_id::bigint;
    if l.id is not null then
      if l.license_doc_path is not null then out := out || jsonb_build_object('group','Compliance documents','type','Trade licence','name',coalesce(l.license_doc_name,'trade licence'),'bucket','supplier-docs','path',l.license_doc_path); end if;
      if l.iban_doc_path is not null then out := out || jsonb_build_object('group','Compliance documents','type','Bank / IBAN','name',coalesce(l.iban_doc_name,'iban letter'),'bucket','supplier-docs','path',l.iban_doc_path); end if;
      if l.egr_doc_path is not null then out := out || jsonb_build_object('group','Compliance documents','type','Establishment card','name',coalesce(l.egr_doc_name,'establishment card'),'bucket','supplier-docs','path',l.egr_doc_path); end if;
      if l.insurance_doc_path is not null then out := out || jsonb_build_object('group','Compliance documents','type','Insurance','name','insurance','bucket','supplier-docs','path',l.insurance_doc_path); end if;
      if l.vat_doc_path is not null then out := out || jsonb_build_object('group','Compliance documents','type','VAT certificate','name','vat certificate','bucket','supplier-docs','path',l.vat_doc_path); end if;
      if l.company_profile_doc_path is not null then out := out || jsonb_build_object('group','Compliance documents','type','Company profile','name','company profile','bucket','supplier-docs','path',l.company_profile_doc_path); end if;
      if l.signed_terms_path is not null then out := out || jsonb_build_object('group','Compliance documents','type','Signed terms','name','signed terms','bucket','signed-terms','path',l.signed_terms_path); end if;
      if l.catalog_doc_paths is not null then
        out := out || coalesce((select jsonb_agg(jsonb_build_object('group','Catalogues','type','Catalogue','name','catalogue','bucket','supplier-docs','path',x)) from unnest(l.catalog_doc_paths) x),'[]'::jsonb);
      end if;
      -- Storage scan: surface any stored documents whose column pointers are null (files live under <folder>/<supplier_id>/<file>).
      out := out || coalesce((
        select jsonb_agg(jsonb_build_object(
          'group', case when split_part(o.name,'/',1) in ('catalogs','catalogues') then 'Catalogues'
                        when o.bucket_id = 'signed-terms' then 'Signed terms'
                        else 'Compliance documents' end,
          'type', case split_part(o.name,'/',1)
                    when 'licence' then 'Trade licence' when 'license' then 'Trade licence' when 'licenses' then 'Trade licence'
                    when 'certs' then 'Certificate' when 'cert' then 'Certificate' when 'insurance' then 'Insurance'
                    when 'profile' then 'Company profile' when 'company_profile' then 'Company profile'
                    when 'catalogs' then 'Catalogue' when 'catalogues' then 'Catalogue'
                    when 'iban' then 'Bank / IBAN' when 'bank' then 'Bank / IBAN'
                    when 'vat' then 'VAT certificate' when 'egr' then 'Establishment card'
                    when 'terms' then 'Signed terms'
                    else initcap(replace(split_part(o.name,'/',1),'_',' ')) end,
          'name', regexp_replace(split_part(o.name,'/', greatest(array_length(string_to_array(o.name,'/'),1),1)), '^[0-9]+_', ''),
          'bucket', o.bucket_id,
          'path', o.name))
        from storage.objects o
        where o.bucket_id in ('supplier-docs','signed-terms')
          and split_part(o.name,'/',2) = p_id
          and not exists (select 1 from jsonb_array_elements(out) xx where xx->>'path' = o.name)
      ), '[]'::jsonb);
    end if;
    out := out || coalesce((select jsonb_agg(jsonb_build_object('group','Quotations submitted','type','Quote #'||q.id,'name',coalesce(q.original_file_name,'quote file'),'bucket','quote-files','path',q.original_file_path) order by q.created_at desc)
                            from public.quotes q where q.supplier_id = p_id::bigint and q.original_file_path is not null),'[]'::jsonb);

  elsif p_entity = 'customer' then
    out := out || coalesce((select jsonb_agg(jsonb_build_object('group','Drawings & RFQ files','type','RFQ drawing','name',coalesce(i.drawing_file_name,'drawing'),'bucket','drawing-files','path',i.drawing_file_path) order by i.created_at desc)
                            from public.inquiries i where i.customer_id = p_id::uuid and i.drawing_file_path is not null),'[]'::jsonb);
    out := out || coalesce((select jsonb_agg(jsonb_build_object('group','Quotations received','type','Quote #'||q.id,'name',coalesce(q.original_file_name,'quote file'),'bucket','quote-files','path',q.original_file_path) order by q.created_at desc)
                            from public.quotes q join public.inquiries i on i.id = q.inquiry_id where i.customer_id = p_id::uuid and q.original_file_path is not null),'[]'::jsonb);

  elsif p_entity in ('rfq','inquiry') then
    out := out || coalesce((select jsonb_agg(jsonb_build_object('group','Drawing','type','RFQ drawing','name',coalesce(i.drawing_file_name,'drawing'),'bucket','drawing-files','path',i.drawing_file_path))
                            from public.inquiries i where i.id = p_id::uuid and i.drawing_file_path is not null),'[]'::jsonb);
    out := out || coalesce((select jsonb_agg(jsonb_build_object('group','Quotations','type','Quote #'||q.id,'name',coalesce(q.original_file_name,'quote file'),'bucket','quote-files','path',q.original_file_path) order by q.created_at desc)
                            from public.quotes q where q.inquiry_id = p_id::uuid and q.original_file_path is not null),'[]'::jsonb);
  end if;
  return out;
end $function$


CREATE OR REPLACE FUNCTION public.fn_eval_run()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare k jsonb;
begin
  k := public.fn_eval_snapshot(30);
  insert into public.agent_evals(window_days,kpis) values (30,k);
end $function$


CREATE OR REPLACE FUNCTION public.fn_eval_snapshot(p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  intake_total int; intake_complete int; q_total int; q_scored int; q_pass numeric; q_avg numeric;
  inq_matched int; inq_all int; inq_done int; inq_open int; esc_pending int; esc_total int; lat_avg numeric;
  dec_total int; dec_grounded int; k jsonb;
begin
  select count(*) filter (where created_at > now()-(p_days||' days')::interval),
         count(*) filter (where created_at > now()-(p_days||' days')::interval and coalesce(rfq_ready,false))
    into intake_total, intake_complete from inquiries;
  select count(*) filter (where created_at > now()-(p_days||' days')::interval),
         count(*) filter (where created_at > now()-(p_days||' days')::interval and quality is not null),
         avg(nullif(quality->>'score','')::numeric) filter (where created_at > now()-(p_days||' days')::interval),
         count(*) filter (where created_at > now()-(p_days||' days')::interval and nullif(quality->>'score','')::numeric >= 60)
    into q_total, q_scored, q_avg, q_pass from quotes;
  select count(*) filter (where i.created_at > now()-(p_days||' days')::interval),
         count(*) filter (where i.created_at > now()-(p_days||' days')::interval and exists(select 1 from inquiry_matches m where m.inquiry_id=i.id))
    into inq_all, inq_matched from inquiries i;
  select count(*) filter (where created_at > now()-(p_days||' days')::interval and (status in ('completed','accepted','closed') or completed_at is not null)),
         count(*) filter (where created_at > now()-(p_days||' days')::interval) into inq_done, inq_open from inquiries;
  begin select count(*) filter (where created_at > now()-(p_days||' days')::interval and status='pending'), count(*) filter (where created_at > now()-(p_days||' days')::interval) into esc_pending, esc_total from agent_actions; exception when others then esc_pending:=0; esc_total:=0; end;
  begin select round(avg(extract(epoch from (finished_at-started_at)))::numeric,1) into lat_avg from agent_runs where started_at > now()-(p_days||' days')::interval and finished_at is not null; exception when others then lat_avg:=null; end;
  begin select count(*), count(*) filter (where jsonb_array_length(coalesce(sources,'[]'))>0) into dec_total, dec_grounded from decision_log where created_at > now()-(p_days||' days')::interval; exception when others then dec_total:=0; dec_grounded:=0; end;

  k := jsonb_build_object(
    'window_days', p_days,
    'rfq_completeness_pct', case when intake_total=0 then null else round(intake_complete::numeric/intake_total*100,1) end,
    'quote_gate_pass_pct',  case when q_scored=0 then null else round(q_pass::numeric/q_scored*100,1) end,
    'quote_quality_avg',    round(coalesce(q_avg,0),1),
    'match_coverage_pct',   case when inq_all=0 then null else round(inq_matched::numeric/inq_all*100,1) end,
    'resolution_pct',       case when inq_open=0 then null else round(inq_done::numeric/inq_open*100,1) end,
    'escalation_rate_pct',  case when esc_total=0 then null else round(esc_pending::numeric/esc_total*100,1) end,
    'agent_latency_sec_avg',lat_avg,
    'decision_grounding_pct', case when dec_total=0 then null else round(dec_grounded::numeric/dec_total*100,1) end,
    'clarification_efficiency', null, 'hallucination_rate_pct', null, 'customer_satisfaction', null,
    'samples', jsonb_build_object('inquiries',intake_total,'quotes',q_total,'agent_actions',esc_total,'decisions',dec_total));
  return k;
end $function$


CREATE OR REPLACE FUNCTION public.fn_event_dispatch(p_lookback_minutes integer DEFAULT 1440)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_delivered integer := 0; v_tasks integer := 0; v_gated integer := 0;
        r record; v_task bigint; v_dept text; v_tier text;
begin
  for r in
    select e.id as event_id, e.event_type, e.entity_type, e.entity_id, e.actor, e.occurred_at, s.agent_key, s.reason
    from company_event e
    join event_subscription s on s.active and s.event_type = e.event_type
    left join event_delivery d on d.event_id = e.id and d.agent_key = s.agent_key
    where d.id is null
      and e.occurred_at > now() - make_interval(mins => greatest(p_lookback_minutes, 1))
      and s.agent_key <> coalesce(e.actor, '')
    order by e.id
  loop
    select department into v_dept from org_agents where agent_key = r.agent_key;
    v_task := null;

    -- 7.3 PRECONDITION. This used to hard-code tier 'autonomous', so a subscriber was granted
    -- autonomy by the dispatcher rather than by the authority model. It reads the tier now.
    if v_dept is not null then
      v_tier := coalesce(public.fn_dept_authority(v_dept, 'analysis')->>'tier', 'gated');
      if v_tier <> 'autonomous' then v_gated := v_gated + 1; end if;
      insert into org_tasks (dept_key, title, detail, status, tier, needs_founder, action_class, decided_by)
      values (v_dept,
              left(r.event_type || ' on ' || r.entity_type || ' ' || coalesce(r.entity_id,''), 200),
              format('Event %s (%s %s) raised by %s at %s. You subscribe to this because: %s. Act on it or close it with a reason.',
                     r.event_type, r.entity_type, coalesce(r.entity_id,'-'), coalesce(r.actor,'system'), r.occurred_at, coalesce(r.reason,'subscription')),
              case when v_tier = 'autonomous' then 'assigned' else 'proposed' end,
              v_tier, v_tier <> 'autonomous', 'analysis', 'fn_event_dispatch')
      returning id into v_task;
      v_tasks := v_tasks + 1;
    end if;

    insert into event_delivery (event_id, agent_key, event_type, task_id)
    values (r.event_id, r.agent_key, r.event_type, v_task)
    on conflict do nothing;
    v_delivered := v_delivered + 1;
  end loop;

  return jsonb_build_object('delivered', v_delivered, 'tasks_created', v_tasks,
                            'tasks_awaiting_a_human', v_gated,
                            'lookback_minutes', p_lookback_minutes);
end; $function$


CREATE OR REPLACE FUNCTION public.fn_evolution_scan()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  insert into evolution_proposal (trigger_kind, subject, observation, evidence, proposal, change_class)
  select 'repeated_failure', r.agent,
         format('%s failed %s times in the last 7 days.', r.agent, r.fails),
         jsonb_build_object('failures_7d', r.fails),
         format('Root-cause %s rather than retry it. If the failure is external, add a documented fallback to continuity_plan; if it is a parsing or contract failure, fix the contract and add a regression test.', r.agent),
         'code'
  from (select agent, count(*) fails from agent_runs
        where status = 'error' and started_at > now() - interval '7 days'
        group by agent having count(*) >= 3) r
  on conflict do nothing;

  insert into evolution_proposal (trigger_kind, subject, observation, evidence, proposal, change_class)
  select 'metric_off_target', s.metric_key,
         format('%s is %s against a target of %s.', s.label, coalesce(s.value::text,'unmeasured'), s.target),
         jsonb_build_object('value', s.value, 'target', s.target, 'owner', s.owner_dept),
         format('%s owns this. Either the target is wrong and should be restated, or the operating approach behind it is wrong and should change. Do not carry it as-is for another period.', coalesce(s.owner_dept,'exec')),
         'process'
  from v_bi_scorecard s where s.state = 'OFF_TARGET'
  on conflict do nothing;

  insert into evolution_proposal (trigger_kind, subject, observation, evidence, proposal, change_class)
  select 'cost_anomaly', c.fn,
         format('%s made %s model calls in 30 days that the cost governor flagged as avoidable.', c.fn, c.n),
         jsonb_build_object('avoidable_calls', c.n, 'cost_aed', c.cost),
         format('Replace the flagged path in %s with a rule, a lookup or SQL, or drop it to the small tier.', c.fn),
         'model_routing'
  from (select fn, count(*) n, round(sum(cost_aed),2) cost from ai_cost_log
        where could_be_cheaper and occurred_at > now() - interval '30 days'
        group by fn having count(*) >= 5) c
  on conflict do nothing;

  return (select count(*) from evolution_proposal where status='proposed');
end; $function$


CREATE OR REPLACE FUNCTION public.fn_exam_pick_agent()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select k.agent_key
  from (select distinct agent_key from agent_knowledge where agent_key <> '_global') k
  left join (select agent_key, max(created_at) last_exam from knowledge_exam_results group by agent_key) e
    on e.agent_key = k.agent_key
  order by e.last_exam asc nulls first, k.agent_key
  limit 1;
$function$


CREATE OR REPLACE FUNCTION public.fn_exam_revert(p_agent_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare n int;
begin
  delete from agent_knowledge
    where topic like 'exam:%' and (p_agent_key is null or agent_key = p_agent_key);
  get diagnostics n = row_count;
  update knowledge_exam_results set filled = false, knowledge_id = null
    where filled and (p_agent_key is null or agent_key = p_agent_key);
  return jsonb_build_object('reverted', n, 'agent', coalesce(p_agent_key,'(all)'));
end $function$


CREATE OR REPLACE FUNCTION public.fn_exception_alerts()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  rev_today numeric; rev_prev numeric;
  gw_bad int; q24 int; qpass24 int; last_backup timestamptz;
  fired text[] := '{}';
  procedure_note text;
begin
  -- helper: only fire if same event not raised in last 12h
  -- 1) revenue drop > 20% day-over-day (needs a meaningful prior day)
  select coalesce(sum(reveal_fee),0) into rev_today from transactions
    where revealed_at::date = current_date and coalesce(refund_status,'')<>'approved';
  select coalesce(sum(reveal_fee),0) into rev_prev from transactions
    where revealed_at::date = current_date-1 and coalesce(refund_status,'')<>'approved';
  if rev_prev >= 100 and rev_today < rev_prev*0.8 then
     if not exists(select 1 from founder_alerts where event='revenue_drop' and created_at>now()-interval '12 hours') then
        insert into founder_alerts(level,event,detail,channel) values
          ('critical','revenue_drop','Revenue AED '||round(rev_today)||' today vs AED '||round(rev_prev)||' yesterday (>20% drop).','email');
        fired := array_append(fired,'revenue_drop'); end if;
  end if;

  -- 2) payment gateway offline (latest stripe health check failing in last hour)
  select count(*) into gw_bad from health_checks
    where created_at>now()-interval '1 hour' and not ok
      and (lower(coalesce(check_kind,'')) like '%stripe%' or lower(coalesce(target,'')) like '%stripe%' or lower(coalesce(check_kind,'')) like '%pay%');
  if gw_bad > 0 then
     if not exists(select 1 from founder_alerts where event='gateway_offline' and created_at>now()-interval '3 hours') then
        insert into founder_alerts(level,event,detail,channel) values
          ('critical','gateway_offline','Payment gateway health check failing in the last hour.','email');
        fired := array_append(fired,'gateway_offline'); end if;
  end if;

  -- 3) AI confidence / quote-quality below threshold (proxy: gate pass-rate collapse with volume)
  select count(*) filter (where quality is not null),
         count(*) filter (where nullif(quality->>'score','')::numeric >= 60)
    into q24, qpass24 from quotes where created_at>now()-interval '24 hours';
  if q24 >= 5 and qpass24::numeric/nullif(q24,0) < 0.5 then
     if not exists(select 1 from founder_alerts where event='ai_confidence_low' and created_at>now()-interval '12 hours') then
        insert into founder_alerts(level,event,detail,channel) values
          ('warning','ai_confidence_low','Quote-quality gate pass rate '||round(qpass24::numeric/q24*100)||'% over last 24h ('||q24||' quotes) — below 50% threshold.','email');
        fired := array_append(fired,'ai_confidence_low'); end if;
  end if;

  -- 4) backup stale (no backup manifest in > 8 days)
  select max(updated_at) into last_backup from storage.objects where bucket_id='backups' and name like '%/_manifest.json';
  if last_backup is null or last_backup < now()-interval '8 days' then
     if not exists(select 1 from founder_alerts where event='backup_stale' and created_at>now()-interval '24 hours') then
        insert into founder_alerts(level,event,detail,channel) values
          ('critical','backup_stale','No fresh backup manifest in over 8 days (last: '||coalesce(last_backup::text,'never')||').','email');
        fired := array_append(fired,'backup_stale'); end if;
  end if;

  -- surface criticals as founder notifications too
  insert into notifications(type,to_role,channel,subject,body)
  select 'exception_alert','admin','email','QuotesDone ALERT: '||event, detail
  from founder_alerts fa
  where fa.created_at>now()-interval '2 minutes' and fa.level='critical'
    and not exists(select 1 from notifications n where n.type='exception_alert' and n.subject='QuotesDone ALERT: '||fa.event and n.created_at>now()-interval '3 hours');

  return jsonb_build_object('fired', to_jsonb(fired), 'rev_today',rev_today,'rev_prev',rev_prev,'checked_at',now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_exec_meeting()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare m jsonb; findings jsonb := '[]'::jsonb; actions int := 0; recs jsonb;
  v_period text := to_char(now(),'IYYY-"W"IW');
  v_rev numeric; v_spend numeric; v_sup int; v_open int; v_avail numeric;
  v_red int; v_amber int; v_green int; r record;
begin
  -- ensure the OS reviews for this week exist before the meeting reads them
  if not exists (select 1 from os_review where period = v_period) then
    perform fn_os_review();
  end if;

  select count(*) filter (where health='red'), count(*) filter (where health='amber'), count(*) filter (where health='green')
    into v_red, v_amber, v_green from os_review where period = v_period;

  select coalesce(sum(coalesce(reveal_fee,app_fee,0)),0) into v_rev from transactions where revealed_at > now()-interval '7 days';
  select coalesce(sum(cost_aed),0) into v_spend from ai_cost_log where occurred_at > now()-interval '7 days';
  select count(*) into v_sup from leads where approval_status='approved';
  select count(*) into v_open from org_tasks where status<>'done';
  select round(100.0*count(*) filter (where ok)/nullif(count(*),0),1) into v_avail
    from health_checks where check_kind='http' and created_at > now()-interval '7 days';

  m := jsonb_build_object('week',v_period,'os_green',v_green,'os_amber',v_amber,'os_red',v_red,
       'revenue_7d_aed',v_rev,'ai_spend_7d_aed',round(coalesce(v_spend,0),2),
       'approved_suppliers',v_sup,'supplier_target',860,
       'open_tasks',v_open,'platform_availability_pct',v_avail);

  -- AGENDA ITEM 1..10: every operating system that is not green, named with its owner
  for r in
    select o.num, o.name, r2.health, r2.owner_agent, r2.findings
    from os_review r2 join operating_system o on o.os_key = r2.os_key
    where r2.period = v_period and r2.health <> 'green' order by
      case r2.health when 'red' then 1 else 2 end, o.num
  loop
    findings := findings || jsonb_build_array(jsonb_build_object(
      'item', r.num||'. '||r.name, 'owner', coalesce(r.owner_agent,'unassigned'),
      'health', r.health, 'finding', r.findings::text));
  end loop;

  -- COMPANY-LEVEL ITEMS the CEO owns directly
  if coalesce(v_rev,0)=0 then
    findings := findings || jsonb_build_array(jsonb_build_object('item','Revenue','owner','cfo','health','amber','finding','No revenue recognised in the last 7 days.'));
  end if;
  if v_sup < 860 then
    findings := findings || jsonb_build_array(jsonb_build_object('item','Supplier coverage','owner','procurement','health',
      case when v_sup=0 then 'red' else 'amber' end,
      'finding', v_sup||' approved suppliers against a target of 860 (10 in each of 86 categories).'));
  end if;
  if coalesce(v_avail,100) < 99.5 then
    findings := findings || jsonb_build_array(jsonb_build_object('item','Platform availability','owner','cto','health','amber','finding','Availability '||coalesce(v_avail,0)||'% against 99.5%.'));
  end if;

  insert into org_tasks (dept_key,title,detail,status,tier,needs_founder,action_class)
  select coalesce((select department from org_agents where agent_key=f->>'owner'),'exec'),
    'Exec meeting '||v_period||': '||(f->>'item'),
    'Health: '||(f->>'health')||'. Owner: '||(f->>'owner')||'. '||(f->>'finding')
    ||' Raised at the weekly executive meeting. Close it, or bring evidence the standard is wrong.',
    'proposed','advisory',false,'exec_review'
  from jsonb_array_elements(findings) f
  where not exists (select 1 from org_tasks t where t.title='Exec meeting '||v_period||': '||(f->>'item') and t.status<>'done');
  get diagnostics actions = row_count;

  recs := case when jsonb_array_length(findings)=0
    then jsonb_build_array('All ten operating systems green and company metrics within tolerance. Hold current priorities.')
    else jsonb_build_array(
      v_red||' operating system(s) red, '||v_amber||' amber. Each has a named owner and a tracked action.',
      'Priority order follows the constitution: compliance, then customer trust, then quality, then revenue.') end;

  insert into exec_reports (officer,period,summary,findings,recommendations,metrics,status)
  values ('ceo',v_period,
    'Weekly executive meeting across ten operating systems. '||v_green||' green, '||v_amber||' amber, '||v_red
    ||' red. '||jsonb_array_length(findings)||' agenda finding(s), '||actions||' action(s) assigned.',
    findings, recs, m, 'open')
  on conflict do nothing;

  insert into agent_runs (agent,started_at,finished_at,status,counts,note)
  values ('exec_meeting',now(),now(),'ok',
    jsonb_build_object('os_green',v_green,'os_amber',v_amber,'os_red',v_red,'findings',jsonb_array_length(findings),'actions',actions),
    'Executive meeting '||v_period||': '||v_green||' green / '||v_amber||' amber / '||v_red||' red across ten operating systems, '||actions||' actions assigned.');

  return jsonb_build_object('week',v_period,'green',v_green,'amber',v_amber,'red',v_red,
                            'findings',jsonb_array_length(findings),'actions',actions,'metrics',m);
end $function$


CREATE OR REPLACE FUNCTION public.fn_experience_promote()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v_promoted int:=0; v_rejected int:=0; v_agent text;
begin
  for r in select m.* from org_memory m
           where m.active and m.kind='lesson'
             and m.created_at < now() - interval '7 days'
             and not exists (select 1 from agent_knowledge k
                             where k.layer='experience' and k.topic like '%[org#'||m.id||']')
  loop
    if exists (select 1 from policy_rules p where p.active and r.content ~* p.forbid_regex) then
      v_rejected := v_rejected + 1;
      insert into founder_alerts(level,event,detail,channel)
        values ('warn','experience_promotion_blocked',
                'org_memory lesson #'||r.id||' contradicts policy_rules and was NOT promoted: '||left(r.content,300),'system');
    else
      select coalesce(d.brain_agent,'_global') into v_agent from org_departments d where d.dept_key=r.scope;
      insert into agent_knowledge(agent_key, topic, content, priority, layer)
        values (coalesce(v_agent,'_global'),
                'Experience: '||left(regexp_replace(r.content,'^\[[a-z]+\]\s*',''),60)||' [org#'||r.id||']',
                r.content, 5, 'experience');
      v_promoted := v_promoted + 1;
    end if;
  end loop;
  return jsonb_build_object('promoted', v_promoted, 'lint_rejected', v_rejected);
end $function$


CREATE OR REPLACE FUNCTION public.fn_experiment_assign(p_key text, p_subject text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare e record; existing text; roll int; acc int:=0; v jsonb; chosen text;
begin
  select * into e from experiments where key=p_key and status='running';
  if e is null then return null; end if;
  select variant into existing from experiment_assignments where experiment=p_key and subject=p_subject;
  if existing is not null then return existing; end if;
  roll := (abs(('x'||substr(md5(p_key||':'||p_subject),1,8))::bit(32)::int) % 100);
  for v in select * from jsonb_array_elements(e.variants) loop
    acc := acc + coalesce((v->>'weight')::int,0);
    if roll < acc then chosen := v->>'name'; exit; end if;
  end loop;
  chosen := coalesce(chosen, (e.variants->0->>'name'));
  insert into experiment_assignments(experiment,subject,variant) values(p_key,p_subject,chosen) on conflict do nothing;
  return chosen;
end $function$


CREATE OR REPLACE FUNCTION public.fn_experiment_record(p_key text, p_subject text, p_event text, p_value numeric DEFAULT 1)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v text;
begin
  select variant into v from experiment_assignments where experiment=p_key and subject=p_subject;
  insert into experiment_events(experiment,subject,variant,event,value) values(p_key,p_subject,v,p_event,p_value);
end $function$


CREATE OR REPLACE FUNCTION public.fn_experiment_results(p_key text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select jsonb_object_agg(variant, stats) from (
    select a.variant,
      jsonb_build_object(
        'subjects', count(distinct a.subject),
        'conversions', count(distinct e.subject) filter (where e.event='convert'),
        'conv_rate_pct', round(100.0*count(distinct e.subject) filter (where e.event='convert')/nullif(count(distinct a.subject),0),1)
      ) stats
    from experiment_assignments a left join experiment_events e on e.experiment=a.experiment and e.subject=a.subject
    where a.experiment=p_key group by a.variant) z;
$function$


CREATE OR REPLACE FUNCTION public.fn_expiring_docs(p_days integer DEFAULT 60)
 RETURNS TABLE(id bigint, company_name text, sector text, doc text, expiry date, days_left integer, status text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select l.id, l.company_name, l.sector, d.label, d.exp, (d.exp-current_date),
    case when d.exp<current_date then 'expired' when d.exp<=current_date+30 then 'expiring' else 'soon' end
  from leads l, lateral (values ('Trade license',l.license_expiry),('ISO certification',l.iso_expiry),
     ('Insurance',l.insurance_expiry),('Manufacturer authorization',l.manufacturer_auth_expiry)) d(label,exp)
  where d.exp is not null and d.exp <= current_date + p_days
    and coalesce(l.approval_status,'')='approved'
  order by d.exp asc;
$function$


CREATE OR REPLACE FUNCTION public.fn_fa_acquire(p_name text, p_category text, p_acquire_date date, p_cost numeric, p_salvage numeric, p_life_months integer, p_in_service date DEFAULT NULL::date, p_fund_account text DEFAULT '1000'::text, p_post_gl boolean DEFAULT true, p_by text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare a bigint; j bigint;
begin
  insert into public.fa_assets(name,category,acquire_date,in_service_date,cost,salvage_value,
        useful_life_months,created_by)
    values (p_name,p_category,coalesce(p_acquire_date,current_date),
            coalesce(p_in_service,p_acquire_date,current_date),
            round(p_cost,2),round(coalesce(p_salvage,0),2),p_life_months,p_by)
    returning id into a;
  update public.fa_assets set asset_no='FA-'||lpad(a::text,6,'0') where id=a;
  if p_post_gl then                                  -- Dr Fixed Asset  Cr funding account
    j := public.fn_gl_entry(coalesce(p_acquire_date,current_date),
           'Asset acquisition '||p_name, 'fa_acquire', a::text,
           jsonb_build_array(jsonb_build_object('account','1600','debit',round(p_cost,2)),
                             jsonb_build_object('account',p_fund_account,'credit',round(p_cost,2))), p_by);
  end if;
  return a;
end $function$


CREATE OR REPLACE FUNCTION public.fn_fa_depreciate(p_asset bigint, p_period date)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare a record; depreciable numeric(18,2); remaining numeric(18,2);
        monthly numeric(18,2); amt numeric(18,2); j bigint;
begin
  select * into a from public.fa_assets where id=p_asset;
  if a.id is null then raise exception 'asset % not found', p_asset; end if;
  if a.status <> 'active' then return null; end if;
  if p_period < a.in_service_date then return null; end if;               -- not yet in service
  if exists (select 1 from public.fa_depreciation where asset_id=p_asset and period=p_period) then
    return null;                                                          -- already booked
  end if;
  depreciable := a.cost - a.salvage_value;
  remaining := depreciable - a.accumulated_depreciation;
  if remaining <= 0 then
    update public.fa_assets set status='fully_depreciated' where id=p_asset; return null;
  end if;
  monthly := round(depreciable / a.useful_life_months, 2);
  amt := least(monthly, remaining);                                       -- final period soaks rounding
  j := public.fn_gl_entry(p_period, 'Depreciation '||a.asset_no||' '||to_char(p_period,'YYYY-MM'),
         'fa_deprec', p_asset::text,
         jsonb_build_array(jsonb_build_object('account',a.expense_account,'debit',amt),
                           jsonb_build_object('account',a.accum_account,'credit',amt)), null);
  insert into public.fa_depreciation(asset_id,period,amount,gl_journal_id) values (p_asset,p_period,amt,j);
  update public.fa_assets
     set accumulated_depreciation = accumulated_depreciation + amt,
         status = case when accumulated_depreciation + amt >= depreciable then 'fully_depreciated' else 'active' end
   where id=p_asset;
  return j;
end $function$


CREATE OR REPLACE FUNCTION public.fn_fa_dispose(p_asset bigint, p_date date, p_proceeds numeric DEFAULT 0, p_proceeds_account text DEFAULT '1000'::text, p_by text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare a record; nbv numeric(18,2); proceeds numeric(18,2); gainloss numeric(18,2);
        gl_lines jsonb; j bigint;
begin
  select * into a from public.fa_assets where id=p_asset;
  if a.id is null then raise exception 'asset % not found', p_asset; end if;
  if a.status='disposed' then raise exception 'asset % already disposed', p_asset; end if;
  proceeds := round(coalesce(p_proceeds,0),2);
  nbv := a.cost - a.accumulated_depreciation;
  gainloss := proceeds - nbv;                          -- +gain / -loss
  gl_lines := jsonb_build_array(
      jsonb_build_object('account',a.accum_account,'debit',a.accumulated_depreciation),  -- clear accum
      jsonb_build_object('account',a.asset_account,'credit',a.cost));                     -- remove cost
  if proceeds > 0 then
    gl_lines := gl_lines || jsonb_build_object('account',p_proceeds_account,'debit',proceeds);
  end if;
  if gainloss > 0 then
    gl_lines := gl_lines || jsonb_build_object('account','4300','credit',gainloss);       -- gain
  elsif gainloss < 0 then
    gl_lines := gl_lines || jsonb_build_object('account','6500','debit',-gainloss);       -- loss
  end if;
  j := public.fn_gl_entry(coalesce(p_date,current_date), 'Disposal '||a.asset_no,
         'fa_dispose', p_asset::text, gl_lines, p_by);
  update public.fa_assets set status='disposed', disposed_date=coalesce(p_date,current_date) where id=p_asset;
  return j;
end $function$


CREATE OR REPLACE FUNCTION public.fn_fa_run_depreciation(p_period date DEFAULT NULL::date)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare per date := coalesce(p_period, (date_trunc('month',current_date)+interval '1 month -1 day')::date);
        r record; n int := 0; j bigint;
begin
  for r in select id from public.fa_assets where status='active' and in_service_date <= per loop
    j := public.fn_fa_depreciate(r.id, per);
    if j is not null then n := n + 1; end if;
  end loop;
  return n;
end $function$


CREATE OR REPLACE FUNCTION public.fn_faq_answer(p_text text, p_min_rank numeric DEFAULT 0.15, p_embedding vector DEFAULT NULL::vector, p_min_similarity numeric DEFAULT 0.86)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v_q tsquery; v_tpl record; v_sim numeric;
begin
  if p_text is null or length(btrim(p_text)) < 2 then
    return jsonb_build_object('answered', false, 'reason', 'input too short');
  end if;

  -- 1. Fixed intents. No retrieval, no model.
  select * into v_tpl from response_template
   where active and (
     (intent='greeting' and p_text ~* '^\s*(hi|hey|hello|salam|marhaba|good (morning|afternoon|evening))\W*$') or
     (intent='thanks'   and p_text ~* '^\s*(thanks|thank you|thx|shukran|much appreciated)\W*$')
   ) limit 1;
  if found then
    update response_template set used_count = used_count + 1 where key = v_tpl.key;
    return jsonb_build_object('answered', true, 'source', 'template', 'key', v_tpl.key,
                              'answer', v_tpl.body, 'confidence', 1.0);
  end if;

  -- 2. Keyword match. Cheap and precise when the wording lines up.
  v_q := websearch_to_tsquery('english', p_text);
  if v_q is not null then
    select f.question, f.answer,
           ts_rank(to_tsvector('english', coalesce(f.question,'')||' '||coalesce(f.answer,'')), v_q) as rank
      into r
      from company_faq f
     where f.public and f.status='approved'
       and to_tsvector('english', coalesce(f.question,'')||' '||coalesce(f.answer,'')) @@ v_q
     order by rank desc limit 1;
    if found and r.rank >= p_min_rank then
      return jsonb_build_object('answered', true, 'source', 'faq_keyword', 'question', r.question,
                                'answer', r.answer, 'confidence', round(r.rank::numeric, 4));
    end if;
  end if;

  -- 3. Semantic match. Catches the same question asked in different words.
  if p_embedding is not null then
    select f.question, f.answer, 1 - (f.embedding_gte <=> p_embedding) as sim into r
      from company_faq f
     where f.public and f.status='approved' and f.embedding_gte is not null
     order by f.embedding_gte <=> p_embedding limit 1;
    if found then
      v_sim := round((r.sim)::numeric, 4);
      if v_sim >= p_min_similarity then
        return jsonb_build_object('answered', true, 'source', 'faq_semantic', 'question', r.question,
                                  'answer', r.answer, 'confidence', v_sim);
      end if;
      return jsonb_build_object('answered', false, 'reason', 'no confident FAQ match',
                                'best_similarity', v_sim);
    end if;
  end if;

  return jsonb_build_object('answered', false, 'reason', 'no confident FAQ match');
end $function$


CREATE OR REPLACE FUNCTION public.fn_field_normalise(p_field_id text, p_value text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_type text; v_tol integer; v_norm text; v_num numeric; v_match text[];
begin
  if p_value is null then return null; end if;
  select answer_type, numeric_tolerance into v_type, v_tol
    from public.field_definition where field_id = p_field_id;

  v_norm := lower(btrim(regexp_replace(p_value, '\s+', ' ', 'g')));

  if coalesce(v_type,'') in ('number','numeric','integer','decimal','quantity') then
    v_match := regexp_match(replace(v_norm, ',', ''), '(-?[0-9]+(?:\.[0-9]+)?)');
    if v_match is not null then
      v_num := v_match[1]::numeric;
      return trim(to_char(round(v_num, coalesce(v_tol, 2)), 'FM99999999999990.99999999'));
    end if;
  end if;

  return v_norm;
end $function$


CREATE OR REPLACE FUNCTION public.fn_field_value_allowed(p_field_id text, p_value text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case
    when p_value is null then true
    else coalesce(
      (select p_value = any(fd.allowed_values) from public.field_definition fd
        where fd.field_id = p_field_id and fd.allowed_values is not null), true)
  end;
$function$


CREATE OR REPLACE FUNCTION public.fn_finance_ai()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare k record; fc jsonb; v_health numeric; n_esc int;
  s_run numeric; s_prof numeric; s_coll numeric; s_bud numeric;
begin
  select * into k from finance_kpis;
  fc := fn_finance_forecast();

  s_run := case when k.runway_months is null then (case when k.cash>0 then 80 else 10 end)
                when k.runway_months>=6 then 100 when k.runway_months>=3 then 70 when k.runway_months>=1 then 40 else 10 end;
  s_prof := case when k.net_income>0 then 100 when k.margin_pct is null then 50 else greatest(10, least(100, 60 + k.margin_pct/5)) end;
  s_coll := coalesce(k.collection_rate, 70);
  s_bud := greatest(0, 100 - coalesce(k.budget_overruns,0)*20);
  v_health := round(s_run*0.35 + s_prof*0.25 + s_coll*0.20 + s_bud*0.20, 1);

  insert into finance_kpi_snapshots(snapshot_date, kpis, forecast)
  values (current_date, to_jsonb(k) || jsonb_build_object('health',v_health), fc)
  on conflict (snapshot_date) do update set kpis=excluded.kpis, forecast=excluded.forecast, created_at=now();

  -- ESCALATIONS to founder (never auto-resolved; agent never moves money)
  if k.cash <= 0 then
    perform fin_alert('cash_negative','high','Book cash is negative',
      'Book cash is '||to_char(k.cash,'FM999999990.00')||' AED and owner capital is 0. Record a capital injection or fund operations to restore a positive position.');
  elsif k.runway_months is not null and k.runway_months < 3 then
    perform fin_alert('low_runway','high','Low cash runway',
      'Runway is ~'||k.runway_months||' months at the current burn. Increase revenue, cut spend, or add capital.');
  end if;
  if k.ar_overdue > 0 then
    perform fin_alert('ar_overdue', case when k.ar_overdue>=500 then 'high' else 'medium' end, 'Overdue collections',
      'AED '||to_char(k.ar_overdue,'FM999999990.00')||' in supplier commission is overdue. Reminders are automated; review whether to escalate or apply fines.');
  end if;
  if k.ap_overdue > 0 then
    perform fin_alert('ap_overdue','high','Overdue bills to pay',
      'AED '||to_char(k.ap_overdue,'FM999999990.00')||' in supplier bills is overdue. Review and pay — money movement is yours to action.');
  end if;
  if coalesce(k.budget_overruns,0) > 0 then
    perform fin_alert('budget_overrun','medium','Budget overrun',
      k.budget_overruns||' expense budget line(s) are over 110% of plan. Review spend or re-budget.');
  end if;

  select count(*) into n_esc from agent_actions where agent='finance_ai' and status in ('pending','needs_review');
  return jsonb_build_object('ran_at',now(),'health',v_health,'kpis',to_jsonb(k),'forecast',fc,'open_alerts',n_esc);
end $function$


CREATE OR REPLACE FUNCTION public.fn_finance_forecast()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  with base as (
    select (select coalesce(sum(balance),0) from gl_account_balances where code in ('1000','1050')) as cash,
           (select coalesce(sum(case when ga.type='revenue' then l.credit-l.debit else 0 end),0)
              from gl_journal_lines l join gl_journal j on j.id=l.journal_id and j.status='posted'
              join gl_accounts ga on ga.code=l.account_code where j.entry_date>=current_date-30) as rev30,
           (select coalesce(sum(case when ga.type='expense' then l.debit-l.credit else 0 end),0)
              from gl_journal_lines l join gl_journal j on j.id=l.journal_id and j.status='posted'
              join gl_accounts ga on ga.code=l.account_code where j.entry_date>=current_date-30) as exp30
  ),
  hz as (
    select h,
      (select coalesce(sum(amount_due),0) from supplier_dues where status not in ('paid','waived') and coalesce(due_date_30,reveal_date+30) <= current_date + h) as ar_in,
      (select coalesce(sum(balance_due),0) from ap_open_bills where coalesce(due_date, bill_date) <= current_date + h) as ap_out
    from (values (30),(60),(90)) v(h)
  )
  select jsonb_build_object(
    'as_of', now(),
    'cash_now', (select cash from base),
    'assumptions', jsonb_build_object('revenue_run_rate_30d',(select rev30 from base),'expense_run_rate_30d',(select exp30 from base)),
    'horizons', (select jsonb_agg(jsonb_build_object(
        'days', h,
        'expected_inflows', round(ar_in + (select rev30 from base)*(h/30.0), 2),
        'expected_outflows', round(ap_out + (select exp30 from base)*(h/30.0), 2),
        'projected_cash', round((select cash from base) + ar_in + (select rev30 from base)*(h/30.0) - ap_out - (select exp30 from base)*(h/30.0), 2),
        'revenue_forecast', round((select rev30 from base)*(h/30.0), 2)
      ) order by h) from hz)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_flag(p_key text, p_ctx jsonb DEFAULT '{}'::jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare f record; aud jsonb; h int; subj text;
begin
  select * into f from feature_flags where key=p_key;
  if f is null or not f.enabled then return false; end if;
  aud := coalesce(f.audience,'{}');
  -- audience gates
  if aud ? 'country' and not (upper(coalesce(p_ctx->>'country','')) = any(select upper(jsonb_array_elements_text(aud->'country')))) then return false; end if;
  if aud ? 'category' and not (lower(coalesce(p_ctx->>'category','')) = any(select lower(jsonb_array_elements_text(aud->'category')))) then return false; end if;
  if aud ? 'role' and not (lower(coalesce(p_ctx->>'role','')) = any(select lower(jsonb_array_elements_text(aud->'role')))) then return false; end if;
  if coalesce((aud->>'enterprise')::boolean,false) and not coalesce((p_ctx->>'enterprise')::boolean,false) then return false; end if;
  -- percentage rollout, deterministic by subject
  subj := coalesce(p_ctx->>'subject', p_ctx->>'email', p_ctx->>'id', 'anon');
  h := (abs(('x'||substr(md5(p_key||':'||subj),1,8))::bit(32)::int) % 100);
  return h < coalesce(f.rollout_pct,100);
end $function$


CREATE OR REPLACE FUNCTION public.fn_founder_brief()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_owner text; v_run bigint;
  v_reg int; v_cust int; v_inq7 int; v_q7 int; v_deals int; v_rev numeric;
  v_pend int; v_kyc int; v_refunds int; v_reviews int;
  v_hot int; v_gap int; v_newsup int; v_newcust int;
  v_bd_q int; v_bd_sent int; v_chat_open int; v_viol int;
  v_officer text; v_health jsonb;
  v_topcats text; v_qpr numeric; v_conv numeric;
  v_expired int; v_crit int; v_decisions text; v_dn int := 0;
  v_body text; v_subj text;
  v_auto_cleared int; v_auto_appr int; v_handled text;   -- Phase B additions
  v_obj_open int := 0; v_obj_await int := 0; v_obj_done24 int := 0; v_task_done24 int := 0; v_obj_line text;  -- Org-foundation additions
begin
  select split_part(coalesce(value,'management@quotesdone.com'),',',1) into v_owner from app_secrets where key='admin_emails';
  if v_owner is null then v_owner := 'management@quotesdone.com'; end if;
  insert into agent_runs(agent, started_at) values ('brief', now()) returning id into v_run;

  begin select coalesce(registered_supplier_count(),0) into v_reg; exception when others then v_reg := 0; end;
  select count(*) into v_cust from customers;
  select count(*) into v_inq7 from inquiries where created_at >= now()-interval '7 days';
  select count(*) into v_q7 from quotes where created_at >= now()-interval '7 days';
  select count(*) into v_deals from transactions;
  select coalesce(sum(coalesce(reveal_fee,app_fee,0)),0) into v_rev from transactions where coalesce(fee_status,'')<>'refunded' and coalesce(refund_status,'')<>'approved';
  select count(*) into v_pend from agent_actions where status in ('pending','held_for_review','proposed','open','needs_review');
  select count(*) into v_kyc from leads where approval_status='pending';
  select count(*) into v_refunds from transactions where refund_status='requested';
  select count(*) into v_reviews from inbound_messages where needs_review=true;
  select count(distinct i.id) into v_hot from inquiries i join quotes q on q.inquiry_id=i.id left join transactions t on t.inquiry_id=i.id where t.id is null and i.status not in ('completed','accepted','closed','cancelled');
  select count(*) into v_gap from inquiries i where i.status not in ('completed','accepted','closed','cancelled') and not exists (select 1 from inquiry_matches m where m.inquiry_id=i.id);
  select count(*) into v_newsup from leads where registration_submitted_at >= now()-interval '7 days';
  select count(*) into v_newcust from customers where created_at >= now()-interval '7 days';
  select count(*) into v_bd_q from outreach where status='queued';
  select count(*) into v_bd_sent from outreach where status='sent';
  select count(*) into v_chat_open from chat_threads where status='open';
  select count(*) into v_viol from chat_violations where created_at >= now()-interval '7 days';

  begin select public.fn_health_index() into v_health; exception when others then v_health := null; end;

  begin
    select string_agg(cat,', ') into v_topcats from (
      select coalesce(nullif(category,''),'(uncategorized)') cat, count(*) n
      from inquiries where created_at>=now()-interval '7 days'
      group by 1 order by n desc limit 3) z;
  exception when others then v_topcats := null; end;

  begin
    select round(avg(qc),1) into v_qpr from (
      select count(*) qc from quotes q join inquiries i on i.id=q.inquiry_id
      where i.created_at>=now()-interval '30 days' group by q.inquiry_id) z;
  exception when others then v_qpr := null; end;
  begin
    select round(100.0*count(distinct t.inquiry_id)/nullif(count(distinct i.id),0),1) into v_conv
    from inquiries i left join transactions t on t.inquiry_id=i.id
    where i.created_at>=now()-interval '30 days';
  exception when others then v_conv := null; end;

  begin select count(*) into v_expired from leads where license_expiry is not null and license_expiry < current_date and coalesce(approval_status,'')='approved'; exception when others then v_expired:=0; end;
  select count(*) into v_crit from founder_alerts where level='critical' and created_at>=now()-interval '24 hours';

  begin
    select string_agg('- ['||label||'] '||act, E'\n')
    into v_officer
    from (
      select case er.officer
               when 'strategy' then 'Strategy' when 'operations' then 'Ops'
               when 'procurement_quality' then 'Quality' when 'data_science' then 'Data'
               when 'product_ux' then 'Product' when 'competitive' then 'Compete' else er.officer end as label,
             left(coalesce(rec->>'action',''),160) as act,
             case lower(coalesce(rec->>'impact','')) when 'high' then 0 when 'medium' then 1 else 2 end as ord
      from (select distinct on (officer) officer, recommendations, created_at from exec_reports order by officer, created_at desc) er,
           lateral jsonb_array_elements(er.recommendations) rec
      where coalesce(rec->>'action','') <> ''
      order by ord, label limit 5
    ) z;
  exception when others then v_officer := null; end;

  -- Phase B: what the Chief of Staff handled autonomously in the last 24h.
  select count(*) into v_auto_cleared from agent_actions
    where decided_by='chief_of_staff (auto)' and decided_at >= now()-interval '24 hours';
  begin
    select count(*) into v_auto_appr from leads
      where approval_decided_by='chief_of_staff (auto)' and approved_at >= now()-interval '24 hours';
  exception when others then v_auto_appr := 0; end;
  begin
    select string_agg('- '||type||': '||n, E'\n' order by n desc)
      into v_handled
    from (select type, count(*) n from notifications
          where status='digest' and created_at >= now()-interval '24 hours'
          group by type) z;
  exception when others then v_handled := null; end;

  -- Org foundation: the founder's objectives and how the organization is executing them.
  begin
    select count(*) into v_obj_open from org_objectives where status in ('open','in_progress','blocked');
    select count(*) into v_obj_done24 from org_objectives where status='done' and closed_at >= now()-interval '24 hours';
    select count(*) into v_task_done24 from org_tasks where status='done' and updated_at >= now()-interval '24 hours';
    select count(*) into v_obj_await from org_tasks t
      where t.status in ('proposed','escalated')
        and exists (select 1 from org_objectives o where o.id=t.objective_id and o.status in ('open','in_progress','blocked'));
    select string_agg(
        '- "'||left(o.objective,80)||'" — '||
        (select count(*) from org_tasks t where t.objective_id=o.id and t.status='done')||'/'||
        (select count(*) from org_tasks t where t.objective_id=o.id)||' tasks done'||
        case when (select count(*) from org_tasks t where t.objective_id=o.id and t.status in ('proposed','escalated'))>0
             then ', '||(select count(*) from org_tasks t where t.objective_id=o.id and t.status in ('proposed','escalated'))||' awaiting you'
             else '' end,
        E'\n' order by o.id desc)
      into v_obj_line from org_objectives o where o.status in ('open','in_progress','blocked');
  exception when others then v_obj_open:=0; v_obj_await:=0; v_obj_done24:=0; v_task_done24:=0; v_obj_line:=null; end;

  v_decisions := '';
  if v_kyc > 0 then v_dn:=v_dn+1; v_decisions := v_decisions||v_dn||'. Approve/deny '||v_kyc||' supplier KYC application(s)'||E'\n'; end if;
  if v_refunds > 0 then v_dn:=v_dn+1; v_decisions := v_decisions||v_dn||'. Resolve '||v_refunds||' refund request(s)'||E'\n'; end if;
  if v_obj_await > 0 then v_dn:=v_dn+1; v_decisions := v_decisions||v_dn||'. '||v_obj_await||' objective step(s) awaiting your approval/input'||E'\n'; end if;
  if v_expired > 0 then v_dn:=v_dn+1; v_decisions := v_decisions||v_dn||'. Review '||v_expired||' supplier(s) with EXPIRED trade licence'||E'\n'; end if;
  if v_crit > 0 then v_dn:=v_dn+1; v_decisions := v_decisions||v_dn||'. Address '||v_crit||' critical alert(s) raised in last 24h'||E'\n'; end if;
  if v_dn = 0 then v_decisions := 'None outstanding.'||E'\n'; end if;

  v_subj := 'QuotesDone daily brief — '||to_char(now() at time zone 'Asia/Dubai','Dy DD Mon');
  v_body :=
    'Good morning. Here is your QuotesDone snapshot.'||E'\n\n'||
    'HANDLED FOR YOU (last 24h): auto-cleared '||v_auto_cleared||' routine item(s)'||
      case when v_auto_appr>0 then ', auto-approved '||v_auto_appr||' licence-clean supplier(s)' else '' end||'.'||
      case when v_handled is not null then E'\n'||v_handled else '' end||E'\n\n'||
    'MARKETPLACE HEALTH: '||coalesce(v_health->>'index','—')||'/100 ('||coalesce(v_health->>'band','no data')||')'||
      case when coalesce(v_health->>'note','')<>'' then '  — '||(v_health->>'note') else '' end||E'\n\n'||
    'OBJECTIVES (what the organization is driving for you)'||E'\n'||
    '- Active objectives: '||v_obj_open||'  ·  tasks completed (24h): '||v_task_done24||'  ·  objectives closed (24h): '||v_obj_done24||E'\n'||
      case when v_obj_line is not null and v_obj_line<>'' then v_obj_line||E'\n' else '' end||E'\n'||
    'NEEDS YOU TODAY'||E'\n'||
    '- Approvals waiting: '||v_pend||' (incl. '||v_kyc||' supplier KYC)'||E'\n'||
    '- Refund requests: '||v_refunds||E'\n'||
    '- Inbound emails to review: '||v_reviews||E'\n'||
    '- Hot leads (quotes in, not revealed): '||v_hot||E'\n'||
    '- Supply gaps (demand, no supplier matched): '||v_gap||E'\n'||
    '- Chat: '||v_chat_open||' open, '||v_viol||' policy flag(s) this week'||E'\n\n'||
    'THIS WEEK'||E'\n'||
    '- New inquiries: '||v_inq7||'  ·  quotes: '||v_q7||E'\n'||
    '- Avg quotes/RFQ (30d): '||coalesce(v_qpr::text,'—')||'  ·  Conversion (30d): '||coalesce(v_conv::text,'—')||'%'||E'\n'||
    '- New customers: '||v_newcust||'  ·  new supplier registrations: '||v_newsup||E'\n'||
    '- Deals (reveals) all-time: '||v_deals||'  ·  revenue recognized: AED '||round(v_rev)||E'\n'||
    '- Top categories (7d): '||coalesce(v_topcats,'—')||E'\n\n'||
    'GROWTH'||E'\n'||
    '- Suppliers registered: '||v_reg||'  ·  BD invites queued: '||v_bd_q||'  ·  sent: '||v_bd_sent||E'\n'||
    case when v_officer is not null and v_officer <> '' then E'\n'||'OFFICER PRIORITIES (from weekly analysis)'||E'\n'||v_officer||E'\n' else '' end ||
    E'\n'||'DECISIONS NEEDED'||E'\n'||v_decisions||
    E'\n'||'Open your dashboard: https://quotesdone.com/os  (Ops for live status; Governance for officer reports).';

  insert into notifications(type,to_email,to_role,channel,subject,body) values ('founder_brief',v_owner,'admin','email',v_subj,v_body);

  update notifications set status='digested' where status='digest' and created_at <= now();

  update agent_runs set finished_at=now(), status='ok', counts=jsonb_build_object('approvals',v_pend,'hot',v_hot,'gaps',v_gap,'bd_queued',v_bd_q,'kyc',v_kyc,'health',(v_health->>'index'),'decisions',v_dn,'auto_cleared_24h',v_auto_cleared,'objectives_open',v_obj_open) where id=v_run;
end;$function$


CREATE OR REPLACE FUNCTION public.fn_fraud_resolve(p_subject_type text, p_subject_id text, p_action text, p_by text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_ok boolean := true; v_msg text := '';
begin
  if p_action = 'ban' then
    begin
      if p_subject_type in ('customer','customers') then
        update customers set banned=true, banned_reason=coalesce(banned_reason,'fraud: manual ban by '||coalesce(p_by,'admin')) where id = p_subject_id::uuid;
      elsif p_subject_type in ('supplier','lead','leads') then
        update leads set banned=true, matching_blocked=true, matching_block_reason=coalesce(matching_block_reason,'fraud ban'), banned_reason=coalesce(banned_reason,'fraud: manual ban by '||coalesce(p_by,'admin')) where id = p_subject_id::bigint;
      else v_ok:=false; v_msg:='unknown subject_type';
      end if;
    exception when others then v_ok:=false; v_msg:=SQLERRM;
    end;
    update fraud_flags set status='resolved', updated_at=now() where subject_type=p_subject_type and subject_id=p_subject_id;
  elsif p_action = 'unban' then
    begin
      if p_subject_type in ('customer','customers') then update customers set banned=false, banned_reason=null where id=p_subject_id::uuid;
      elsif p_subject_type in ('supplier','lead','leads') then update leads set banned=false, matching_blocked=false where id=p_subject_id::bigint;
      end if;
    exception when others then v_ok:=false; v_msg:=SQLERRM; end;
    update fraud_flags set status='resolved', updated_at=now() where subject_type=p_subject_type and subject_id=p_subject_id;
  elsif p_action = 'dismiss' then
    update fraud_flags set status='dismissed', updated_at=now() where subject_type=p_subject_type and subject_id=p_subject_id;
  else v_ok:=false; v_msg:='unknown action';
  end if;
  return jsonb_build_object('ok', v_ok, 'action', p_action, 'subject', p_subject_type||':'||p_subject_id, 'error', nullif(v_msg,''), 'by', p_by, 'at', now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_fraud_scan()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare before_ct int; after_ct int;
begin
  select count(*) into before_ct from fraud_flags;

  -- Abnormal pricing vs category benchmark (uses fn_price_confidence bands)
  insert into fraud_flags(kind,severity,subject_type,subject_id,detail,updated_at)
  select 'abnormal_price',
         case when (x.pc->>'band')='suspiciously_low' then 'high' else 'medium' end,
         'quote', q.id::text,
         jsonb_build_object('band',x.pc->>'band','amount',q.quote_amount,'category',i.category,'median',x.pc->>'median'), now()
  from quotes q join inquiries i on i.id=q.inquiry_id
  cross join lateral (select fn_price_confidence(i.category, q.quote_amount) as pc) x
  where (x.pc->>'band') in ('suspiciously_low','suspiciously_high')
  on conflict (kind,subject_type,subject_id) do update set detail=excluded.detail, severity=excluded.severity, updated_at=now();

  -- Duplicate registered-supplier phones
  insert into fraud_flags(kind,severity,subject_type,subject_id,detail,updated_at)
  select 'dup_supplier_phone','medium','phone', phone,
         jsonb_build_object('supplier_ids', array_agg(id), 'count', count(*)), now()
  from leads where claimed = true and coalesce(phone,'') <> '' group by phone having count(*) > 1
  on conflict (kind,subject_type,subject_id) do update set detail=excluded.detail, updated_at=now();

  -- Duplicate customer phones
  insert into fraud_flags(kind,severity,subject_type,subject_id,detail,updated_at)
  select 'dup_customer_phone','medium','cphone', phone,
         jsonb_build_object('customer_ids', array_agg(id), 'count', count(*)), now()
  from customers where coalesce(phone,'') <> '' group by phone having count(*) > 1
  on conflict (kind,subject_type,subject_id) do update set detail=excluded.detail, updated_at=now();

  -- Identical bid amounts on the same RFQ from different suppliers (possible collusion/copy)
  insert into fraud_flags(kind,severity,subject_type,subject_id,detail,updated_at)
  select 'identical_bids','high','inquiry', inquiry_id::text,
         jsonb_build_object('amount', quote_amount, 'suppliers', array_agg(distinct supplier_id)), now()
  from quotes where quote_amount > 0
  group by inquiry_id, quote_amount having count(distinct supplier_id) > 1
  on conflict (kind,subject_type,subject_id) do update set detail=excluded.detail, updated_at=now();

  -- Copied quotations: same committed_hash across different suppliers
  insert into fraud_flags(kind,severity,subject_type,subject_id,detail,updated_at)
  select 'copied_quote','high','hash', committed_hash,
         jsonb_build_object('quote_ids', array_agg(id), 'suppliers', array_agg(distinct supplier_id)), now()
  from quotes where coalesce(committed_hash,'') <> ''
  group by committed_hash having count(distinct supplier_id) > 1
  on conflict (kind,subject_type,subject_id) do update set detail=excluded.detail, updated_at=now();

  select count(*) into after_ct from fraud_flags;
  return jsonb_build_object('total_flags', after_ct, 'new_flags', after_ct - before_ct);
end $function$


CREATE OR REPLACE FUNCTION public.fn_freeze_supplier_brief(p_inquiry_id uuid, p_reason text DEFAULT 'dispatch'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_brief jsonb; v_sha text; v_prev_sha text; v_ver integer;
begin
  -- MUST read the live projection. Reading inquiries_supplier_safe here would mean reading the
  -- previously frozen brief back, and no later change could ever be detected.
  select to_jsonb(s) - 'status' - 'outcome' - 'hired_supplier_id'
    into v_brief from public.inquiries_supplier_live s where s.id = p_inquiry_id;
  if v_brief is null then
    return jsonb_build_object('frozen', false, 'reason', 'inquiry_not_found');
  end if;
  v_sha := encode(sha256(convert_to(v_brief::text, 'UTF8')), 'hex');
  select b.brief_sha256, b.version into v_prev_sha, v_ver
    from public.inquiry_supplier_brief b where b.inquiry_id = p_inquiry_id order by b.version desc limit 1;
  if v_prev_sha is not null and v_prev_sha = v_sha then
    return jsonb_build_object('frozen', false, 'reason', 'unchanged', 'version', v_ver, 'sha256', v_sha);
  end if;
  insert into public.inquiry_supplier_brief(inquiry_id, version, frozen_reason, brief, brief_sha256)
  values (p_inquiry_id, coalesce(v_ver, 0) + 1, coalesce(p_reason, 'dispatch'), v_brief, v_sha)
  returning version into v_ver;
  return jsonb_build_object('frozen', true, 'version', v_ver, 'sha256', v_sha);
end $function$


CREATE OR REPLACE FUNCTION public.fn_gate_state_satisfies(s gate_state)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select s in ('passed','not_applicable');
$function$


CREATE OR REPLACE FUNCTION public.fn_gl_entry(p_date date, p_memo text, p_source text, p_ref text, p_lines jsonb, p_created_by text DEFAULT 'system'::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare jid bigint; ln jsonb; i int := 0;
begin
  insert into public.gl_journal(entry_date, memo, source, source_ref, created_by)
    values (coalesce(p_date, (now() at time zone 'utc')::date), p_memo, coalesce(p_source,'manual'), p_ref, p_created_by)
    returning id into jid;
  for ln in select * from jsonb_array_elements(p_lines) loop
    i := i + 1;
    insert into public.gl_journal_lines(journal_id, line_no, account_code, debit, credit, memo)
      values (jid, i, (ln->>'account'),
              round(coalesce((ln->>'debit')::numeric,0),2),
              round(coalesce((ln->>'credit')::numeric,0),2),
              ln->>'memo');
  end loop;
  perform public.fn_gl_post(jid);
  return jid;
end $function$


CREATE OR REPLACE FUNCTION public.fn_gl_journal_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
begin
  if tg_op in ('UPDATE','DELETE') and old.status = 'posted'
     and not (tg_op='UPDATE' and new.status='void' and old.status='posted' and new.reverses is not null) then
    -- allow only the controlled void marking done by fn_gl_reverse (new.status='void')
    if tg_op='DELETE' or (tg_op='UPDATE' and old.status='posted' and new.status='posted'
         and (new.entry_date<>old.entry_date or new.memo is distinct from old.memo or new.source<>old.source)) then
      raise exception 'Posted journal % is immutable (reverse it instead)', old.id;
    end if;
  end if;
  return case when tg_op='DELETE' then old else new end;
end $function$


CREATE OR REPLACE FUNCTION public.fn_gl_lines_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare st text;
begin
  select status into st from public.gl_journal where id = coalesce(new.journal_id, old.journal_id);
  if st = 'posted' then
    raise exception 'Cannot modify lines of a posted journal (reverse it instead)';
  end if;
  return case when tg_op='DELETE' then old else new end;
end $function$


CREATE OR REPLACE FUNCTION public.fn_gl_net_income()
 RETURNS numeric
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select coalesce(sum(case when type='revenue' then balance else -balance end),0)
  from public.gl_account_balances where type in ('revenue','expense');
$function$


CREATE OR REPLACE FUNCTION public.fn_gl_post(p_journal bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare d numeric(18,2); c numeric(18,2); n int; st text;
begin
  select status into st from public.gl_journal where id=p_journal;
  if st is null then raise exception 'journal % not found', p_journal; end if;
  if st='posted' then return p_journal; end if;
  select coalesce(sum(debit),0), coalesce(sum(credit),0), count(*) into d,c,n from public.gl_journal_lines where journal_id=p_journal;
  if n < 2 then raise exception 'journal % needs at least 2 lines', p_journal; end if;
  if d <> c then raise exception 'journal % out of balance: debits % <> credits %', p_journal, to_char(d,'FM999999990.00'), to_char(c,'FM999999990.00'); end if;
  if d = 0 then raise exception 'journal % has zero amount', p_journal; end if;
  update public.gl_journal
     set status='posted', posted_at=now(),
         entry_no = coalesce(entry_no, 'JE-'||lpad(p_journal::text,6,'0'))
   where id=p_journal;
  return p_journal;
end $function$


CREATE OR REPLACE FUNCTION public.fn_gl_reverse(p_journal bigint, p_date date, p_memo text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare jid bigint; r record;
begin
  if (select status from public.gl_journal where id=p_journal) <> 'posted' then
    raise exception 'can only reverse a posted journal'; end if;
  insert into public.gl_journal(entry_date, memo, source, source_ref, reverses, created_by)
    values (coalesce(p_date,(now() at time zone 'utc')::date),
            coalesce(p_memo,'Reversal of JE '||p_journal), 'reversal', p_journal::text, p_journal, 'system')
    returning id into jid;
  for r in select account_code, debit, credit, line_no from public.gl_journal_lines where journal_id=p_journal loop
    insert into public.gl_journal_lines(journal_id, line_no, account_code, debit, credit)
      values (jid, r.line_no, r.account_code, r.credit, r.debit);  -- swap
  end loop;
  perform public.fn_gl_post(jid);
  return jid;
end $function$


CREATE OR REPLACE FUNCTION public.fn_gl_sync_business()
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; n int := 0; acct text;
        fee_pct numeric; fee_fixed numeric; fee numeric(18,2); gross numeric(18,2); net numeric(18,2);
        fx numeric; amt_aed numeric(18,2); diff numeric(18,2); extra numeric(18,2); lines jsonb;
begin
  select num_value into fee_pct   from public.gl_settings where key='stripe_fee_pct';
  select num_value into fee_fixed from public.gl_settings where key='stripe_fee_fixed';
  select num_value into fx        from public.gl_settings where key='usd_to_aed';
  fee_pct   := coalesce(fee_pct,0);
  fee_fixed := coalesce(fee_fixed,0);
  fx        := coalesce(fx, 3.6725);

  -- 1) Reveal-fee revenue with Stripe fee split (refunded transactions excluded)
  for r in
    select id, reveal_fee, coalesce(revealed_at::date, current_date) as d
    from public.transactions
    where fee_status='paid' and coalesce(reveal_fee,0) > 0
      and coalesce(refund_status,'') not in ('refunded','refund_approved')
      and not exists (select 1 from public.gl_journal g where g.source='reveal_fee' and g.source_ref=transactions.id::text)
  loop
    gross := round(r.reveal_fee,2);
    fee   := round(gross*fee_pct/100 + fee_fixed, 2);
    if fee >= gross then fee := 0; end if;
    net   := gross - fee;
    perform public.fn_gl_entry(r.d, 'Reveal fee (net of Stripe fee)', 'reveal_fee', r.id::text,
      case when fee > 0 then
        jsonb_build_array(
          jsonb_build_object('account','1050','debit',net),
          jsonb_build_object('account','6100','debit',fee),
          jsonb_build_object('account','4000','credit',gross))
      else
        jsonb_build_array(
          jsonb_build_object('account','1050','debit',gross),
          jsonb_build_object('account','4000','credit',gross))
      end, 'gl_sync');
    n := n + 1;
  end loop;

  -- 1b) REFUND PAID OUT TO THE CUSTOMER (previously never posted at all).
  -- If revenue was booked before the refund, this also reverses its effect on the P&L.
  for r in
    select t.id, coalesce(t.reveal_fee, t.app_fee, 0) as amt,
           coalesce(t.refund_resolved_at::date, t.revealed_at::date, current_date) as d
    from public.transactions t
    where coalesce(t.refund_status,'') in ('refunded','refund_approved')
      and coalesce(coalesce(t.reveal_fee, t.app_fee), 0) > 0
      and not exists (select 1 from public.gl_journal g where g.source='refund_paid' and g.source_ref=t.id::text)
  loop
    gross := round(r.amt,2);
    perform public.fn_gl_entry(r.d, 'Reveal fee refunded to customer (paid from our balance)',
      'refund_paid', r.id::text,
      jsonb_build_array(jsonb_build_object('account','6900','debit',gross),
                        jsonb_build_object('account','1050','credit',gross)), 'gl_sync');
    n := n + 1;
  end loop;

  -- 2) Clawback RAISED on the supplier. Credits 6900 (recovering the refund), NOT 4100.
  --    Any admin fee / interest assessed at the same time is genuine income -> 4400.
  for r in
    select id, amount_due,
           coalesce(admin_fee,0) + coalesce(interest_amount,0) as extra_owed,
           coalesce(reveal_date, created_at::date, current_date) as d
    from public.supplier_dues
    where coalesce(amount_due,0) > 0
      and coalesce(status,'') not in ('waived','cancelled','reversed')
      and not exists (select 1 from public.gl_journal g where g.source='commission_accrue' and g.source_ref=supplier_dues.id::text)
  loop
    extra := round(coalesce(r.extra_owed,0),2);
    lines := jsonb_build_array(
      jsonb_build_object('account','1110','debit', round(r.amount_due,2) + extra),
      jsonb_build_object('account','6900','credit', round(r.amount_due,2)));
    if extra > 0 then lines := lines || jsonb_build_array(jsonb_build_object('account','4400','credit', extra)); end if;
    perform public.fn_gl_entry(r.d,
      'Refund clawback raised on supplier' || case when extra > 0 then ' (incl. ' || extra || ' admin fee/interest)' else '' end,
      'commission_accrue', r.id::text, lines, 'gl_sync');
    n := n + 1;
  end loop;

  -- 2b) Supplier SETTLES via Stripe.
  for r in
    select id, amount_due,
           coalesce(fine_amount,0) + coalesce(interest_amount,0) + coalesce(admin_fee,0) as extra_owed,
           paid_at::date as d
    from public.supplier_dues
    where status in ('paid','settled') and paid_at is not null and coalesce(amount_due,0) > 0
      and not exists (select 1 from public.gl_journal g where g.source='commission_collect' and g.source_ref=supplier_dues.id::text)
  loop
    extra := round(coalesce(r.extra_owed,0),2);
    gross := round(r.amount_due,2) + extra;
    fee   := round(gross*fee_pct/100 + fee_fixed, 2);
    if fee >= gross then fee := 0; end if;
    net   := gross - fee;

    lines := jsonb_build_array(jsonb_build_object('account','1050','debit',net));
    if fee > 0 then lines := lines || jsonb_build_array(jsonb_build_object('account','6100','debit',fee)); end if;
    lines := lines || jsonb_build_array(jsonb_build_object('account','1110','credit', gross));

    perform public.fn_gl_entry(r.d,
      'Refund clawback settled by supplier via Stripe' || case when extra > 0 then ' (incl. ' || extra || ' admin fee/interest)' else '' end,
      'commission_collect', r.id::text, lines, 'gl_sync');
    n := n + 1;
  end loop;

  -- 2c) SUBSCRIPTION revenue (RULE 1). Previously never posted - 4200 sat unused.
  for r in
    select l.id, l.registration_fee_due, l.registration_paid_at::date as d
    from public.leads l
    where l.registration_status = 'paid'
      and l.registration_paid_at is not null
      and coalesce(l.registration_fee_due,0) >= 0
      and coalesce(l.subscription_exempt,false) = false
      and not exists (select 1 from public.gl_journal g
                      where g.source='subscription' and g.source_ref = l.id::text || ':' || l.registration_paid_at::date)
  loop
    gross := round(coalesce(r.registration_fee_due,0),2);
    if gross <= 0 then continue; end if;
    fee := round(gross*fee_pct/100 + fee_fixed, 2);
    if fee >= gross then fee := 0; end if;
    net := gross - fee;
    lines := jsonb_build_array(jsonb_build_object('account','1050','debit',net));
    if fee > 0 then lines := lines || jsonb_build_array(jsonb_build_object('account','6100','debit',fee)); end if;
    lines := lines || jsonb_build_array(jsonb_build_object('account','4200','credit',gross));
    perform public.fn_gl_entry(r.d, 'Annual supplier subscription', 'subscription',
      r.id::text || ':' || r.d::text, lines, 'gl_sync');
    n := n + 1;
  end loop;

  -- 3) Expense charges, converted to AED (the ledger currency)
  for r in
    select e.id, e.amount, upper(coalesce(e.currency,'AED')) as cur, e.category, e.vendor,
           coalesce(e.charged_on, e.created_at::date) as d
    from public.expense_entries e
    where coalesce(e.amount,0) > 0
      and not exists (select 1 from public.gl_journal g where g.source='expense' and g.source_ref=e.id::text)
  loop
    if r.cur not in ('AED','USD') then
      begin
        insert into public.founder_alerts(level, event, detail, channel)
        values ('warn', 'gl_unconvertible_currency',
                'Expense #'||r.id||' from '||coalesce(r.vendor,'?')||' is in '||r.cur||
                ', which has no rate in gl_settings, so it was NOT posted. Expenses are understated by '||
                r.amount||' '||r.cur||' until a rate is added. Skipped rather than booked at 1:1.', 'system');
      exception when others then null; end;
      continue;
    end if;
    amt_aed := round(r.amount * case when r.cur='USD' then fx else 1 end, 2);
    acct := coalesce((select account_code from public.gl_expense_map m where m.category=r.category), '6300');
    perform public.fn_gl_entry(r.d,
      'Expense: '||coalesce(r.category,'G&A')||case when r.cur='USD' then ' ('||r.amount||' USD @ '||fx||')' else '' end,
      'expense', r.id::text,
      jsonb_build_array(jsonb_build_object('account',acct,'debit',amt_aed),
                        jsonb_build_object('account','1000','credit',amt_aed)), 'gl_sync');
    n := n + 1;
  end loop;

  -- 3b) One-off FX correction for USD expenses posted at 1:1 before the 19 Jul 2026 fix.
  for r in
    select e.id, e.amount, e.category, e.vendor,
           coalesce(e.charged_on, e.created_at::date) as d,
           (select sum(jl.debit) from public.gl_journal g
              join public.gl_journal_lines jl on jl.journal_id = g.id
             where g.source='expense' and g.source_ref = e.id::text and jl.debit > 0) as posted_aed
    from public.expense_entries e
    where upper(coalesce(e.currency,'AED')) = 'USD'
      and coalesce(e.amount,0) > 0
      and exists (select 1 from public.gl_journal g where g.source='expense' and g.source_ref=e.id::text)
      and not exists (select 1 from public.gl_journal g where g.source='expense_fx_adj' and g.source_ref=e.id::text)
  loop
    diff := round(r.amount * fx, 2) - coalesce(r.posted_aed, 0);
    if diff is null or diff = 0 then continue; end if;
    acct := coalesce((select account_code from public.gl_expense_map m where m.category=r.category), '6300');
    perform public.fn_gl_entry(r.d,
      'FX correction: expense #'||r.id||' ('||coalesce(r.vendor,'?')||') was booked at 1:1; restated at USD/AED '||fx,
      'expense_fx_adj', r.id::text,
      jsonb_build_array(jsonb_build_object('account',acct,'debit',diff),
                        jsonb_build_object('account','1000','credit',diff)), 'gl_fx_fix');
    n := n + 1;
  end loop;

  return n;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_goal_period_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v numeric; n int := 0;
begin
  for r in
    select gp.id, gp.goal_key, gp.target_value, g.measure_sql, g.direction
    from goal_period gp join company_goals g on g.key = gp.goal_key
    where g.active and g.measure_sql is not null
  loop
    v := null;
    begin execute r.measure_sql into v; exception when others then v := null; end;
    if v is not null then
      update goal_period
         set actual_value = v,
             status = case
               when r.target_value is null or r.target_value = 0 then 'tracking'
               when coalesce(r.direction,'up') = 'down'
                 then case when v <= r.target_value then 'on_track' else 'at_risk' end
                 else case when v >= r.target_value then 'on_track'
                           when v >= r.target_value * 0.9 then 'near' else 'at_risk' end
             end,
             updated_at = now()
       where id = r.id;
      n := n + 1;
    end if;
  end loop;

  insert into agent_runs (agent, started_at, finished_at, status, counts, note)
  values ('goal_period_refresh', now(), now(), 'ok', jsonb_build_object('updated', n),
          'Department/company goal periods refreshed from live measures: '||n||' rows updated.');
  return jsonb_build_object('updated', n);
end $function$


CREATE OR REPLACE FUNCTION public.fn_governance_stamp()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_sensitive boolean;
begin
  v_sensitive := (coalesce(NEW.agent,'') ~* 'legal|financ|complian|security'
                  or coalesce(NEW.kind,'') ~* 'legal|financ|complian|security|payment|refund|payout|pricing|price');

  -- Explainability: stamp a confidence + evidence basis when the caller did not provide one.
  -- These agents derive recommendations deterministically from live platform data, so the
  -- factual basis is high-confidence; the evidence line records exactly why.
  if NEW.confidence is null then
    NEW.confidence := 0.9;
    if NEW.evidence is null then
      NEW.evidence := jsonb_build_object('basis','deterministic rule from live platform data',
                                         'agent',NEW.agent,'kind',NEW.kind);
    end if;
  end if;

  -- Escalation marker (does not reroute status): low confidence or sensitive domain.
  if NEW.escalated is not true and (coalesce(NEW.confidence,0) < 0.6 or v_sensitive) then
    NEW.escalated := true;
    NEW.escalation_reason := coalesce(NEW.escalation_reason,
      case when coalesce(NEW.confidence,0) < 0.6
           then 'Confidence below 0.60 threshold — human review required.'
           else 'Sensitive domain (legal/financial/compliance/security) — human review required.' end);
  end if;

  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.fn_graph_rebuild()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare n_nodes int := 0; n_edges int := 0;
begin
  delete from graph_edges; delete from graph_nodes;

  insert into graph_nodes (kind, ref_id, label)
  select 'operating_system', os_key, name from operating_system where active
  union all select 'department', dept_key, name from org_departments where active
  union all select 'employee', agent_key, coalesce(title, agent_key) from org_agents where active
  union all select 'category', slug, name from catalog_supplier_categories
  union all select 'goal', key, goal from company_goals where active
  union all select 'workflow', workflow_key, name from workflow
  union all select 'responsibility', responsibility, responsibility from os_responsibility
  on conflict do nothing;
  get diagnostics n_nodes = row_count;

  insert into graph_edges (src_kind, src_ref, rel, dst_kind, dst_ref)
  select 'operating_system', os_key, 'contains', 'department', dept_key from os_department
  union all
  select 'department', a.department, 'employs', 'employee', a.agent_key from org_agents a where a.active
  union all
  select 'employee', manager_key, 'manages', 'employee', agent_key from org_agents where active and manager_key is not null
  union all
  select 'operating_system', os_key, 'owns', 'responsibility', responsibility from os_responsibility
  union all
  select 'operating_system', os_key, 'runs', 'workflow', workflow_key from workflow where os_key is not null
  union all
  select distinct 'employee', k.agent_key, 'accountable_for', 'goal', k.serves_goal
    from employee_kpi k where k.active and k.serves_goal is not null
     and exists (select 1 from company_goals g where g.key=k.serves_goal and g.active)
     and exists (select 1 from org_agents a where a.agent_key=k.agent_key and a.active)
  union all
  select distinct 'category', c.slug, 'served_by', 'employee', m.agent_slug
    from category_agent_map m join catalog_supplier_categories c on c.slug=m.catalog_slug
   where exists (select 1 from org_agents a where a.agent_key=m.agent_slug and a.active)
  on conflict do nothing;
  get diagnostics n_edges = row_count;

  insert into agent_runs (agent,started_at,finished_at,status,counts,note)
  values ('graph_rebuild',now(),now(),'ok',jsonb_build_object('nodes',n_nodes,'edges',n_edges),
    'Company brain rebuilt: '||n_nodes||' nodes, '||n_edges||' edges.');
  return jsonb_build_object('nodes',n_nodes,'edges',n_edges);
end $function$


CREATE OR REPLACE FUNCTION public.fn_group_dispatch_report(p_group_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_gd public.v_group_dispatch%rowtype; v_blockers jsonb := '[]'::jsonb; r record;
        v_active jsonb; v_out jsonb; v_opt jsonb; v_conf jsonb; v_comp jsonb; v_n_active int;
begin
  select * into v_gd from public.v_group_dispatch where group_id = p_group_id;
  if not found then return jsonb_build_object('ok', false, 'error', 'unknown_group'); end if;

  select coalesce(jsonb_agg(jsonb_build_object('trade', trade_key, 'disposition', disposition)
                            order by trade_key), '[]'::jsonb), count(*)
    into v_active, v_n_active from public.v_trade_scope_status
   where group_id = p_group_id and coalesce(contributes,false) and coalesce(workstream_active,false);
  select coalesce(jsonb_agg(jsonb_build_object('trade', trade_key, 'disposition', disposition,
                                               'reason', reason) order by trade_key), '[]'::jsonb)
    into v_out from public.v_trade_scope_status
   where group_id = p_group_id and disposition in ('excluded','by_others','client_supplied');
  select coalesce(jsonb_agg(jsonb_build_object('trade', trade_key, 'disposition', disposition,
                                               'reason', reason) order by trade_key), '[]'::jsonb)
    into v_opt from public.v_trade_scope_status
   where group_id = p_group_id and disposition in ('optional','future_phase','proposed','unknown');
  select coalesce(jsonb_agg(jsonb_build_object('trade', trade_key, 'clauses', clause_indexes,
                                               'reason', reason) order by trade_key), '[]'::jsonb)
    into v_conf from public.v_trade_scope_status
   where group_id = p_group_id and coalesce(is_conflict,false);
  select coalesce(jsonb_agg(jsonb_build_object('trade', trade_key, 'component', scope_component,
                                               'disposition', disposition) order by trade_key, scope_component), '[]'::jsonb)
    into v_comp from public.v_scope_disposition_effective
   where group_id = p_group_id and scope_component <> 'complete_trade_scope' and disposition <> 'included';

  if v_n_active = 0 then
    if jsonb_array_length(v_conf) > 0 then
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
        'blocker','scope_confirmation_required','severity','blocking','conflicts', v_conf,
        'detail','Contradictory scope statements of equal specificity. The customer must say which applies.',
        'remedy','Answer the open clarification.'));
    else
      v_blockers := v_blockers || jsonb_build_array(public.fn_p2c1_no_active_trade_blocker(v_out, v_opt));
    end if;
  elsif jsonb_array_length(v_conf) > 0 then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'blocker','scope_confirmation_required','severity','blocking','conflicts', v_conf,
      'detail','Some trades are active but an unresolved scope conflict remains.'));
  end if;

  if cardinality(v_gd.shared_missing_mandatory) > 0 then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'blocker','shared_mandatory_missing','severity','blocking',
      'fields', to_jsonb(v_gd.shared_missing_mandatory),
      'detail','Shared project fields required by an active workstream are unanswered.'));
  end if;
  if not v_gd.no_unresolved_shared_conflict then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'blocker','open_shared_conflict','severity','blocking',
      'fields', (select coalesce(jsonb_agg(c.field_id), '[]'::jsonb)
                   from public.inquiry_answer_conflict c
                   join public.field_definition fd on fd.field_id = c.field_id
                  where c.group_id = p_group_id and c.resolved_at is null and fd.scope = 'shared'),
      'detail','A shared field has sources that disagree. Every workstream is affected.'));
  end if;
  for r in select * from public.v_workstream_dispatch
            where group_id = p_group_id and active and not dispatch_eligible loop
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'blocker','trade_not_eligible','severity','blocking','trade_key', r.trade_key,
      'missing_mandatory', to_jsonb(r.missing_mandatory),
      'unresolved_conflicts', to_jsonb(r.blocked_by), 'gate_states', r.gate_states,
      'detail','This trade is not dispatch-eligible, so the group is not.'));
  end loop;
  for r in select gr.gate_key,
                  coalesce((select g.state::text from public.inquiry_gate g
                             where g.group_id = p_group_id and g.workstream_id is null
                               and g.gate_key = gr.gate_key), 'not_evaluated') as state
             from public.inquiry_gate_required gr where gr.level = 'group' loop
    if r.state not in ('passed','not_applicable') then
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
        'blocker','group_gate_not_satisfied','severity','blocking','gate_key', r.gate_key,
        'state', r.state,
        'detail', case when r.state = 'not_evaluated'
                       then 'This gate has never been evaluated. Absent reads as failed.'
                       else 'Gate state is ' || r.state || '.' end));
    end if;
  end loop;
  if jsonb_array_length(v_comp) > 0 then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'blocker','component_scope_restriction','severity','informational','restrictions', v_comp,
      'detail','Parts of an active trade are out of scope. The trade still dispatches; the RFQ must carry the restriction.'));
  end if;
  for r in select trade_key, evidence_score, score_basis, evidence_source
             from public.inquiry_trade_candidate
            where group_id = p_group_id and status = 'proposed' loop
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'blocker','trade_awaiting_confirmation','severity','informational','trade_key', r.trade_key,
      'evidence_source', r.evidence_source, 'evidence_score', r.evidence_score,
      'score_basis', r.score_basis,
      'detail','Proposed but not confirmed. It contributes nothing to dispatch until a person confirms it.'));
  end loop;
  if exists (select 1 from public.inquiry_trade_clarification
              where group_id = p_group_id and answered_at is null) then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'blocker','open_clarification','severity','blocking',
      'question', (select question_en from public.inquiry_trade_clarification
                    where group_id = p_group_id and answered_at is null limit 1),
      'detail','The customer has been asked to settle the scope.'));
  end if;

  return jsonb_build_object(
    'ok', true, 'group_id', p_group_id,
    'overall_dispatch_eligible', (v_gd.overall_dispatch_eligible and v_n_active > 0
                                  and jsonb_array_length(v_conf) = 0),
    'active_included_trades', v_active, 'excluded_or_by_others_trades', v_out,
    'optional_or_future_trades', v_opt, 'unresolved_scope_conflicts', v_conf,
    'component_scope_restrictions', v_comp,
    'active_workstreams', v_gd.active_workstreams, 'shared_complete', v_gd.shared_complete,
    'group_gate_states', v_gd.gate_states, 'blocking_trades', to_jsonb(v_gd.blocking_trades),
    'blockers', v_blockers, 'blocker_count', jsonb_array_length(v_blockers));
end $function$


CREATE OR REPLACE FUNCTION public.fn_health_index()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  s_acq numeric; s_supp numeric; s_rfq numeric; s_qual numeric;
  s_resp numeric; s_disp numeric; s_up numeric;
  signups_7d int; quotes_7d int; approved_suppliers int;
  inq_total int; inq_done int; avg_qual numeric; avg_resp numeric;
  blocked_30d int; msgs_30d int; up_ok int; up_tot int;
  parts numeric[]; overall numeric; band text; present int;
begin
  select count(*) into signups_7d from customers where created_at > now()-interval '7 days';
  select count(*) into quotes_7d  from quotes    where created_at > now()-interval '7 days';
  select count(*) into approved_suppliers from leads
     where coalesce(approval_status,'')='approved' or claimed=true;
  -- RFQ completion: real RFQs only (exclude split-parent containers and customer-cancelled),
  -- success = completed/won or closed-with-a-hire (a "closed, not hired" is NOT a completion).
  select count(*) filter (where created_at > now()-interval '90 days'
                            and coalesce(status,'')<>'split' and coalesce(category,'')<>'combined'
                            and coalesce(status,'')<>'cancelled'),
         count(*) filter (where created_at > now()-interval '90 days'
                            and coalesce(status,'')<>'split' and coalesce(category,'')<>'combined'
                            and (status in ('completed','won')
                                 or (status='closed' and coalesce(outcome,'') in ('hired','hired_elsewhere'))))
    into inq_total, inq_done from inquiries;
  select avg(nullif(quality->>'score','')::numeric) into avg_qual
    from quotes where quality is not null and created_at > now()-interval '90 days';
  select avg(nullif(rv_response_rate,0)) into avg_resp
    from leads where coalesce(rv_reveals,0) > 0;
  select count(*) filter (where coalesce(blocked,false)),
         count(*) into blocked_30d, msgs_30d
    from messages where created_at > now()-interval '30 days';
  select count(*) filter (where ok), count(*) into up_ok, up_tot
    from health_checks where created_at > now()-interval '24 hours';

  s_acq  := least(100, signups_7d * 10.0);
  s_supp := case when approved_suppliers=0 and quotes_7d=0 then null
                 else least(100, quotes_7d * 5.0) end;
  s_rfq  := case when inq_total=0 then null else round(inq_done::numeric/inq_total*100,1) end;
  s_qual := avg_qual;
  s_resp := case when avg_resp is null then null
                 when avg_resp <= 1 then round(avg_resp*100,1) else round(avg_resp,1) end;
  s_disp := case when msgs_30d=0 then null
                 else greatest(0, 100 - least(100, blocked_30d*5.0)) end;
  s_up   := case when up_tot=0 then null else round(up_ok::numeric/up_tot*100,1) end;

  parts := array_remove(array[s_acq,s_supp,s_rfq,s_qual,s_resp,s_disp,s_up], null);
  present := coalesce(array_length(parts,1),0);
  overall := case when present=0 then null else round((select avg(x) from unnest(parts) x),1) end;
  band := case when overall is null then 'no data'
               when overall >= 75 then 'healthy'
               when overall >= 50 then 'watch'
               else 'attention' end;

  return jsonb_build_object(
    'index', overall, 'band', band, 'components_present', present,
    'note', case when present < 3 then 'insufficient data — pre-traction; index will firm up with volume' else null end,
    'components', jsonb_build_object(
       'customer_acquisition', s_acq, 'supplier_activity', s_supp, 'rfq_completion', s_rfq,
       'quote_quality', s_qual, 'response_time', s_resp, 'dispute_health', s_disp,
       'uptime', s_up, 'revenue', null),
    'raw', jsonb_build_object(
       'signups_7d', signups_7d, 'quotes_7d', quotes_7d, 'approved_suppliers', approved_suppliers,
       'inquiries_eligible_90d', inq_total, 'completed_90d', inq_done,
       'blocked_msgs_30d', blocked_30d, 'uptime_ok', up_ok, 'uptime_checks', up_tot),
    'computed_at', now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_idea_rescore()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  new.score := public.fn_idea_score(new.expected_value_aed, new.effort, new.confidence);
  new.updated_at := now();
  return new;
end; $function$


CREATE OR REPLACE FUNCTION public.fn_idea_score(p_value numeric, p_effort text, p_confidence numeric)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select round(
    coalesce(p_value,0)
    * coalesce(p_confidence,0.5)
    / case lower(coalesce(p_effort,'m'))
        when 's' then 1 when 'small' then 1
        when 'm' then 3 when 'medium' then 3
        when 'l' then 8 when 'large' then 8
        when 'xl' then 20 else 3 end
  , 2);
$function$


CREATE OR REPLACE FUNCTION public.fn_identify_contact(p_phone text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_d text; v_tail text; v_name text; v_sid bigint; v_cid text; v_claimed boolean; v_appr boolean;
begin
  v_d := regexp_replace(coalesce(p_phone,''), '[^0-9]', '', 'g');
  if length(v_d) < 7 then return json_build_object('audience','unknown'); end if;
  v_tail := right(v_d, 9);   -- tolerate +9715..., 05..., 5... variants

  select id, company_name, coalesce(claimed,false), (approval_status='approved')
    into v_sid, v_name, v_claimed, v_appr
   from leads
   where right(regexp_replace(coalesce(phone_e164,''),'[^0-9]','','g'),9) = v_tail
      or right(regexp_replace(coalesce(phone,''),'[^0-9]','','g'),9) = v_tail
      or right(regexp_replace(coalesce(whatsapp,''),'[^0-9]','','g'),9) = v_tail
   limit 1;
  if v_sid is not null then
    return json_build_object('audience','supplier','name',v_name,'claimed',v_claimed,'approved',coalesce(v_appr,false));
  end if;

  select id::text, full_name into v_cid, v_name from customers
   where right(regexp_replace(coalesce(phone,''),'[^0-9]','','g'),9) = v_tail
   limit 1;
  if v_cid is not null then
    return json_build_object('audience','customer','name',v_name);
  end if;

  return json_build_object('audience','unknown');
end $function$


CREATE OR REPLACE FUNCTION public.fn_inbox_list()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'kpis', jsonb_build_object(
      'needs_review', (select count(*) from public.inbound_messages where needs_review=true and replied_at is null),
      'untriaged', (select count(*) from public.inbound_messages where needs_review=true and triaged_at is null and replied_at is null),
      'replied_7d', (select count(*) from public.inbound_messages where replied_at > now()-interval '7 days')),
    'rows', coalesce((select jsonb_agg(jsonb_build_object(
        'id',id,'from_email',from_email,'subject',subject,'body',left(coalesce(body,''),1200),
        'category',ai_category,'summary',ai_summary,'draft',ai_draft_reply,
        'triaged_at',triaged_at,'created_at',created_at) order by created_at desc)
      from (select * from public.inbound_messages
             where needs_review=true and replied_at is null order by created_at desc limit 50) m),'[]'::jsonb)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_inbox_send(p_id bigint, p_body text, p_by text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare m public.inbound_messages%rowtype;
begin
  select * into m from public.inbound_messages where id=p_id;
  if m.id is null then return jsonb_build_object('error','message not found'); end if;
  if m.from_email is null then return jsonb_build_object('error','no sender address'); end if;
  if coalesce(trim(p_body),'')='' then return jsonb_build_object('error','empty reply'); end if;

  insert into public.notifications(type,to_email,to_role,channel,subject,body)
    values('inbound_reply', m.from_email, null, 'email',
           case when coalesce(m.subject,'') ilike 're:%' then m.subject else 'Re: '||coalesce(m.subject,'your message') end,
           p_body);

  update public.inbound_messages set replied_at=now(), replied_by=coalesce(p_by,'founder'), needs_review=false where id=p_id;
  update public.agent_actions set status='approved', decided_by=coalesce(p_by,'founder'), decided_at=now()
   where target_table='inbound_messages' and target_id=p_id::text
     and status in ('pending','held_for_review','proposed','open');
  return jsonb_build_object('ok',true, 'to', m.from_email);
end $function$


CREATE OR REPLACE FUNCTION public.fn_inquiry_answer_confirm(p_group_id bigint, p_field_id text, p_value text, p_confirmed_by text, p_reason text, p_workstream_ids bigint[] DEFAULT NULL::bigint[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_res jsonb; v_conflict_id bigint; v_kept integer;
begin
  if coalesce(btrim(p_confirmed_by),'') = '' or coalesce(btrim(p_reason),'') = '' then
    return jsonb_build_object('ok', false, 'error', 'who_and_why_required');
  end if;

  select id into v_conflict_id from public.inquiry_answer_conflict
   where group_id = p_group_id and field_id = p_field_id and resolved_at is null;

  v_res := public.fn_inquiry_answer_set(p_group_id, p_field_id, p_value, 'customer_confirmed',
             'customer', p_confirmed_by, null, p_workstream_ids, null);
  if not (v_res->>'ok')::boolean then return v_res; end if;

  if v_conflict_id is not null then
    insert into public.inquiry_answer_conflict_value (conflict_id, value, precedence, source_kind)
    values (v_conflict_id, p_value, 'customer_confirmed', 'customer');
    update public.inquiry_answer_conflict
       set resolved_at = now(), resolved_by = p_confirmed_by, resolution_reason = p_reason
     where id = v_conflict_id;
    select count(*) into v_kept from public.inquiry_answer_conflict_value where conflict_id = v_conflict_id;
  end if;

  insert into public.inquiry_state_audit (group_id, event, detail, actor)
  values (p_group_id, 'conflict_resolved_by_confirmation',
          jsonb_build_object('field_id', p_field_id, 'conflict_id', v_conflict_id,
                             'reason', p_reason, 'evidence_values_kept', v_kept), p_confirmed_by);

  return jsonb_build_object('ok', true, 'action', v_res->>'action', 'conflict_id', v_conflict_id,
                            'evidence_values_kept', v_kept);
end $function$


CREATE OR REPLACE FUNCTION public.fn_inquiry_answer_set(p_group_id bigint, p_field_id text, p_value text, p_precedence answer_precedence, p_source_kind text, p_actor text DEFAULT 'system'::text, p_unit text DEFAULT NULL::text, p_workstream_ids bigint[] DEFAULT NULL::bigint[], p_document jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_fd public.field_definition%rowtype; v_answer_scope text;
  v_live public.inquiry_answer%rowtype; v_new_id bigint; v_conflict_id bigint;
  v_norm_new text; v_norm_live text; v_rank_new integer; v_rank_live integer;
  v_ws bigint; v_bad_ws bigint[]; v_action text;
begin
  select * into v_fd from public.field_definition where field_id = p_field_id;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'unknown_field', 'field_id', p_field_id);
  end if;
  if not exists (select 1 from public.inquiry_workstream_group where id = p_group_id) then
    return jsonb_build_object('ok', false, 'error', 'unknown_group');
  end if;

  v_answer_scope := case v_fd.scope when 'shared' then 'inquiry_shared' else v_fd.scope end;

  if v_fd.scope <> 'shared' then
    if p_workstream_ids is null or array_length(p_workstream_ids, 1) is null then
      return jsonb_build_object('ok', false, 'error', 'workstream_required',
        'message', 'A trade-specific answer must say which workstream it belongs to.');
    end if;
    select array_agg(w.id) into v_bad_ws
      from public.inquiry_workstream w
     where w.id = any(p_workstream_ids)
       and (w.group_id <> p_group_id
            or (v_fd.scope = 'trade_specific' and w.trade_key <> v_fd.trade_key)
            or (v_fd.scope = 'trade_subset' and not exists (
                  select 1 from public.field_definition_trade t
                   where t.field_id = v_fd.field_id and t.trade_key = w.trade_key)));
    if v_bad_ws is not null then
      return jsonb_build_object('ok', false, 'error', 'trade_mismatch',
        'field_id', p_field_id, 'field_trade', v_fd.trade_key, 'rejected_workstreams', v_bad_ws,
        'message', 'This field belongs to another trade. A trade-specific answer cannot satisfy a workstream that does not own the field.');
    end if;
    if (select count(*) from public.inquiry_workstream
         where id = any(p_workstream_ids)) <> array_length(p_workstream_ids, 1) then
      return jsonb_build_object('ok', false, 'error', 'unknown_workstream');
    end if;
  end if;

  select * into v_live from public.inquiry_answer
   where group_id = p_group_id and field_id = p_field_id and superseded_by is null;

  if not found then
    insert into public.inquiry_answer (group_id, field_id, value, unit, scope, precedence,
                                       source_kind, confirmed_at, confirmed_by)
    values (p_group_id, p_field_id, p_value, coalesce(p_unit, v_fd.unit), v_answer_scope,
            p_precedence, p_source_kind,
            case when p_precedence = 'customer_confirmed' then now() end,
            case when p_precedence = 'customer_confirmed' then p_actor end)
    returning id into v_new_id;
    v_action := 'inserted';
  else
    v_rank_new  := public.fn_answer_precedence_rank(p_precedence);
    v_rank_live := public.fn_answer_precedence_rank(v_live.precedence);
    v_norm_new  := public.fn_field_normalise(p_field_id, p_value);
    v_norm_live := public.fn_field_normalise(p_field_id, v_live.value);

    if v_rank_new < v_rank_live
       or (v_rank_new = v_rank_live and p_precedence = 'customer_confirmed'
           and v_norm_new is distinct from v_norm_live) then
      v_new_id := public.fn_inquiry_answer_supersede(v_live.id, p_group_id, p_field_id, p_value,
                    coalesce(p_unit, v_fd.unit), v_answer_scope, p_precedence, p_source_kind, p_actor);
      v_action := 'superseded';

    elsif v_norm_new is not distinct from v_norm_live then
      v_new_id := v_live.id;
      insert into public.inquiry_answer_corroboration
        (answer_id, value, normalised_value, precedence, source_kind, document_id)
      values (v_live.id, p_value, v_norm_new, p_precedence, p_source_kind, p_document->>'document_id');
      v_action := 'corroborated';

    else
      v_new_id := v_live.id;
      select id into v_conflict_id from public.inquiry_answer_conflict
       where group_id = p_group_id and field_id = p_field_id and resolved_at is null;
      if v_conflict_id is null then
        insert into public.inquiry_answer_conflict (group_id, field_id, blocking_scope)
        values (p_group_id, p_field_id,
                case when v_fd.scope = 'shared' then 'shared' else 'trade' end)
        returning id into v_conflict_id;
        insert into public.inquiry_answer_conflict_value (conflict_id, value, precedence, source_kind)
        values (v_conflict_id, v_live.value, v_live.precedence, v_live.source_kind);
      end if;
      insert into public.inquiry_answer_conflict_value
        (conflict_id, value, precedence, source_kind, document_id)
      values (v_conflict_id, p_value, p_precedence, p_source_kind, p_document->>'document_id');
      v_action := 'conflict_opened';
    end if;
  end if;

  if v_fd.scope <> 'shared' and v_action in ('inserted','superseded') then
    foreach v_ws in array p_workstream_ids loop
      insert into public.inquiry_answer_scope (answer_id, workstream_id)
      values (v_new_id, v_ws) on conflict do nothing;
    end loop;
  end if;

  if p_document is not null and v_action in ('inserted','superseded') then
    insert into public.inquiry_answer_document
      (answer_id, document_id, page_or_sheet, extraction_confidence, original_text, assigned_scope)
    values (v_new_id, p_document->>'document_id', p_document->>'page_or_sheet',
            (p_document->>'extraction_confidence')::numeric, p_document->>'original_text', v_answer_scope);
  end if;

  insert into public.inquiry_state_audit (group_id, event, detail, actor)
  values (p_group_id, 'answer_' || v_action,
          jsonb_build_object('field_id', p_field_id, 'precedence', p_precedence,
                             'source_kind', p_source_kind, 'answer_id', v_new_id,
                             'conflict_id', v_conflict_id), p_actor);

  return jsonb_build_object('ok', true, 'action', v_action, 'answer_id', v_new_id,
                            'field_id', p_field_id, 'conflict_id', v_conflict_id,
                            'scope', v_answer_scope);
end $function$


CREATE OR REPLACE FUNCTION public.fn_inquiry_answer_supersede(p_live_id bigint, p_group_id bigint, p_field_id text, p_value text, p_unit text, p_scope text, p_precedence answer_precedence, p_source_kind text, p_actor text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_new_id bigint;
begin
  v_new_id := nextval(pg_get_serial_sequence('public.inquiry_answer','id'));
  update public.inquiry_answer set superseded_by = v_new_id where id = p_live_id;
  insert into public.inquiry_answer (id, group_id, field_id, value, unit, scope, precedence,
                                     source_kind, confirmed_at, confirmed_by)
  values (v_new_id, p_group_id, p_field_id, p_value, p_unit, p_scope, p_precedence, p_source_kind,
          case when p_precedence = 'customer_confirmed' then now() end,
          case when p_precedence = 'customer_confirmed' then p_actor end);
  insert into public.inquiry_answer_scope (answer_id, workstream_id)
    select v_new_id, workstream_id from public.inquiry_answer_scope where answer_id = p_live_id
    on conflict do nothing;
  return v_new_id;
end $function$


CREATE OR REPLACE FUNCTION public.fn_inquiry_dispatch_eligible(p_inquiry_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with ws as (
    select d.workstream_id, d.trade_key, d.dispatch_eligible, d.mandatory_complete,
           d.no_unresolved_conflict, d.gates_passed, d.missing_mandatory, d.blocked_by
    from public.inquiry_workstream_group g
    join public.inquiry_workstream w on w.group_id = g.id
    join public.v_workstream_dispatch d on d.workstream_id = w.id
    where g.inquiry_id = p_inquiry_id and w.active
  )
  select case
    when (select count(*) from ws) = 0
      then jsonb_build_object('eligible', true, 'reason', 'no_workstreams', 'workstreams', 0)
    when (select bool_and(dispatch_eligible) from ws)
      then jsonb_build_object('eligible', true, 'reason', 'all_workstreams_eligible',
                              'workstreams', (select count(*) from ws))
    else jsonb_build_object(
      'eligible', false,
      'reason', 'workstream_not_dispatch_eligible',
      'workstreams', (select count(*) from ws),
      'blocking', (select jsonb_agg(jsonb_build_object(
          'workstream_id', workstream_id, 'trade', trade_key,
          'mandatory_complete', mandatory_complete,
          'no_unresolved_conflict', no_unresolved_conflict,
          'gates_passed', gates_passed,
          'missing_mandatory', to_jsonb(missing_mandatory),
          'blocked_by', to_jsonb(blocked_by)))
        from ws where not dispatch_eligible))
  end;
$function$


CREATE OR REPLACE FUNCTION public.fn_inquiry_interpret(p_group_id bigint, p_customer_text text DEFAULT NULL::text, p_structured jsonb DEFAULT NULL::jsonb, p_documents jsonb DEFAULT NULL::jsonb, p_actor text DEFAULT 'system'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id jsonb; v_n integer; v_apply jsonb; v_active text[]; v_conf boolean;
begin
  v_id := public.fn_trade_identify(p_group_id, p_customer_text, p_structured, p_documents, p_actor);
  if not coalesce((v_id->>'ok')::boolean,false) then return v_id; end if;

  v_n := public.fn_scope_detect(p_group_id, p_customer_text, p_actor);
  v_apply := public.fn_scope_apply(p_group_id, p_actor);

  select coalesce(array_agg(trade_key order by trade_key),'{}') into v_active
    from public.inquiry_workstream where group_id = p_group_id and active;
  select exists (select 1 from public.v_trade_scope_status
                  where group_id = p_group_id and is_conflict) into v_conf;

  -- Nothing active, or an unresolved scope conflict, must ask.
  if cardinality(v_active) = 0 or v_conf then
    insert into public.inquiry_trade_clarification (group_id, question_en, question_ar, options, reason)
    select p_group_id,
           case when v_conf then 'Two statements in your enquiry disagree about scope. Which applies?'
                else 'Which trades does this enquiry cover?' end,
           case when v_conf then 'هناك عبارتان متعارضتان بشأن نطاق العمل. أيهما ينطبق؟'
                else 'ما هي التخصصات التي يشملها هذا الطلب؟' end,
           coalesce((select array_agg(distinct trade_key) from public.v_trade_scope_status
                      where group_id = p_group_id and (is_conflict or not coalesce(contributes,false))),
                    array['hvac','electrical','plumbing','fire','elv']),
           case when v_conf then 'Contradictory scope statements of equal specificity. Resolved by asking, never by preferring the last sentence.'
                else 'Every detected trade is excluded, by others, optional, future-phase or unresolved.' end
    where not exists (select 1 from public.inquiry_trade_clarification c
                       where c.group_id = p_group_id and c.answered_at is null);
  end if;

  return jsonb_build_object('ok', true, 'identification', v_id, 'dispositions_recorded', v_n,
                            'scope_applied', v_apply,
                            'active_trades', to_jsonb(v_active),
                            'scope_conflict', v_conf,
                            'clarification_required',
                              exists (select 1 from public.inquiry_trade_clarification
                                       where group_id = p_group_id and answered_at is null));
end $function$


CREATE OR REPLACE FUNCTION public.fn_inquiry_workstream_activate(p_group_id bigint, p_trade_key text, p_actor text DEFAULT 'system'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_ws_id bigint; v_route integer; v_reactivated boolean := false; v_reqs integer;
begin
  if not exists (select 1 from public.mep_trade where trade_key = p_trade_key) then
    return jsonb_build_object('ok', false, 'error', 'unknown_trade', 'trade_key', p_trade_key);
  end if;
  if not exists (select 1 from public.inquiry_workstream_group where id = p_group_id) then
    return jsonb_build_object('ok', false, 'error', 'unknown_group');
  end if;

  select catalog_num into v_route from public.mep_trade_route
   where trade_key = p_trade_key and is_primary order by catalog_num limit 1;

  select id into v_ws_id from public.inquiry_workstream
   where group_id = p_group_id and trade_key = p_trade_key;

  if v_ws_id is null then
    insert into public.inquiry_workstream (group_id, trade_key, route_catalog_num)
    values (p_group_id, p_trade_key, v_route) returning id into v_ws_id;
  else
    update public.inquiry_workstream
       set active = true, activated_at = now(), deactivated_at = null
     where id = v_ws_id and active = false;
    v_reactivated := found;
    update public.inquiry_workstream set active = true where id = v_ws_id;
  end if;

  insert into public.inquiry_workstream_requirement (workstream_id, question_id, field_id, mandatory)
  select v_ws_id, min(q.question_id), s.field_id, bool_or(q.mandatory)
    from public.mep_trade_route tr
    join public.kb_operational_route_map m on m.catalog_num = tr.catalog_num
    join kb_stage.questions q on q.subcategory_slug = m.subcategory_slug
    join public.field_definition_source s
      on s.subcategory_slug = q.subcategory_slug and s.source_field_key = q.field_key
    left join public.subcategory_trade_contribution c
      on c.subcategory_slug = m.subcategory_slug and c.catalog_num = tr.catalog_num
     and c.trade_key = tr.trade_key
   where tr.trade_key = p_trade_key and q.field_key is not null
     and coalesce(c.contribution, 'technical') <> 'excluded'
     and (coalesce(c.contribution, 'technical') <> 'regulatory'
          or q.field_key = any(coalesce(c.contributed_field_keys, '{}'::text[])))
     and not exists (select 1 from public.field_definition_reference r
                      where r.field_id = s.field_id and r.referencing_trade_key = p_trade_key)
   group by s.field_id
  on conflict (workstream_id, field_id) do update
     set mandatory = public.inquiry_workstream_requirement.mandatory or excluded.mandatory;

  get diagnostics v_reqs = row_count;

  insert into public.inquiry_state_audit (group_id, workstream_id, event, detail, actor)
  values (p_group_id, v_ws_id,
          case when v_reactivated then 'workstream_reactivated' else 'workstream_activated' end,
          jsonb_build_object('trade_key', p_trade_key, 'route_catalog_num', v_route,
                             'requirements', v_reqs), p_actor);

  return jsonb_build_object('ok', true, 'workstream_id', v_ws_id, 'trade_key', p_trade_key,
                            'reactivated', v_reactivated, 'requirements', v_reqs);
end $function$


CREATE OR REPLACE FUNCTION public.fn_inquiry_workstream_deactivate(p_group_id bigint, p_trade_key text, p_actor text DEFAULT 'system'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_ws_id bigint;
begin
  update public.inquiry_workstream
     set active = false, deactivated_at = now()
   where group_id = p_group_id and trade_key = p_trade_key and active
   returning id into v_ws_id;
  if v_ws_id is null then
    return jsonb_build_object('ok', false, 'error', 'not_active');
  end if;
  insert into public.inquiry_state_audit (group_id, workstream_id, event, detail, actor)
  values (p_group_id, v_ws_id, 'workstream_deactivated',
          jsonb_build_object('trade_key', p_trade_key), p_actor);
  return jsonb_build_object('ok', true, 'workstream_id', v_ws_id);
end $function$


CREATE OR REPLACE FUNCTION public.fn_internal_auth(p_secret text, p_function text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare c public.internal_credential%rowtype; v_hash text; v_fn text;
begin
  v_fn := lower(btrim(coalesce(p_function, '')));
  if v_fn = '' then
    insert into public.internal_credential_audit (allowed, reason, function_name)
    values (false, 'no_function_named', p_function);
    return jsonb_build_object('ok', false, 'error', 'no_function_named',
      'message', 'The verifier was called without naming the function being invoked, so it cannot check scope.');
  end if;

  if coalesce(btrim(p_secret), '') = '' then
    insert into public.internal_credential_audit (allowed, reason, function_name)
    values (false, 'no_credential_presented', v_fn);
    return jsonb_build_object('ok', false, 'error', 'no_credential_presented');
  end if;

  v_hash := public.fn_internal_credential_hash(p_secret);
  select * into c from public.internal_credential where secret_hash = v_hash;

  if not found then
    insert into public.internal_credential_audit (allowed, reason, function_name)
    values (false, 'unknown_credential', v_fn);
    return jsonb_build_object('ok', false, 'error', 'unknown_credential');
  end if;

  if not c.active or c.retired_at is not null then
    insert into public.internal_credential_audit (credential_id, context, function_name, allowed, reason)
    values (c.id, c.context, v_fn, false, 'credential_retired');
    return jsonb_build_object('ok', false, 'error', 'credential_retired', 'context', c.context);
  end if;

  if c.expires_at is not null and c.expires_at <= now() then
    insert into public.internal_credential_audit (credential_id, context, function_name, allowed, reason)
    values (c.id, c.context, v_fn, false, 'credential_expired');
    return jsonb_build_object('ok', false, 'error', 'credential_expired', 'context', c.context,
      'expired_at', c.expires_at);
  end if;

  if not (c.scope @> array['*'] or c.scope @> array[v_fn]) then
    insert into public.internal_credential_audit (credential_id, context, function_name, allowed, reason, detail)
    values (c.id, c.context, v_fn, false, 'out_of_scope', jsonb_build_object('scope', c.scope));
    return jsonb_build_object('ok', false, 'error', 'out_of_scope', 'context', c.context,
      'message', format('The %s credential is not scoped to call %s.', c.context, v_fn));
  end if;

  update public.internal_credential
     set last_used_at = now(), last_function = v_fn, use_count = use_count + 1
   where id = c.id;

  -- THE ADDITION. Legacy only.
  if c.is_legacy then
    insert into public.internal_credential_audit (credential_id, context, function_name, allowed, reason)
    values (c.id, c.context, v_fn, true, 'legacy_secret_used');
  end if;

  return jsonb_build_object('ok', true, 'context', c.context, 'credential_id', c.id,
                            'legacy', c.is_legacy, 'scope_all', c.scope @> array['*']);
end $function$


CREATE OR REPLACE FUNCTION public.fn_internal_credential_audit_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  raise exception 'internal_credential_audit is append-only; % is not permitted', TG_OP using errcode = '42501';
end $function$


CREATE OR REPLACE FUNCTION public.fn_internal_credential_hash(p_secret text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
  select encode(extensions.hmac(p_secret,
           (select value from public.app_secrets where key = 'internal_credential_hmac_key'),
           'sha256'), 'hex');
$function$


CREATE OR REPLACE FUNCTION public.fn_internal_credential_issue(p_context text, p_scope text[], p_label text DEFAULT NULL::text, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare v_secret text; v_id bigint;
begin
  if coalesce(btrim(p_context), '') = '' then raise exception 'a context is required' using errcode = '22023'; end if;
  if p_scope is null or array_length(p_scope, 1) is null then
    raise exception 'a scope is required - name the functions this credential may call' using errcode = '22023';
  end if;
  -- The whole point of 9.5. An unrestricted credential is what we are removing, so it cannot be
  -- issued: only the seeded legacy row is allowed to hold '*'.
  if p_scope @> array['*'] then
    raise exception 'scope ''*'' is reserved for the legacy shared secret and cannot be issued' using errcode = '22023';
  end if;

  v_secret := encode(extensions.gen_random_bytes(32), 'hex');
  insert into public.internal_credential (context, label, secret_hash, scope, expires_at)
  values (btrim(p_context), p_label, public.fn_internal_credential_hash(v_secret),
          array(select distinct lower(btrim(s)) from unnest(p_scope) s where btrim(s) <> ''), p_expires_at)
  returning id into v_id;

  insert into public.internal_credential_audit (credential_id, context, allowed, reason, detail)
  values (v_id, btrim(p_context), true, 'issued', jsonb_build_object('scope', p_scope, 'label', p_label));

  -- Returned ONCE. There is no way to read it back; a lost credential is rotated, not recovered.
  return jsonb_build_object('ok', true, 'id', v_id, 'context', btrim(p_context), 'secret', v_secret,
    'warning', 'This secret is shown once and cannot be retrieved again. Store it now.');
end $function$


CREATE OR REPLACE FUNCTION public.fn_internal_credential_retire(p_id bigint, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c public.internal_credential%rowtype;
begin
  if length(coalesce(btrim(p_reason), '')) < 8 then
    raise exception 'a reason of at least 8 characters is required' using errcode = '22023';
  end if;
  select * into c from public.internal_credential where id = p_id;
  if not found then raise exception 'no credential %', p_id using errcode = '22023'; end if;

  update public.internal_credential set active = false, retired_at = now() where id = p_id;
  insert into public.internal_credential_audit (credential_id, context, allowed, reason, detail)
  values (p_id, c.context, true, 'retired',
          jsonb_build_object('why', p_reason, 'use_count_at_retirement', c.use_count, 'last_used_at', c.last_used_at));

  return jsonb_build_object('ok', true, 'id', p_id, 'context', c.context,
    'use_count_at_retirement', c.use_count, 'last_used_at', c.last_used_at);
end $function$


CREATE OR REPLACE FUNCTION public.fn_internal_credential_rotate(p_context text, p_label text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_old public.internal_credential%rowtype; v_new jsonb;
begin
  select * into v_old from public.internal_credential
   where context = btrim(p_context) and active and retired_at is null
   order by created_at desc limit 1;
  if not found then raise exception 'no active credential for context %', p_context using errcode = '22023'; end if;
  if v_old.scope @> array['*'] then
    raise exception 'the legacy shared secret is withdrawn, not rotated - see supabase/rollback and the 9.5 runbook' using errcode = '22023';
  end if;

  v_new := public.fn_internal_credential_issue(v_old.context, v_old.scope,
             coalesce(p_label, 'rotated from #' || v_old.id));
  update public.internal_credential set rotated_at = now() where id = v_old.id;

  return v_new || jsonb_build_object('previous_id', v_old.id,
    'note', 'The previous credential is STILL ACTIVE. Move callers across, watch use_count stop rising, then retire it.');
end $function$


CREATE OR REPLACE FUNCTION public.fn_inv_adjust(p_item bigint, p_qty_delta numeric, p_unit_cost numeric DEFAULT NULL::numeric, p_offset_account text DEFAULT '6300'::text, p_date date DEFAULT NULL::date, p_memo text DEFAULT NULL::text, p_by text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare onq numeric(18,4); onv numeric(18,2); avg_c numeric(18,4);
        uc numeric(18,4); amt numeric(18,2); j bigint; inv_acct text; m bigint;
begin
  if p_qty_delta = 0 then raise exception 'adjustment qty_delta cannot be 0'; end if;
  select coalesce(sum(qty_delta),0), coalesce(sum(cost_delta),0)
    into onq, onv from public.inv_stock_moves where item_id=p_item;
  avg_c := case when onq <> 0 then onv/onq else 0 end;
  uc := coalesce(p_unit_cost, avg_c);                 -- default to current avg for reductions
  amt := round(p_qty_delta * uc, 2);                  -- signed
  select inventory_account into inv_acct from public.inv_items where id=p_item;
  if inv_acct is null then raise exception 'item % not found', p_item; end if;
  -- positive delta: Dr Inventory / Cr offset ; negative: Dr offset / Cr Inventory
  if amt >= 0 then
    j := public.fn_gl_entry(coalesce(p_date,current_date), coalesce(p_memo,'Inventory adjustment'),
           'inv_adjust', p_item::text,
           jsonb_build_array(jsonb_build_object('account',inv_acct,'debit',amt),
                             jsonb_build_object('account',p_offset_account,'credit',amt)), p_by);
  else
    j := public.fn_gl_entry(coalesce(p_date,current_date), coalesce(p_memo,'Inventory adjustment'),
           'inv_adjust', p_item::text,
           jsonb_build_array(jsonb_build_object('account',p_offset_account,'debit',-amt),
                             jsonb_build_object('account',inv_acct,'credit',-amt)), p_by);
  end if;
  insert into public.inv_stock_moves(item_id,move_date,move_type,qty_delta,cost_delta,
       unit_cost,ref_type,ref_id,gl_journal_id,memo,created_by)
    values (p_item, coalesce(p_date,current_date),'adjust', p_qty_delta, amt, uc,
            'adjust', p_item::text, j, p_memo, p_by)
    returning id into m;
  return m;
end $function$


CREATE OR REPLACE FUNCTION public.fn_inv_issue(p_item bigint, p_qty numeric, p_date date DEFAULT NULL::date, p_ref_type text DEFAULT 'manual'::text, p_ref_id text DEFAULT NULL::text, p_by text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare onq numeric(18,4); onv numeric(18,2); avg_c numeric(18,4);
        amt numeric(18,2); j bigint; inv_acct text; cogs_acct text; m bigint;
begin
  select coalesce(sum(qty_delta),0), coalesce(sum(cost_delta),0)
    into onq, onv from public.inv_stock_moves where item_id=p_item;
  if p_qty <= 0 then raise exception 'issue qty must be > 0'; end if;
  if p_qty > onq then raise exception 'insufficient stock for item %: have %, need %', p_item, onq, p_qty; end if;
  avg_c := case when onq <> 0 then onv/onq else 0 end;
  amt := round(p_qty * avg_c, 2);
  select inventory_account, cogs_account into inv_acct, cogs_acct from public.inv_items where id=p_item;
  j := public.fn_gl_entry(coalesce(p_date,current_date),
         'Inventory issue item '||p_item, 'inv_issue', p_ref_id,
         jsonb_build_array(jsonb_build_object('account',cogs_acct,'debit',amt),
                           jsonb_build_object('account',inv_acct,'credit',amt)), p_by);
  insert into public.inv_stock_moves(item_id,move_date,move_type,qty_delta,cost_delta,
       unit_cost,ref_type,ref_id,gl_journal_id,created_by)
    values (p_item, coalesce(p_date,current_date),'out', -p_qty, -amt, avg_c,
            p_ref_type, p_ref_id, j, p_by)
    returning id into m;
  return m;
end $function$


CREATE OR REPLACE FUNCTION public.fn_inv_receive(p_item bigint, p_qty numeric, p_unit_cost numeric, p_date date DEFAULT NULL::date, p_ref_type text DEFAULT 'manual'::text, p_ref_id text DEFAULT NULL::text, p_post_gl boolean DEFAULT true, p_by text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare amt numeric(18,2); j bigint; inv_acct text; m bigint;
begin
  if p_qty <= 0 then raise exception 'receive qty must be > 0'; end if;
  select inventory_account into inv_acct from public.inv_items where id=p_item;
  if inv_acct is null then raise exception 'item % not found', p_item; end if;
  amt := round(p_qty * p_unit_cost, 2);
  if p_post_gl then                                   -- Dr Inventory  Cr Cash(1000)
    j := public.fn_gl_entry(coalesce(p_date,current_date),
           'Inventory receipt item '||p_item, 'inv_receipt', p_ref_id,
           jsonb_build_array(jsonb_build_object('account',inv_acct,'debit',amt),
                             jsonb_build_object('account','1000','credit',amt)), p_by);
  end if;
  insert into public.inv_stock_moves(item_id,move_date,move_type,qty_delta,cost_delta,
       unit_cost,ref_type,ref_id,gl_journal_id,created_by)
    values (p_item, coalesce(p_date,current_date),'in', p_qty, amt, p_unit_cost,
            p_ref_type, p_ref_id, j, p_by)
    returning id into m;
  return m;
end $function$


CREATE OR REPLACE FUNCTION public.fn_invite_ramp()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_base int := 10; v_ceiling int := 200;
  v_sent_total int; v_last_sent timestamptz; v_stage int;
  v_sent7 int; v_bounced7 int; v_rate numeric;
  v_cur int; v_new int; v_note text;
begin
  -- only manage the cap while the campaign is on; if paused, leave it as-is
  if coalesce((select value from app_secrets where key='invite_enabled'),'false') <> 'true' then
    return coalesce((select nullif(value,'')::int from app_secrets where key='invite_daily_cap'), v_base);
  end if;

  v_cur := coalesce((select nullif(value,'')::int from app_secrets where key='invite_daily_cap'), v_base);

  select count(*), max(invited_at) into v_sent_total, v_last_sent from leads where invited_at is not null;
  select count(*) into v_sent7    from leads where invited_at > now() - interval '7 days';
  select count(*) into v_bounced7 from leads where invite_status='bounced' and invited_at > now() - interval '7 days';
  v_rate := v_bounced7::numeric / greatest(v_sent7,1);

  -- STAGE ON VOLUME ISSUED, NOT ON THE CALENDAR. The previous ladder read
  -- (today - min(invited_at)::date), so it advanced while the enqueuer was timing out and nothing
  -- was being sent. A warm-up schedule that ratchets on a domain that is not sending is a
  -- deliverability incident held in escrow until somebody fixes the sender.
  v_stage := case when v_sent_total <  25 then 10
                  when v_sent_total <  75 then 25
                  when v_sent_total < 200 then 50
                  when v_sent_total < 500 then 100
                  else v_ceiling end;

  if v_last_sent is null then
    v_new := v_base;
    v_note := 'nothing issued yet; cap held at base '||v_base;
  elsif v_last_sent < now() - interval '3 days' then
    -- Silence is now a reportable state. Seven days of daily statement timeouts went unnoticed
    -- because the only thing watching filed its alarm into a queue with no reader.
    v_new := v_base;
    v_note := 'stalled: nothing issued since '||to_char(v_last_sent at time zone 'UTC','YYYY-MM-DD HH24:MI')||'Z; cap held at base '||v_base;
    if not exists (select 1 from founder_alerts where event='invite_sender_stalled' and created_at > now()-interval '24 hours') then
      insert into founder_alerts(level,event,detail,channel)
      values('crit','invite_sender_stalled',
             'Supplier invites: nothing issued since '||to_char(v_last_sent at time zone 'UTC','YYYY-MM-DD HH24:MI')
             ||'Z, but invite_enabled is true. The enqueuer is FAILING, not paused. '
             ||'Check select * from public.v_cron_failing.','system');
    end if;
  elsif v_sent7 >= 20 and v_rate >= 0.05 then
    v_new := greatest(v_base, floor(v_cur * 0.5)::int);   -- deliverability wobble: throttle down
    v_note := 'throttle: 7d bounce '||round(v_rate*100,1)||'% ('||v_bounced7||'/'||v_sent7||') >= 5%; cap '||v_cur||'->'||v_new;
  else
    v_new := least(v_stage, v_cur * 2);                   -- healthy: warm up, at most 2x/day, capped by the volume-stage
    v_note := 'healthy: '||v_sent_total||' issued lifetime, stage '||v_stage||', 7d bounce '||round(v_rate*100,1)||'% ('||v_bounced7||'/'||greatest(v_sent7,0)||'); cap '||v_cur||'->'||v_new;
  end if;

  v_new := greatest(v_base, least(v_new, v_ceiling));
  if v_new <> v_cur then
    update app_secrets set value = v_new::text where key='invite_daily_cap';
    insert into agent_runs(agent,status,counts,note,finished_at)
      values('invite_ramp','ok',jsonb_build_object('old_cap',v_cur,'new_cap',v_new,'sent_total',v_sent_total),coalesce(v_note,''),now());
    if v_new < v_cur then
      insert into founder_alerts(level,event,detail,channel)
        values('warn','invite_cap_throttled','Supplier-invite cap reduced '||v_cur||'->'||v_new||' — '||coalesce(v_note,'')||'. Hard auto-pause still triggers at 8%.','system');
    end if;
  end if;
  return v_new;
end; $function$


CREATE OR REPLACE FUNCTION public.fn_invite_week_activate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if NEW.kind = 'invite_campaign_week'
     and NEW.status in ('approved','done','auto_done','accepted','resolved','closed','completed')
     and coalesce(OLD.status,'') is distinct from NEW.status then
    update invite_schedule set status='approved' where status='pending' and day >= (now() at time zone 'UTC')::date;
    update app_secrets set value='true' where key in ('invite_enabled','supplier_emails_enabled');
    insert into founder_alerts(level,event,detail,channel)
      values('info','invite_week_approved','Supplier invite week approved in OS — schedule activated and sending enabled.','system');
  end if;
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.fn_is_matchable(p_verified boolean, p_banned boolean, p_matching_blocked boolean, p_approval_status text, p_permanently_closed boolean, p_chat_strikes integer)
 RETURNS boolean
 LANGUAGE sql
 STABLE PARALLEL SAFE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select coalesce(p_verified, false)                                        -- the rule: verified
     and coalesce(p_banned, false) = false
     and coalesce(p_matching_blocked, false) = false                        -- carries expired documents,
                                                                            -- reconciled daily by
                                                                            -- fn_reconcile_doc_blocks(0)
     and coalesce(p_permanently_closed, false) = false                      -- never RFQ a closed business
     and coalesce(p_approval_status, '') not in ('action_required','rejected')
     and coalesce(p_chat_strikes, 0) < public.fn_matching_strike_limit();   -- the no-response exception
$function$


CREATE OR REPLACE FUNCTION public.fn_is_working_day(p_date date)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select extract(isodow from p_date) < 6
     and not exists (select 1 from public.public_holidays h where h.holiday_date = p_date);
$function$


CREATE OR REPLACE FUNCTION public.fn_jsonb_text_array(j jsonb)
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select case when j is null or jsonb_typeof(j) <> 'array' then null
              else (select array_agg(x) from jsonb_array_elements_text(j) x) end;
$function$


CREATE OR REPLACE FUNCTION public.fn_kb_approve(p_revision bigint, p_reviewer text, p_notes text DEFAULT NULL::text, p_publish boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record;
begin
  select * into r from public.kb_revisions where id=p_revision;
  if r is null then return jsonb_build_object('error','revision not found'); end if;
  update public.kb_revisions set status=case when p_publish then 'published' else 'approved' end,
    reviewer=p_reviewer, review_notes=p_notes, decided_at=now() where id=p_revision;
  -- apply to live agent_knowledge when publishing that kind
  if p_publish and r.entry_kind='agent_knowledge' and position(' :: ' in r.entry_ref)>0 then
    update agent_knowledge set content=r.content
     where agent_key=split_part(r.entry_ref,' :: ',1) and topic=split_part(r.entry_ref,' :: ',2);
  end if;
  return jsonb_build_object('ok',true,'revision',p_revision,'status',case when p_publish then 'published' else 'approved' end);
end $function$


CREATE OR REPLACE FUNCTION public.fn_kb_gov_approve(p_kind text, p_id text, p_by text DEFAULT 'founder'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare n int;
begin
  if p_kind = 'regulation' then
    update regulations set approved_at = now(), approved_by = p_by where id::text = p_id and approved_at is null;
    get diagnostics n = row_count;
    perform kb_sync();
    update agent_actions set status='approved', decided_at=now(), decided_by=p_by
      where kind='knowledge_approval' and detail->>'ref'=p_id and detail->>'kind'='regulation' and status in ('pending','needs_review');
    return jsonb_build_object('approved', n, 'kind', p_kind, 'id', p_id);
  end if;
  return jsonb_build_object('error','unsupported_kind', 'kind', p_kind);
end $function$


CREATE OR REPLACE FUNCTION public.fn_kb_next_question(p_catalog_num integer, p_answered jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
declare v_scope jsonb; v_next jsonb; v_missing jsonb; v_total int; v_answered int; v_blocking int;
begin
  -- scope = the knowledge subcategories this live catalogue route maps to
  with scope as (
    select m.package_slug, m.subcategory_slug, m.priority
    from public.kb_operational_route_map m where m.catalog_num = p_catalog_num
  ),
  qs as (
    select q.question_id, q.source_question_id, q.field_key, q.question_en, q.question_ar,
           q.answer_type, q.allowed_values, q.unit, q.mandatory, q.on_missing, q.impact,
           q.answerable_by_documents, q.category_slug, q.subcategory_slug,
           coalesce((q.activation->>'order')::int, 999) as ord
    from kb_stage.questions q
    join scope s on s.package_slug = q.category_slug and s.subcategory_slug = q.subcategory_slug
    where q.field_key is not null
  ),
  -- One question per field_key across all mapped subcategories. A composite route (signage maps to
  -- 3 packages) otherwise asks "which emirate?" seven times.
  dedup as (
    select distinct on (field_key) * from qs order by field_key, mandatory desc, ord, question_id
  ),
  open as (
    select * from dedup
    where not (p_answered ? field_key)
       or nullif(btrim(coalesce(p_answered->>field_key, '')), '') is null
  )
  select
    (select to_jsonb(o) from open o order by o.mandatory desc, o.ord, o.question_id limit 1),
    (select coalesce(jsonb_agg(jsonb_build_object('field_key', o.field_key, 'mandatory', o.mandatory,
                                                  'on_missing', o.on_missing) order by o.mandatory desc, o.ord), '[]'::jsonb)
       from open o),
    (select count(*) from dedup where mandatory),
    (select count(*) from dedup d where d.mandatory and p_answered ? d.field_key
        and nullif(btrim(coalesce(p_answered->>d.field_key,'')),'') is not null),
    (select count(*) from open o where o.mandatory
        and (o.on_missing is null or o.on_missing ilike 'block%' or o.on_missing ilike '%block%'))
  into v_next, v_missing, v_total, v_answered, v_blocking;

  return jsonb_build_object(
    'catalog_num', p_catalog_num,
    'next_question', v_next,
    'missing', v_missing,
    'mandatory_total', coalesce(v_total, 0),
    'mandatory_answered', coalesce(v_answered, 0),
    'completeness', case when coalesce(v_total,0) = 0 then null
                         else round(coalesce(v_answered,0)::numeric / v_total, 3) end,
    -- The single auditable gate the external reviewer asked for: one boolean, one query, one place.
    'dispatch_eligible', coalesce(v_blocking, 0) = 0,
    'blocking_count', coalesce(v_blocking, 0),
    'source', 'kb_stage.questions (deterministic, no model call)');
end $function$


CREATE OR REPLACE FUNCTION public.fn_kb_reconcile()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_stripped int:=0; v_aliased int:=0; v_uncat int; v_noncanon int;
begin
  with upd as (
    update public.kb_chunks c set category = substring(c.category from 5)
    where c.category like 'cat:%'
      and ( substring(c.category from 5) in (select slug from public.category_agents where active)
         or substring(c.category from 5) in (select category from public.category_specs) )
    returning 1
  ) select count(*) into v_stripped from upd;

  with oneone as (
    select category, min(maps_to) as target
    from public.kb_category_aliases group by category having count(distinct maps_to)=1
  ), upd2 as (
    update public.kb_chunks c set category = o.target
    from oneone o where c.category = o.category and c.category <> o.target
    returning 1
  ) select count(*) into v_aliased from upd2;

  select count(*) into v_uncat from public.kb_chunks where category is null or category='';
  select count(distinct category) into v_noncanon from public.kb_chunks
    where category is not null and category<>'' and category not like 'cat:%'
      and category not in (select slug from public.category_agents where active)
      and category not in (select category from public.category_specs);

  return jsonb_build_object('cat_prefix_stripped',v_stripped,'alias_remapped',v_aliased,
    'uncategorized_left',v_uncat,'noncanonical_categories_left',v_noncanon,
    'note','Normalized kb_chunks categories: stripped '||v_stripped||' cat: prefix(es), remapped '||v_aliased||' via curated 1:1 aliases. '||v_uncat||' chunk(s) remain uncategorized (global knowledge — still semantically retrievable).');
end $function$


CREATE OR REPLACE FUNCTION public.fn_kb_retrieve(p_catalog_num integer, p_query text, p_limit integer DEFAULT 6, p_modules text[] DEFAULT NULL::text[])
 RETURNS TABLE(record_id text, title text, content text, module text, record_type text, authority text, validation_status text, confidence numeric, source_ids jsonb, escalate boolean, rank real)
 LANGUAGE sql
 STABLE
AS $function$
with scope as (
  select m.package_slug, m.subcategory_slug from public.kb_operational_route_map m
  where m.catalog_num = p_catalog_num
), q as (
  select to_tsquery('simple',
           nullif(array_to_string(
             array(select w || ':*' from unnest(regexp_split_to_array(lower(coalesce(p_query,'')), '[^a-z0-9؀-ۿ]+')) w
                   where length(w) >= 3), ' | '), '')) tsq
)
select r.record_id, r.title, left(r.content, 4000), r.module, r.record_type, r.authority,
       r.validation_status, r.confidence, r.source_ids,
       (r.escalation_rule is not null or r.module = 'uae_regulations') as escalate,
       ts_rank(to_tsvector('simple', r.title || ' ' || left(r.content, 4000)), q.tsq) as rank
from kb_stage.records r
join scope s on s.package_slug = r.category_slug and s.subcategory_slug = r.subcategory_slug
cross join q
where r.validation_status in ('reviewed', 'source_verified', 'approved')
  and (p_modules is null or r.module = any (p_modules))
  and (q.tsq is null or to_tsvector('simple', r.title || ' ' || left(r.content, 4000)) @@ q.tsq)
order by rank desc, r.confidence desc nulls last, r.record_id
limit greatest(p_limit, 1);
$function$


CREATE OR REPLACE FUNCTION public.fn_kb_route(p_text text, p_limit integer DEFAULT 5)
 RETURNS TABLE(catalog_num integer, live_slug text, live_name text, score numeric, matched_aliases jsonb, languages text[])
 LANGUAGE sql
 STABLE
AS $function$
with q as (select ' ' || kb_norm(p_text) || ' ' as t),
hits as (
  select a.catalog_num, a.alias, a.language, a.weight, a.negative,
         array_length(string_to_array(a.alias_norm, ' '), 1) as words
  from public.kb_operational_alias a, q
  where length(a.alias_norm) >= 3
    and q.t like '%' || ' ' || a.alias_norm || ' ' || '%'
),
scored as (
  select h.catalog_num,
         sum(case when h.negative then -1 else 1 end * h.weight * h.words) as score,
         jsonb_agg(jsonb_build_object('alias', h.alias, 'lang', h.language,
                                      'w', h.weight, 'words', h.words, 'neg', h.negative)
                   order by h.weight * h.words desc) as matched,
         array_agg(distinct h.language) as langs
  from hits h group by h.catalog_num
)
select s.catalog_num, c.slug, c.name, s.score, s.matched, s.langs
from scored s join public.catalog_supplier_categories c on c.num = s.catalog_num
where s.score > 0
order by s.score desc, s.catalog_num
limit greatest(p_limit, 1);
$function$


CREATE OR REPLACE FUNCTION public.fn_kb_route_activation_blocked(p_catalog_num integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r record; v_reasons text[] := '{}';
begin
  select * into r from public.kb_operational_route where catalog_num = p_catalog_num;
  if not found then
    return jsonb_build_object('blocked', true, 'reasons', array['no such route']);
  end if;

  if r.regulatory_coverage_status <> 'confirmed_none'
     and r.regulatory_coverage_status <> 'confirmed_covered' then
    v_reasons := v_reasons || ('regulatory coverage is ' || r.regulatory_coverage_status);
  end if;

  if not exists (select 1 from public.kb_operational_route_map m where m.catalog_num = p_catalog_num) then
    v_reasons := v_reasons || 'no mapped subcategory';
  end if;

  if not exists (select 1 from public.kb_operational_alias a
                  where a.catalog_num = p_catalog_num and a.language = 'ar') then
    v_reasons := v_reasons || 'no Arabic alias';
  end if;

  return jsonb_build_object('blocked', array_length(v_reasons, 1) is not null,
                            'reasons', coalesce(v_reasons, '{}'),
                            'regulatory_coverage_status', r.regulatory_coverage_status,
                            'route', r.catalog_name);
end $function$


CREATE OR REPLACE FUNCTION public.fn_kb_route_decide(p_text text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  v jsonb; top numeric; second numeric; n int; v_action text; v_conf numeric; v_reason text;
begin
  select coalesce(jsonb_agg(to_jsonb(r) order by r.score desc), '[]'::jsonb) into v
  from (select * from public.fn_kb_route(p_text, 5)) r;

  n := jsonb_array_length(v);
  if n = 0 then
    return jsonb_build_object(
      'action', 'ask_clarifying_question', 'confidence', 0, 'top_score', 0,
      'candidates', '[]'::jsonb, 'catalog_num', null, 'multi_category', false,
      'reason', 'no deterministic alias matched the customer wording',
      'clarification', 'Could you tell me in your own words what you need supplied or done? For example "waterproof a warehouse roof" or "supply 200 office chairs".',
      'normalised', public.kb_norm(p_text));
  end if;

  top    := (v->0->>'score')::numeric;
  second := case when n > 1 then (v->1->>'score')::numeric else 0 end;
  v_conf := round(top / nullif(top + second, 0), 3);

  if top < 3 then
    v_action := 'ask_clarifying_question';
    v_reason := 'only a weak fragment matched; not enough to act on';
  elsif n = 1 or top >= second * 1.5 then
    v_action := 'route_or_ask_scope_details';
    v_reason := case when n = 1 then 'single deterministic alias match'
                     else 'leading route is decisively ahead of the runner-up' end;
  else
    v_action := 'ask_clarifying_question';
    v_reason := 'leading routes are too close to call';
  end if;

  return jsonb_build_object(
    'action', v_action,
    'confidence', v_conf,
    'top_score', top,
    'candidates', v,
    'catalog_num', case when v_action = 'route_or_ask_scope_details' then (v->0->>'catalog_num')::int else null end,
    -- A genuinely multi-trade request (a fit-out that is also flooring and also joinery) is NOT an
    -- error to be collapsed to one route. Flagged so the intake can open several RFQs rather than
    -- forcing the buyer to pick one.
    'multi_category', (n > 1 and second >= top * 0.75),
    'reason', v_reason,
    'clarification', case when v_action = 'ask_clarifying_question' then
        'Just so this reaches the right suppliers - is this closer to "' || (v->0->>'live_name') ||
        '" or "' || coalesce(v->1->>'live_name', 'something else') || '"?' end,
    'normalised', public.kb_norm(p_text));
end $function$


CREATE OR REPLACE FUNCTION public.fn_kb_submit_revision(p_kind text, p_ref text, p_content text, p_author text DEFAULT 'agent'::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare id bigint;
begin
  insert into public.kb_revisions(entry_kind,entry_ref,version,content,status,author,ai_validation)
  values (p_kind,p_ref, public._kb_next_ver(p_kind,p_ref), p_content, 'in_review', p_author, public.fn_kb_validate(p_content))
  returning id into id;
  return id;
end $function$


CREATE OR REPLACE FUNCTION public.fn_kb_validate(p_content text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare flags text[]:='{}'; ok boolean:=true;
begin
  if length(coalesce(p_content,'')) < 40 then flags:=array_append(flags,'too_short'); ok:=false; end if;
  if p_content !~* '(source|per |according to|standard|code|regulation|SIRA|DCD|DEWA|ISO|IEC|BS |EN |NFPA|Estidama|ESMA|[0-9])' then
     flags:=array_append(flags,'no_citation_or_specifics'); ok:=false; end if;
  if p_content ~* '(always|never|guaranteed|100%|best in the world)' then flags:=array_append(flags,'absolute_claim_review'); end if;
  return jsonb_build_object('passed',ok,'flags',to_jsonb(flags),'checked_at',now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_knowledge_curator()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare k record; v_health numeric; n_task int; n_appr int:=0; rec record; rc record; v_gaps jsonb;
begin
  select * into k from knowledge_kpis;
  select * into rc from reg_coverage;
  v_health := round(coalesce(k.coverage_pct,0)*0.30 + coalesce(k.accuracy_pct,0)*0.25 + coalesce(k.freshness_pct,0)*0.25 + coalesce(k.usage_reach_pct,0)*0.20,1);
  insert into knowledge_kpi_snapshots(snapshot_date,kpis) values (current_date, to_jsonb(k) || jsonb_build_object('health',v_health,'reg_coverage',to_jsonb(rc)))
    on conflict (snapshot_date) do update set kpis=excluded.kpis, created_at=now();

  perform kn_task('playbook_gap', (k.categories_total - k.cat_with_playbook) > 0, 'medium', 'Qualification playbook gaps',
    (k.categories_total - k.cat_with_playbook)||' of '||k.categories_total||' categories lack a qualification playbook. Generating them sharpens RFQ qualification quality.');
  perform kn_task('stale_compliance', (k.compliance_active - k.compliance_fresh) > 0, 'low', 'Stale compliance sources',
    (k.compliance_active - k.compliance_fresh)||' compliance sources have not been re-checked in 45 days.');
  perform kn_task('low_accuracy', coalesce(k.flagged_revisions,0) > 0, 'medium', 'Knowledge flagged by validation',
    k.flagged_revisions||' knowledge revisions failed or were flagged by AI validation. Review before they can mislead the agents.');
  perform kn_task('reg_coverage', rc.missing > 0, 'high', 'UAE codes not yet indexed as full documents',
    'Regulatory library is '||rc.coverage_pct||'% complete ('||rc.indexed||'/'||rc.free_codes||' free-published codes fully indexed; '||rc.critical_indexed||'/'||rc.critical_total||' critical). Still missing (critical first): '
    ||coalesce((select string_agg(authority||' — '||code_name, '; ') from (select authority,code_name from reg_catalog where copyright='free' and status<>'indexed' order by priority, authority limit 10) g),'none')
    ||'. Many are portal/viewer-gated or scanned — supply official full PDFs (or a licensed copy) to index them.');

  -- NEW: per-agent knowledge staleness → one auto-closing task per lagging agent.
  v_gaps := fn_dispatch_agent_knowledge_gaps();

  for rec in select id::text as rid, title, authority from regulations where approved_at is null loop
    if not exists (select 1 from agent_actions where kind='knowledge_approval' and detail->>'ref'=rec.rid and detail->>'kind'='regulation' and status in ('pending','needs_review')) then
      insert into agent_actions(agent,kind,status,risk,title,recommendation,detail,target_table,target_id)
      values ('knowledge_curator','knowledge_approval','pending','high',
        'Approve regulation: '||coalesce(rec.title,'#'||rec.rid),
        'A new/updated high-stakes regulation ('||coalesce(rec.authority,'')||') is awaiting your approval before it publishes to the knowledge base.',
        jsonb_build_object('kind','regulation','ref',rec.rid,'authority',rec.authority),'regulations', rec.rid);
      n_appr := n_appr + 1;
    end if;
  end loop;

  select count(*) into n_task from agent_actions where agent='knowledge_curator' and status in ('pending','needs_review');
  return jsonb_build_object('ran_at',now(),'health',v_health,'kpis',to_jsonb(k),'reg_coverage',to_jsonb(rc),'open_items',n_task,'new_approvals',n_appr,'agent_gaps',v_gaps->'summary');
end $function$


CREATE OR REPLACE FUNCTION public.fn_knowledge_decay()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare n_decayed int; n_quarantined int; n_tasks int := 0;
begin
  update agent_knowledge
     set confidence = greatest(0.10, round((confidence - (0.05 * greatest(1, floor(extract(epoch from (now() - review_due))/(30*86400)))))::numeric, 2)),
         validation_status = 'stale'
   where review_due < now()
     and coalesce(validation_status,'') <> 'quarantined'
     and confidence > 0.10;
  get diagnostics n_decayed = row_count;

  update agent_knowledge
     set validation_status = 'quarantined'
   where confidence < 0.35 and coalesce(validation_status,'') <> 'quarantined';
  get diagnostics n_quarantined = row_count;

  -- a quarantined expert is a capability gap, so it becomes work
  insert into org_tasks (dept_key, title, detail, status, tier, needs_founder, action_class)
  select 'knowledge',
         'Knowledge quarantined: '||agent_key,
         count(*)||' knowledge item(s) for '||agent_key||' fell below the confidence floor and are no longer served. '
         ||'Refresh from source and re-validate, or retire the topic.',
         'proposed','advisory', false, 'knowledge_fill'
    from agent_knowledge
   where validation_status='quarantined'
   group by agent_key
  having not exists (select 1 from org_tasks t where t.title='Knowledge quarantined: '||agent_knowledge.agent_key and t.status<>'done');
  get diagnostics n_tasks = row_count;

  insert into agent_runs (agent, started_at, finished_at, status, counts, note)
  values ('knowledge_decay', now(), now(), 'ok',
          jsonb_build_object('decayed',n_decayed,'quarantined',n_quarantined,'tasks',n_tasks),
          'Knowledge decay: '||n_decayed||' item(s) past review lost confidence, '||n_quarantined
          ||' quarantined below the floor, '||n_tasks||' refresh task(s) opened.');

  return jsonb_build_object('decayed',n_decayed,'quarantined',n_quarantined,'tasks',n_tasks);
end $function$


CREATE OR REPLACE FUNCTION public.fn_knowledge_exam_summary()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  with recent as (
    select * from knowledge_exam_results where created_at > now() - interval '30 days'
  ),
  per as (
    select agent_key,
      count(*) as examined,
      count(*) filter (where verdict='correct') as correct,
      count(*) filter (where verdict in ('wrong','partial','not_covered')) as gaps,
      count(*) filter (where filled) as filled,
      max(created_at) as last_exam
    from recent group by agent_key
  )
  select jsonb_build_object(
    'overall', jsonb_build_object(
      'question_bank', (select count(*) from knowledge_exam_questions),
      'exams_30d', (select count(*) from recent),
      'agents_examined', (select count(*) from per),
      'gaps_filled_30d', (select count(*) from recent where filled),
      'avg_score', (select round(100.0*count(*) filter (where verdict='correct')/nullif(count(*),0),1) from recent)
    ),
    'agents', coalesce((select jsonb_agg(jsonb_build_object(
        'agent_key', agent_key, 'examined', examined, 'correct', correct,
        'score_pct', round(100.0*correct/nullif(examined,0),1),
        'gaps', gaps, 'filled', filled, 'last_exam', last_exam
      ) order by round(100.0*correct/nullif(examined,0),1) asc nulls first) from per), '[]'::jsonb)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_knowledge_gaps(p_stale_days integer DEFAULT 14, p_thin_min integer DEFAULT 4)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  with base as (
    select ca.slug, ca.name, ca.emoji,
      (select count(*) from agent_knowledge k where k.agent_key = ca.slug or k.agent_key = 'cat:'||ca.slug) as items,
      (select max(updated_at) from agent_knowledge k where k.agent_key = ca.slug or k.agent_key = 'cat:'||ca.slug) as last_updated
    from category_agents ca where coalesce(ca.active,true)
  ),
  scored as (
    select slug, name, emoji, items, last_updated,
      case when last_updated is null then null else floor(extract(epoch from (now()-last_updated))/86400)::int end as days_stale,
      case when items = 0 then 'missing'
           when last_updated < now() - (p_stale_days||' days')::interval then 'stale'
           when items < p_thin_min then 'thin'
           else 'ok' end as status
    from base
  )
  select jsonb_build_object(
    'thresholds', jsonb_build_object('stale_days', p_stale_days, 'thin_min', p_thin_min),
    'summary', jsonb_build_object(
      'total', (select count(*) from scored),
      'ok', (select count(*) from scored where status='ok'),
      'stale', (select count(*) from scored where status='stale'),
      'thin', (select count(*) from scored where status='thin'),
      'missing', (select count(*) from scored where status='missing'),
      'coverage_pct', round(100.0 * (select count(*) from scored where status='ok') / nullif((select count(*) from scored),0), 1)
    ),
    'agents', coalesce((select jsonb_agg(jsonb_build_object(
        'slug', slug, 'name', name, 'emoji', emoji, 'items', items,
        'last_updated', last_updated, 'days_stale', days_stale, 'status', status
      ) order by case status when 'stale' then 0 when 'thin' then 1 when 'missing' then 2 else 3 end, days_stale desc nulls last, slug)
      from scored), '[]'::jsonb)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_kpi_review()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v_opened int:=0; v_missed int:=0; v_nodata int:=0; v_title text; v_task bigint;
begin
  for r in select * from fn_kpi_scoreboard() loop
    if r.verdict='NO DATA' then v_nodata:=v_nodata+1; continue; end if;
    if r.verdict<>'MISSED' then continue; end if;
    v_missed := v_missed+1;
    v_title := 'KPI missed: '||r.metric||' ('||r.agent_key||')';
    if exists (select 1 from org_tasks where title=v_title and status<>'done') then continue; end if;

    insert into org_tasks (dept_key, title, detail, status, tier, needs_founder, action_class)
    values (coalesce(r.department,'exec'), v_title,
      'Owner: '||r.agent_key||'. Target '||coalesce(r.target::text,'?')||' '||coalesce(r.unit,'')||
      ', actual '||coalesce(r.actual::text,'?')||' ('||coalesce(r.attainment::text,'?')||'% of target), cadence '||coalesce(r.cadence,'?')||
      '. Serves company goal: '||coalesce(r.serves_goal,'unassigned')||
      '. Diagnose the cause and either close the gap or propose a revised target with evidence.',
      'proposed','advisory', false, 'recommend')
    returning id into v_task;

    perform fn_outcome_open(
      p_actor           => r.agent_key,
      p_decision        => 'Close the gap on: '||r.metric,
      p_subject_type    => 'org_task',
      p_subject_id      => v_task::text,
      p_expected_kpi_id => r.kpi_id,
      p_rationale       => 'KPI missed at '||coalesce(r.attainment::text,'?')||'% of target. Opened automatically by the weekly KPI review.',
      p_direction       => case when r.unit='percent_max' then 'down' else 'up' end,
      p_measure_after   => case when r.cadence='weekly' then interval '14 days' else interval '35 days' end
    );

    v_opened := v_opened+1;
  end loop;

  insert into agent_runs (agent, started_at, finished_at, status, counts, note)
  values ('kpi_review', now(), now(), 'ok',
          jsonb_build_object('missed',v_missed,'opened',v_opened,'no_data',v_nodata),
          'Weekly KPI review: '||v_missed||' missing target, '||v_opened||' task(s) + outcome record(s) opened, '||v_nodata||' with no data.');
  return jsonb_build_object('missed',v_missed,'opened',v_opened,'no_data',v_nodata);
end $function$


CREATE OR REPLACE FUNCTION public.fn_kpi_scoreboard()
 RETURNS TABLE(kpi_id bigint, agent_key text, department text, kpi text, metric text, cadence text, serves_goal text, target numeric, unit text, actual numeric, attainment numeric, verdict text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v numeric; t numeric;
begin
  for r in
    select k.id, k.agent_key, a.department, k.kpi, k.metric, k.cadence,
           k.serves_goal, k.target_value, k.unit, k.measure_sql
    from employee_kpi k
    left join org_agents a on a.agent_key = k.agent_key
    where k.active
    order by a.department nulls last, k.agent_key, k.id
  loop
    v := null;
    begin
      if r.measure_sql is not null then execute r.measure_sql into v; end if;
    exception when others then v := null;
    end;

    t := null;
    begin
      t := r.target_value::numeric;
    exception when others then t := null;
    end;

    kpi_id := r.id; agent_key := r.agent_key; department := r.department;
    kpi := r.kpi; metric := r.metric; cadence := r.cadence;
    serves_goal := r.serves_goal; target := t; unit := r.unit; actual := v;

    if v is null or t is null or t = 0 then
      attainment := null;
    elsif r.unit = 'percent_max' then
      attainment := round(least(100.0, 100.0 * t / nullif(v,0)), 1);
    else
      attainment := round(100.0 * v / t, 1);
    end if;

    verdict := case
      when v is null then 'NO DATA'
      when attainment is null then 'NO TARGET'
      when attainment >= 100 then 'MET'
      when attainment >= 90 then 'NEAR'
      else 'MISSED' end;

    return next;
  end loop;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_kv_block(obj jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare k text; v text; out text := ''; begin
  if obj is null then return '  (no data)'; end if;
  for k, v in select key, value from jsonb_each_text(obj) loop
    if v is null or k in ('id','snapshot_date','created_at','captured_at') then continue; end if;
    out := out || '  ' || initcap(replace(k,'_',' ')) || ': ' || v || E'\n';
  end loop;
  if out = '' then out := '  (no data)'; end if;
  return rtrim(out, E'\n');
end $function$


CREATE OR REPLACE FUNCTION public.fn_lead_lifecycle_stage(l leads)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  select case
    when l.claimed is true
      or l.signed is true
      or l.registration_submitted_at is not null
      or nullif(btrim(coalesce(l.claimed_by, '')), '') is not null
      or nullif(btrim(coalesce(l.approval_status, '')), '') is not null
      or nullif(btrim(coalesce(l.registration_status, '')), '') is not null
      then 'registered'
    when l.portal_updated_at is not null
      or l.accepted_terms_at is not null
      or l.owner_email_verified is true
      then 'responded'
    when lower(btrim(coalesce(l.invite_status, ''))) in ('bounced', 'failed', 'undeliverable', 'invalid', 'rejected')
      then 'undeliverable'
    when (l.invited_at is not null and l.invited_at < now() - interval '14 days')
      or (l.invited_at is null and l.contacted is true and coalesce(l.created_at, now()) < now() - interval '14 days')
      then 'no_response'
    when l.invited_at is not null
      or l.contacted is true
      or nullif(btrim(coalesce(l.invite_status, '')), '') is not null
      then 'contacted'
    else 'not_contacted'
  end
$function$


CREATE OR REPLACE FUNCTION public.fn_leads_exception_invariant()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_days   int := public.fn_supplier_exception_days();
  v_now    timestamptz := now();
  v_needs  boolean;
  v_isopen boolean;
begin
  v_needs  := coalesce(new.approval_status, '') = 'action_required';
  v_isopen := new.exception_opened_at is not null and new.exception_closed_at is null;

  if v_needs and not v_isopen then
    -- (a) OPEN IT HERE. supplier_api commits the status first and opens the window afterwards
    -- inside a try/catch that swallows failures; if that RPC never lands, the supplier is stranded
    -- in a state no sweep can see. Opening it in the same statement that sets the status removes
    -- the ordering problem entirely, whatever the caller does.
    new.exception_opened_at        := v_now;
    new.exception_due_at           := v_now + make_interval(days => v_days);
    new.exception_reminders        := 0;
    new.exception_last_reminder_at := null;
    new.exception_closed_at        := null;
    new.exception_outcome          := null;

  elsif v_needs and v_isopen and new.exception_due_at is null then
    -- Open but with no deadline: same invisibility, different route in.
    new.exception_due_at := v_now + make_interval(days => v_days);

  elsif (not v_needs) and v_isopen then
    -- (b)(c) CLOSE IT HERE. An approved or verified supplier must not carry an open window: it is
    -- invisible to every sweep, and it poisons the NEXT demotion with a stale due date.
    new.exception_closed_at := v_now;
    new.exception_outcome   := case
      when coalesce(new.approval_status,'') in ('approved','verified') or new.verified is true then 'resolved'
      when coalesce(new.approval_status,'') = 'rejected' then coalesce(new.exception_outcome, 'closed_rejected')
      else 'closed_status_change' end;
    if new.exception_outcome = 'resolved' then new.licence_gate_reason := null; end if;
  end if;

  -- Backstop. If the branches above ever stop covering a case, fail loudly here rather than
  -- writing a row that no queue can see. A CHECK constraint cannot express this (it depends on
  -- two column groups at once) and would also have blocked the legacy rows this trigger repairs.
  if (coalesce(new.approval_status,'') = 'action_required')
     <> (new.exception_opened_at is not null and new.exception_closed_at is null) then
    raise exception
      'leads %: exception window and approval_status disagree (status=%, open=%). An open window '
      'must mean action_required and nothing else — otherwise the supplier is in a state no sweep '
      'and no view can see.', new.id, new.approval_status,
      (new.exception_opened_at is not null and new.exception_closed_at is null)
      using errcode = 'check_violation';
  end if;

  if coalesce(new.approval_status,'') = 'action_required' and new.exception_due_at is null then
    raise exception 'leads %: action_required with no exception_due_at — both sweep loops skip it.', new.id
      using errcode = 'check_violation';
  end if;

  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_leads_licence_gate_rerun()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare g jsonb; has_doc boolean;
begin
  if tg_op = 'UPDATE'
     and new.license_doc_path  is not distinct from old.license_doc_path
     and new.trade_license_no  is not distinct from old.trade_license_no
     and new.license_expiry    is not distinct from old.license_expiry then
    return new;
  end if;

  has_doc := coalesce(new.license_doc_path, '') <> '';
  g := public.fn_supplier_licence_gate(new.license_doc_path, new.trade_license_no, new.license_expiry);

  if (g ->> 'ok')::boolean then
    if coalesce(new.approval_status,'') = 'action_required' then
      new.approval_status     := 'approved';
      new.licence_gate_reason := null;
    elsif coalesce(new.approval_status,'') = 'rejected'
          and coalesce(new.exception_outcome,'') = 'expired_auto_rejected' then
      new.approval_status     := 'approved';
      new.licence_gate_reason := null;
      new.exception_outcome   := 'recovered_after_auto_reject';
    end if;
  elsif has_doc then
    -- Evidence exists and fails. THIS is the case worth acting on.
    if coalesce(new.approval_status,'') in ('approved','verified') then
      new.approval_status     := 'action_required';
      new.licence_gate_reason := g ->> 'reason';
    elsif coalesce(new.approval_status,'') = 'action_required' then
      new.licence_gate_reason := g ->> 'reason';
    end if;
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_legal_ai()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare k record; v_health numeric; v_terms numeric; v_fresh numeric; n int; v_missing text; v_regchg int;
begin
  select * into k from legal_kpis;
  -- refresh checklist presence
  update legal_checklist lc set present = exists(select 1 from legal_documents d where d.slug = lc.match_slug);

  v_terms := round((coalesce(k.customer_terms_acceptance_pct,0)+coalesce(k.supplier_terms_acceptance_pct,0))/2,1);
  v_fresh := case when k.policies_published=0 then 0 else round(100.0*(k.policies_published-k.policies_stale)/k.policies_published,1) end;
  v_health := round(coalesce(k.coverage_pct,0)*0.35 + v_terms*0.30 + v_fresh*0.20 + greatest(0,100-coalesce(k.open_legal_flags,0)*10)*0.15,1);

  insert into legal_kpi_snapshots(snapshot_date,kpis) values (current_date, to_jsonb(k)||jsonb_build_object('legal_health',v_health,'terms_acceptance_avg',v_terms))
    on conflict (snapshot_date) do update set kpis=excluded.kpis, created_at=now();

  select string_agg(requirement,'; ') into v_missing from legal_checklist where not present and priority=1;
  select count(*) into v_regchg from compliance_sources where last_changed_at >= now()-interval '30 days';

  -- ESCALATIONS (founder-visible legal_flag; never legal advice)
  perform leg_flag('missing_core_docs', coalesce(k.critical_missing,0)>0, 'high', 'Core legal documents missing',
    'The platform is operating without these core documents: '||coalesce(v_missing,'')||'. They govern your contractual relationship with customers and suppliers (liability, governing law, dispute resolution). Have a licensed UAE lawyer prepare and approve them, then publish as versioned legal documents.');
  perform leg_flag('supplier_terms_acceptance', coalesce(k.suppliers_approved,0)>0 and coalesce(k.supplier_terms_acceptance_pct,0) < 90, 'high', 'Suppliers have not accepted current terms',
    'Only '||coalesce(k.supplier_terms_acceptance_pct,0)||'% of approved suppliers have accepted the current terms. Enforce terms acceptance (click-wrap / signed) at onboarding so agreements are enforceable.');
  perform leg_flag('customer_terms_acceptance', coalesce(k.customer_terms_acceptance_pct,0) < 90, 'medium', 'Customers have not accepted current terms',
    'Only '||coalesce(k.customer_terms_acceptance_pct,0)||'% of customers have accepted the current terms. Gate key actions (posting an inquiry / paying to reveal) behind explicit terms acceptance.');
  perform leg_flag('stale_policies', coalesce(k.policies_stale,0)>0, 'low', 'Policies due for annual review',
    k.policies_stale||' published policy(ies) have not been reviewed in over a year. Schedule an annual legal review.');
  perform leg_flag('reg_change_review', v_regchg>0, 'medium', 'Regulatory change may affect your terms/policies',
    v_regchg||' monitored authority source(s) changed in the last 30 days. Review whether your terms, privacy or compliance policies need updating with a lawyer.');

  select count(*) into n from agent_actions where agent='legal_ai' and status in ('pending','needs_review');
  return jsonb_build_object('ran_at',now(),'legal_health',v_health,'kpis',to_jsonb(k),'open_flags',n);
end $function$


CREATE OR REPLACE FUNCTION public.fn_lint_outbound(p_hours integer DEFAULT 24)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select jsonb_build_object(
    'hits', count(*),
    'sample', coalesce(jsonb_agg(jsonb_build_object('when',a.created_at,'rule',p.name,'reply',left(a.reply,160))) filter (where p.id is not null), '[]'::jsonb)
  )
  from assistant_logs a
  left join policy_rules p on p.active and a.reply ~* p.forbid_regex
  where a.created_at > now() - make_interval(hours => p_hours)
    and p.id is not null;
$function$


CREATE OR REPLACE FUNCTION public.fn_llm_cache_get(p_key text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v text;
begin
  update llm_cache set hits = hits + 1, last_hit_at = now()
  where cache_key = p_key and expires_at > now()
  returning response into v;
  return v;
end; $function$


CREATE OR REPLACE FUNCTION public.fn_llm_cache_lookup(p_key text, p_embedding vector DEFAULT NULL::vector, p_task_class text DEFAULT NULL::text, p_min_similarity numeric DEFAULT 0.95)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v_sim numeric;
begin
  -- 1. exact
  select * into r from llm_cache
   where cache_key = p_key and (expires_at is null or expires_at > now()) limit 1;
  if found then
    update llm_cache set hits = hits + 1, last_hit_at = now() where cache_key = r.cache_key;
    return jsonb_build_object('hit', true, 'kind', 'exact', 'response', r.response,
                              'model', r.model_used, 'similarity', 1.0);
  end if;

  -- 2. semantic. Deliberately scoped to the same task_class: a research answer must
  -- never be served to a classification prompt just because they read alike.
  if p_embedding is not null then
    select c.*, 1 - (c.embedding_gte <=> p_embedding) as sim into r
      from llm_cache c
     where c.embedding_gte is not null
       and (c.expires_at is null or c.expires_at > now())
       and (p_task_class is null or c.task_class is not distinct from p_task_class)
     order by c.embedding_gte <=> p_embedding
     limit 1;
    if found then
      v_sim := round((r.sim)::numeric, 4);
      if v_sim >= p_min_similarity then
        update llm_cache set hits = hits + 1, last_hit_at = now() where cache_key = r.cache_key;
        return jsonb_build_object('hit', true, 'kind', 'semantic', 'response', r.response,
                                  'model', r.model_used, 'similarity', v_sim);
      end if;
    end if;
  end if;

  return jsonb_build_object('hit', false);
end $function$


CREATE OR REPLACE FUNCTION public.fn_llm_cache_put(p_key text, p_fn text, p_task_class text, p_model text, p_response text, p_ttl_minutes integer DEFAULT 1440)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  insert into llm_cache (cache_key, fn, task_class, model_used, response, expires_at)
  values (p_key, p_fn, p_task_class, p_model, p_response, now() + make_interval(mins => greatest(p_ttl_minutes,1)))
  on conflict (cache_key) do update set response = excluded.response, model_used = excluded.model_used,
    expires_at = excluded.expires_at, created_at = now();
$function$


CREATE OR REPLACE FUNCTION public.fn_llm_cache_store(p_key text, p_fn text, p_task_class text, p_model text, p_response text, p_ttl_minutes integer, p_embedding vector DEFAULT NULL::vector, p_saved_usd numeric DEFAULT 0)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  insert into llm_cache (cache_key, fn, task_class, model_used, response, prompt_hash,
                         expires_at, embedding_gte, saved_usd)
  values (p_key, p_fn, p_task_class, p_model, p_response, p_key,
          now() + make_interval(mins => greatest(coalesce(p_ttl_minutes,60),1)), p_embedding, coalesce(p_saved_usd,0))
  on conflict (cache_key) do update set response = excluded.response, model_used = excluded.model_used,
    expires_at = excluded.expires_at, embedding_gte = coalesce(excluded.embedding_gte, llm_cache.embedding_gte);
$function$


CREATE OR REPLACE FUNCTION public.fn_llm_drift_watch()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v jsonb := '[]'::jsonb; v_off int; v_fb numeric; v_fail int; v_owner text; v_recent int;
begin
  select count(*) into v_recent from llm_calls where created_at > now() - interval '24 hours';
  if v_recent = 0 then
    return jsonb_build_object('checked_at', now(), 'calls_24h', 0, 'findings', 0,
                              'note','no llm traffic in 24h - nothing to judge');
  end if;

  -- 1. any model not on the approved list
  select count(*) into v_off from v_llm_offpolicy;
  if v_off > 0 then
    v := v || jsonb_build_object('issue','off_policy_model','severity','high',
         'detail',(select jsonb_agg(jsonb_build_object('fn',fn,'model',model,'calls',calls)) from v_llm_offpolicy));
  end if;

  -- 2. fallback rate: Opus answering when Sonnet was asked means Sonnet is failing
  select round(100.0 * count(*) filter (where fell_back) / nullif(count(*),0), 1)
    into v_fb from llm_calls where created_at > now() - interval '24 hours';
  if coalesce(v_fb,0) > 20 then
    v := v || jsonb_build_object('issue','high_fallback_rate','severity','high','pct',v_fb,
         'detail','the primary model is failing often - you are paying fallback prices silently');
  end if;

  -- 3. outright failures
  select count(*) into v_fail from llm_calls
   where created_at > now() - interval '24 hours' and not ok;
  if v_fail > 5 then
    v := v || jsonb_build_object('issue','llm_failures','severity','medium','count',v_fail);
  end if;

  if jsonb_array_length(v) > 0 then
    v_owner := split_part(coalesce((select value from app_secrets where key='admin_emails'),
                                   'management@quotesdone.com'), ',', 1);
    -- once per 24h only, so a standing problem does not spam (lesson from the smoke check)
    if not exists (select 1 from founder_alerts
                    where event='llm_drift' and created_at > now() - interval '24 hours') then
      insert into founder_alerts(level,event,detail,channel)
        values ('warn','llm_drift','Model policy drift: '||v::text, 'system');
      insert into notifications(type,to_email,to_role,channel,subject,body,status)
        values ('llm_drift', v_owner, 'admin', 'email', 'QuotesDone: AI model drift detected',
                'The model-policy watch found issues in the last 24h:'||chr(10)||chr(10)||
                jsonb_pretty(v)||chr(10)||chr(10)||
                'Check the AI Observability view (v_llm_model_mix / v_llm_offpolicy).', 'queued');
    end if;
  end if;

  return jsonb_build_object('checked_at', now(), 'calls_24h', v_recent,
                            'findings', jsonb_array_length(v), 'detail', v);
end $function$


CREATE OR REPLACE FUNCTION public.fn_llm_log(p_fn text, p_dept text, p_agent text, p_task_class text, p_model text, p_because text, p_tier text, p_prompt_tokens integer, p_output_tokens integer, p_cached boolean, p_cache_key text, p_latency_ms integer, p_ok boolean)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_cost numeric := 0; v_in numeric; v_out numeric; v_cheaper boolean := false; v_reason text; v_alt text;
begin
  if not coalesce(p_cached,false) then
    select in_aed_per_mtok, out_aed_per_mtok into v_in, v_out from model_rate where model = p_model;
    if v_in is not null then
      v_cost := round( coalesce(p_prompt_tokens,0)/1000000.0 * v_in
                     + coalesce(p_output_tokens,0)/1000000.0 * v_out, 6);
    end if;
  end if;

  select deterministic_alternative into v_alt from model_policy where task_class = p_task_class;
  if v_alt is not null and v_alt <> '' then
    v_cheaper := true; v_reason := 'A deterministic path exists for this task class: ' || v_alt;
  elsif not coalesce(p_cached,false) and exists (
      select 1 from model_rate used join model_rate alt on alt.model = 'anthropic/claude-sonnet-5'
      where used.model = p_model and used.out_aed_per_mtok > alt.out_aed_per_mtok) then
    v_cheaper := true; v_reason := 'claude-sonnet-5 is cheaper than ' || p_model || ' for the same output.';
  elsif not coalesce(p_cached,false) and coalesce(p_output_tokens,0) < 200
      and exists (select 1 from model_policy mp where mp.task_class = p_task_class and mp.tier = 'small') then
    v_cheaper := true; v_reason := 'Output under 200 tokens on a small-tier class - a cache entry or a rule may serve this without a model call.';
  end if;

  insert into ai_cost_log (fn, dept_key, agent_key, task_class, model_used, model_selected_because, tier,
                           prompt_tokens, output_tokens, cached, cache_hit_key, latency_ms, cost_aed,
                           could_be_cheaper, cheaper_reason, ok)
  values (p_fn, p_dept, p_agent, p_task_class, p_model, p_because, p_tier,
          p_prompt_tokens, p_output_tokens, coalesce(p_cached,false), p_cache_key, p_latency_ms, v_cost,
          v_cheaper, v_reason, coalesce(p_ok,true));

  if p_dept is not null and v_cost > 0 then
    update department_budget set spent_aed = coalesce(spent_aed,0) + v_cost, updated_at = now()
    where dept_key = p_dept;
  end if;

  return v_cost;
end; $function$


CREATE OR REPLACE FUNCTION public.fn_marketing_ai()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare k record; v_plan jsonb; v_health numeric; n_rec int; push jsonb; contentgaps jsonb; topcats text;
  s_cadence numeric; s_reach numeric; s_funnel numeric; s_pipeline numeric; v_meta_idle boolean; v_meta_has boolean;
begin
  select * into k from marketing_kpis;
  v_meta_has := exists(select 1 from meta_insights where campaign_name ilike '%quotesdone%');
  v_meta_idle := v_meta_has and (coalesce(k.meta_active_campaigns,0)=0 or coalesce(k.meta_spend_30d,0)=0);

  select coalesce(jsonb_agg(jsonb_build_object('category',category,'inquiries_90d',inquiries_90d,'suppliers',suppliers) order by inquiries_90d desc, suppliers asc),'[]'::jsonb)
    into push from (select * from marketing_category_demand where inquiries_90d>0 and suppliers=0 order by inquiries_90d desc, suppliers asc limit 8) t;
  select coalesce(jsonb_agg(jsonb_build_object('category',category,'has_seo',has_seo_page,'has_blog',has_blog) order by inquiries_90d desc),'[]'::jsonb)
    into contentgaps from (select * from marketing_category_demand where (not has_seo_page or not has_blog) order by inquiries_90d desc limit 8) t;
  select string_agg(category,', ') into topcats from (select category from marketing_category_demand where inquiries_90d>0 and suppliers=0 order by inquiries_90d desc limit 5) t;

  v_plan := jsonb_build_object(
    'as_of', now(),
    'push_supply', push,
    'content_gaps', contentgaps,
    'cadence', jsonb_build_object('blog_published',k.blog_published,'drafts_pending',k.drafts_pending,'social_staged',k.social_staged),
    'funnel', jsonb_build_object('inq_to_quote_pct',k.inq_to_quote_pct,'quote_to_reveal_pct',k.quote_to_reveal_pct,'revenue_30d',k.revenue_30d),
    'meta', jsonb_build_object('spend_30d',k.meta_spend_30d,'clicks_30d',k.meta_clicks_30d,'results_30d',k.meta_results_30d,'active_campaigns',k.meta_active_campaigns,'cpl',k.meta_cpl,'roi',k.meta_roi,'idle',v_meta_idle),
    'priorities', (
      select coalesce(jsonb_agg(p),'[]'::jsonb) from (
        select 'Launch & fund your paused QuotesDone Meta campaign to generate leads' as p where v_meta_idle
        union all select 'Onboard suppliers in: '||coalesce(topcats,'—') where k.supply_gaps>0
        union all select 'Review & publish '||k.drafts_pending||' pending content drafts' where k.drafts_pending>0
        union all select 'Stage social posts for this week' where coalesce(k.social_staged,0)=0
        union all select 'Generate SEO pages for '||k.seo_gaps||' uncovered categories' where k.seo_gaps>0
      ) x
    )
  );

  s_cadence := least(100, (case when k.blog_published>0 then 50 else 0 end) + (case when k.social_staged>0 then 30 else 0 end) + (case when k.drafts_pending between 1 and 10 then 20 when k.drafts_pending=0 then 10 else 5 end));
  s_reach := least(100, coalesce(k.seo_generated,0)*3);
  s_funnel := coalesce(k.quote_to_reveal_pct, 40);
  s_pipeline := least(100, (case when k.leads_total>1000 then 60 else k.leads_total/20.0 end) + least(40, k.outreach_sent));
  v_health := round(s_cadence*0.30 + s_reach*0.25 + s_funnel*0.25 + s_pipeline*0.20,1);

  insert into marketing_snapshots(snapshot_date, kpis, plan)
  values (current_date, to_jsonb(k) || jsonb_build_object('health',v_health), v_plan)
  on conflict (snapshot_date) do update set kpis=excluded.kpis, plan=excluded.plan, created_at=now();

  perform mkt_rec('supply_gap', coalesce(k.supply_gaps,0)>0, 'medium', 'Demand without supply',
    coalesce(k.supply_gaps,0)||' categor'||(case when k.supply_gaps=1 then 'y has' else 'ies have' end)||' customer demand but no approved suppliers'||(case when topcats is not null then ' ('||topcats||')' else '' end)||'. Prioritise supplier onboarding / BD there.');
  perform mkt_rec('drafts_backlog', coalesce(k.drafts_pending,0)>10, 'low', 'Content drafts awaiting review',
    k.drafts_pending||' content drafts are pending your review. Approve or publish to grow organic reach.');
  perform mkt_rec('no_social', coalesce(k.social_staged,0)=0, 'low', 'No social posts queued',
    'No social posts are staged. Queue this week''s posts to keep the channels active.');
  perform mkt_rec('seo_gap', coalesce(k.seo_gaps,0)>0, 'low', 'SEO coverage gaps',
    k.seo_gaps||' categories lack an SEO page. Generate them to capture search demand.');
  perform mkt_rec('meta_idle', v_meta_idle, 'medium', 'Meta ad campaign idle',
    'Your QuotesDone Meta campaign is paused / not spending. Launch and fund it to start generating leads — the platform will track spend, results, CPL and ROI automatically once a Meta access token is added.');

  select count(*) into n_rec from agent_actions where agent='marketing_ai' and status in ('pending','needs_review');
  return jsonb_build_object('ran_at',now(),'health',v_health,'kpis',to_jsonb(k),'plan',v_plan,'open_recommendations',n_rec);
end $function$


CREATE OR REPLACE FUNCTION public.fn_marketing_blog_publish(p_id uuid, p_published boolean, p_by text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare r public.blog_posts%rowtype;
begin
  update public.blog_posts set published = p_published,
    published_at = case when p_published and published_at is null then now() else published_at end,
    updated_at = now()
  where id = p_id returning * into r;
  if r.id is null then return jsonb_build_object('ok', false, 'error', 'not_found'); end if;
  begin insert into public.os_audit_log(actor, action, entity, entity_id, detail)
    values (coalesce(nullif(btrim(p_by),''),'operator'), case when p_published then 'blog_publish' else 'blog_unpublish' end, 'blog_posts', p_id::text, jsonb_build_object('title', r.title));
  exception when others then null; end;
  return jsonb_build_object('ok', true, 'published', r.published);
end $function$


CREATE OR REPLACE FUNCTION public.fn_marketing_library_search(p_query text, p_limit integer DEFAULT 5)
 RETURNS TABLE(id bigint, category text, title text, content text, rank real)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare q_or tsquery; words text[];
begin
  words := array(
    select w from unnest(
      regexp_split_to_array(lower(regexp_replace(coalesce(p_query,''),'[^a-z0-9 ]',' ','g')), '\s+')
    ) w where length(w) > 2);
  if array_length(words,1) is null then return; end if;
  begin
    q_or := to_tsquery('english', array_to_string(words, ' | '));
  exception when others then return; end;
  return query
    select l.id, l.category, l.title, l.content, ts_rank(l.tsv, q_or) as rank
    from public.marketing_library l
    where l.tsv @@ q_or
    order by ts_rank(l.tsv, q_or) desc, l.id
    limit greatest(1, least(coalesce(p_limit,5), 20));
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_marketing_studio()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'kpis', (select to_jsonb(k) from marketing_kpis k limit 1),
    'trend', coalesce((select jsonb_agg(jsonb_build_object(
        'd', to_char(s.snapshot_date,'Mon DD'),
        'leads', nullif(s.kpis->>'leads_total','')::numeric,
        'blog', nullif(s.kpis->>'blog_published','')::numeric,
        'social', nullif(s.kpis->>'social_published','')::numeric,
        'seo', nullif(s.kpis->>'seo_pages','')::numeric
      ) order by s.snapshot_date) from marketing_snapshots s),'[]'::jsonb),
    'social', coalesce((select jsonb_agg(jsonb_build_object(
        'id', p.id, 'image_url', p.image_url,
        'text', coalesce(p.content->>'all', p.content->>'text', left(p.content::text,400)),
        'channels', to_jsonb(p.channels), 'status', p.status, 'mode', p.mode, 'error', p.error, 'created_at', p.created_at
      ) order by p.created_at desc) from social_posts p),'[]'::jsonb),
    'blog', coalesce((select jsonb_agg(jsonb_build_object(
        'id', b.id, 'title', b.title, 'slug', b.slug, 'category', b.category, 'excerpt', b.excerpt,
        'published', b.published, 'published_at', b.published_at, 'body_html', left(b.body_html, 24000)
      ) order by b.updated_at desc) from blog_posts b),'[]'::jsonb),
    'review', (select coalesce(fn_review_pending(),'[]'::jsonb))
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_marketplace_analytics()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare res jsonb;
begin
  with q_first as (  -- first quote latency per rfq
    select i.id, min(qq.created_at) as first_quote_at, i.created_at, i.category
    from inquiries i left join quotes qq on qq.inquiry_id = i.id group by i.id, i.created_at, i.category
  ),
  spread as (  -- savings potential per rfq with >=2 quotes
    select inquiry_id, min(quote_amount) lo, max(quote_amount) hi, count(*) n
    from quotes where quote_amount > 0 group by inquiry_id having count(*) >= 2
  )
  select jsonb_build_object(
    'rfqs_today',   (select count(*) from inquiries where created_at >= date_trunc('day', now())),
    'rfqs_7d',      (select count(*) from inquiries where created_at >= now() - interval '7 days'),
    'rfqs_30d',     (select count(*) from inquiries where created_at >= now() - interval '30 days'),
    'avg_first_quote_hours', (select round(avg(extract(epoch from (first_quote_at - created_at))/3600.0)::numeric,1) from q_first where first_quote_at is not null),
    'response_rate_pct', (
      select case when count(*)>0 then round(100.0 * count(*) filter (where exists (
        select 1 from quotes q where q.inquiry_id = m.inquiry_id and q.supplier_id = m.supplier_id)) / count(*), 1) else null end
      from inquiry_matches m),
    'avg_savings_pct', (select round(avg(case when hi>0 then 100.0*(hi-lo)/hi else 0 end)::numeric,1) from spread),
    'abandoned_rfqs', (select count(*) from inquiries i where i.created_at < now() - interval '7 days'
                        and coalesce(i.status,'') not in ('completed','cancelled')
                        and not exists (select 1 from quotes q where q.inquiry_id = i.id)),
    'active_suppliers_30d', (select count(distinct supplier_id) from quotes where created_at >= now() - interval '30 days'),
    'supplier_capacity_avg', (select round(avg(c)::numeric,1) from (select supplier_id, count(*) c from quotes where created_at >= now() - interval '30 days' group by supplier_id) s),
    'competitive_categories', (
      select coalesce(jsonb_agg(x order by x.avg_quotes desc), '[]'::jsonb) from (
        select i.category, round(avg(qc.c)::numeric,2) as avg_quotes, count(*) as rfqs
        from inquiries i join (select inquiry_id, count(*) c from quotes group by inquiry_id) qc on qc.inquiry_id=i.id
        where i.created_at >= now() - interval '90 days' and i.category is not null
        group by i.category order by avg_quotes desc limit 8) x),
    'category_growth', (
      select coalesce(jsonb_agg(g), '[]'::jsonb) from (
        select category,
          count(*) filter (where created_at >= now() - interval '30 days') as this_30d,
          count(*) filter (where created_at >= now() - interval '60 days' and created_at < now() - interval '30 days') as prev_30d
        from inquiries where category is not null and created_at >= now() - interval '60 days'
        group by category order by this_30d desc limit 10) g),
    'generated_at', now()
  ) into res;
  return res;
end $function$


CREATE OR REPLACE FUNCTION public.fn_match_capability(p_trades text[], p_need text DEFAULT 'executes'::text, p_products text[] DEFAULT '{}'::text[], p_brands text[] DEFAULT '{}'::text[], p_project_type text DEFAULT NULL::text, p_value numeric DEFAULT NULL::numeric, p_emirate text DEFAULT NULL::text, p_limit integer DEFAULT 12)
 RETURNS TABLE(supplier_id bigint, company_name text, score numeric, trades text[], roles text[], product_hits integer, brand_hit boolean, ptype_hit boolean, track numeric, why text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
with w as (
  select coalesce((select value::text::numeric from decision_policy where key='score_w_product'),40)      as w_prod,
         coalesce((select value::text::numeric from decision_policy where key='score_w_brand'),20)        as w_brand,
         coalesce((select value::text::numeric from decision_policy where key='score_w_project_type'),15) as w_ptype,
         coalesce((select value::text::numeric from decision_policy where key='score_w_track_record'),15) as w_track,
         coalesce((select value::text::numeric from decision_policy where key='score_w_size_fit'),10)     as w_size
),
req_auth as (
  select coalesce(array_agg(distinct a),'{}') as codes
  from public.taxonomy_trade t, unnest(t.authority_required) a
  where t.code = any(p_trades)
),
cand as (
  select sc.supplier_id, sc.trades, sc.roles, sc.products_norm, sc.brands, sc.project_types,
         sc.min_project_value, sc.max_project_value, sc.coverage_emirates,
         l.company_name, l.emirate as lead_emirate,
         least(1, greatest(0, coalesce(sp.quote_rate, sp.perf_score, 0))) as track
  from public.supplier_capabilities sc
  join public.leads l on l.id = sc.supplier_id
  left join public.supplier_perf sp on sp.supplier_id = sc.supplier_id
  where sc.confirmed_at is not null                        -- GATE: supplier confirmed their own scope
    and sc.trades && p_trades                              -- GATE: trade intersection
    and not (sc.excluded_trades && p_trades)               -- GATE: declared negative scope
    and public.fn_is_matchable(l.verified, l.banned, l.matching_blocked,
                               l.approval_status, l.permanently_closed, l.chat_strikes)
    and exists (                                            -- GATE: role can actually do this kind of work
      select 1 from public.taxonomy_role r
      where r.code = any(sc.roles)
        and case p_need when 'supplies'    then r.supplies
                        when 'whole_scope' then r.whole_scope
                        else r.executes end
    )
    and not exists (                                        -- GATE: every mandatory authority held
      select 1 from unnest((select codes from req_auth)) a
      where not (sc.authority_approvals ? a)
    )
    and (p_value is null or (                               -- GATE: job size inside their range
          (sc.min_project_value is null or p_value >= sc.min_project_value)
      and (sc.max_project_value is null or p_value <= sc.max_project_value)))
    and (p_emirate is null or                               -- GATE: they cover the emirate asked for
         coalesce(cardinality(sc.coverage_emirates), 0) = 0
      or exists (select 1 from unnest(sc.coverage_emirates) ce where ce ilike p_emirate)
      or l.emirate ilike p_emirate)
),
scored as (
  select c.*,
    (select count(distinct pq) from unnest(p_products) pq
      where exists (select 1 from unnest(c.products_norm) pp
                    where pp ilike '%'||pq||'%' or pq ilike '%'||pp||'%'))::int as product_hits,
    (cardinality(p_brands) > 0 and exists (
       select 1 from unnest(p_brands) bq join unnest(c.brands) bb on bb ilike '%'||bq||'%' or bq ilike '%'||bb||'%'
     )) as brand_hit,
    (p_project_type is not null and exists (
       select 1 from unnest(c.project_types) pt
       where pt ilike '%'||p_project_type||'%' or p_project_type ilike '%'||pt||'%'
     )) as ptype_hit,
    (p_value is not null and c.min_project_value is not null and c.max_project_value is not null) as size_known
  from cand c
)
select s.supplier_id, s.company_name,
  round(
      w.w_prod  * (case when cardinality(p_products) > 0
                        then s.product_hits::numeric / cardinality(p_products) else 0 end)
    + w.w_brand * (case when s.brand_hit then 1 else 0 end)
    + w.w_ptype * (case when s.ptype_hit then 1 else 0 end)
    + w.w_track * s.track
    + w.w_size  * (case when s.size_known then 1 else 0.5 end)
  , 1) as score,
  s.trades, s.roles, s.product_hits, s.brand_hit, s.ptype_hit, round(s.track,3) as track,
  concat_ws(' · ',
    'trades ' || array_to_string(array(select unnest(s.trades) intersect select unnest(p_trades)), '+'),
    case when s.product_hits > 0 then s.product_hits||'/'||cardinality(p_products)||' products' end,
    case when s.brand_hit then 'brand match' end,
    case when s.ptype_hit then 'project type' end,
    case when p_emirate is not null then
      case when coalesce(cardinality(s.coverage_emirates),0) = 0 then 'coverage not stated'
           else 'covers ' || p_emirate end end
  ) as why
from scored s, w
order by score desc, s.track desc, s.supplier_id
limit greatest(1, p_limit);
$function$


CREATE OR REPLACE FUNCTION public.fn_matching_strike_limit()
 RETURNS integer
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select coalesce((select value::text::int from public.decision_policy where key='matching_strike_limit'), 3);
$function$


CREATE OR REPLACE FUNCTION public.fn_memory_search(p_q text, p_kinds text[] DEFAULT NULL::text[], p_lim integer DEFAULT 20)
 RETURNS TABLE(kind text, ref text, snippet text, ts timestamp with time zone, score real)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with qy as (select plainto_tsquery('english', coalesce(p_q,'')) q)
  select s.kind, s.ref, s.snippet, s.ts, s.score from (
    select 'rfq'::text kind, i.id::text ref, left(coalesce(i.summary, i.raw_input, i.spec::text),220) snippet,
           i.created_at ts, ts_rank(to_tsvector('english', coalesce(i.summary,'')||' '||coalesce(i.raw_input,'')||' '||coalesce(i.spec::text,'')||' '||coalesce(i.category,'')), qy.q) score
    from inquiries i, qy where (p_kinds is null or 'rfq'=any(p_kinds))
      and to_tsvector('english', coalesce(i.summary,'')||' '||coalesce(i.raw_input,'')||' '||coalesce(i.spec::text,'')||' '||coalesce(i.category,'')) @@ qy.q
    union all
    select 'quote', q.id::text, left(coalesce(q.scope, q.notes),220), q.created_at,
           ts_rank(to_tsvector('english', coalesce(q.scope,'')||' '||coalesce(q.notes,'')||' '||coalesce(q.conditions,'')), qy.q)
    from quotes q, qy where (p_kinds is null or 'quote'=any(p_kinds))
      and to_tsvector('english', coalesce(q.scope,'')||' '||coalesce(q.notes,'')||' '||coalesce(q.conditions,'')) @@ qy.q
    union all
    select 'supplier', l.id::text, left(coalesce(l.company_name,'')||' — '||coalesce(l.capability_summary, l.description, l.services),220), l.created_at,
           ts_rank(to_tsvector('english', coalesce(l.company_name,'')||' '||coalesce(l.capability_summary,'')||' '||coalesce(l.services,'')||' '||coalesce(l.description,'')||' '||coalesce(l.categories,'')), qy.q)
    from leads l, qy where (p_kinds is null or 'supplier'=any(p_kinds))
      and to_tsvector('english', coalesce(l.company_name,'')||' '||coalesce(l.capability_summary,'')||' '||coalesce(l.services,'')||' '||coalesce(l.description,'')||' '||coalesce(l.categories,'')) @@ qy.q
    union all
    select 'customer', c.id::text, left(coalesce(c.full_name,'')||' '||coalesce(c.email,''),220), c.created_at,
           ts_rank(to_tsvector('english', coalesce(c.full_name,'')||' '||coalesce(c.email,'')), qy.q)
    from customers c, qy where (p_kinds is null or 'customer'=any(p_kinds))
      and to_tsvector('english', coalesce(c.full_name,'')||' '||coalesce(c.email,'')) @@ qy.q
    union all
    select 'case', a.rfq_id, left(coalesce(a.ai_summary->>'summary',''),220), a.created_at,
           ts_rank(to_tsvector('english', coalesce(a.ai_summary->>'summary','')||' '||coalesce(a.category,'')), qy.q)
    from rfq_archives a, qy where (p_kinds is null or 'case'=any(p_kinds))
      and to_tsvector('english', coalesce(a.ai_summary->>'summary','')||' '||coalesce(a.category,'')) @@ qy.q
    union all
    select 'knowledge', k.agent_key||' :: '||k.topic, left(k.content,220), k.created_at,
           ts_rank(to_tsvector('english', coalesce(k.topic,'')||' '||coalesce(k.content,'')), qy.q)
    from agent_knowledge k, qy where (p_kinds is null or 'knowledge'=any(p_kinds))
      and to_tsvector('english', coalesce(k.topic,'')||' '||coalesce(k.content,'')) @@ qy.q
    union all
    select 'decision', dl.id::text, left(dl.kind||' -> '||coalesce(dl.decision,'')||' '||coalesce(dl.reasons::text,''),220), dl.created_at,
           ts_rank(to_tsvector('english', coalesce(dl.kind,'')||' '||coalesce(dl.decision,'')||' '||coalesce(dl.reasons::text,'')), qy.q)
    from decision_log dl, qy where (p_kinds is null or 'decision'=any(p_kinds))
      and to_tsvector('english', coalesce(dl.kind,'')||' '||coalesce(dl.decision,'')||' '||coalesce(dl.reasons::text,'')) @@ qy.q
  ) s
  order by s.score desc, s.ts desc
  limit greatest(1, coalesce(p_lim,20));
$function$


CREATE OR REPLACE FUNCTION public.fn_mep_full_scope(p_text_norm text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r record; v_re text; v_sep text := '[^[:alnum:].;,،؛' || chr(10) || ']+';
begin
  for r in select pattern_norm, lang from public.mep_trade_pattern where kind = 'mep_full_phrase' loop
    if public.fn_term_matches(p_text_norm, r.pattern_norm, r.lang) then
      return jsonb_build_object('matched', true, 'basis', 'explicit_full_mep_phrase',
                                'anchor', r.pattern_norm, 'modifier', null, 'modifier_kind', null);
    end if;
  end loop;

  for r in
    select a.pattern_norm as anchor, m.pattern_norm as modifier, m.kind as modifier_kind, a.lang
      from public.mep_trade_pattern a
      join public.mep_trade_pattern m on m.kind in ('scope_full','scope_container')
     where a.kind = 'mep_anchor'
  loop
    v_re := '(^|[^[:alnum:]])' || r.anchor || '(' || v_sep || '[[:alnum:]]+){0,2}' || v_sep
            || r.modifier || '($|[^[:alnum:]])';
    if p_text_norm ~ v_re then
      return jsonb_build_object('matched', true, 'basis', 'anchor_plus_modifier',
                                'anchor', r.anchor, 'modifier', r.modifier,
                                'modifier_kind', r.modifier_kind);
    end if;
    v_re := '(^|[^[:alnum:]])' || r.modifier || '(' || v_sep || '[[:alnum:]]+){0,2}' || v_sep
            || r.anchor || '($|[^[:alnum:]])';
    if p_text_norm ~ v_re then
      return jsonb_build_object('matched', true, 'basis', 'modifier_plus_anchor',
                                'anchor', r.anchor, 'modifier', r.modifier,
                                'modifier_kind', r.modifier_kind);
    end if;
  end loop;

  return jsonb_build_object('matched', false, 'basis', null);
end $function$


CREATE OR REPLACE FUNCTION public.fn_model_autoswitch()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v_new text; v_n int := 0;
begin
  for r in
    select o.task_class, o.model_used,
           avg(case when o.ok and coalesce(o.parse_ok,true) then 1.0 else 0.0 end) sr, count(*) n
    from model_outcome o
    where o.occurred_at > now() - interval '14 days'
    group by 1,2 having count(*) >= 20
       and avg(case when o.ok and coalesce(o.parse_ok,true) then 1.0 else 0.0 end) < 0.85
  loop
    -- only act if this model is still the primary for that class
    if not exists (select 1 from model_policy p where p.task_class = r.task_class
                    and p.model_primary = r.model_used and p.active) then continue; end if;

    select mr.model_id into v_new from model_registry mr
     join model_registry cur on cur.model_id = r.model_used
     where mr.active and mr.approved and mr.in_per_mtok_usd > cur.in_per_mtok_usd
     order by mr.in_per_mtok_usd asc limit 1;
    if v_new is null then continue; end if;

    update model_policy set model_primary = v_new where task_class = r.task_class and active;
    v_n := v_n + 1;

    insert into founder_alerts (level, event, detail, channel)
    values ('warn','model_autoswitched',
      'Task class "' || r.task_class || '" was failing on ' || r.model_used || ' (' ||
      round(r.sr*100,1) || '% success over ' || r.n || ' runs, floor 85%). Promoted to ' || v_new ||
      '. Cheaper is only correct while it works; this is the loop that checks.', 'system');

    insert into org_tasks (dept_key, title, detail, status, tier, action_class, needs_founder)
    values ('it', left('Model auto-switched for ' || r.task_class, 200),
      'Automatic promotion after measured failure. Class: ' || r.task_class ||
      E'\nWas: ' || r.model_used || ' at ' || round(r.sr*100,1) || '% success over ' || r.n || ' runs' ||
      E'\nNow: ' || v_new ||
      E'\n\nReview whether the prompt is at fault rather than the model - a badly specified task fails on every tier, and promoting it just costs more.',
      'proposed','supervised','analysis', false);
  end loop;
  return v_n;
end $function$


CREATE OR REPLACE FUNCTION public.fn_model_benchmark()
 RETURNS TABLE(task_class text, model_used text, runs bigint, success_rate numeric, avg_cost_usd numeric, verdict text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  return query
  with s as (
    select o.task_class, o.model_used,
           count(*) as runs,
           round(avg(case when o.ok and coalesce(o.parse_ok, true) then 1.0 else 0.0 end), 4) as success_rate,
           round(avg(o.cost_usd)::numeric, 6) as avg_cost_usd
    from model_outcome o
    where o.occurred_at > now() - interval '30 days'
    group by 1, 2
    having count(*) >= 20   -- never judge a model on a handful of runs
  )
  select s.task_class, s.model_used, s.runs, s.success_rate, s.avg_cost_usd,
         case
           when s.success_rate >= 0.95 then 'GOOD - safe to keep or promote for this class'
           when s.success_rate >= 0.85 then 'ACCEPTABLE - watch'
           else 'POOR - this class needs a stronger tier'
         end
  from s order by s.task_class, s.success_rate desc;

  -- Feed the score back onto the registry so routing can see it.
  update model_registry r set quality_score = q.sr, updated_at = now()
  from (
    select o.model_used, round(avg(case when o.ok and coalesce(o.parse_ok,true) then 1.0 else 0.0 end),4) sr
    from model_outcome o where o.occurred_at > now() - interval '30 days'
    group by 1 having count(*) >= 20
  ) q
  where r.model_id = q.model_used;
end $function$


CREATE OR REPLACE FUNCTION public.fn_model_cost_usd(p_model text, p_in_tokens integer, p_out_tokens integer, p_cached_in_tokens integer DEFAULT 0)
 RETURNS numeric
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select round(
      ( (greatest(coalesce(p_in_tokens,0) - coalesce(p_cached_in_tokens,0), 0)::numeric / 1000000) * r.in_per_mtok_usd
      + (coalesce(p_cached_in_tokens,0)::numeric / 1000000) * coalesce(r.cache_read_per_mtok_usd, r.in_per_mtok_usd)
      + (coalesce(p_out_tokens,0)::numeric / 1000000) * r.out_per_mtok_usd
      )::numeric, 6)
  from model_registry r where r.model_id = p_model;
$function$


CREATE OR REPLACE FUNCTION public.fn_monthly_report()
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ select public.fn_period_report('monthly'); $function$


CREATE OR REPLACE FUNCTION public.fn_norm_roles(p_text text)
 RETURNS text[]
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select coalesce(array_agg(distinct r.code order by r.code), '{}')
  from public.taxonomy_role r
  where r.active
    and exists (
      select 1 from unnest(r.aliases || r.code) a
      where length(a) >= 3
        and coalesce(p_text,'') ~* ('\m' || regexp_replace(a, '([.*+?^${}()|\[\]\\])', '\\\1', 'g'))
    );
$function$


CREATE OR REPLACE FUNCTION public.fn_norm_text(p_text text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select translate(
           regexp_replace(
             lower(btrim(regexp_replace(coalesce(p_text,''), '\s+', ' ', 'g'))),
             '[ًٌٍَُِّْـٰ]', '', 'g'),
           'أإآٱىة', 'اااايه');
$function$


CREATE OR REPLACE FUNCTION public.fn_norm_trades(p_text text)
 RETURNS text[]
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select coalesce(array_agg(distinct t.code order by t.code), '{}')
  from public.taxonomy_trade t
  where t.active
    and exists (
      select 1 from unnest(t.aliases || t.code) a
      where length(a) >= 3
        and coalesce(p_text,'') ~* ('\m' || regexp_replace(a, '([.*+?^${}()|\[\]\\])', '\\\1', 'g'))
    );
$function$


CREATE OR REPLACE FUNCTION public.fn_normalize_founder_alert_level()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF lower(coalesce(NEW.level,'')) = 'crit' THEN NEW.level := 'critical'; END IF;
  RETURN NEW;
END
$function$


CREATE OR REPLACE FUNCTION public.fn_notifications_dead_letter_held(p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_moved int := 0;
begin
  with old as (
    select * from public.notifications
     where status = 'held' and created_at < now() - make_interval(days => greatest(1, p_days))
  ), ins as (
    insert into public.dead_letter (source, source_id, kind, reason, payload, first_failed_at)
    select 'notifications', o.id::text, o.type,
           'held longer than ' || p_days || ' days; supplier mail was disabled and never re-enabled',
           to_jsonb(o) - 'body', o.created_at
      from old o
    returning 1
  )
  update public.notifications n set status = 'dead'
    from old o where n.id = o.id;
  get diagnostics v_moved = row_count;
  return jsonb_build_object('ok', true, 'dead_lettered', v_moved);
end $function$


CREATE OR REPLACE FUNCTION public.fn_notifications_digest()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare types jsonb;
begin
  if coalesce(NEW.channel,'email') <> 'email' then return NEW; end if;
  if NEW.status is not null and NEW.status not in ('queued','pending') then return NEW; end if;
  if coalesce(NEW.to_role,'') not in ('admin','founder','owner') then return NEW; end if;
  -- HARD EXCLUSIONS: these always send immediately regardless of policy.
  if coalesce(NEW.type,'') ~* 'money|refund|security|legal|fraud|critical|founder_alert|chief_of_staff|founder_brief|verify|otp|reset|password' then return NEW; end if;
  if coalesce(NEW.subject,'') ~* 'critical|urgent|fraud|breach|\mdown\M|failed|failure' then return NEW; end if;
  -- POLICY allowlist of routine types to fold into the brief.
  select value into types from public.decision_policy where key='alert_digest_types';
  if types is not null and types ? coalesce(NEW.type,'') then
    NEW.status := 'digest';
  end if;
  return NEW;
exception when others then
  return NEW;  -- a classifier error must never block a notification insert
end $function$


CREATE OR REPLACE FUNCTION public.fn_notifications_release_held(p_max integer DEFAULT 500)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_released int;
begin
  with picked as (
    select id from public.notifications where status = 'held' order by id limit greatest(1, p_max)
  )
  update public.notifications n set status = 'queued'
    from picked p where n.id = p.id
  returning 1 into v_released;
  get diagnostics v_released = row_count;
  return jsonb_build_object('ok', true, 'released', v_released);
end $function$


CREATE OR REPLACE FUNCTION public.fn_notify_matched_supplier()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_email text; v_cat text; v_em text;
begin
  select email into v_email from leads where id=NEW.supplier_id;
  select category, emirate into v_cat, v_em from inquiries where id=NEW.inquiry_id;
  if v_email is not null and position('@' in v_email) > 1 then
    insert into notifications(type,to_email,to_role,lead_id,inquiry_id,subject,body,channel,status)
    values('new_inquiry', v_email, 'supplier', NEW.supplier_id, NEW.inquiry_id,
      'New job request on QuotesDone',
      'A customer is requesting quotes for: '||coalesce(v_cat,'a project')||coalesce(' ('||v_em||')','')||
      '. Log in to your QuotesDone supplier portal to view the brief and submit your quote.',
      'email','queued');
  end if;
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.fn_notify_supplier(p_transaction uuid, p_actor text DEFAULT 'customer'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare t record; st jsonb; sup record; cust_email text; v_admin text; v_subject text; v_body text;
        v_call_days int; v_claim_days int; v_new_deadline timestamptz;
begin
  st := public.fn_refund_state(p_transaction);
  if st ? 'error' then return st; end if;
  if (st->>'can_notify') <> 'true' then
    return jsonb_build_object('ok', false, 'error', 'not_available', 'state', st->>'state',
                              'notify_available_at', st->>'notify_available_at');
  end if;

  select * into t from transactions where id = p_transaction;
  select company_name, coalesce(claimed_by, email) as email into sup from leads where id = t.supplier_id;
  select email into cust_email from customers where id = t.customer_id;
  v_admin := coalesce((select split_part(value,',',1) from app_secrets where key='admin_emails'),
                      'management@quotesdone.com');

  v_call_days  := coalesce((select value::text::int from decision_policy where key='refund_call_after_working_days'), 3);
  v_claim_days := coalesce((select value::text::int from decision_policy where key='refund_claim_after_call_working_days'), 3);

  v_subject := 'Awaiting your response — QuotesDone reveal #' || left(t.id::text, 8);
  v_body :=
    'Hello,' || chr(10) || chr(10) ||
    'A customer paid to reveal your contact details on QuotesDone on ' ||
      to_char(t.revealed_at at time zone 'Asia/Dubai','DD Mon YYYY') ||
      ' and has not yet heard from you.' || chr(10) || chr(10) ||
    'Everyone is copied on this email so you can simply reply to all and pick it up here.' || chr(10) || chr(10) ||
    'If we have not heard from you within ' || v_call_days::text ||
      ' working days, we will call you. If we still cannot reach you and the customer is refunded, the reveal fee is recovered from your account under the supplier terms.' || chr(10) || chr(10) ||
    'If you have already been in touch with this customer, reply here and we will close this off.' || chr(10) || chr(10) ||
    'QuotesDone';

  insert into notifications(type, to_email, cc_emails, to_role, lead_id, inquiry_id, channel, subject, body, status)
  values ('reveal_no_response_notice', sup.email,
          array_remove(array[cust_email, v_admin], null),
          'supplier', t.supplier_id, t.inquiry_id, 'email', v_subject, v_body, 'queued');

  -- Deadline must outlive the ladder the customer is being asked to follow.
  v_new_deadline := public.fn_add_working_days(
                      public.fn_add_working_days(now(), v_call_days), v_claim_days);

  update transactions
     set customer_notified_at = now(),
         refund_deadline = greatest(coalesce(refund_deadline, now()), v_new_deadline)
   where id = p_transaction;

  insert into agent_actions(agent, kind, status, risk, title, recommendation, detail, target_table, target_id)
  values ('customer_success','supplier_unresponsive','needs_review','high',
          'Supplier not responding after a paid reveal: ' || coalesce(sup.company_name,'#'||t.supplier_id),
          'Customer has formally notified them. Call the supplier after the working-day window; a refund may only be approved once that has elapsed.',
          jsonb_build_object('transaction_id', t.id, 'supplier_id', t.supplier_id,
                             'inquiry_id', t.inquiry_id, 'notified_at', now(),
                             'call_due_at', public.fn_add_working_days(now(), v_call_days),
                             'refund_claim_until', v_new_deadline),
          'transactions', t.id::text);

  return jsonb_build_object('ok', true, 'notified_at', now(),
                            'recipients', jsonb_build_array(sup.email, cust_email, v_admin),
                            'refund_claim_until', v_new_deadline,
                            'state', public.fn_refund_state(p_transaction));
end $function$


CREATE OR REPLACE FUNCTION public.fn_officer_recs(n integer DEFAULT 8)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select string_agg(line, E'\n') from (
    select '- ['||er.officer||'] '||left(coalesce(rec->>'action',''),150) as line
    from (select distinct on (officer) officer, recommendations from exec_reports order by officer, created_at desc) er,
         lateral jsonb_array_elements(er.recommendations) rec
    where coalesce(rec->>'action','')<>''
    limit n) z;
$function$


CREATE OR REPLACE FUNCTION public.fn_onboarding_gate(p_agent text)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select coalesce(
    (select jsonb_build_object('agent',agent_key,'status',status,
       'outputs_need_review', status <> 'certified',
       'reason', case status
         when 'certified' then 'fully onboarded'
         when 'probation' then 'passed exams; first '||probation_reviews_required||' outputs need founder/lead review ('||probation_reviews_done||' done)'
         when 'recert_due' then 'certification expired; re-examination pending'
         else 'not yet examined on the four knowledge layers' end)
     from org_onboarding where agent_key=p_agent),
    jsonb_build_object('agent',p_agent,'status','unknown','outputs_need_review',true,
      'reason','no onboarding record - treat as uncertified'));
$function$


CREATE OR REPLACE FUNCTION public.fn_onboarding_ingest_runs()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v_updated int := 0;
begin
  for r in select agent, score_pct, run_at from canon_eval_runs where run_at > now() - interval '8 days' loop
    insert into org_onboarding(agent_key, department)
      values (r.agent, (select department from org_agents where agent_key=r.agent))
      on conflict (agent_key) do nothing;
    update org_onboarding set l1_score=r.score_pct, l1_at=r.run_at, updated_at=now()
      where agent_key=r.agent and (l1_at is null or l1_at < r.run_at);
    v_updated := v_updated + 1;
  end loop;
  update org_onboarding o set status='probation', updated_at=now()
    where o.status in ('onboarding','recert_due')
      and o.l1_score >= o.pass_threshold and o.l2_score >= o.pass_threshold;
  update org_onboarding o set status='certified', certified_at=now(),
      recert_due=(now()+interval '90 days')::date, updated_at=now()
    where o.status='probation' and o.probation_reviews_done >= o.probation_reviews_required;
  update org_onboarding o set status='recert_due', updated_at=now()
    where o.status='certified' and o.recert_due is not null and o.recert_due < current_date;
  return jsonb_build_object('runs_ingested', v_updated);
end $function$


CREATE OR REPLACE FUNCTION public.fn_operations_ai()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare k record; v_health numeric; n int;
begin
  select * into k from ops_kpis;
  v_health := round(greatest(0, 100
    - least(30, coalesce(k.no_quote_backlog,0)*3)
    - (case when coalesce(k.avg_first_quote_hours,0) > 72 then 20 when coalesce(k.avg_first_quote_hours,0) > 48 then 10 else 0 end)
    - (case when coalesce(k.response_rate_pct,100) < 40 then 15 when coalesce(k.response_rate_pct,100) < 60 then 7 else 0 end)
    - least(15, coalesce(k.overdue_tasks,0)*3)
    - coalesce(k.cron_failures_24h,0)*4
    - least(10, coalesce(k.agent_errors_24h,0)*2)
    - (case when coalesce(k.high_risk_pending,0) > 5 then 8 else 0 end)),1);

  insert into ops_kpi_snapshots(snapshot_date,kpis) values (current_date, to_jsonb(k)||jsonb_build_object('ops_health',v_health))
    on conflict (snapshot_date) do update set kpis=excluded.kpis, created_at=now();

  perform ops_rec('no_quote_backlog', coalesce(k.no_quote_backlog,0) > 0, 'medium', 'Inquiries stuck without quotes',
    k.no_quote_backlog||' inquir(y/ies) older than 7 days have no quotes — a supply/response bottleneck. Chase matched suppliers or onboard supply in those categories.');
  perform ops_rec('slow_first_quote', coalesce(k.avg_first_quote_hours,0) > 48, 'medium', 'First quotes are slow',
    'First quotes are averaging '||coalesce(k.avg_first_quote_hours,0)||' hours. Tighten supplier response SLAs / nudges to speed the funnel.');
  perform ops_rec('low_response_rate', coalesce(k.response_rate_pct,100) < 60, 'medium', 'Supplier response rate is low',
    'Supplier response rate is '||coalesce(k.response_rate_pct,0)||'%. Improve matching quality and supplier enablement.');
  perform ops_rec('approvals_backlog', coalesce(k.pending_approvals,0) > 15, 'low', 'Approval queue building up',
    k.pending_approvals||' items are awaiting your decision ('||coalesce(k.high_risk_pending,0)||' high-risk). Clear the queue so the agents can proceed.');
  perform ops_rec('overdue_tasks', coalesce(k.overdue_tasks,0) > 0, 'low', 'Overdue tasks',
    k.overdue_tasks||' task(s) are past due. Reschedule or action them.');
  perform ops_rec('automation_failures', coalesce(k.cron_failures_24h,0) > 0 or coalesce(k.agent_errors_24h,0) > 5, 'high', 'Automation failures detected',
    coalesce(k.cron_failures_24h,0)||' scheduled-job failure(s) and '||coalesce(k.agent_errors_24h,0)||' agent error(s) in 24h. Investigate the failing jobs.');

  select count(*) into n from agent_actions where agent='operations_ai' and status in ('pending','needs_review');
  return jsonb_build_object('ran_at',now(),'ops_health',v_health,'kpis',to_jsonb(k),'open_recommendations',n);
end $function$


CREATE OR REPLACE FUNCTION public.fn_opportunity_scan()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; n int := 0;
begin
  -- underserved categories that already hold a viable pool: ready demand, no action
  for r in select * from v_supply_gap where status='READY - not yet invited' order by sendable desc limit 10 loop
    insert into opportunity (kind,title,detail,evidence,value_score,effort,confidence,detected_by)
    select 'underserved_category','Untapped pool: '||r.name,
      r.name||' holds '||r.sendable||' sendable suppliers and zero invitations sent. The pool is already sufficient for the 10-approved target.',
      jsonb_build_object('slug',r.slug,'sendable',r.sendable,'approved',r.approved),
      least(100, r.sendable/5.0), 'low', 0.8, 'intel_director'
    where not exists (select 1 from opportunity o where o.title='Untapped pool: '||r.name and o.status='open');
    if found then n := n+1; end if;
  end loop;

  -- categories where knowledge exists but no supply: capability ahead of market
  for r in select * from v_supply_gap where status='NO POOL - must source from scratch' limit 5 loop
    insert into opportunity (kind,title,detail,evidence,value_score,effort,confidence,detected_by)
    select 'unmet_demand','Whitespace: '||r.name,
      'A fully briefed category expert exists for '||r.name||' with zero suppliers anywhere in the pool. Either a genuine market gap worth owning, or a category to retire.',
      jsonb_build_object('slug',r.slug,'sendable',0), 40,'high',0.5,'market_analyst'
    where not exists (select 1 from opportunity o where o.title='Whitespace: '||r.name and o.status='open');
    if found then n := n+1; end if;
  end loop;

  -- cost opportunity
  if (select count(*) filter (where could_be_cheaper) from ai_cost_log where occurred_at>now()-interval '30 days') > 10 then
    insert into opportunity (kind,title,detail,evidence,value_score,effort,confidence,detected_by)
    select 'cost_saving','Over-specified AI calls',
      (select count(*) filter (where could_be_cheaper)||' of '||count(*)||' calls in the last 30 days could have been served by a cheaper model.' from ai_cost_log where occurred_at>now()-interval '30 days'),
      '{}'::jsonb, 60,'low',0.9,'optimisation_eng'
    where not exists (select 1 from opportunity where title='Over-specified AI calls' and status='open');
    if found then n := n+1; end if;
  end if;

  insert into agent_runs (agent,started_at,finished_at,status,counts,note)
  values ('opportunity_scan',now(),now(),'ok',jsonb_build_object('found',n),
    'Opportunity scan: '||n||' new opportunity(ies) detected without being asked.');
  return jsonb_build_object('found',n);
end $function$


CREATE OR REPLACE FUNCTION public.fn_ops_authority_check(p_dept_key text, p_action_class text, p_amount_aed numeric DEFAULT NULL::numeric, p_risk text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
declare v_prod text; v_thresh numeric; v_map record; v_gate record; v_tier text; v_reason text;
begin
  select max_tier, threshold_aed into v_prod, v_thresh
    from public.org_authority where dept_key = p_dept_key and action_class = p_action_class;

  select * into v_map from public.action_class_gate where action_class = p_action_class;

  select * into v_gate from ops_kb_stage.hard_gates
   where raw->>'action_class' = coalesce(v_map.gate_action_class, p_action_class) limit 1;

  v_tier := coalesce(v_prod, 'gated');
  v_reason := case when v_prod is null
                   then 'no org_authority row for this department and action class - defaulting to gated'
                   else 'org_authority.max_tier' end;

  -- DECLARED GATES WIN. An action class nobody has reviewed cannot be autonomous. This is the rule
  -- that closes 7.1: previously an autonomous org_authority row with no matching gate sailed through,
  -- which is exactly how refund_within_window, content_publish, code_selfheal and role_define ran
  -- outside the gates that name them.
  if v_map.action_class is null and v_tier <> 'gated' then
    v_tier := 'gated';
    v_reason := 'action class "' || p_action_class || '" has no row in action_class_gate. Unreviewed is not unrestricted: '
             || 'map it to a hard gate, or to NULL with a stated rationale, before it can act on its own.';
  end if;

  if v_gate.record_id is not null and coalesce(v_gate.raw->>'default_tier','gated') = 'gated' and v_tier <> 'gated' then
    if v_thresh is not null and p_amount_aed is not null and p_amount_aed <= v_thresh then
      v_reason := format('hard gate "%s" applies but %s AED is within the delegated threshold of %s AED',
                         v_gate.title, p_amount_aed, v_thresh);
    else
      v_tier := 'gated';
      v_reason := 'hard gate "' || v_gate.title || '" overrides org_authority (a hard gate may only tighten, never widen)'
               || case when v_thresh is not null and p_amount_aed is null
                       then '; a delegated threshold of ' || v_thresh || ' AED exists but no amount was stated'
                       else '' end;
    end if;
  end if;

  if v_thresh is not null and p_amount_aed is not null and p_amount_aed > v_thresh then
    v_tier := 'gated';
    v_reason := format('amount %s AED exceeds the department threshold of %s AED', p_amount_aed, v_thresh);
  end if;

  if p_risk = 'critical' and v_tier = 'autonomous' then
    v_tier := 'gated';
    v_reason := 'risk_level=critical is never executed autonomously';
  end if;

  return jsonb_build_object(
    'department', p_dept_key, 'action_class', p_action_class,
    'effective_tier', v_tier,
    'may_act_autonomously', (v_tier = 'autonomous'),
    'requires_approval', (v_tier = 'gated'),
    'reviewed', (v_map.action_class is not null),
    'hard_gate', case when v_gate.record_id is null then null else jsonb_build_object(
        'title', v_gate.title, 'approval_role', v_gate.raw->>'approval_role',
        'threshold', v_gate.raw->>'threshold', 'rollback', v_gate.raw->>'rollback') end,
    'production_tier', v_prod, 'threshold_aed', v_thresh, 'reason', v_reason,
    'source', 'org_authority + action_class_gate + ops_kb_stage.hard_gates (deterministic, no model call)');
end $function$


CREATE OR REPLACE FUNCTION public.fn_ops_dashboard()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  active_rfqs int; rfqs_today int; done_today int; ttfq numeric; qpr numeric;
  accept_rate numeric; conv numeric;
  rev_today numeric; rev_month numeric; pending_fees numeric; outstanding_inv int; cash_recv numeric;
  ai_conf numeric; waiting int; onboard_q int; disputes int; escalations int;
  uptime numeric; queue_size int; failed int; last_backup timestamptz; api_lat numeric;
  health jsonb;
begin
  -- MARKETPLACE
  select count(*) into active_rfqs from inquiries where status not in ('completed','accepted','closed','cancelled');
  select count(*) into rfqs_today from inquiries where created_at::date=current_date;
  select count(*) into done_today from inquiries where (completed_at::date=current_date) or (status in ('completed','accepted') and stage_changed_at::date=current_date);
  select round(avg(extract(epoch from (fq - ic))/3600.0),1) into ttfq from (
    select i.created_at ic, min(q.created_at) fq from inquiries i join quotes q on q.inquiry_id=i.id
    where i.created_at>=now()-interval '30 days' group by i.id) z where fq is not null;
  select round(avg(qc),1) into qpr from (select count(*) qc from quotes q join inquiries i on i.id=q.inquiry_id where i.created_at>=now()-interval '30 days' group by q.inquiry_id) z;
  select round(avg(nullif(rv_response_rate,0)) ,1) into accept_rate from leads where coalesce(rv_reveals,0)>0;
  select round(100.0*count(distinct t.inquiry_id)/nullif(count(distinct i.id),0),1) into conv
    from inquiries i left join transactions t on t.inquiry_id=i.id where i.created_at>=now()-interval '30 days';

  -- REVENUE
  select coalesce(sum(reveal_fee),0) into rev_today from transactions where revealed_at::date=current_date and coalesce(refund_status,'')<>'approved';
  select coalesce(sum(reveal_fee),0) into rev_month from transactions where date_trunc('month',revealed_at)=date_trunc('month',now()) and coalesce(refund_status,'')<>'approved';
  begin select coalesce(sum(amount_due),0) into pending_fees from supplier_dues where coalesce(status,'')<>'paid'; exception when others then pending_fees:=0; end;
  begin select count(*) into outstanding_inv from reveal_invoices ri left join transactions t on t.id=ri.transaction_id where coalesce(t.fee_status,'')<>'paid'; exception when others then outstanding_inv:=0; end;
  select coalesce(sum(reveal_fee),0) into cash_recv from transactions where coalesce(fee_status,'')='paid';

  -- OPERATIONS
  begin select public.fn_health_index() into health; exception when others then health:=null; end;
  select round(100.0*count(*) filter (where nullif(quality->>'score','')::numeric>=60)/nullif(count(*) filter (where quality is not null),0),1) into ai_conf
    from quotes where created_at>=now()-interval '7 days';
  select count(*) into waiting from inquiries where status in ('clarify','clarifying','awaiting_customer','needs_info');
  select count(*) into onboard_q from leads where approval_status='pending';
  select count(*) into disputes from transactions where refund_status='requested';
  select (select count(*) from agent_actions where status='pending')
        + (select count(*) from founder_alerts where level='critical' and created_at>=now()-interval '24 hours') into escalations;

  -- INFRASTRUCTURE
  select round(100.0*count(*) filter (where ok)/nullif(count(*),0),1) into uptime from health_checks where created_at>=now()-interval '24 hours';
  select count(*) into queue_size from notifications where coalesce(status,'')in('queued','pending','');
  begin select count(*) into failed from agent_runs where status='error' and coalesce(finished_at,started_at)>=now()-interval '24 hours'; exception when others then failed:=0; end;
  select max(updated_at) into last_backup from storage.objects where bucket_id='backups' and name like '%/_manifest.json';
  select round(avg(latency_ms),0) into api_lat from health_checks where created_at>=now()-interval '1 hour' and latency_ms is not null;

  return jsonb_build_object(
    'as_of', now(),
    'marketplace', jsonb_build_object('active_rfqs',active_rfqs,'rfqs_today',rfqs_today,'completed_today',done_today,
        'avg_hours_to_first_quote',ttfq,'avg_quotes_per_rfq',qpr,'supplier_acceptance_pct',accept_rate,'conversion_pct',conv),
    'revenue', jsonb_build_object('today_aed',rev_today,'month_aed',rev_month,'pending_fees_aed',pending_fees,
        'outstanding_invoices',outstanding_inv,'cash_received_aed',cash_recv),
    'operations', jsonb_build_object('ai_confidence_pct',ai_conf,'rfqs_waiting_clarification',waiting,
        'onboarding_queue',onboard_q,'disputes',disputes,'escalations',escalations),
    'infrastructure', jsonb_build_object('uptime_pct',uptime,'queue_size',queue_size,'failed_jobs_24h',failed,
        'backup_age_hours', case when last_backup is null then null else round(extract(epoch from (now()-last_backup))/3600.0,1) end,
        'api_latency_ms',api_lat),
    'health_index', coalesce(health->>'index',null));
end $function$


CREATE OR REPLACE FUNCTION public.fn_ops_department_context(p_dept_key text, p_topic text DEFAULT NULL::text, p_limit integer DEFAULT 6)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
with q as (
  select to_tsquery('simple', nullif(array_to_string(
      array(select w || ':*' from unnest(regexp_split_to_array(lower(coalesce(p_topic,'')), '[^a-z0-9]+')) w
            where length(w) >= 3), ' | '), '')) tsq
)
select jsonb_build_object(
  'department', p_dept_key,
  'company_core', (
    select coalesce(jsonb_agg(jsonb_build_object('title', c.title, 'content', c.body)), '[]'::jsonb)
    from (select r.title, left(r.content,1200) body from ops_kb_stage.records r
          where r.scope_type = 'company' and r.module in ('identity','principles','governance','privacy','language')
            and r.validation_status in ('reviewed','source_verified','approved')
          order by r.record_type limit 8) c),
  'department_knowledge', (
    select coalesce(jsonb_agg(s.x), '[]'::jsonb) from (
      select jsonb_build_object('record_id', r.record_id, 'title', r.title,
                                'content', left(r.content, 1500), 'module', r.module,
                                'implementation_status', r.implementation_status,
                                'authority_tier', r.authority_tier, 'risk_level', r.risk_level,
                                'source_ids', r.source_ids) x
      from ops_kb_stage.records r, q
      where r.scope_type = 'department' and r.scope_key = p_dept_key
        and r.validation_status in ('reviewed','source_verified','approved')
        and (q.tsq is null or to_tsvector('simple', r.title || ' ' || left(r.content,4000)) @@ q.tsq)
      order by ts_rank(to_tsvector('simple', r.title || ' ' || left(r.content,4000)), q.tsq) desc,
               r.implementation_status, r.record_id
      limit greatest(p_limit,1)) s),
  'live_data', (
    select coalesce(jsonb_agg(jsonb_build_object('object', b.object_name, 'kind', b.db_object_kind,
                                                 'purpose', b.read_purpose, 'write_policy', b.write_policy)), '[]'::jsonb)
    from ops_kb_stage.live_bindings b
    where b.department_key = p_dept_key and b.mapping_status = 'mapped'),
  'authoritative_sources', (
    select coalesce(jsonb_agg(jsonb_build_object('source_id', s2.source_id, 'title', s2.title,
                                                 'publisher', s2.publisher, 'url', s2.url_or_path)), '[]'::jsonb)
    from ops_kb_stage.sources s2
    where exists (select 1 from ops_kb_stage.records r
                  where r.scope_key = p_dept_key and s2.source_id = any(r.source_ids))),
  'hard_gates', (
    select coalesce(jsonb_agg(jsonb_build_object('action_class', g.raw->>'action_class',
                                                 'approval_role', g.raw->>'approval_role')), '[]'::jsonb)
    from ops_kb_stage.hard_gates g),
  'institutional_memory', (
    select coalesce(jsonb_agg(jsonb_build_object('headline', m.headline, 'outcome', m.outcome)), '[]'::jsonb)
    from (select headline, outcome from public.institutional_memory order by created_at desc limit 3) m),
  'note', 'staging corpus: nothing here is enabled or approved; implementation_status must be checked before acting'
);
$function$


CREATE OR REPLACE FUNCTION public.fn_ops_metrics()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare res jsonb;
begin
  select jsonb_build_object(
    'open_rfqs_no_quotes_7d', (select count(*) from inquiries i where i.created_at < now()-interval '7 days'
        and coalesce(i.status,'') not in ('completed','cancelled','closed')
        and not exists (select 1 from quotes q where q.inquiry_id=i.id)),
    'matched_not_quoted', (select count(*) from inquiry_matches m
        where not exists (select 1 from quotes q where q.inquiry_id=m.inquiry_id and q.supplier_id=m.supplier_id)),
    'avg_first_quote_hours', (select (fn_marketplace_analytics()->>'avg_first_quote_hours')::numeric),
    'response_rate_pct', (select (fn_marketplace_analytics()->>'response_rate_pct')::numeric),
    'pipeline_by_stage', (select coalesce(jsonb_agg(jsonb_build_object('stage',label,'deals',deals,'value',value) order by sort_order),'[]'::jsonb) from crm_pipeline_report),
    'overdue_activities', (select overdue_activities from crm_deal_kpis)
  ) into res;
  return res;
end $function$


CREATE OR REPLACE FUNCTION public.fn_ops_run_scenarios()
 RETURNS TABLE(scenario_id text, kind text, scope_key text, verdict text, failures text[])
 LANGUAGE sql
AS $function$
with checked as (
  select s.record_id, s.kind, s.scope_key,
    array_remove(array[
      case when not exists (select 1 from ops_kb_stage.departments d where d.department_key = s.scope_key)
            and s.kind = 'department' then 'department not in the corpus department index' end,
      case when s.kind = 'workflow'
            and not exists (select 1 from ops_kb_stage.workflows w where w.workflow_key = s.scope_key)
           then 'workflow_key does not resolve to an imported workflow' end,
      case when coalesce(btrim(s.expected_behaviour), '') = '' then 'no expected behaviour stated' end,
      case when jsonb_array_length(coalesce(s.pass_criteria, '[]'::jsonb)) = 0 then 'no pass criteria' end,
      case when s.kind = 'department'
            and not exists (select 1 from ops_kb_stage.records r
                            where r.scope_type='department' and r.scope_key = s.scope_key
                              and r.module = 'professional_knowledge')
           then 'department has no professional knowledge to reason from' end,
      case when s.kind = 'department'
            and not exists (select 1 from ops_kb_stage.live_bindings b
                            where b.department_key = s.scope_key and b.mapping_status='mapped')
           then 'department has no resolved live-data binding' end,
      case when s.kind = 'department'
            and not exists (select 1 from ops_kb_stage.decision_rules dr where dr.department_key = s.scope_key)
           then 'department has no decision rules' end
    ], null) as failures
  from ops_kb_stage.scenarios s
)
select c.record_id, c.kind, c.scope_key,
       case when cardinality(c.failures) = 0 then 'RUNNABLE' else 'BLOCKED' end,
       c.failures
from checked c;
$function$


CREATE OR REPLACE FUNCTION public.fn_ops_watch()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_run bigint; v_ai_1h int; v_ai_24h int; v_top_email text; v_top_cnt int; v_err6h int; v_runerr6h int; v_spammer record; v_owner text; v_alerts int:=0;
  function_alerted boolean;
  v_wd_last timestamptz; v_wd_seen timestamptz;
begin
  insert into agent_runs(agent,started_at) values('ops_watch',clock_timestamp()) returning id into v_run;
  select split_part(coalesce(value,'management@quotesdone.com'),',',1) into v_owner from app_secrets where key='admin_emails';
  select count(*) into v_ai_1h from ai_usage where created_at>=now()-interval '1 hour';
  select count(*) into v_ai_24h from ai_usage where created_at>=now()-interval '24 hours';
  select email,count(*) into v_top_email,v_top_cnt from ai_usage where created_at>=now()-interval '24 hours' group by email order by count(*) desc limit 1;
  select count(*) into v_err6h from error_events where created_at>=now()-interval '6 hours' and severity in ('error','high','critical');
  select count(*) into v_runerr6h from agent_runs where status='error' and started_at>=now()-interval '6 hours';

  if (v_ai_1h > coalesce((select value::int from app_secrets where key='ai_cost_alert_hourly'),300))
     or (v_ai_24h > coalesce((select value::int from app_secrets where key='ai_cost_alert_daily'),2500)) then
    insert into error_events(source,kind,severity,detail) values('ops_watch','ai_cost_spike','high',jsonb_build_object('last_hour',v_ai_1h,'last_24h',v_ai_24h,'top_email',v_top_email,'top_count',v_top_cnt));
    select exists(select 1 from notifications where type='ops_alert' and subject like 'QuotesDone: AI usage spike%' and created_at>=now()-interval '6 hours') into function_alerted;
    if v_owner is not null and not function_alerted then
      insert into notifications(type,to_email,to_role,channel,subject,body) values('ops_alert',v_owner,'admin','email','QuotesDone: AI usage spike',
        'AI calls in last hour: '||v_ai_1h||', last 24h: '||v_ai_24h||'. Heaviest user: '||coalesce(v_top_email,'?')||' ('||coalesce(v_top_cnt,0)||'). Check for abuse or runaway cost. You can set ai_kill_switch=true to pause AI.');
      v_alerts:=v_alerts+1;
    end if;
  end if;

  if v_err6h > 20 or v_runerr6h > 10 then
    select exists(select 1 from notifications where type='ops_alert' and subject like 'QuotesDone: error spike%' and created_at>=now()-interval '6 hours') into function_alerted;
    if v_owner is not null and not function_alerted then
      insert into notifications(type,to_email,to_role,channel,subject,body) values('ops_alert',v_owner,'admin','email','QuotesDone: error spike',
        'Errors in last 6h: '||v_err6h||' app errors, '||v_runerr6h||' failed agent runs. Open the IT agent to investigate.');
      v_alerts:=v_alerts+1;
    end if;
  end if;

  for v_spammer in select customer_id, count(*) c from inquiries where created_at>=now()-interval '24 hours' group by customer_id having count(*)>40 loop
    insert into error_events(source,kind,severity,detail) values('ops_watch','inquiry_spam','medium',jsonb_build_object('customer_id',v_spammer.customer_id,'count',v_spammer.c));
    v_alerts:=v_alerts+1;
  end loop;

  select max(started_at) into v_wd_last from agent_runs
    where agent='agent_silence_watch' and status='ok' and started_at >= now()-interval '48 hours';
  select first_seen into v_wd_seen from cron_job_seen where jobname='agent_silence_watch_daily';

  if v_wd_last is null and v_wd_seen is not null and v_wd_seen < now()-interval '48 hours' then
    insert into error_events(source,kind,severity,detail)
      values('ops_watch','watchdog_silent','critical',
             jsonb_build_object('agent','agent_silence_watch','registered_since',v_wd_seen,
                                'note','no successful run in 48h - cron failures are going unobserved'));
    select exists(select 1 from notifications where type='ops_alert' and subject like 'QuotesDone: cron watchdog is down%' and created_at>=now()-interval '6 hours') into function_alerted;
    if v_owner is not null and not function_alerted then
      insert into notifications(type,to_email,to_role,channel,subject,body) values('ops_alert',v_owner,'admin','email','QuotesDone: cron watchdog is down',
        'agent_silence_watch has not completed successfully in 48 hours. While it is down, failing or stalled scheduled jobs will not raise alerts. Check that the agent_silence_watch_daily cron job is registered and running.');
      v_alerts:=v_alerts+1;
    end if;
  end if;

  update agent_runs set finished_at=clock_timestamp(),status='ok',counts=jsonb_build_object('ai_1h',v_ai_1h,'ai_24h',v_ai_24h,'err6h',v_err6h,'run_err6h',v_runerr6h,'alerts',v_alerts,'watchdog_ok',(v_wd_last is not null)) where id=v_run;
end; $function$


CREATE OR REPLACE FUNCTION public.fn_org_action_executor_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_scope text[];
begin
  if new.kind = 'edge' then
    select c.scope into v_scope
      from public.internal_credential c
     where c.context = 'fn.cos_execute'
       and c.active and c.retired_at is null
     limit 1;

    if v_scope is null then
      raise exception
        'org_action_executor: no live fn.cos_execute credential, so an edge executor target cannot be validated. Refusing the write rather than registering a callee nothing has authorised.'
        using errcode = 'check_violation';
    end if;

    if not (new.target = any (v_scope)) then
      raise exception
        'org_action_executor: edge target % is outside the fn.cos_execute credential scope. cos_execute would POST service-role authority to it. Widen the credential scope deliberately if this executor is intended; do not widen it to make an INSERT succeed.',
        new.target
        using errcode = 'check_violation';
    end if;

  elsif new.kind = 'rpc' then
    if not exists (select 1 from public.org_action_executor_rpc_allowed a where a.target = new.target) then
      raise exception
        'org_action_executor: rpc target % is not in org_action_executor_rpc_allowed. cos_execute runs rpc executors as service-role, so this is a grant of arbitrary database authority. Add it to the allow-list deliberately first.',
        new.target
        using errcode = 'check_violation';
    end if;

  else
    raise exception
      'org_action_executor: unknown kind %. cos_execute only understands edge and rpc, so a row with any other kind is either dead or a mistake. Refusing it rather than storing it.', new.kind
      using errcode = 'check_violation';
  end if;

  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_org_authority_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_reason text := nullif(trim(coalesce(current_setting('app.change_reason', true), '')), '');
  v_widen  boolean;
  v_obj    text := 'org_authority:' || coalesce(new.dept_key, old.dept_key) || '/'
                                    || coalesce(new.action_class, old.action_class);
begin
  if tg_op = 'DELETE' then
    v_widen := false;   -- removing a row removes a permission
  else
    v_widen := public.fn_authority_rank(new.max_tier) > public.fn_authority_rank(coalesce(old.max_tier, 'advisory'))
            or coalesce(new.threshold_aed, 0) > coalesce(old.threshold_aed, 0);
  end if;

  if v_widen and (v_reason is null or length(v_reason) < 12) then
    raise exception
      'org_authority %: raising a department''s tier or money threshold needs a stated reason. '
      'Run `set local app.change_reason = ''why, in a sentence'';` in the same transaction. '
      'Lowering never needs one.', v_obj
      using errcode = 'check_violation';
  end if;

  insert into public.autonomy_control_audit (object, op, direction, old_value, new_value, reason)
  values (v_obj, tg_op,
          case when v_widen then 'widen' else 'tighten' end,
          coalesce(old.max_tier,'') || '/' || coalesce(old.threshold_aed::text,''),
          coalesce(new.max_tier,'') || '/' || coalesce(new.threshold_aed::text,''),
          v_reason);
  return coalesce(new, old);
end $function$


CREATE OR REPLACE FUNCTION public.fn_org_exec_invite(p_cap integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_enabled boolean; v_cap int; v_sent int;
begin
  v_enabled := coalesce((select value from app_secrets where key='invite_enabled'),'false')='true';
  v_cap := coalesce((select nullif(value,'')::int from app_secrets where key='invite_daily_cap'), 10);
  select public.enqueue_supplier_invites(p_cap) into v_sent;
  return jsonb_build_object(
    'invited', coalesce(v_sent,0),
    'campaign_enabled', v_enabled,
    'daily_cap', v_cap,
    'note', case when not v_enabled then 'Invite campaign is not enabled yet — 0 sent. It starts on its scheduled date; the deliverability-gated ramp will then send within the daily cap.'
                 else 'Enqueued '||coalesce(v_sent,0)||' invite(s) this run, within the daily cap of '||v_cap||' and bounce-rate guard.' end
  );
end $function$


CREATE OR REPLACE FUNCTION public.fn_org_exec_knowledge_fill(p_limit integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_gaps int; v_req bigint; v_recon jsonb;
begin
  -- self-heal the taxonomy every run (fast, synchronous)
  v_recon := public.fn_kb_reconcile();
  -- how many service categories still have zero knowledge chunks
  select count(*) into v_gaps from public.category_specs s
    where not exists (select 1 from public.kb_chunks k where k.category = s.category);
  -- trigger the (slow) generator in the background
  select net.http_post(
    url:='https://htdblwldjkcgjvmqkbeh.supabase.co/functions/v1/kb_autofill_gaps',
    headers:='{"Content-Type":"application/json"}'::jsonb,
    body:=jsonb_build_object('__secret',(select value from public.app_secrets where key='cred_db_internal'),'limit',greatest(1,least(coalesce(p_limit,5),5))),
    timeout_milliseconds:=280000
  ) into v_req;
  return jsonb_build_object('empty_categories', v_gaps, 'autofill_triggered', true, 'reconcile', v_recon,
    'note', case when v_gaps=0 then 'Knowledge base complete: 0 empty categories. Taxonomy reconciled ('||coalesce(v_recon->>'cat_prefix_stripped','0')||' prefixes stripped, '||coalesce(v_recon->>'alias_remapped','0')||' aliased).'
                 else 'Triggered background gap-fill for '||v_gaps||' empty category(ies); taxonomy reconciled. Generation runs in the background and logs to agent_runs.' end);
end $function$


CREATE OR REPLACE FUNCTION public.fn_org_export()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
select jsonb_build_object(
 'exported_at', now(),
 'org_departments', (select jsonb_agg(to_jsonb(t) order by t.sort) from org_departments t),
 'org_agents', (select jsonb_agg(to_jsonb(t) order by t.agent_key) from org_agents t),
 'org_authority', (select jsonb_agg(to_jsonb(t) order by t.dept_key, t.action_class) from org_authority t),
 'org_onboarding', (select jsonb_agg(to_jsonb(t) order by t.agent_key) from org_onboarding t),
 'decision_policy', (select jsonb_agg(to_jsonb(t) order by t.key) from decision_policy t),
 'policy_rules', (select jsonb_agg(to_jsonb(t) order by t.id) from policy_rules t),
 'canon_eval_questions', (select jsonb_agg(to_jsonb(t) order by t.id) from canon_eval_questions t),
 'agent_knowledge', (select jsonb_agg(jsonb_build_object('agent_key',agent_key,'topic',topic,'layer',layer,'priority',priority,'content',content) order by agent_key, priority desc, topic) from agent_knowledge t),
 'company_vision', (select jsonb_agg(to_jsonb(t)) from company_vision t),
 'ai_constitution', (select jsonb_agg(to_jsonb(t)) from ai_constitution t where active),
 'migrations', (select jsonb_agg(jsonb_build_object('version',version,'name',name) order by version) from supabase_migrations.schema_migrations)
)
$function$


CREATE OR REPLACE FUNCTION public.fn_org_scorecard()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select coalesce(jsonb_agg(row_to_json(x) order by x.sort),'[]'::jsonb) from (
    select d.dept_key, d.name, d.north_star, d.lead_agent, d.sort,
      (select count(*) from public.org_tasks t where t.dept_key=d.dept_key and t.status in ('proposed','assigned','in_progress','blocked')) as open_tasks,
      (select count(*) from public.org_tasks t where t.dept_key=d.dept_key and (t.needs_founder or t.status='escalated') and t.status not in ('done','failed')) as escalations,
      (select count(*) from public.agent_actions a where a.status in ('pending','needs_review','open') and (
          (d.dept_key='finance' and a.kind ~* 'finance|refund|dues') or
          (d.dept_key='legal' and a.kind ~* 'legal|compliance') or
          (d.dept_key='supplier_success' and a.kind ~* 'supplier|approve|licence|kyc') or
          (d.dept_key='customer_success' and a.kind ~* 'customer|refund|escalation') or
          (d.dept_key='it' and a.kind ~* 'incident|security') or
          (d.dept_key='marketing' and a.kind ~* 'market|content') or
          (d.dept_key='knowledge' and a.kind ~* 'knowledge|coverage')
        )) as dept_queue
    from public.org_departments d where d.active
  ) x;
$function$


CREATE OR REPLACE FUNCTION public.fn_org_task_autonomy_brake()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v jsonb;
begin
  if new.status is distinct from 'in_progress' or old.status = 'in_progress' then
    return new;
  end if;
  if coalesce(new.tier, 'advisory') = 'advisory' then
    return new;   -- WI-001 permits shadow development; advice-only work is not broad autonomy
  end if;
  v := public.fn_autonomy_status();
  if (v ->> 'allowed')::boolean then
    return new;
  end if;
  raise exception
    'org_tasks: task % cannot start at tier %. Broad autonomy is blocked: %. This is WI-001 being '
    'enforced rather than merely declared — clear the blocker, or drop the task to advisory.',
    new.id, new.tier, (v ->> 'blockers')
    using errcode = 'check_violation';
end $function$


CREATE OR REPLACE FUNCTION public.fn_os_automation_list()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_agg(x order by x->>'category', x->>'human_name'), '[]'::jsonb) from (
    select jsonb_build_object(
      'jobid', j.jobid, 'jobname', j.jobname,
      'human_name', coalesce(r.human_name, initcap(replace(replace(j.jobname,'_',' '),'-',' '))),
      'category', coalesce(r.category,'Operations'), 'purpose', coalesce(r.purpose,''),
      'schedule', j.schedule, 'active', j.active,
      'last_status', lr.status, 'last_start', lr.start_time, 'last_end', lr.end_time,
      'last_message', left(coalesce(lr.return_message,''), 240)
    ) as x
    from cron.job j
    left join public.cron_registry r on r.jobname = j.jobname
    left join lateral (
      select status, start_time, end_time, return_message
      from cron.job_run_details d where d.jobid = j.jobid
      order by d.start_time desc nulls last limit 1
    ) lr on true
  ) q;
$function$


CREATE OR REPLACE FUNCTION public.fn_os_automation_reschedule(p_jobid bigint, p_schedule text, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE nm text; oldsched text;
BEGIN
  SELECT jobname, schedule INTO nm, oldsched FROM cron.job WHERE jobid = p_jobid;
  IF nm IS NULL THEN RETURN jsonb_build_object('ok',false,'error','job_not_found'); END IF;
  IF coalesce(array_length(regexp_split_to_array(btrim(p_schedule), '\s+'),1),0) <> 5 THEN
    RETURN jsonb_build_object('ok',false,'error','schedule_must_have_5_fields'); END IF;
  BEGIN PERFORM cron.alter_job(job_id := p_jobid, schedule := p_schedule);
  EXCEPTION WHEN others THEN RETURN jsonb_build_object('ok',false,'error',SQLERRM); END;
  INSERT INTO public.os_audit_log(actor,action,entity,entity_id,detail,ok)
  VALUES (coalesce(p_actor,'os'),'automation_reschedule','cron_job',p_jobid::text,jsonb_build_object('jobname',nm,'old',oldsched,'new',p_schedule),true);
  RETURN jsonb_build_object('ok',true,'schedule',p_schedule);
END $function$


CREATE OR REPLACE FUNCTION public.fn_os_automation_run(p_jobid bigint, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE cmd text; nm text; ok boolean := true; msg text := '';
BEGIN
  SELECT command, jobname INTO cmd, nm FROM cron.job WHERE jobid = p_jobid;
  IF cmd IS NULL THEN RETURN jsonb_build_object('ok',false,'error','job_not_found'); END IF;
  BEGIN EXECUTE cmd; EXCEPTION WHEN others THEN ok := false; msg := SQLERRM; END;
  INSERT INTO public.os_audit_log(actor,action,entity,entity_id,detail,ok)
  VALUES (coalesce(p_actor,'os'),'automation_run','cron_job',p_jobid::text,jsonb_build_object('jobname',nm,'error',msg),ok);
  RETURN jsonb_build_object('ok',ok,'error',nullif(msg,''));
END $function$


CREATE OR REPLACE FUNCTION public.fn_os_automation_set_active(p_jobid bigint, p_active boolean, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE nm text;
BEGIN
  SELECT jobname INTO nm FROM cron.job WHERE jobid = p_jobid;
  IF nm IS NULL THEN RETURN jsonb_build_object('ok',false,'error','job_not_found'); END IF;
  PERFORM cron.alter_job(job_id := p_jobid, active := p_active);
  INSERT INTO public.os_audit_log(actor,action,entity,entity_id,detail,ok)
  VALUES (coalesce(p_actor,'os'),'automation_active','cron_job',p_jobid::text,jsonb_build_object('jobname',nm,'active',p_active),true);
  RETURN jsonb_build_object('ok',true,'active',p_active);
END $function$


CREATE OR REPLACE FUNCTION public.fn_os_catalog_get(p_category text)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'category', cs.category,
    'label', coalesce(cs.label, cs.category),
    'fields', coalesce(cs.fields, '[]'::jsonb),
    'spec_group', g.grp,
    'specs', (select coalesce(jsonb_agg(jsonb_build_object(
        'id', q.id, 'aspect', q.aspect, 'label', q.label, 'match_regex', q.match_regex,
        'mandatory', q.mandatory, 'note', coalesce(q.note,'')) order by q.mandatory desc, q.aspect), '[]'::jsonb)
      from public.category_quote_specs q where q.spec_group = g.grp)
  )
  from public.category_specs cs, lateral (select public.fn_quote_spec_group(cs.category) as grp) g
  where cs.category = p_category;
$function$


CREATE OR REPLACE FUNCTION public.fn_os_catalog_list()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_agg(jsonb_build_object(
    'category', cs.category,
    'label', coalesce(cs.label, cs.category),
    'n_fields', coalesce(jsonb_array_length(cs.fields), 0),
    'spec_group', public.fn_quote_spec_group(cs.category),
    'n_specs', (select count(*) from public.category_quote_specs q where q.spec_group = public.fn_quote_spec_group(cs.category))
  ) order by cs.category), '[]'::jsonb)
  from public.category_specs cs;
$function$


CREATE OR REPLACE FUNCTION public.fn_os_catalog_save_fields(p_category text, p_fields jsonb, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE oldf jsonb;
BEGIN
  IF jsonb_typeof(p_fields) <> 'array' THEN RETURN jsonb_build_object('ok',false,'error','fields_must_be_a_list'); END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_fields) e
             WHERE jsonb_typeof(e) <> 'object' OR coalesce(e->>'question','')='' OR coalesce(e->>'key','')='') THEN
    RETURN jsonb_build_object('ok',false,'error','each_question_needs_a_key_and_question_text'); END IF;
  SELECT fields INTO oldf FROM public.category_specs WHERE category = p_category;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'error','category_not_found'); END IF;
  UPDATE public.category_specs SET fields = p_fields, updated_at = now() WHERE category = p_category;
  INSERT INTO public.os_audit_log(actor,action,entity,entity_id,detail,ok)
  VALUES (coalesce(p_actor,'os'),'catalog_save_fields','category',p_category,
          jsonb_build_object('n_fields', jsonb_array_length(p_fields)), true);
  RETURN jsonb_build_object('ok',true,'n_fields', jsonb_array_length(p_fields));
END $function$


CREATE OR REPLACE FUNCTION public.fn_os_catalog_spec_delete(p_id bigint, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE g text; a text;
BEGIN
  SELECT spec_group, aspect INTO g, a FROM public.category_quote_specs WHERE id=p_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'error','spec_not_found'); END IF;
  DELETE FROM public.category_quote_specs WHERE id=p_id;
  INSERT INTO public.os_audit_log(actor,action,entity,entity_id,detail,ok)
  VALUES (coalesce(p_actor,'os'),'catalog_spec_delete','quote_spec',p_id::text,jsonb_build_object('spec_group',g,'aspect',a), true);
  RETURN jsonb_build_object('ok',true);
END $function$


CREATE OR REPLACE FUNCTION public.fn_os_catalog_spec_upsert(p_id bigint, p_spec_group text, p_aspect text, p_label text, p_regex text, p_mandatory boolean, p_note text, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE newid bigint;
BEGIN
  IF coalesce(p_spec_group,'')='' OR coalesce(p_aspect,'')='' OR coalesce(p_label,'')='' OR coalesce(p_regex,'')='' THEN
    RETURN jsonb_build_object('ok',false,'error','group_aspect_label_and_pattern_required'); END IF;
  BEGIN PERFORM regexp_match('validation probe', p_regex);
  EXCEPTION WHEN others THEN RETURN jsonb_build_object('ok',false,'error','invalid_pattern: '||SQLERRM); END;
  IF p_id IS NOT NULL AND p_id > 0 THEN
    UPDATE public.category_quote_specs SET spec_group=p_spec_group, aspect=p_aspect, label=p_label, match_regex=p_regex, mandatory=coalesce(p_mandatory,false), note=nullif(p_note,'')
      WHERE id=p_id RETURNING id INTO newid;
    IF newid IS NULL THEN RETURN jsonb_build_object('ok',false,'error','spec_not_found'); END IF;
  ELSE
    INSERT INTO public.category_quote_specs(spec_group,aspect,label,match_regex,mandatory,note)
      VALUES (p_spec_group,p_aspect,p_label,p_regex,coalesce(p_mandatory,false),nullif(p_note,'')) RETURNING id INTO newid;
  END IF;
  INSERT INTO public.os_audit_log(actor,action,entity,entity_id,detail,ok)
  VALUES (coalesce(p_actor,'os'),'catalog_spec_upsert','quote_spec',newid::text,
          jsonb_build_object('spec_group',p_spec_group,'aspect',p_aspect,'mandatory',coalesce(p_mandatory,false)), true);
  RETURN jsonb_build_object('ok',true,'id',newid);
END $function$


CREATE OR REPLACE FUNCTION public.fn_os_catalog_test_gate(p_category text, p_sample text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE grp text; res jsonb;
BEGIN
  grp := public.fn_quote_spec_group(p_category);
  WITH asp AS (
    SELECT q.aspect, q.label, q.mandatory,
           (CASE WHEN coalesce(p_sample,'') = '' THEN false ELSE p_sample ~* q.match_regex END) AS matched
    FROM public.category_quote_specs q WHERE q.spec_group = grp
  )
  SELECT jsonb_build_object(
    'category', p_category, 'spec_group', grp,
    'aspects', coalesce((select jsonb_agg(jsonb_build_object('aspect',aspect,'label',label,'mandatory',mandatory,'matched',matched) order by mandatory desc, aspect) from asp),'[]'::jsonb),
    'total', (select count(*) from asp),
    'matched_count', (select count(*) from asp where matched),
    'mandatory_missing', coalesce((select jsonb_agg(label order by label) from asp where mandatory and not matched),'[]'::jsonb),
    'passes', (select coalesce(bool_and(matched),true) from asp where mandatory)
  ) INTO res;
  RETURN res;
END $function$


CREATE OR REPLACE FUNCTION public.fn_os_command()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_health jsonb; v_ops jsonb; v_counts jsonb; v_attention jsonb; v_pipeline jsonb;
begin
  v_health := to_jsonb(fn_health_index());
  v_ops    := to_jsonb(fn_ops_dashboard());

  select jsonb_build_object(
    'suppliers_total', (select count(*) from leads),
    'rfqs_total',      (select count(*) from inquiries),
    'rfqs_active',     (select count(*) from inquiries where status = 'quoted'),
    'rfqs_revealed',   (select count(*) from inquiries where status = 'revealed'),
    'rfqs_cancelled',  (select count(*) from inquiries where status = 'cancelled'),
    'quotes_total',    (select count(*) from quotes),
    'decisions_7d',    (select count(*) from decision_log where created_at > now() - interval '7 days'),
    'decisions_24h',   (select count(*) from decision_log where created_at > now() - interval '24 hours')
  ) into v_counts;

  select jsonb_build_object(
    'sent',      (select count(*) from inquiries where status = 'sent' and parent_inquiry_id is null),
    'matched',   (select count(distinct im.inquiry_id) from inquiry_matches im join inquiries i on i.id = im.inquiry_id where i.status = 'sent'),
    'quoted',    (select count(*) from inquiries where status = 'quoted'),
    'revealed',  (select count(*) from inquiries where status = 'revealed'),
    'completed', (select count(*) from inquiries where status in ('completed','won'))
  ) into v_pipeline;

  select coalesce(jsonb_agg(x order by created_at desc), '[]'::jsonb) into v_attention
  from (
    select id, actor, kind, decision, confidence, route_to, created_at,
           jsonb_build_object('id', id, 'actor', actor, 'kind', kind, 'decision', decision,
             'confidence', confidence, 'route_to', route_to, 'created_at', created_at) as x
    from decision_log where route_to is not null and route_to <> 'auto'
    order by created_at desc limit 8
  ) t;

  return jsonb_build_object(
    'ok', true, 'generated_at', now(),
    'health', v_health, 'ops', v_ops, 'counts', v_counts,
    'pipeline', v_pipeline, 'attention', v_attention
  );
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_os_dashboard_viz()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  out jsonb := '{}'::jsonb;
  v_total bigint; v_contacted bigint; v_invited bigint; v_claimed bigint;
  v_registered bigint; v_verified bigint; v_approved bigint;
  v_runs24 bigint; v_agents24 bigint; v_failed24 bigint;
  j_sector jsonb; j_emirate jsonb; j_invites jsonb; j_agents jsonb; j_funnel jsonb; j_pipeline jsonb;
begin
  select count(*) into v_total from leads;
  select count(*) into v_contacted from leads where contacted is true;
  select count(*) into v_invited from leads where invited_at is not null;
  select count(*) into v_claimed from leads where claimed is true;
  select count(*) into v_registered from leads where registration_submitted_at is not null;
  select count(*) into v_verified from leads where verified is true;
  select count(*) into v_approved from leads where approved_at is not null;

  -- agent activity from agent_runs (the same source the header/Smart Engine use)
  begin
    select count(*) filter (where started_at > now() - interval '24 hours'),
           count(distinct agent) filter (where started_at > now() - interval '24 hours'),
           count(*) filter (where started_at > now() - interval '24 hours' and status in ('error','failed'))
      into v_runs24, v_agents24, v_failed24 from agent_runs;
    select coalesce(jsonb_agg(x), '[]'::jsonb) into j_agents from (
      select agent as label, count(*)::int as n
      from agent_runs where started_at > now() - interval '24 hours'
      group by agent order by count(*) desc limit 8
    ) x;
  exception when others then v_runs24 := 0; v_agents24 := 0; v_failed24 := 0; j_agents := '[]'::jsonb; end;

  select coalesce(jsonb_agg(x), '[]'::jsonb) into j_sector from (
    select coalesce(nullif(trim(sector),''),'unspecified') as label, count(*)::int as n
    from leads group by 1 order by count(*) desc limit 12
  ) x;

  select coalesce(jsonb_agg(x), '[]'::jsonb) into j_emirate from (
    select coalesce(nullif(trim(emirate),''),'unknown') as label, count(*)::int as n
    from leads group by 1 order by count(*) desc limit 9
  ) x;

  select coalesce(jsonb_agg(jsonb_build_object('d', to_char(d.day,'Mon DD'), 'n', coalesce(c.n,0)) order by d.day), '[]'::jsonb)
    into j_invites
  from (select generate_series((current_date - interval '13 days')::date, current_date, interval '1 day')::date as day) d
  left join (select invited_at::date as day, count(*)::int as n from leads where invited_at > now() - interval '14 days' group by 1) c
    on c.day = d.day;

  j_funnel := jsonb_build_array(
    jsonb_build_object('stage','Sourced', 'n', v_total),
    jsonb_build_object('stage','Contacted', 'n', v_contacted),
    jsonb_build_object('stage','Invited', 'n', v_invited),
    jsonb_build_object('stage','Claimed', 'n', v_claimed),
    jsonb_build_object('stage','Registered', 'n', v_registered),
    jsonb_build_object('stage','Verified', 'n', v_verified),
    jsonb_build_object('stage','Approved', 'n', v_approved)
  );

  begin
    j_pipeline := jsonb_build_array(
      jsonb_build_object('stage','New', 'n', (select count(*) from inquiries)),
      jsonb_build_object('stage','Matched', 'n', (select count(distinct inquiry_id) from quotes)),
      jsonb_build_object('stage','Quoted', 'n', (select count(*) from quotes)),
      jsonb_build_object('stage','Revealed', 'n', (select count(*) from quotes where coalesce(revealed,false) is true)),
      jsonb_build_object('stage','Won', 'n', (select count(*) from inquiries where status = 'won'))
    );
  exception when others then j_pipeline := jsonb_build_array(); end;

  out := jsonb_build_object(
    'headline', jsonb_build_object(
      'suppliers_total', v_total, 'invited_total', v_invited, 'verified_total', v_verified,
      'approved_total', v_approved, 'registered_total', v_registered,
      'agents_active_24h', v_agents24, 'runs_24h', v_runs24, 'runs_failed_24h', v_failed24),
    'funnel', j_funnel,
    'pipeline', j_pipeline,
    'by_sector', j_sector,
    'by_emirate', j_emirate,
    'invites_14d', j_invites,
    'agents_24h', j_agents,
    'generated_at', to_char(now(),'YYYY-MM-DD"T"HH24:MI:SSOF')
  );
  return out;
end $function$


CREATE OR REPLACE FUNCTION public.fn_os_detail(p_entity text, p_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_tbl text; v_idcol text := 'id'; v_row jsonb;
begin
  case p_entity
    when 'inquiries' then v_tbl:='inquiries';
    when 'quotes' then v_tbl:='quotes';
    when 'transactions' then v_tbl:='transactions';
    when 'customers' then v_tbl:='customers';
    when 'suppliers' then v_tbl:='leads';
    when 'agent_actions' then v_tbl:='agent_actions';
    when 'doc_reviews' then v_tbl:='doc_reviews';
    when 'kb_revisions' then v_tbl:='kb_revisions';
    when 'inbox' then v_tbl:='inbound_messages';
    when 'documents' then v_tbl:='documents';
    when 'dropbox' then v_tbl:='dropbox_files';
    when 'invoices' then v_tbl:='reveal_invoices'; v_idcol:='transaction_id';
    when 'notifications' then v_tbl:='notifications';
    when 'tasks' then v_tbl:='crm_tasks';
    when 'po' then v_tbl:='po_orders';
    when 'expenses' then v_tbl:='expenses';
    when 'agent_runs' then v_tbl:='agent_runs';
    when 'fraud' then v_tbl:='fraud_flags'; v_idcol:='subject_id';
    else return jsonb_build_object('error','unknown_entity');
  end case;
  execute format('select to_jsonb(t) from %I t where %I::text = %L limit 1', v_tbl, v_idcol, p_id) into v_row;
  if v_row is null then return jsonb_build_object('error','not_found'); end if;
  return jsonb_build_object('entity',p_entity,'record',v_row);
end $function$


CREATE OR REPLACE FUNCTION public.fn_os_health()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE res jsonb;
BEGIN
  SELECT jsonb_build_object(
    'generated_at', now(),
    'failing_crons', coalesce((
      SELECT jsonb_agg(jsonb_build_object('job', j.jobname, 'status', lr.status, 'when', lr.end_time, 'message', left(coalesce(lr.return_message,''),160)) ORDER BY lr.end_time DESC)
      FROM cron.job j
      JOIN LATERAL (SELECT status, end_time, return_message FROM cron.job_run_details d WHERE d.jobid=j.jobid ORDER BY d.start_time DESC LIMIT 1) lr ON true
      WHERE lr.status = 'failed' AND lr.end_time > now() - interval '24 hours'
    ), '[]'::jsonb),
    'agent_errors_24h', (SELECT count(*) FROM public.agent_runs WHERE status='error' AND started_at > now() - interval '24 hours'),
    'top_error_agents', coalesce((SELECT jsonb_agg(x) FROM (SELECT jsonb_build_object('agent',agent,'errors',count(*)) x FROM public.agent_runs WHERE status='error' AND started_at > now()-interval '24 hours' GROUP BY agent ORDER BY count(*) DESC LIMIT 6) q),'[]'::jsonb),
    'health_check_fails_24h', (SELECT count(*) FROM public.health_checks WHERE ok=false AND created_at > now()-interval '24 hours'),
    'ai_health_fails', coalesce((SELECT value FROM public.app_secrets WHERE key='ai_health_fails'),'0'),
    'payments_7d_count', (SELECT count(*) FROM public.transactions WHERE revealed_at > now()-interval '7 days'),
    'payments_7d_revenue_aed', coalesce((SELECT round(sum(reveal_fee)::numeric,2) FROM public.transactions WHERE revealed_at > now()-interval '7 days'),0)
  ) INTO res;
  res := res || jsonb_build_object('overall',
    CASE WHEN jsonb_array_length(res->'failing_crons') > 0 OR (res->>'agent_errors_24h')::int > 25 THEN 'attention' ELSE 'healthy' END);
  RETURN res;
END $function$


CREATE OR REPLACE FUNCTION public.fn_os_improve()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; n int := 0; q text; qs text[];
  v_failed int; v_slow int; v_cost numeric; v_manual int; v_dead int;
begin
  for r in select o.os_key, o.name, o.owner_agent,
                  coalesce((select department from org_agents a where a.agent_key=o.owner_agent),'exec') as dept
           from operating_system o where o.active
  loop
    qs := array[]::text[];

    select count(*) into v_failed from agent_runs ar
      join os_department od on od.os_key = r.os_key
      join org_agents a on a.department = od.dept_key and a.agent_key = ar.agent
     where ar.status='error' and ar.started_at > now()-interval '7 days';

    select count(*) into v_slow from org_tasks t join os_department od on od.dept_key=t.dept_key
     where od.os_key=r.os_key and t.status<>'done' and t.created_at < now()-interval '14 days';

    select coalesce(sum(c.cost_aed),0) into v_cost from ai_cost_log c
      join os_department od on od.dept_key = c.dept_key
     where od.os_key = r.os_key and c.occurred_at > now()-interval '7 days';

    select count(*) into v_manual from org_tasks t join os_department od on od.dept_key=t.dept_key
     where od.os_key=r.os_key and t.needs_founder;

    select count(*) into v_dead from workflow w where w.os_key=r.os_key and not w.active;

    if v_failed > 0 then qs := array_append(qs,'What failed? '||v_failed||' agent run(s) errored this week in '||r.name||'. Root cause each one.'); end if;
    if v_slow   > 0 then qs := array_append(qs,'What slowed us? '||v_slow||' task(s) have been open over 14 days in '||r.name||'. Why has none closed?'); end if;
    if v_cost   > 0 then qs := array_append(qs,'What cost too much? '||r.name||' spent '||round(v_cost,2)||' AED on AI this week. Which calls could a cheaper model have served?'); end if;
    if v_manual > 0 then qs := array_append(qs,'What can be automated? '||v_manual||' task(s) in '||r.name||' still need the founder. Which of those is a rule rather than a judgement?'); end if;
    if v_dead   > 0 then qs := array_append(qs,'What should be deleted? '||v_dead||' inactive workflow(s) remain in '||r.name||'. Retire or revive them.'); end if;

    foreach q in array qs loop
      insert into org_tasks (dept_key,title,detail,status,tier,needs_founder,action_class)
      select r.dept, left(r.name||' improvement: '||q, 120),
             q||E'\n\nOwner: '||coalesce(r.owner_agent,'unassigned')||'. Answer with evidence. If the answer implies a change, open it through fn_outcome_open so it is graded against a baseline.',
             'proposed','advisory',false,'recommend'
      where not exists (select 1 from org_tasks t where t.title = left(r.name||' improvement: '||q,120) and t.status<>'done');
      if found then n := n+1; end if;
    end loop;
  end loop;

  insert into agent_runs (agent,started_at,finished_at,status,counts,note)
  values ('os_improve',now(),now(),'ok',jsonb_build_object('questions',n),
    'Continuous improvement: '||n||' question(s) raised across the ten operating systems.');
  return jsonb_build_object('questions',n);
end $function$


CREATE OR REPLACE FUNCTION public.fn_os_incident_list(p_status text)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',id,'title',title,'kind',kind,'severity',severity,'status',status,
    'description',detail->>'description','opened_by',opened_by,'opened_at',opened_at,
    'resolved_at',resolved_at,'resolution',resolution) order by (status='open') desc, opened_at desc), '[]'::jsonb)
  from public.os_incidents
  where p_status is null or p_status='' or status = p_status;
$function$


CREATE OR REPLACE FUNCTION public.fn_os_incident_open(p_title text, p_kind text, p_severity text, p_detail jsonb, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE nid bigint;
BEGIN
  IF coalesce(p_title,'')='' THEN RETURN jsonb_build_object('ok',false,'error','title_required'); END IF;
  INSERT INTO public.os_incidents(title, kind, severity, detail, opened_by)
  VALUES (p_title, coalesce(nullif(p_kind,''),'other'), coalesce(nullif(p_severity,''),'medium'), coalesce(p_detail,'{}'::jsonb), coalesce(p_actor,'os'))
  RETURNING id INTO nid;
  INSERT INTO public.os_audit_log(actor,action,entity,entity_id,detail,ok)
  VALUES (coalesce(p_actor,'os'),'incident_open','incident',nid::text,jsonb_build_object('title',p_title,'severity',p_severity),true);
  BEGIN
    PERFORM net.http_post(
      url := 'https://htdblwldjkcgjvmqkbeh.supabase.co/functions/v1/alert_founder',
      headers := jsonb_build_object('Content-Type','application/json'),
      body := jsonb_build_object('__secret',(select value from public.app_secrets where key='cred_db_internal'),
                                 'event','OS incident #'||nid||' ('||coalesce(p_severity,'medium')||'): '||p_title,
                                 'detail',left(coalesce(p_detail->>'description',''),300),'level','action')
    );
  EXCEPTION WHEN others THEN /* notification is best-effort */ END;
  RETURN jsonb_build_object('ok',true,'id',nid);
END $function$


CREATE OR REPLACE FUNCTION public.fn_os_incident_resolve(p_id bigint, p_resolution text, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE public.os_incidents SET status='resolved', resolved_by=coalesce(p_actor,'os'), resolved_at=now(), resolution=nullif(p_resolution,'')
  WHERE id=p_id AND status <> 'resolved';
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'error','not_found_or_already_resolved'); END IF;
  INSERT INTO public.os_audit_log(actor,action,entity,entity_id,detail,ok)
  VALUES (coalesce(p_actor,'os'),'incident_resolve','incident',p_id::text,jsonb_build_object('resolution',p_resolution),true);
  RETURN jsonb_build_object('ok',true);
END $function$


CREATE OR REPLACE FUNCTION public.fn_os_list(p_entity text, p_params jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_tbl text; v_cols text; v_search text[]; v_status text; v_order text; v_idcol text := 'id';
  v_q text := coalesce(nullif(trim(p_params->>'q'),''), null);
  v_st text := coalesce(nullif(trim(p_params->>'status'),''), null);
  v_limit int := least(coalesce((p_params->>'limit')::int, 60), 300);
  v_offset int := greatest(coalesce((p_params->>'offset')::int, 0), 0);
  v_where text := ' where true'; v_rows jsonb; v_total bigint; v_sql text; v_fk text; v_fv text;
begin
  case p_entity
    when 'inquiries' then v_tbl:='inquiries'; v_cols:='id,category,emirate,status,pipeline_stage,scope_type,budget,expected_value,rfq_ready,customer_id,hired_supplier_id,outcome,created_at'; v_search:=array['category','emirate','summary','role_needed']; v_status:='status'; v_order:=' order by created_at desc';
    when 'quotes' then v_tbl:='quotes'; v_cols:='id,inquiry_id,supplier_id,quote_amount,customer_price,app_fee,status,review_status,lead_time,warranty,created_at,expires_at'; v_search:=array['notes','scope','payment_terms']; v_status:='status'; v_order:=' order by created_at desc';
    when 'transactions' then v_tbl:='transactions'; v_cols:='id,inquiry_id,supplier_id,customer_id,quote_amount,reveal_fee,app_fee,fee_status,refund_status,revealed_at,payment_ref'; v_search:=array['payment_ref','refund_reason']; v_status:='fee_status'; v_order:=' order by revealed_at desc nulls last';
    when 'customers' then v_tbl:='customers'; v_cols:='id,full_name,email,phone,email_verified,phone_verified,banned,chat_strikes,locale,created_at'; v_search:=array['full_name','email','phone']; v_status:=null; v_order:=' order by created_at desc';
    when 'suppliers' then v_tbl:='leads'; v_cols:='id,company_name,sector,emirate,city,approval_status,verification_status,verified,matching_blocked,banned,rating,app_rating,capability_score,registration_status,contact_name,email,phone,created_at'; v_search:=array['company_name','email','sector','phone']; v_status:='approval_status'; v_order:=' order by created_at desc';
    when 'agent_actions' then v_tbl:='agent_actions'; v_cols:='id,agent,kind,title,status,risk,confidence,target_table,target_id,escalated,created_at,decided_at,decided_by'; v_search:=array['title','recommendation','agent','kind']; v_status:='status'; v_order:=' order by (status=''pending'') desc, created_at desc';
    when 'doc_reviews' then v_tbl:='doc_reviews'; v_cols:='id,from_email,subject,file_name,ai_category,ai_suggested_field,ai_confidence,status,auto_applied,created_at,file_path'; v_search:=array['subject','from_email','file_name','ai_category']; v_status:='status'; v_order:=' order by created_at desc';
    when 'kb_revisions' then v_tbl:='kb_revisions'; v_cols:='id,entry_kind,entry_ref,version,status,author,reviewer,created_at,decided_at'; v_search:=array['entry_ref','entry_kind','author']; v_status:='status'; v_order:=' order by created_at desc';
    when 'inbox' then v_tbl:='inbound_messages'; v_cols:='id,from_email,to_email,subject,ai_category,needs_review,attachments_count,replied_at,created_at'; v_search:=array['subject','from_email','ai_summary']; v_status:='ai_category'; v_order:=' order by created_at desc';
    when 'documents' then v_tbl:='documents'; v_cols:='id,file_name,kind,ref_table,ref_id,mime,status,indexed,bucket,path,created_at'; v_search:=array['file_name','kind','ref_table']; v_status:='status'; v_order:=' order by created_at desc';
    when 'dropbox' then v_tbl:='dropbox_files'; v_cols:='id,path,name,is_folder,size,server_modified,synced_at'; v_search:=array['path','name']; v_status:=null; v_order:=' order by is_folder desc, name asc';
    when 'invoices' then v_tbl:='reveal_invoices'; v_cols:='transaction_id,invoice_no,bucket,path,created_at'; v_search:=array['invoice_no']; v_status:=null; v_order:=' order by created_at desc'; v_idcol:='transaction_id';
    when 'notifications' then v_tbl:='notifications'; v_cols:='id,type,to_email,to_role,subject,status,channel,created_at,sent_at,last_error'; v_search:=array['subject','to_email','type']; v_status:='status'; v_order:=' order by created_at desc';
    when 'tasks' then v_tbl:='crm_tasks'; v_cols:='id,title,status,priority,entity,entity_id,due_date,created_at,done_at'; v_search:=array['title','detail']; v_status:='status'; v_order:=' order by (status<>''done'') desc, due_date asc nulls last';
    when 'notes' then v_tbl:='crm_notes'; v_cols:='id,entity,entity_id,body,author,created_at'; v_search:=array['body','author']; v_status:=null; v_order:=' order by created_at desc';
    when 'po' then v_tbl:='po_orders'; v_cols:='id,po_no,vendor_id,status,subtotal,currency,order_date,expected_date,approved_by,approved_at,created_at'; v_search:=array['po_no','memo']; v_status:='status'; v_order:=' order by created_at desc';
    when 'expenses' then v_tbl:='expenses'; v_cols:='id,vendor,category,description,amount,currency,cadence,expense_date,active,created_at'; v_search:=array['vendor','description','category']; v_status:=null; v_order:=' order by expense_date desc nulls last';
    when 'agent_runs' then v_tbl:='agent_runs'; v_cols:='id,agent,status,started_at,finished_at,note'; v_search:=array['agent','note']; v_status:='status'; v_order:=' order by started_at desc nulls last';
    when 'fraud' then v_tbl:='fraud_flags'; v_cols:='kind,subject_type,subject_id,severity,status,detail,created_at'; v_search:=array['kind','subject_type','subject_id']; v_status:='status'; v_order:=' order by created_at desc'; v_idcol:='subject_id';
    else return jsonb_build_object('error','unknown_entity','entity',p_entity);
  end case;

  if v_st is not null and v_status is not null then v_where := v_where || format(' and %I = %L', v_status, v_st); end if;
  if v_q is not null then
    v_where := v_where || ' and (' || array_to_string(array(select format('coalesce(%I::text,'''') ilike %L', c, '%'||v_q||'%') from unnest(v_search) c), ' or ') || ')';
  end if;
  if p_params ? 'filters' then
    for v_fk, v_fv in select key, value from jsonb_each_text(p_params->'filters') loop
      if v_fk = any(array['inquiry_id','supplier_id','customer_id','quote_id','ref_table','ref_id','agent','entity','entity_id','category','emirate','lead_id','vendor_id','target_table','target_id']) and position(v_fk in v_cols) > 0 and v_fv is not null then
        v_where := v_where || format(' and %I::text = %L', v_fk, v_fv);
      end if;
    end loop;
  end if;

  execute format('select count(*) from %I%s', v_tbl, v_where) into v_total;
  v_sql := format('select coalesce(jsonb_agg(to_jsonb(t)),''[]''::jsonb) from (select %s from %I%s%s limit %s offset %s) t', v_cols, v_tbl, v_where, v_order, v_limit, v_offset);
  execute v_sql into v_rows;
  return jsonb_build_object('entity',p_entity,'id_col',v_idcol,'columns',string_to_array(v_cols, ','),'total',v_total,'rows',v_rows);
end $function$


CREATE OR REPLACE FUNCTION public.fn_os_nav()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'badges', jsonb_build_object(
      'approvals', (select count(*) from agent_actions where status='pending'),
      'tasks', (select count(*) from crm_tasks where coalesce(status,'') <> 'done'),
      'suppliers_review', (select count(*) from leads where coalesce(approval_status,'') in ('submitted','pending','under_review','pending_review')),
      'notifications', (select count(*) from notifications where coalesce(status,'') not in ('sent','delivered','read')),
      'knowledge_review', (select count(*) from kb_revisions where coalesce(status,'')='pending'),
      'documents_review', (select count(*) from doc_reviews where coalesce(status,'')='pending'),
      'disputes', (select count(*) from transactions where coalesce(refund_status,'') in ('requested','pending')),
      'fraud_open', (select count(*) from fraud_flags where coalesce(status,'open') not in ('dismissed','resolved','closed')),
      'rfqs_active', (select count(*) from inquiries where coalesce(status,'') not in ('completed','cancelled','closed'))
    ),
    'generated_at', now()
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_os_reconcile()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE res jsonb; gl_diff numeric;
BEGIN
  BEGIN SELECT coalesce(sum(debit),0) - coalesce(sum(credit),0) INTO gl_diff FROM public.gl_journal_lines;
  EXCEPTION WHEN others THEN gl_diff := NULL; END;
  SELECT jsonb_build_object(
    'generated_at', now(),
    'transactions_total', (SELECT count(*) FROM public.transactions),
    'revenue_reveal_fees_aed', coalesce((SELECT round(sum(reveal_fee)::numeric,2) FROM public.transactions),0),
    'refunds_pending', (SELECT count(*) FROM public.transactions WHERE refund_status='requested'),
    'refunds_resolved', (SELECT count(*) FROM public.transactions WHERE refund_status IS NOT NULL AND refund_status <> 'requested'),
    'stripe_events_total', (SELECT count(*) FROM public.stripe_events),
    'stripe_paid_checkouts', (SELECT count(*) FROM public.stripe_events WHERE type='checkout.session.completed' AND payment_status='paid'),
    'gl_debits_minus_credits', CASE WHEN gl_diff IS NULL THEN NULL ELSE round(gl_diff,2) END,
    'gl_balanced', CASE WHEN gl_diff IS NULL THEN NULL ELSE (abs(gl_diff) < 0.01) END
  ) INTO res;
  RETURN res;
END $function$


CREATE OR REPLACE FUNCTION public.fn_os_record(p_entity text, p_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v jsonb;
begin
  if p_entity='supplier' then select to_jsonb(l) into v from leads l where l.id = p_id::bigint;
  elsif p_entity='rfq' then select to_jsonb(i) into v from inquiries i where i.id = p_id::uuid;
  elsif p_entity='customer' then select to_jsonb(c) into v from customers c where c.id = p_id::uuid;
  elsif p_entity='quote' then select to_jsonb(q) into v from quotes q where q.id = p_id::uuid;
  elsif p_entity='agent_action' then select to_jsonb(a) into v from agent_actions a where a.id = p_id::bigint;
  elsif p_entity='task' then select to_jsonb(t) into v from crm_tasks t where t.id = p_id::bigint;
  else v := null; end if;
  return jsonb_build_object('entity',p_entity,'id',p_id,'record',v);
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_os_review()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v_period text := to_char(now(),'IYYY-"W"IW');
  v_health text; v_find jsonb; v_act int; v_total int := 0; v_red int := 0; v_amber int := 0;
  v_missed int; v_stale int; v_overspend numeric;
begin
  for r in select * from v_os_scoreboard loop
    v_find := '[]'::jsonb; v_act := 0;

    select count(*) into v_missed from org_tasks t
      join os_department od on od.dept_key = t.dept_key
     where od.os_key = r.os_key and t.title like 'KPI missed:%' and t.status <> 'done';

    select count(*) into v_stale from org_tasks t
      join os_department od on od.dept_key = t.dept_key
     where od.os_key = r.os_key and t.status <> 'done' and t.created_at < now() - interval '14 days';

    v_overspend := case when r.budget_aed > 0 then round(100.0*r.spent_aed/r.budget_aed,1) else 0 end;

    if r.employees = 0 then
      v_find := v_find || jsonb_build_array(jsonb_build_object('issue','no employees','detail','This operating system has no staff.'));
    end if;
    if r.kpis = 0 then
      v_find := v_find || jsonb_build_array(jsonb_build_object('issue','no KPIs','detail','This operating system cannot be held to account.'));
    end if;
    if r.kpis_unmeasurable > 0 then
      v_find := v_find || jsonb_build_array(jsonb_build_object('issue','unmeasurable KPIs','detail',r.kpis_unmeasurable||' KPI(s) have no measure.'));
    end if;
    if v_missed > 0 then
      v_find := v_find || jsonb_build_array(jsonb_build_object('issue','KPIs missing target','detail',v_missed||' unclosed KPI gap(s).'));
    end if;
    if v_stale > 0 then
      v_find := v_find || jsonb_build_array(jsonb_build_object('issue','stale work','detail',v_stale||' task(s) open more than 14 days.'));
    end if;
    if v_overspend >= 95 then
      v_find := v_find || jsonb_build_array(jsonb_build_object('issue','budget halt','detail',v_overspend||'% of monthly AI budget spent.'));
    elsif v_overspend >= 70 then
      v_find := v_find || jsonb_build_array(jsonb_build_object('issue','budget degrade','detail',v_overspend||'% of monthly AI budget spent.'));
    end if;

    v_health := case
      when r.employees = 0 or r.kpis = 0 or v_overspend >= 95 then 'red'
      when jsonb_array_length(v_find) > 0 then 'amber'
      else 'green' end;

    if v_health <> 'green' then
      insert into org_tasks (dept_key, title, detail, status, tier, needs_founder, action_class)
      select coalesce((select department from org_agents where agent_key = r.owner_agent), 'exec'),
             'OS review ['||v_health||']: '||r.name,
             'Owner: '||coalesce(r.owner_agent,'unassigned')||'. Week '||v_period||'. Findings: '||v_find::text
             ||'. Close each finding or bring evidence the standard is wrong.',
             'proposed','advisory', false, 'exec_review'
      where not exists (select 1 from org_tasks t2 where t2.title like 'OS review [%]: '||r.name and t2.status <> 'done');
      get diagnostics v_act = row_count;
    end if;

    insert into os_review (os_key, period, owner_agent, health, metrics, findings, actions)
    values (r.os_key, v_period, r.owner_agent, v_health,
            jsonb_build_object('departments',r.departments,'employees',r.employees,'open_tasks',r.open_tasks,
                               'kpis',r.kpis,'kpis_unmeasurable',r.kpis_unmeasurable,
                               'budget_pct',v_overspend,'kpi_gaps',v_missed,'stale_tasks',v_stale),
            v_find, v_act)
    on conflict (os_key, period) do update
      set health=excluded.health, metrics=excluded.metrics, findings=excluded.findings,
          actions=excluded.actions, created_at=now();

    v_total := v_total + 1;
    if v_health='red' then v_red := v_red+1; elsif v_health='amber' then v_amber := v_amber+1; end if;
  end loop;

  insert into agent_runs (agent, started_at, finished_at, status, counts, note)
  values ('os_review', now(), now(), case when v_red>0 then 'error' else 'ok' end,
          jsonb_build_object('reviewed',v_total,'red',v_red,'amber',v_amber,'green',v_total-v_red-v_amber),
          'Operating system review, week '||v_period||': '||(v_total-v_red-v_amber)||' green, '||v_amber||' amber, '||v_red||' red.');

  return jsonb_build_object('reviewed',v_total,'red',v_red,'amber',v_amber,'green',v_total-v_red-v_amber);
end $function$


CREATE OR REPLACE FUNCTION public.fn_os_runbooks()
 RETURNS jsonb
