 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ select public.fn_period_report('quarterly'); $function$


CREATE OR REPLACE FUNCTION public.fn_query_platform(p_topic text, p_args jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v jsonb;
begin
  case lower(coalesce(p_topic,''))
    when 'topics' then
      v := jsonb_build_object('topics', jsonb_build_array(
        'knowledge','agents','agent_ops','ai','analytics','company','customers','documents',
        'ea','exec','finance','fraud','governance','marketing','marketplace','operations',
        'refunds','reports','strategy','suppliers','supplier_360','customer_360','rfq_360','funnel'));
    when 'knowledge'   then v := to_jsonb(fn_ws_knowledge());
    when 'agents'      then v := to_jsonb(fn_ws_agents());
    when 'agent_ops'   then v := to_jsonb(fn_ws_agent_ops(coalesce(p_args->>'agent','')));
    when 'ai'          then v := to_jsonb(fn_ws_ai());
    when 'analytics'   then v := to_jsonb(fn_ws_analytics());
    when 'company'     then v := to_jsonb(fn_ws_company());
    when 'customers'   then v := to_jsonb(fn_ws_customers());
    when 'documents'   then v := to_jsonb(fn_ws_documents());
    when 'ea'          then v := to_jsonb(fn_ws_ea());
    when 'exec'        then v := to_jsonb(fn_ws_exec());
    when 'finance'     then v := to_jsonb(fn_ws_finance());
    when 'fraud'       then v := to_jsonb(fn_ws_fraud());
    when 'governance'  then v := to_jsonb(fn_ws_governance());
    when 'marketing'   then v := to_jsonb(fn_ws_marketing());
    when 'marketplace' then v := to_jsonb(fn_ws_marketplace());
    when 'operations'  then v := to_jsonb(fn_ws_operations());
    when 'refunds'     then v := to_jsonb(fn_ws_refunds());
    when 'reports'     then v := to_jsonb(fn_ws_reports());
    when 'strategy'    then v := to_jsonb(fn_ws_strategy());
    when 'suppliers'   then v := to_jsonb(fn_ws_suppliers(coalesce(p_args,'{}'::jsonb)));
    when 'supplier_360' then v := to_jsonb(fn_ws_supplier_360((p_args->>'id')::bigint));
    when 'customer_360' then v := to_jsonb(fn_ws_customer_360((p_args->>'id')::uuid));
    when 'rfq_360'      then v := to_jsonb(fn_ws_rfq_360((p_args->>'id')::uuid));
    when 'funnel'       then v := to_jsonb(funnel_metrics(coalesce((p_args->>'days')::int,30)));
    else v := jsonb_build_object('error','unknown_topic','hint','call with topic=topics to list valid topics');
  end case;
  return coalesce(v,'{}'::jsonb);
exception when others then
  return jsonb_build_object('error','query_failed','topic',p_topic,'detail',sqlerrm);
end $function$


CREATE OR REPLACE FUNCTION public.fn_quote_category_score(p_quote text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare q record; grp text; blob text; r record;
        tot int:=0; okc int:=0; miss jsonb:='[]'::jsonb; pres jsonb:='[]'::jsonb; mand_missing int:=0;
begin
  select * into q from quotes where id=p_quote::uuid;
  if q is null then return jsonb_build_object('applicable',false,'reason','quote not found'); end if;
  grp := fn_quote_spec_group(coalesce((select category from inquiries where id=q.inquiry_id),''));
  if grp is null then return jsonb_build_object('applicable',false,'reason','no category spec group'); end if;
  if not exists (select 1 from category_quote_specs where spec_group=grp) then
    return jsonb_build_object('applicable',false,'reason','no specs defined for '||grp); end if;

  select lower(concat_ws(' ', q.scope, q.conditions, q.exclusions, q.notes, q.warranty,
           q.payment_terms, q.lead_time, q.validity,
           (select string_agg(concat_ws(' ',description,brand,model,specification),' ')
              from quote_items where quote_id=p_quote)))
    into blob;
  blob := coalesce(blob,'');

  for r in select * from category_quote_specs where spec_group=grp order by mandatory desc, aspect loop
    tot := tot + 1;
    if blob ~* r.match_regex then
      okc := okc + 1; pres := pres || to_jsonb(r.aspect);
    else
      miss := miss || jsonb_build_object('aspect',r.aspect,'label',r.label,'mandatory',r.mandatory);
      if r.mandatory then mand_missing := mand_missing + 1; end if;
    end if;
  end loop;

  return jsonb_build_object(
    'applicable', true, 'group', grp,
    'aspects_total', tot, 'aspects_present', okc,
    'mandatory_missing', mand_missing,
    'category_pass', (mand_missing = 0),
    'present', pres, 'missing', miss);
end $function$


CREATE OR REPLACE FUNCTION public.fn_quote_category_score_text(p_category text, p_text text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare grp text; blob text; r record; tot int:=0; okc int:=0; mand_missing int:=0; miss jsonb:='[]'::jsonb;
begin
  grp := fn_quote_spec_group(coalesce(p_category,''));
  if grp is null or not exists (select 1 from category_quote_specs where spec_group=grp) then
    return jsonb_build_object('applicable',false); end if;
  blob := lower(coalesce(p_text,''));
  for r in select * from category_quote_specs where spec_group=grp loop
    tot := tot + 1;
    if blob ~* r.match_regex then okc := okc + 1;
    else miss := miss || jsonb_build_object('aspect',r.aspect,'mandatory',r.mandatory);
      if r.mandatory then mand_missing := mand_missing + 1; end if; end if;
  end loop;
  return jsonb_build_object('applicable',true,'group',grp,'aspects_total',tot,'aspects_present',okc,
    'mandatory_missing',mand_missing,'category_pass',(mand_missing=0),'missing',miss);
end $function$


CREATE OR REPLACE FUNCTION public.fn_quote_coach(p_quote uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare sc jsonb; lbls text[]; miss text; sup record; co text; subject text; msg text;
begin
  sc := public.fn_quote_structured_score(p_quote::text);
  if (sc->>'submittable')::boolean then return jsonb_build_object('ok',true,'submittable',true); end if;
  lbls := '{}';
  for miss in select jsonb_array_elements_text(sc->'missing') loop
    lbls := array_append(lbls, case miss
      when 'line_items' then 'an itemised breakdown — add each item as a line'
      when 'unit_prices_on_all_items' then 'a unit price on every line item'
      when 'brand_model_per_item' then 'the brand and model for each item'
      when 'specifications' then 'technical specifications for the items'
      when 'labour_or_installation' then 'labour / installation cost'
      when 'warranty' then 'the warranty offered'
      when 'lead_time' then 'the lead time / delivery timeline'
      when 'payment_terms' then 'your payment terms'
      when 'exclusions' then 'what is excluded from the quote'
      when 'validity' then 'how long the quote is valid'
      else miss end);
  end loop;
  select l.company_name, l.claimed_by, l.email into sup
    from public.quotes q join public.leads l on l.id=q.supplier_id where q.id=p_quote;
  co := coalesce(sup.company_name,'there');
  if not exists (select 1 from public.notifications n where n.type='quote_coaching'
                   and n.to_email=coalesce(sup.claimed_by,sup.email) and n.created_at > now()-interval '24 hours'
                   and n.body like '%'||p_quote::text||'%') then
    subject := 'Your quote needs a few more details before we can send it';
    msg := 'Hi '||co||','||E'\n\n'||'Thanks for your quote. To make it competitive and send it to the customer, please add the following in your supplier portal:'||E'\n\n'
      ||'• '||array_to_string(lbls, E'\n• ')||E'\n\n'
      ||'Detailed quotes (with brands, specifications and a clear itemised breakdown) win far more often. Open your portal, complete these, and we will send it to the customer right away.'||E'\n\n'||'(ref '||p_quote::text||')';
    insert into public.notifications(type,to_email,to_role,channel,subject,body,status)
      values('quote_coaching', coalesce(sup.claimed_by,sup.email), 'supplier','email',subject,msg,'queued');
  end if;
  return jsonb_build_object('ok',true,'submittable',false,'missing',lbls,'score',sc->>'score');
end $function$


CREATE OR REPLACE FUNCTION public.fn_quote_coach_text(p_quote text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare gen jsonb; cat jsonb; asks text[] := '{}'; m jsonb; lbl text;
        gen_labels jsonb := jsonb_build_object(
          'line_items','an itemised breakdown (not just a lump sum)',
          'unit_prices_on_all_items','a unit price on every line',
          'brand_model_per_item','the brand/model for each item',
          'specifications','the key specifications',
          'labour_or_installation','the labour / installation cost',
          'warranty','the warranty period','lead_time','the lead / delivery time',
          'payment_terms','the payment terms','exclusions','what is excluded',
          'validity','how long the quote is valid');
begin
  select quality into gen from quotes where id = p_quote::uuid;
  -- generic completeness gaps
  if gen ? 'missing' then
    for m in select * from jsonb_array_elements(gen->'missing') loop
      lbl := gen_labels->>(m #>> '{}'); if lbl is null then lbl := m #>> '{}'; end if;
      asks := asks || lbl;
    end loop;
  end if;
  -- category-specific domain gaps (mandatory only)
  cat := fn_quote_category_score(p_quote);
  if (cat->>'applicable')::boolean and cat ? 'missing' then
    for m in select * from jsonb_array_elements(cat->'missing') loop
      if (m->>'mandatory')::boolean then asks := asks || lower(m->>'label'); end if;
    end loop;
  end if;
  asks := (select array_agg(distinct a) from unnest(asks) a);
  if coalesce(array_length(asks,1),0) = 0 then
    return jsonb_build_object('complete', true, 'message',
      'Your quote looks complete — thank you. Customers will be able to compare it fairly.');
  end if;
  return jsonb_build_object('complete', false, 'missing_count', array_length(asks,1),
    'message', 'Almost there. To help customers compare your quote fairly and pick you, please add: '
      || array_to_string(asks, '; ') || '. This makes your quote stronger, not harder — complete quotes win more often.',
    'asks', to_jsonb(asks));
end $function$


CREATE OR REPLACE FUNCTION public.fn_quote_recompute_submittable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare qid uuid; sc jsonb; cat jsonb; ok boolean;
begin
  qid := coalesce(NEW.quote_id, OLD.quote_id);
  begin sc := public.fn_quote_structured_score(qid::text); exception when others then sc := null; end;
  begin cat := public.fn_quote_category_score(qid::text); exception when others then cat := null; end;
  if sc is not null then
    ok := (sc->>'submittable')::boolean
          and (cat is null or (cat->>'applicable')::boolean is not true or (cat->>'category_pass')::boolean);
    update public.quotes set submittable = ok
      where id = qid and submittable is distinct from ok;
  end if;
  return coalesce(NEW, OLD);
end $function$


CREATE OR REPLACE FUNCTION public.fn_quote_score_json(p_quote jsonb, p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare n int; priced int; branded int; laboured int; spec_n int; pts int:=0; miss text[]:='{}'; it jsonb;
begin
  n:=0; priced:=0; branded:=0; laboured:=0; spec_n:=0;
  for it in select * from jsonb_array_elements(coalesce(p_items,'[]'::jsonb)) loop
    n:=n+1;
    if coalesce((it->>'unit_price')::numeric,0) > 0 then priced:=priced+1; end if;
    if coalesce(it->>'brand','')<>'' and coalesce(it->>'model','')<>'' then branded:=branded+1; end if;
    if (it->>'labour') is not null or (it->>'install') is not null then laboured:=laboured+1; end if;
    if coalesce(it->>'specification','')<>'' then spec_n:=spec_n+1; end if;
  end loop;
  if n=0 then miss:=array_append(miss,'line_items');
  else pts:=pts+15; if priced=n then pts:=pts+20; else miss:=array_append(miss,'unit_prices_on_all_items'); end if; end if;
  if n>0 and branded=n then pts:=pts+15; else miss:=array_append(miss,'brand_model_per_item'); end if;
  if n>0 and spec_n>=greatest(1,n/2) then pts:=pts+10; else miss:=array_append(miss,'specifications'); end if;
  if laboured>0 then pts:=pts+10; else miss:=array_append(miss,'labour_or_installation'); end if;
  if coalesce(p_quote->>'warranty','')<>'' then pts:=pts+6; else miss:=array_append(miss,'warranty'); end if;
  if coalesce(p_quote->>'lead_time','')<>'' then pts:=pts+6; else miss:=array_append(miss,'lead_time'); end if;
  if coalesce(p_quote->>'payment_terms','')<>'' then pts:=pts+6; else miss:=array_append(miss,'payment_terms'); end if;
  if coalesce(p_quote->>'exclusions','')<>'' then pts:=pts+6; else miss:=array_append(miss,'exclusions'); end if;
  if coalesce(p_quote->>'validity','')<>'' then pts:=pts+6; else miss:=array_append(miss,'validity'); end if;
  return jsonb_build_object('score',pts,'submittable',pts>=70,'items',n,'missing',to_jsonb(miss));
end $function$


CREATE OR REPLACE FUNCTION public.fn_quote_spec_group(p_category text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case
    when p_category ~* 'duct.?clean|ac.?duct' then 'acduct'
    when p_category ~* 'facade.?clean|facade cleaning' then 'facade'
    when p_category ~* 'water.?tank' then 'watertank'
    when p_category ~* 'cctv|surveillance|security|access.?control|intercom|alarm' then 'security'
    when p_category ~* 'fire|safety|sprinkler|extinguisher|civil.?defen' then 'fire'
    when p_category ~* 'scaffold' then 'scaffolding'
    when p_category ~* 'demolition|strip.?out' then 'demolition'
    when p_category ~* 'garage.?door|shutter|rolling' then 'shutters'
    when p_category ~* 'elevator|escalator|^lift|lifts' then 'elevators'
    when p_category ~* 'generator' then 'generators'
    when p_category ~* 'solar|photovolt|shams' then 'solar'
    when p_category ~* 'swimming|pool' then 'pools'
    when p_category ~* 'tent|shade|pergola|awning|gazebo' then 'shade'
    when p_category ~* 'landscap|garden|softscape|hardscape|irrigation' then 'landscaping'
    when p_category ~* 'pest' then 'pestcontrol'
    when p_category ~* 'mover|moving|relocation|packing' then 'movers'
    when p_category ~* 'upholstery|curtain|blind|sofa' then 'upholstery'
    when p_category ~* 'wallpaper|wall covering' then 'wallpaper'
    when p_category ~* 'carpet' then 'carpet'
    when p_category ~* 'tiling|tile|marble|granite' then 'tiling'
    when p_category ~* 'floor|spc|vinyl|lvt|epoxy.?floor|parquet|laminate' then 'flooring'
    when p_category ~* 'paint' then 'painting'
    when p_category ~* 'gypsum|false.?ceiling|ceiling|drywall|plasterboard|partition' then 'gypsum'
    when p_category ~* 'waterproof' then 'waterproofing'
    when p_category ~* 'insulation' then 'insulation'
    when p_category ~* 'roofing|^roof|roof ' then 'roofing'
    when p_category ~* 'steel|fabrication' then 'steel'
    when p_category ~* 'masonry|block|^plaster' then 'masonry'
    when p_category ~* 'smart.?home|home.?automation|automation|knx' then 'smarthome'
    when p_category ~* 'av.?system|audio.?visual|audio visual' then 'avsystems'
    when p_category ~* 'network|structured.?cabl' then 'networking'
    when p_category ~* 'signage|sign.?board|3d letter' then 'signage'
    when p_category ~* 'acrylic|perspex|plexiglass' then 'acrylic'
    when p_category ~* 'interior.?design' then 'interiordesign'
    when p_category ~* 'fit.?out' then 'fitout'
    when p_category ~* 'combined.?mep|^mep$|mep' then 'mep'
    when p_category ~* 'glass|glaz|alumin|curtain.?wall|shopfront|balustrad' then 'glazing'
    when p_category ~* 'joinery|kitchen|furniture|carpentr|cabinet|wardrobe|cupboard' then 'joinery'
    when p_category ~* 'hvac|^ac-|air.?con|duct|chiller|cooling|ac.?maintenance' then 'hvac'
    when p_category ~* 'electric|wiring|dewa' then 'electrical'
    when p_category ~* 'plumb|sanitary|drainage' then 'plumbing'
    when p_category ~* 'facade' then 'glazing'
    when p_category ~* 'clean|housekeep' then 'cleaning'
    when p_category ~* 'handyman' then 'handyman'
    when p_category ~* 'facilit|general.?service|miscellaneous|^other|^general' then 'general'
    else null end;
$function$


CREATE OR REPLACE FUNCTION public.fn_quote_structured_score(p_quote text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare n int; priced int; branded int; laboured int; spec_n int; q record; pts int:=0; miss text[]:='{}';
begin
  select count(*), count(*) filter (where unit_price is not null and unit_price>0),
         count(*) filter (where coalesce(brand,'')<>'' and coalesce(model,'')<>''),
         count(*) filter (where labour is not null or install is not null),
         count(*) filter (where coalesce(specification,'')<>'')
    into n, priced, branded, laboured, spec_n from quote_items where quote_id=p_quote;
  select * into q from quotes where id=p_quote::uuid;
  if n=0 then miss:=array_append(miss,'line_items');
  else pts:=pts+15; if priced=n then pts:=pts+20; else miss:=array_append(miss,'unit_prices_on_all_items'); end if; end if;
  if n>0 and branded=n then pts:=pts+15; else miss:=array_append(miss,'brand_model_per_item'); end if;
  if n>0 and spec_n>=greatest(1,n/2) then pts:=pts+10; else miss:=array_append(miss,'specifications'); end if;
  if laboured>0 then pts:=pts+10; else miss:=array_append(miss,'labour_or_installation'); end if;
  if coalesce(q.warranty,'')<>'' then pts:=pts+6; else miss:=array_append(miss,'warranty'); end if;
  if coalesce(q.lead_time,'')<>'' then pts:=pts+6; else miss:=array_append(miss,'lead_time'); end if;
  if coalesce(q.payment_terms,'')<>'' then pts:=pts+6; else miss:=array_append(miss,'payment_terms'); end if;
  if coalesce(q.exclusions,'')<>'' then pts:=pts+6; else miss:=array_append(miss,'exclusions'); end if;
  if coalesce(q.validity,'')<>'' then pts:=pts+6; else miss:=array_append(miss,'validity'); end if;
  return jsonb_build_object('score',pts,'submittable',pts>=70,'items',n,'priced_items',priced,'missing',to_jsonb(miss),'scored_at',now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_rate_limit(p_bucket text, p_limit integer, p_window_seconds integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r ai_rate_limit%rowtype;
begin
  insert into ai_rate_limit (bucket, window_start, count) values (p_bucket, now(), 0)
    on conflict (bucket) do nothing;
  select * into r from ai_rate_limit where bucket = p_bucket for update;
  if r.window_start < now() - make_interval(secs => p_window_seconds) then
    update ai_rate_limit set window_start = now(), count = 1 where bucket = p_bucket;
    return jsonb_build_object('allowed', true, 'count', 1, 'limit', p_limit);
  end if;
  if r.count >= p_limit then
    return jsonb_build_object('allowed', false, 'count', r.count, 'limit', p_limit,
      'retry_after_seconds', greatest(1, p_window_seconds - extract(epoch from (now() - r.window_start))::int));
  end if;
  update ai_rate_limit set count = count + 1 where bucket = p_bucket;
  return jsonb_build_object('allowed', true, 'count', r.count + 1, 'limit', p_limit);
end $function$


CREATE OR REPLACE FUNCTION public.fn_reallocate()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; n int := 0; v_total numeric; v_free numeric := 0;
begin
  -- policy: never move more than 20% of a department's budget in one cycle, never below 200 AED,
  -- only from departments under 30% utilisation, only to departments over 85%.
  for r in
    select b.dept_key, b.monthly_aed, b.spent_aed,
           round(100.0*b.spent_aed/nullif(b.monthly_aed,0),1) as util
    from department_budget b where b.monthly_aed > 200
  loop
    if r.util < 30 and r.monthly_aed * 0.2 >= 50 then
      v_free := v_free + round(r.monthly_aed*0.2,0);
      insert into allocation_change (resource,subject,from_value,to_value,reason,policy)
      values ('ai_budget_aed', r.dept_key, r.monthly_aed, r.monthly_aed - round(r.monthly_aed*0.2,0),
        r.dept_key||' used only '||coalesce(r.util,0)||'% of its budget. Releasing 20% to the pool.',
        'release: utilisation under 30%, cap 20% per cycle, floor 200 AED');
      update department_budget set monthly_aed = monthly_aed - round(monthly_aed*0.2,0), updated_at=now()
       where dept_key = r.dept_key;
      n := n + 1;
    end if;
  end loop;

  if v_free > 0 then
    for r in
      select b.dept_key, b.monthly_aed, round(100.0*b.spent_aed/nullif(b.monthly_aed,0),1) util
      from department_budget b where round(100.0*b.spent_aed/nullif(b.monthly_aed,0),1) > 85
      order by util desc limit 3
    loop
      insert into allocation_change (resource,subject,from_value,to_value,reason,policy)
      values ('ai_budget_aed', r.dept_key, r.monthly_aed, r.monthly_aed + round(v_free/3,0),
        r.dept_key||' is at '||r.util||'% utilisation. Receiving released budget.',
        'grant: utilisation over 85%, split evenly across at most 3 departments');
      update department_budget set monthly_aed = monthly_aed + round(v_free/3,0), updated_at=now()
       where dept_key = r.dept_key;
      n := n + 1;
    end loop;
  end if;

  insert into agent_runs (agent,started_at,finished_at,status,counts,note)
  values ('reallocate',now(),now(),'ok',jsonb_build_object('changes',n,'released_aed',v_free),
    'Resource reallocation: '||n||' change(s), '||v_free||' AED moved from idle to saturated departments. Every change is logged and reversible.');
  return jsonb_build_object('changes',n,'released_aed',v_free);
end $function$


CREATE OR REPLACE FUNCTION public.fn_recert_rotate()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_agent text; v_secret text;
begin
  perform fn_onboarding_ingest_runs();
  select agent_key into v_agent from org_onboarding
    order by coalesce(greatest(l1_at,l2_at,l3_at,l4_at), 'epoch'::timestamptz) asc limit 1;
  if v_agent is null then return jsonb_build_object('skipped','no onboarding records'); end if;
  select value into v_secret from app_secrets where key='cred_db_internal';
  perform net.http_post(
    url:='https://htdblwldjkcgjvmqkbeh.supabase.co/functions/v1/canon_eval',
    body:=jsonb_build_object('__secret', v_secret, 'agent', v_agent, 'limit', 8),
    headers:='{"Content-Type":"application/json"}'::jsonb, timeout_milliseconds:=150000);
  return jsonb_build_object('examined', v_agent);
end $function$


CREATE OR REPLACE FUNCTION public.fn_reconcile_doc_blocks(p_grace_days integer DEFAULT 0)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_lic_susp int := 0; v_ins_susp int := 0; v_restored int := 0;
  v_cut date := current_date - make_interval(days => p_grace_days);
  rec record;
begin
  -- ---- SUSPEND: trade licence expired -------------------------------------------------
  -- Only touches rows that are unblocked or already blocked for a document reason, so a
  -- manual block set by the team is never overwritten or silently cleared.
  for rec in
    select id, company_name, claimed_by, email, phone, whatsapp, license_expiry
      from leads
     where approval_status = 'approved' and coalesce(banned,false) = false
       and license_expiry is not null and license_expiry < v_cut
       and (coalesce(matching_blocked,false) = false
            or matching_block_reason in ('licence_expired','insurance_expired'))
       and coalesce(matching_block_reason,'') is distinct from 'licence_expired'
  loop
    update leads set matching_blocked = true, matching_block_reason = 'licence_expired'
     where id = rec.id;
    v_lic_susp := v_lic_susp + 1;
    insert into notifications(type,to_email,to_role,lead_id,channel,subject,body,status)
    values ('doc_suspended', coalesce(rec.claimed_by, rec.email), 'supplier', rec.id, 'email',
      'Your QuotesDone account is paused - trade licence expired',
      'Dear ' || coalesce(rec.company_name,'supplier') || ',' || chr(10) || chr(10) ||
      'Your trade licence expired on ' || rec.license_expiry || ', so your account has been temporarily paused and you will not receive new customer requests until it is renewed.' || chr(10) || chr(10) ||
      'To restore your account: reply to this email with the renewed licence attached, or upload it in the Documents tab of your supplier portal. Your account is restored automatically as soon as we have a valid copy - nothing else is needed and no fee applies.',
      'queued');
  end loop;

  -- ---- SUSPEND: insurance expired -----------------------------------------------------
  for rec in
    select id, company_name, claimed_by, email, insurance_expiry
      from leads
     where approval_status = 'approved' and coalesce(banned,false) = false
       and insurance_expiry is not null and insurance_expiry < v_cut
       and (coalesce(matching_blocked,false) = false
            or matching_block_reason in ('licence_expired','insurance_expired'))
       and coalesce(matching_block_reason,'') is distinct from 'insurance_expired'
       -- a licence block is the more serious of the two, so do not downgrade its reason
       and coalesce(matching_block_reason,'') is distinct from 'licence_expired'
  loop
    update leads set matching_blocked = true, matching_block_reason = 'insurance_expired'
     where id = rec.id;
    v_ins_susp := v_ins_susp + 1;
    insert into notifications(type,to_email,to_role,lead_id,channel,subject,body,status)
    values ('doc_suspended', coalesce(rec.claimed_by, rec.email), 'supplier', rec.id, 'email',
      'Your QuotesDone account is paused - insurance expired',
      'Dear ' || coalesce(rec.company_name,'supplier') || ',' || chr(10) || chr(10) ||
      'Your insurance certificate expired on ' || rec.insurance_expiry || ', so your account has been temporarily paused and you will not receive new customer requests until it is renewed.' || chr(10) || chr(10) ||
      'To restore your account: reply to this email with the renewed certificate attached, or upload it in the Documents tab of your supplier portal. Your account is restored automatically as soon as we have a valid copy.',
      'queued');
  end loop;

  -- ---- RESTORE: the blocking document is valid again -----------------------------------
  -- Only clears blocks this job set. A manual block stays put.
  for rec in
    select id, company_name, claimed_by, email, matching_block_reason
      from leads
     where matching_block_reason in ('licence_expired','insurance_expired')
       and ((matching_block_reason = 'licence_expired'
             and (license_expiry is null or license_expiry >= v_cut))
         or (matching_block_reason = 'insurance_expired'
             and (insurance_expiry is null or insurance_expiry >= v_cut)))
  loop
    update leads set matching_blocked = false, matching_block_reason = null where id = rec.id;
    v_restored := v_restored + 1;
    insert into notifications(type,to_email,to_role,lead_id,channel,subject,body,status)
    values ('doc_restored', coalesce(rec.claimed_by, rec.email), 'supplier', rec.id, 'email',
      'Your QuotesDone account is active again',
      'Dear ' || coalesce(rec.company_name,'supplier') || ',' || chr(10) || chr(10) ||
      'Thank you - your documents are up to date and your account is active again. You will start receiving matching customer requests immediately.',
      'queued');
  end loop;

  return json_build_object('licence_suspended', v_lic_susp, 'insurance_suspended', v_ins_susp,
                           'restored', v_restored, 'grace_days', p_grace_days, 'ran_at', now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_reconcile_licence_blocks(p_grace_days integer DEFAULT 0)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_suspended int; v_restored int;
begin
  -- Suspend approved, non-banned suppliers whose trade licence is expired (beyond grace),
  -- WITHOUT clobbering manual blocks (only touch rows that are unblocked or already licence-blocked).
  update leads set matching_blocked=true, matching_block_reason='licence_expired'
   where approval_status='approved' and coalesce(banned,false)=false
     and license_expiry is not null
     and license_expiry < (current_date - make_interval(days => p_grace_days))
     and (coalesce(matching_blocked,false)=false or matching_block_reason='licence_expired');
  get diagnostics v_suspended = row_count;
  -- Restore suppliers we auto-blocked once their licence is valid again (renewal-by-reply updates license_expiry).
  update leads set matching_blocked=false, matching_block_reason=null
   where matching_block_reason='licence_expired'
     and (license_expiry is null or license_expiry >= (current_date - make_interval(days => p_grace_days)));
  get diagnostics v_restored = row_count;
  return json_build_object('suspended', v_suspended, 'restored', v_restored, 'grace_days', p_grace_days, 'ran_at', now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_refresh_lead_lifecycle()
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
declare n integer;
begin
  update public.leads l
     set lifecycle_stage = public.fn_lead_lifecycle_stage(l)
   where l.lifecycle_stage is distinct from public.fn_lead_lifecycle_stage(l);
  get diagnostics n = row_count;
  return n;
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_refund_amount_resolve(p_stripe_refund_id text, p_amount_fils bigint, p_by text, p_source text DEFAULT 'manual'::text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.refunds;
begin
  if coalesce(p_amount_fils, 0) <= 0 then
    return jsonb_build_object('ok', false, 'error', 'amount_must_be_positive');
  end if;
  select * into r from public.refunds where stripe_refund_id = p_stripe_refund_id for update;
  if not found then return jsonb_build_object('ok', false, 'error', 'refund_not_found'); end if;

  update public.refunds
     set amount_fils = p_amount_fils,
         amount_source = coalesce(p_source, 'manual'),
         reconciliation_note = left('amount resolved by ' || coalesce(p_by,'unknown') || ' on '
             || to_char(now(),'YYYY-MM-DD') || coalesce(': ' || p_note, ''), 500),
         updated_at = now()
   where id = r.id;

  update public.refund_event_quarantine
     set resolved_at = now(), resolved_by = p_by,
         resolution_note = 'amount supplied: ' || p_amount_fils || ' fils'
   where stripe_refund_id = p_stripe_refund_id and resolved_at is null and reason like 'amount unknown%';

  if r.transaction_id is not null then
    update public.transactions set refund_amount_aed = round(p_amount_fils/100.0, 2) where id = r.transaction_id;
  end if;

  return jsonb_build_object('ok', true, 'refund_id', r.id, 'amount_fils', p_amount_fils);
end $function$


CREATE OR REPLACE FUNCTION public.fn_refund_decide(p_refund_id bigint, p_approve boolean, p_decided_by text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.refunds; v_new text;
begin
  select * into r from public.refunds where id = p_refund_id;
  if not found then return jsonb_build_object('ok', false, 'error', 'not_found'); end if;
  if r.status <> 'requested' then
    return jsonb_build_object('ok', false, 'error', 'not_decidable', 'status', r.status);
  end if;
  if coalesce(btrim(p_decided_by),'') = '' then
    return jsonb_build_object('ok', false, 'error', 'decider_required');
  end if;
  v_new := case when p_approve then 'approved' else 'rejected' end;
  update public.refunds set status = v_new, decided_by = p_decided_by, decided_at = now(), decision_note = p_note
   where id = p_refund_id;
  if r.transaction_id is not null then
    update public.transactions set refund_status = v_new, refund_resolved_at = now(),
           refund_note = coalesce(p_note, refund_note) where id = r.transaction_id;
  end if;
  return jsonb_build_object('ok', true, 'refund_id', p_refund_id, 'status', v_new);
end $function$


CREATE OR REPLACE FUNCTION public.fn_refund_quarantine(p_stripe_refund_id text, p_event_type text, p_reason text, p_payload jsonb DEFAULT NULL::jsonb, p_stripe_event_id text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  insert into public.refund_event_quarantine (stripe_refund_id, stripe_event_id, event_type, reason, payload)
  values (nullif(btrim(coalesce(p_stripe_refund_id,'')),''), nullif(btrim(coalesce(p_stripe_event_id,'')),''),
          p_event_type, p_reason, p_payload)
  returning id;
$function$


CREATE OR REPLACE FUNCTION public.fn_refund_request(p_amount_fils bigint, p_reason_code text, p_requested_by text, p_inquiry_id uuid DEFAULT NULL::uuid, p_customer_id uuid DEFAULT NULL::uuid, p_supplier_lead_id bigint DEFAULT NULL::bigint, p_quote_id uuid DEFAULT NULL::uuid, p_payment_intent text DEFAULT NULL::text, p_charge_id text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_transaction_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id bigint; v_in_window boolean := false; v_auto boolean := false;
        v_thr numeric; v_thr_fils bigint; t public.transactions;
begin
  if p_amount_fils is null or p_amount_fils <= 0 then
    return jsonb_build_object('ok', false, 'error', 'amount_required');
  end if;

  select * into t from public.transactions
   where (p_transaction_id is not null and id = p_transaction_id)
      or (p_transaction_id is null and p_quote_id is not null and quote_id = p_quote_id)
      or (p_transaction_id is null and p_quote_id is null and p_payment_intent is not null and payment_ref = p_payment_intent)
   order by revealed_at desc nulls last limit 1;

  -- Inside the window the customer was promised at reveal, a refund is a commitment already made,
  -- so it does not need a human to agree to it again. Reusing transactions.refund_deadline - which
  -- fn_add_working_days already computed at reveal time - means the window here cannot disagree
  -- with what the customer was told.
  if t.id is not null and t.refund_deadline is not null and t.refund_deadline >= now() then
    v_in_window := true;
  end if;

  select threshold_aed into v_thr from public.org_authority
   where dept_key = 'customer_success' and action_class = 'refund_within_window';
  v_thr_fils := case when v_thr is null then null else (v_thr * 100)::bigint end;

  v_auto := v_in_window and v_thr_fils is not null and p_amount_fils <= v_thr_fils;

  insert into public.refunds (transaction_id, inquiry_id, customer_id, supplier_lead_id, quote_id,
                              stripe_payment_intent, stripe_charge_id,
                              amount_fils, reason_code, reason_note, requested_by,
                              within_auto_window, status, reconciliation_note)
  values (t.id, coalesce(p_inquiry_id, t.inquiry_id), coalesce(p_customer_id, t.customer_id),
          coalesce(p_supplier_lead_id, t.supplier_id), coalesce(p_quote_id, t.quote_id),
          coalesce(p_payment_intent, t.payment_ref), p_charge_id,
          p_amount_fils, p_reason_code, p_note, p_requested_by,
          v_in_window, case when v_auto then 'approved' else 'requested' end,
          case
            when v_in_window and not v_auto and v_thr_fils is null
              then 'HELD FOR A HUMAN: inside the refund window, but no ceiling is declared in '
                || 'org_authority(customer_success, refund_within_window), so nothing is auto-approved.'
            when v_in_window and not v_auto
              then 'HELD FOR A HUMAN: inside the refund window, but ' || round(p_amount_fils/100.0, 2)
                || ' AED is above the declared ceiling of ' || v_thr || ' AED.'
            else null end)
  returning id into v_id;

  if v_auto then
    update public.refunds set decided_by = 'policy:auto_window', decided_at = now(),
           decision_note = 'Inside the refund window promised to the customer at reveal '
             || '(transactions.refund_deadline) and at or below the declared ceiling of ' || v_thr || ' AED.'
     where id = v_id;
  end if;

  if t.id is not null then
    update public.transactions
       set refund_status = case when v_auto then 'approved' else 'requested' end,
           refund_reason = coalesce(refund_reason, p_reason_code),
           refund_requested_at = coalesce(refund_requested_at, now()),
           refund_note = coalesce(p_note, refund_note)
     where id = t.id;
  end if;

  return jsonb_build_object('ok', true, 'refund_id', v_id, 'transaction_id', t.id,
                            'status', case when v_auto then 'approved' else 'requested' end,
                            'within_auto_window', v_in_window,
                            'auto_approved', v_auto,
                            'ceiling_aed', v_thr);
end $function$


CREATE OR REPLACE FUNCTION public.fn_refund_settle(p_stripe_refund_id text, p_status text, p_amount_fils bigint DEFAULT NULL::bigint, p_payment_intent text DEFAULT NULL::text, p_charge_id text DEFAULT NULL::text, p_failure_reason text DEFAULT NULL::text, p_amount_source text DEFAULT 'webhook_event'::text, p_stripe_event_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.refunds; v_status text; v_amount bigint; v_src text; v_q bigint;
begin
  if coalesce(btrim(p_stripe_refund_id),'') = '' then
    v_q := public.fn_refund_quarantine(null, 'refund', 'event carried no refund id',
             jsonb_build_object('status', p_status, 'payment_intent', p_payment_intent), p_stripe_event_id);
    return jsonb_build_object('ok', false, 'error', 'stripe_refund_id_required', 'quarantined', v_q);
  end if;

  v_status := case lower(coalesce(p_status,''))
                when 'succeeded' then 'succeeded' when 'failed' then 'failed'
                when 'canceled' then 'cancelled'  when 'cancelled' then 'cancelled'
                else 'processing' end;
  v_amount := nullif(coalesce(p_amount_fils, 0), 0);
  v_src    := case when v_amount is null then null else coalesce(p_amount_source, 'webhook_event') end;

  select * into r from public.refunds where stripe_refund_id = p_stripe_refund_id for update;

  if not found then
    select * into r from public.refunds
     where stripe_refund_id is null and p_payment_intent is not null
       and stripe_payment_intent = p_payment_intent and status in ('approved','processing','requested')
     order by created_at limit 1 for update;

    if found then
      update public.refunds set stripe_refund_id = p_stripe_refund_id,
             stripe_charge_id = coalesce(p_charge_id, stripe_charge_id) where id = r.id;
    else
      -- Issued outside the platform. Recorded with whatever is actually known, and NOTHING invented:
      -- if the amount is unknown it stays NULL and the row is marked unreconciled.
      insert into public.refunds (stripe_refund_id, stripe_payment_intent, stripe_charge_id,
                                  amount_fils, amount_source, reason_code, reason_note, requested_by, status,
                                  decided_by, decided_at, decision_note, reconciliation_note)
      values (p_stripe_refund_id, p_payment_intent, p_charge_id, v_amount,
              coalesce(v_src, 'unknown'), 'other',
              'Issued outside QuotesDone (Stripe dashboard or API). Recorded by the webhook.',
              'stripe_webhook', coalesce(v_status, 'processing'), 'stripe_dashboard', now(),
              'No in-platform request existed for this refund.',
              case when v_amount is null
                   then 'AMOUNT UNKNOWN - the event carried none and Stripe could not be read. Excluded from all financial totals until resolved.'
                   else null end)
      returning * into r;

      if v_amount is null then
        perform public.fn_refund_quarantine(p_stripe_refund_id, 'refund',
          'amount unknown: absent from the event and not retrievable from Stripe',
          jsonb_build_object('status', v_status, 'payment_intent', p_payment_intent, 'refund_row', r.id),
          p_stripe_event_id);
      end if;

      return jsonb_build_object('ok', true, 'refund_id', r.id, 'status', r.status, 'applied', true,
                                'created', true, 'amount_known', v_amount is not null);
    end if;
  end if;

  -- Duplicate delivery: same state twice. Cheap, silent, correct - but still take the chance to fill
  -- in an amount we did not have before.
  if r.status = v_status then
    if r.amount_fils is null and v_amount is not null then
      update public.refunds
         set amount_fils = v_amount, amount_source = v_src,
             reconciliation_note = 'amount resolved from a later ' || coalesce(p_amount_source,'event'),
             updated_at = now()
       where id = r.id;
      return jsonb_build_object('ok', true, 'refund_id', r.id, 'status', r.status,
                                'idempotent', true, 'applied', false, 'amount_resolved', true);
    end if;
    return jsonb_build_object('ok', true, 'refund_id', r.id, 'status', r.status,
                              'idempotent', true, 'applied', false);
  end if;

  -- The matrix decides. Not a rank, not an ordering heuristic - a declared policy with a reason
  -- attached to every refusal.
  if not public.fn_refund_transition_allowed(r.status, v_status) then
    v_q := public.fn_refund_quarantine(p_stripe_refund_id, 'refund',
      'transition not permitted: ' || r.status || ' -> ' || v_status || '. '
      || coalesce((select note from public.refund_status_transition
                    where from_status = r.status and to_status = v_status), 'no rule declared for this pair'),
      jsonb_build_object('refund_row', r.id, 'from', r.status, 'to', v_status,
                         'amount_fils', p_amount_fils, 'payment_intent', p_payment_intent),
      p_stripe_event_id);
    update public.refunds
       set reconciliation_note = left(coalesce(reconciliation_note || ' | ', '')
           || 'refused ' || r.status || '->' || v_status || ' at ' || to_char(now(),'YYYY-MM-DD HH24:MI'), 500),
           updated_at = now()
     where id = r.id;
    return jsonb_build_object('ok', true, 'refund_id', r.id, 'status', r.status, 'applied', false,
                              'refused_transition', r.status || '->' || v_status, 'quarantined', v_q);
  end if;

  update public.refunds
     set status = v_status,
         amount_fils   = coalesce(v_amount, amount_fils),
         amount_source = case when v_amount is not null then v_src else amount_source end,
         stripe_charge_id = coalesce(p_charge_id, stripe_charge_id),
         stripe_payment_intent = coalesce(p_payment_intent, stripe_payment_intent),
         settled_at = case when v_status = 'succeeded' then coalesce(settled_at, now()) else settled_at end,
         failure_reason = case when v_status = 'failed' then p_failure_reason else failure_reason end,
         reconciliation_note = case
             when v_status = 'succeeded' and coalesce(v_amount, amount_fils) is null
             then 'AMOUNT UNKNOWN on a settled refund - excluded from all financial totals until resolved.'
             else reconciliation_note end,
         updated_at = now()
   where id = r.id;

  if r.transaction_id is not null then
    update public.transactions
       set refund_status = v_status, refund_stripe_id = p_stripe_refund_id,
           refund_amount_aed = case when v_amount is not null then round(v_amount/100.0, 2) else refund_amount_aed end,
           refund_confirmed_at = case when v_status = 'succeeded' then coalesce(refund_confirmed_at, now())
                                      else refund_confirmed_at end
     where id = r.transaction_id;
  end if;

  return jsonb_build_object('ok', true, 'refund_id', r.id, 'status', v_status, 'applied', true,
                            'amount_known', coalesce(v_amount, r.amount_fils) is not null);
end $function$


CREATE OR REPLACE FUNCTION public.fn_refund_state(p_transaction uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare t record; v_notify_days int; v_call_days int;
        v_responded boolean; v_notify_at timestamptz; v_call_at timestamptz; v_state text;
begin
  select * into t from transactions where id = p_transaction;
  if not found then return jsonb_build_object('error','transaction_not_found'); end if;

  v_notify_days := coalesce((select value::text::int from decision_policy where key='refund_notify_after_working_days'),1);
  v_call_days   := coalesce((select value::text::int from decision_policy where key='refund_call_after_working_days'),3);

  v_responded := t.supplier_ack_at is not null
    or exists (select 1 from messages m
               where m.inquiry_id = t.inquiry_id and m.supplier_id = t.supplier_id
                 and m.sender = 'supplier' and coalesce(m.blocked,false) = false
                 and m.created_at > t.revealed_at);

  v_notify_at := case when t.revealed_at is null then null
                      else public.fn_add_working_days(t.revealed_at, v_notify_days) end;
  -- the clock to a refund starts at the CUSTOMER's notice, never at the automatic nudge
  v_call_at   := case when t.customer_notified_at is null then null
                      else public.fn_add_working_days(t.customer_notified_at, v_call_days) end;

  v_state := case
    when t.revealed_at is null                              then 'not_revealed'
    when v_responded                                        then 'supplier_responded'
    when t.refund_status in ('approved','refunded')         then 'refunded'
    when t.customer_notified_at is null and now() < v_notify_at then 'waiting'
    when t.customer_notified_at is null                     then 'notify_available'
    when now() < v_call_at                                  then 'notified_waiting'
    else 'call_due' end;

  return jsonb_build_object(
    'transaction_id', t.id,
    'state', v_state,
    'revealed_at', t.revealed_at,
    'supplier_responded', v_responded,
    'notify_available_at', v_notify_at,
    'can_notify', v_state = 'notify_available',
    'notified_at', t.customer_notified_at,
    'auto_nudged_at', t.nudged_24_at,
    'founder_call_due_at', v_call_at,
    'refund_approvable', v_state = 'call_due',
    'refund_status', t.refund_status,
    'working_days_since_notice', case when t.customer_notified_at is null then 0
                                      else public.fn_working_days_between(t.customer_notified_at, now()) end
  );
end $function$


CREATE OR REPLACE FUNCTION public.fn_refund_transition_allowed(p_from text, p_to text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce((select allowed from public.refund_status_transition
                    where from_status = p_from and to_status = p_to), false);
$function$


CREATE OR REPLACE FUNCTION public.fn_refunds_settled_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.status = 'succeeded' and new.settled_at is null then new.settled_at := now(); end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_register_document(p_bucket text, p_path text, p_kind text, p_ref_table text, p_ref_id text, p_file_name text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if p_path is null or p_path = '' then return; end if;
  insert into public.documents(bucket,path,kind,ref_table,ref_id,file_name)
  values (p_bucket,p_path,p_kind,p_ref_table,p_ref_id, coalesce(p_file_name, split_part(p_path,'/',array_length(string_to_array(p_path,'/'),1))))
  on conflict (bucket,path) do nothing;
end $function$


CREATE OR REPLACE FUNCTION public.fn_regulation_propagate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_cat text; v_flagged integer := 0; v_changed boolean;
begin
  v_changed := (tg_op = 'INSERT')
    or (coalesce(old.body,'')             is distinct from coalesce(new.body,''))
    or (coalesce(old.key_requirements,'{}'::jsonb) is distinct from coalesce(new.key_requirements,'{}'::jsonb))
    or (coalesce(old.summary,'')          is distinct from coalesce(new.summary,''))
    or (coalesce(old.effective_date, 'epoch'::date) is distinct from coalesce(new.effective_date, 'epoch'::date))
    or (coalesce(old.status,'')           is distinct from coalesce(new.status,''))
    or (coalesce(old.categories, '{}')    is distinct from coalesce(new.categories, '{}'));

  if not v_changed then return new; end if;

  -- Flag every affected knowledge base for review. This is what makes the
  -- change reach the specialists' knowledge rather than sitting in a table.
  if new.categories is not null then
    foreach v_cat in array new.categories loop
      update agent_knowledge
        set review_due = current_date
      where agent_key = 'cat:' || v_cat;
      get diagnostics v_flagged = row_count;

      insert into company_event (event_type, entity_type, entity_id, actor, payload)
      values ('regulation.changed','category', v_cat, coalesce(new.approved_by,'compliance_mgr'),
              jsonb_build_object('authority', new.authority, 'title', new.title,
                                 'doc_ref', new.doc_ref, 'effective_date', new.effective_date,
                                 'source_url', new.source_url, 'knowledge_rows_flagged', v_flagged,
                                 'regulation_id', new.id));
    end loop;
  end if;

  return new;
end; $function$


CREATE OR REPLACE FUNCTION public.fn_report_flag(p_title text, p_risk text, p_rec text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if not exists (
    select 1 from public.agent_actions
    where agent='reporting_ai' and kind='report_task' and title=p_title
      and status in ('pending','needs_review')
  ) then
    insert into public.agent_actions(agent, kind, status, risk, title, recommendation, created_at)
    values ('reporting_ai','report_task','needs_review',p_risk,p_title,p_rec, now());
  end if;
end $function$


CREATE OR REPLACE FUNCTION public.fn_report_generate(p_kind text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_title text; v_body text; v_kpis jsonb; v_sections jsonb; v_exec text; v_id bigint;
  j_deal jsonb; j_sup jsonb; j_fin jsonb; j_mkt jsonb; j_ops jsonb; j_cust jsonb; j_ai jsonb;
begin
  if p_kind = 'department' then
    select to_jsonb(k.*) into j_deal from public.crm_deal_kpis k limit 1;
    select to_jsonb(k.*) into j_sup  from public.supplier_kpis  k limit 1;
    select to_jsonb(k.*) into j_fin  from public.finance_kpis   k limit 1;
    select to_jsonb(k.*) into j_mkt  from public.marketing_kpis k limit 1;
    select to_jsonb(k.*) into j_ops  from public.ops_kpis       k limit 1;
    v_sections := jsonb_build_array(
      jsonb_build_object('heading','Sales & Pipeline','body', public.fn_kv_block(j_deal)),
      jsonb_build_object('heading','Supply',          'body', public.fn_kv_block(j_sup)),
      jsonb_build_object('heading','Finance',         'body', public.fn_kv_block(j_fin)),
      jsonb_build_object('heading','Marketing',       'body', public.fn_kv_block(j_mkt)),
      jsonb_build_object('heading','Operations',      'body', public.fn_kv_block(j_ops)));
    v_title := 'Department Report — '||to_char(now(),'YYYY-MM-DD');
    v_exec  := 'Cross-department KPI rollup: Sales/Pipeline, Supply, Finance, Marketing, Operations.';
    v_kpis  := jsonb_build_object('sales',j_deal,'supply',j_sup,'finance',j_fin,'marketing',j_mkt,'operations',j_ops);

  elsif p_kind = 'supplier' then
    select to_jsonb(k.*) into j_sup from public.supplier_kpis k limit 1;
    v_sections := jsonb_build_array(jsonb_build_object('heading','Supplier Base','body', public.fn_kv_block(j_sup)));
    v_title := 'Supplier Report — '||to_char(now(),'YYYY-MM-DD');
    v_exec  := 'Supplier base health, coverage and compliance snapshot.';
    v_kpis  := j_sup;

  elsif p_kind = 'customer' then
    select to_jsonb(k.*) into j_cust from public.customer_kpis k limit 1;
    v_sections := jsonb_build_array(jsonb_build_object('heading','Customer Base','body', public.fn_kv_block(j_cust)));
    v_title := 'Customer Report — '||to_char(now(),'YYYY-MM-DD');
    v_exec  := 'Customer base health, activity and retention snapshot.';
    v_kpis  := j_cust;

  elsif p_kind = 'ai' then
    j_ai := jsonb_build_object(
      'active_agents',     (select count(*) from public.category_agents where active),
      'actions_pending',   (select count(*) from public.agent_actions where status in ('pending','needs_review')),
      'actions_done_7d',   (select count(*) from public.agent_actions where status in ('done','auto_done') and created_at > now()-interval '7 days'),
      'actions_rejected_30d',(select count(*) from public.agent_actions where status='rejected' and created_at > now()-interval '30 days'),
      'avg_run_success_pct',(select round(avg(run_success_pct)::numeric,1) from public.ai_agent_quality),
      'total_open_escalations',(select coalesce(sum(open_escalations),0) from public.ai_agent_quality),
      'cron_jobs_active',  (select count(*) from cron.job where active),
      'cron_failures_24h', (select count(*) from cron.job_run_details where status='failed' and start_time > now()-interval '24 hours'));
    v_sections := jsonb_build_array(
      jsonb_build_object('heading','AI Agent Fleet','body', public.fn_kv_block(j_ai)),
      jsonb_build_object('heading','Latest Trainer Snapshot','body',
        public.fn_kv_block((select kpis from public.ai_trainer_snapshots order by created_at desc limit 1))));
    v_title := 'AI Report — '||to_char(now(),'YYYY-MM-DD');
    v_exec  := 'AI agent fleet activity, autonomy queue, training quality and automation health.';
    v_kpis  := j_ai;
  else
    raise exception 'unknown report kind: % (supported: department, supplier, customer, ai)', p_kind;
  end if;

  v_body := public.fn_report_skeleton(v_title, v_exec, v_sections, '[]'::jsonb, null);
  insert into public.board_reports(week_start, title, body, kpis, report_type, created_at)
    values (current_date, v_title, v_body, v_kpis, p_kind, now())
    returning id into v_id;
  return v_id;
end $function$


CREATE OR REPLACE FUNCTION public.fn_report_skeleton(p_title text, p_exec text, p_sections jsonb, p_decisions jsonb, p_appendix text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare out text; s jsonb; d text; i int := 0;
begin
  out := p_title||E'\n'||repeat('=',length(p_title))||E'\n\n';
  out := out||'EXECUTIVE SUMMARY'||E'\n'||coalesce(p_exec,'—')||E'\n\n';
  for s in select * from jsonb_array_elements(coalesce(p_sections,'[]')) loop
     out := out||upper(coalesce(s->>'heading',''))||E'\n'||coalesce(s->>'body','')||E'\n\n';
  end loop;
  out := out||'DECISIONS REQUIRED'||E'\n';
  if jsonb_array_length(coalesce(p_decisions,'[]'))=0 then out := out||'None outstanding.'||E'\n';
  else for d in select jsonb_array_elements_text(p_decisions) loop i:=i+1; out := out||i||'. '||d||E'\n'; end loop; end if;
  if p_appendix is not null then out := out||E'\n'||'APPENDIX'||E'\n'||p_appendix||E'\n'; end if;
  return out;
end $function$


CREATE OR REPLACE FUNCTION public.fn_reporting_ai()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare k record; v_gen text[] := '{}'; v_flags int := 0; kind text;
begin
  -- Refresh the four agent-owned report types once per calendar day (no intra-day duplicates)
  foreach kind in array array['department','supplier','customer','ai'] loop
    if not exists (select 1 from public.board_reports where report_type=kind and created_at::date=current_date) then
      perform public.fn_report_generate(kind);
      v_gen := v_gen || kind;
    end if;
  end loop;

  select * into k from public.report_kpis;
  insert into public.report_kpi_snapshots(kpis) values (to_jsonb(k));

  -- Flag any scheduled report that is stale or missing (founder-visible, de-duped)
  if coalesce(k.daily_fresh,false) = false then
    perform public.fn_report_flag('Daily briefing is stale or missing','high',
      'No founder daily briefing in the last 36 hours — check the founder_brief_daily cron and fn_founder_brief.'); v_flags:=v_flags+1;
  end if;
  if coalesce(k.weekly_fresh,false) = false then
    perform public.fn_report_flag('Weekly board report overdue','medium',
      'No weekly board report in the last 8 days — check the board_report_weekly cron and fn_board_report.'); v_flags:=v_flags+1;
  end if;
  if coalesce(k.monthly_fresh,false) = false then
    perform public.fn_report_flag('Monthly report not generated this month','medium',
      'No monthly report for the current month yet — fn_monthly_report / monthly_report cron.'); v_flags:=v_flags+1;
  end if;
  if coalesce(k.quarterly_fresh,false) = false then
    perform public.fn_report_flag('Quarterly report missing','medium',
      'No quarterly report in the last ~95 days — run fn_quarterly_report() or check the quarterly_report cron.'); v_flags:=v_flags+1;
  end if;

  return jsonb_build_object('generated', to_jsonb(v_gen), 'new_flags', v_flags,
    'stale_count', k.stale_count, 'total_reports', k.total_reports, 'report_types', k.report_types);
end $function$


CREATE OR REPLACE FUNCTION public.fn_reputation_recompute()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; n int := 0; v_score numeric; v_tier text;
  v_corr numeric; v_rel numeric; v_cost numeric; v_learn numeric; v_collab numeric;
begin
  for r in select agent_key from org_agents where active loop
    -- correctness: graded improvements that moved the metric the right way
    select coalesce(round(100.0*count(*) filter (where verdict='improved')
             /nullif(count(*) filter (where verdict in ('improved','no_change','worse')),0),1), null)
      into v_corr from outcome_record where actor = r.agent_key;
    -- reliability: runs that did not error
    select coalesce(round(100.0*count(*) filter (where status<>'error')/nullif(count(*),0),1), null)
      into v_rel from agent_runs where agent = r.agent_key and started_at > now()-interval '30 days';
    -- cost efficiency: share of calls a cheaper model could NOT have served
    select coalesce(round(100.0*count(*) filter (where not coalesce(could_be_cheaper,false))/nullif(count(*),0),1), null)
      into v_cost from ai_cost_log where agent_key = r.agent_key and occurred_at > now()-interval '30 days';
    -- learning speed: knowledge this agent owns that is validated
    select coalesce(round(100.0*count(*) filter (where validation_status not in ('unvalidated','unreviewed'))
             /nullif(count(*),0),1), null)
      into v_learn from agent_knowledge where owner_agent = r.agent_key;
    -- collaboration: reviews it took part in that reached approval
    select coalesce(round(100.0*count(*) filter (where decision='approve')/nullif(count(*),0),1), null)
      into v_collab from review_chain where author_agent = r.agent_key or reviewer_agent = r.agent_key;

    v_score := round((coalesce(v_corr,50)*0.30 + coalesce(v_rel,50)*0.30 + coalesce(v_cost,50)*0.15
                    + coalesce(v_learn,50)*0.15 + coalesce(v_collab,50)*0.10), 1);
    v_tier := case when v_score >= 85 then 'senior_trusted'
                   when v_score >= 70 then 'trusted'
                   when v_score >= 50 then 'standard' else 'probation' end;

    insert into agent_reputation (agent_key,correctness,reliability,cost_efficiency,learning_speed,collaboration,score,tier,computed_at)
    values (r.agent_key,v_corr,v_rel,v_cost,v_learn,v_collab,v_score,v_tier,now())
    on conflict (agent_key) do update set correctness=excluded.correctness, reliability=excluded.reliability,
      cost_efficiency=excluded.cost_efficiency, learning_speed=excluded.learning_speed,
      collaboration=excluded.collaboration, score=excluded.score, tier=excluded.tier, computed_at=now();
    n := n + 1;
  end loop;

  -- probation is a real consequence: any agent below the floor loses autonomous authority
  update employee_authority a set max_tier='gated'
   from agent_reputation p
  where p.agent_key=a.agent_key and p.tier='probation' and a.max_tier='autonomous';

  insert into agent_runs (agent,started_at,finished_at,status,counts,note)
  values ('reputation',now(),now(),'ok',jsonb_build_object('scored',n),
    'Reputation recomputed for '||n||' employee(s). Probation demotes autonomous authority to gated.');
  return jsonb_build_object('scored',n);
end $function$


CREATE OR REPLACE FUNCTION public.fn_require_grounding(p_answer text, p_sources jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare grounded boolean:=false; reason text;
begin
  if p_sources is not null and jsonb_typeof(p_sources)='array' and jsonb_array_length(p_sources)>0 then
     grounded:=true; reason:='sources provided';
  elsif coalesce(p_answer,'') ~* '(per |according to|source:|standard |code |regulation|SIRA|DCD|ADCD|DEWA|Estidama|Al Sa|ESMA|ISO |IEC |BS |EN |NFPA|knowledge base|checklist)' then
     grounded:=true; reason:='inline citation detected';
  else reason:='no sources or citation — retrieve from knowledge base and cite before answering'; end if;
  return jsonb_build_object('grounded',grounded,'reason',reason);
end $function$


CREATE OR REPLACE FUNCTION public.fn_resilience_watch()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_run bigint; v_owner text; v_secret text;
  v_base text := 'https://htdblwldjkcgjvmqkbeh.supabase.co/functions/v1/';
  v_email_backlog int := 0; v_prev_backlog int; v_flushed boolean := false;
  v_email_on text; v_stripe text; v_kill text;
  v_last_ops timestamptz; v_last_ai timestamptz; v_match_stuck int := 0;
  v_missing text[] := '{}'; k text; v_issues text := ''; v_heals int := 0; v_alerts int := 0;
  v_deduped boolean;
  v_findings text := '';
  v_receipt_lost int := 0; v_receipt_manual int := 0; v_receipt_detail text;
  v_body text;
begin
  select value into v_secret from app_secrets where key='cred_db_internal';
  select split_part(coalesce(value,'management@quotesdone.com'),',',1) into v_owner from app_secrets where key='admin_emails';
  v_owner := coalesce(nullif(btrim(v_owner),''),'management@quotesdone.com');
  insert into agent_runs(agent,started_at) values('resilience_watch',clock_timestamp()) returning id into v_run;

  select value into v_email_on from app_secrets where key='email_enabled';
  select count(*) into v_email_backlog from notifications
    where channel='email' and coalesce(status,'queued') in ('queued','pending') and created_at < now()-interval '15 minutes';
  if v_email_backlog>0 and coalesce(v_email_on,'')='true' and v_secret is not null then
    perform net.http_post(url:=v_base||'send_outbox',
      headers:='{"Content-Type":"application/json"}'::jsonb,
      body:=jsonb_build_object('__secret',v_secret,'limit',50), timeout_milliseconds:=20000);
    v_flushed := true; v_heals := v_heals+1;
    select (counts->>'email_backlog')::int into v_prev_backlog from agent_runs
      where agent='resilience_watch' and id<>v_run order by id desc limit 1;
    if coalesce(v_prev_backlog,0)>0 then
      v_issues := v_issues||'- Email pipeline STUCK: '||v_email_backlog||' message(s) undelivered >15min despite auto-flush.'||E'\n';
    end if;
  end if;

  -- CRITICAL credentials. inbound_secret is scheduled for withdrawal (audit 9.5, due 10 Aug); the
  -- credentials that took over its job, and the ones whose absence is silent and total, are here.
  foreach k in array array[
      'internal_credential_hmac_key',
      'cred_db_internal',
      'openrouter_api_key',
      'resend_api_key',
      'stripe_secret_key',
      'resend_inbound_signing_secret',
      'resend_webhook_signing_secret',
      'resend_inbound_token',
      'resend_webhook_key'
    ] loop
    if not exists(select 1 from app_secrets where key=k and value is not null and length(btrim(value))>0) then
      v_missing := array_append(v_missing,k);
    end if;
  end loop;
  if array_length(v_missing,1)>0 then
    v_issues := v_issues||'- CRITICAL credential(s) MISSING: '||array_to_string(v_missing,', ')||' — dependent flows are down.'||E'\n';
  end if;
  select left(value,8) into v_stripe from app_secrets where key='stripe_secret_key';
  if v_stripe is not null and v_stripe not like 'sk_live_%' then
    v_issues := v_issues||'- Stripe key is NOT live mode — payments will not settle.'||E'\n';
  end if;
  select value into v_kill from app_secrets where key='ai_kill_switch';
  if coalesce(v_kill,'')='true' then
    v_issues := v_issues||'- AI kill-switch is ON — every AI agent is paused.'||E'\n';
  end if;

  select max(started_at) into v_last_ops from agent_runs where agent='ops_watch' and started_at>now()-interval '4 hours';
  select max(started_at) into v_last_ai  from agent_runs where agent='ai_health' and started_at>now()-interval '4 hours';
  if v_last_ops is null or v_last_ops < now()-interval '90 minutes' then
    v_issues := v_issues||'- Ops-watch heartbeat stale (>90min) — the scheduler may be degraded.'||E'\n';
  end if;
  if v_last_ai is null or v_last_ai < now()-interval '45 minutes' then
    v_issues := v_issues||'- AI-health heartbeat stale (>45min) — the scheduler or AI monitor may be down.'||E'\n';
  end if;

  select count(*) into v_match_stuck from inquiries i
    where i.created_at between now()-interval '24 hours' and now()-interval '6 hours'
      and i.status not in ('completed','accepted','closed','cancelled','draft')
      and not exists(select 1 from inquiry_matches m where m.inquiry_id=i.id);
  if v_match_stuck>0 then
    v_issues := v_issues||'- '||v_match_stuck||' inquiry(ies) unmatched for >6h — the matcher may be stuck.'||E'\n';
  end if;

  -- AUDIT §2. A booked expense whose receipt the pipeline HELD and then failed to store: the charge
  -- is in the ledger and the evidence is not. In the UAE the receipt is the deductibility.
  -- to_regclass guard: a watchdog must never be taken down by the absence of the thing it watches.
  if to_regclass('public.v_expense_receipt_gap') is not null then
    select count(*) filter (where document_was_received),
           count(*) filter (where not document_was_received)
      into v_receipt_lost, v_receipt_manual
      from public.v_expense_receipt_gap;

    if v_receipt_lost > 0 then
      select string_agg('#'||id||' '||vendor||' '||amount||' '||currency||' charged '||charged_on
                        ||' (attachment '||coalesce(doc_name,'?')||')', '; ' order by id)
        into v_receipt_detail
        from public.v_expense_receipt_gap where document_was_received;
      v_findings := v_findings||'- '||v_receipt_lost||' booked expense(s) whose receipt was RECEIVED and then lost '
                              ||'before archiving — the charge is in the ledger with no evidence behind it: '
                              ||coalesce(v_receipt_detail,'')
                              ||'. Fix: re-forward the vendor email to the inbound address; it will retry and archive.'||E'\n';
    end if;
  end if;

  v_body := v_issues||v_findings;

  if v_body<>'' then
    select exists(select 1 from notifications where type='resilience_alert' and created_at>now()-interval '3 hours') into v_deduped;
    if not v_deduped and v_secret is not null then
      perform net.http_post(url:=v_base||'alert_founder',
        headers:='{"Content-Type":"application/json"}'::jsonb,
        body:=jsonb_build_object('__secret',v_secret,'event','Resilience: the platform needs attention',
          'level',case when v_issues<>'' then 'critical' else 'warn' end,'dedupe_key','resilience',
          'detail','The self-healing watchdog found issues it could not auto-fix:'||E'\n'||v_body),
        timeout_milliseconds:=20000);
      insert into notifications(type,to_email,to_role,channel,subject,body,status)
        values('resilience_alert',v_owner,'admin','email','QuotesDone resilience: action needed',v_body,'digested');
      v_alerts := v_alerts+1;
    end if;
  end if;

  update agent_runs set finished_at=clock_timestamp(),
    -- status reflects PLATFORM health, not whether the run found something. A finding must not make
    -- the watchdog look like a failed job to fn_watch_failed_runs.
    status=case when v_issues<>'' then 'error' else 'ok' end,
    counts=jsonb_build_object('email_backlog',v_email_backlog,'flushed',v_flushed,'heals',v_heals,'alerts',v_alerts,
                              'receipt_lost',v_receipt_lost,'receipt_manual_backlog',v_receipt_manual,
                              'has_issues',(v_issues<>''),'has_findings',(v_findings<>'')),
    note=coalesce(nullif(v_body,''),'all critical pipelines healthy')
    where id=v_run;
  return jsonb_build_object('ok',true,'email_backlog',v_email_backlog,'flushed',v_flushed,
                            'receipt_lost',v_receipt_lost,'receipt_manual_backlog',v_receipt_manual,
                            'issues',nullif(v_issues,''),'findings',nullif(v_findings,''),'alerts',v_alerts);
end $function$


CREATE OR REPLACE FUNCTION public.fn_resolve_cat_agent(cat text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare k text; c text := lower(trim(coalesce(cat,'')));
begin
  if c = '' then return null; end if;
  if exists(select 1 from category_agents where slug=c and coalesce(active,true)) then return 'cat:'||c; end if;
  if exists(select 1 from agent_knowledge where agent_key='cat:'||c limit 1) then return 'cat:'||c; end if;
  select 'cat:'||slug into k from category_agents
    where coalesce(active,true) and (lower(name) like '%'||c||'%' or c like '%'||slug||'%' or lower(name)=c)
    order by length(slug) desc limit 1;
  return k;
end $function$


CREATE OR REPLACE FUNCTION public.fn_resync_supplier_registration_state()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int;
begin
  with c as (
    update public.leads l
       set registration_status = l.registration_status   -- the trigger overwrites this with the derived value
     where (coalesce(l.claimed,false) or l.founding_rank is not null)
       and l.registration_status is distinct from (public.fn_supplier_registration_state(l.id)->>'status')
    returning 1
  ) select count(*)::int into n from c;
  return n;
end $function$


CREATE OR REPLACE FUNCTION public.fn_review_decide(p_kind text, p_ref_id bigint, p_decision text, p_comment text DEFAULT NULL::text, p_by text DEFAULT 'founder'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare dec text := lower(coalesce(p_decision,'')); ok boolean := false;
begin
  if dec not in ('approve','changes','reject') then return jsonb_build_object('error','decision must be approve|changes|reject'); end if;

  if p_kind = 'marketing_post' then
    update content_drafts set
      review_status = case dec when 'approve' then 'approved' when 'changes' then 'changes_requested' else 'rejected' end,
      founder_comment = coalesce(p_comment, founder_comment), reviewed_at = now()
    where id = p_ref_id and status='draft';
    ok := found;
    -- On approve, social_stage will publish it live (gated by marketing_golive). On changes, the marketing loop revises it.

  elsif p_kind = 'refund' then
    update transactions set
      refund_status = case dec when 'approve' then 'approved' when 'reject' then 'declined' else 'requested' end,
      refund_note = coalesce(p_comment, refund_note),
      refund_resolved_at = case when dec in ('approve','reject') then now() else refund_resolved_at end
    where id = p_ref_id and refund_status='requested';
    ok := found;

  elsif p_kind = 'boost_budget' then
    update review_queue set
      status = case dec when 'approve' then 'approved' when 'changes' then 'changes_requested' else 'rejected' end,
      founder_comment = coalesce(p_comment, founder_comment), decided_at = now(), decided_by = p_by
    where id = p_ref_id and status='pending';
    ok := found;
  else
    return jsonb_build_object('error','unknown kind '||p_kind);
  end if;

  return jsonb_build_object('ok', ok, 'kind', p_kind, 'ref_id', p_ref_id, 'decision', dec);
end $function$


CREATE OR REPLACE FUNCTION public.fn_review_pending()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select jsonb_build_object(
    'marketing_posts', coalesce((select jsonb_agg(jsonb_build_object(
        'kind','marketing_post','ref_id',c.id,'title',c.title,'channel',c.channel,'body',c.body,'image_url',c.image_url,'created_at',c.created_at)
        order by c.created_at desc)
      from content_drafts c where c.status='draft' and coalesce(c.review_status,'pending')='pending'), '[]'::jsonb),
    'refunds', coalesce((select jsonb_agg(jsonb_build_object(
        'kind','refund','ref_id',t.id,'customer_id',t.customer_id,'reason',t.refund_reason,'requested_at',t.refund_requested_at)
        order by t.refund_requested_at desc)
      from transactions t where t.refund_status='requested'), '[]'::jsonb),
    'boost_budgets', coalesce((select jsonb_agg(jsonb_build_object(
        'kind','boost_budget','ref_id',r.id,'title',r.title,'summary',r.summary,'payload',r.payload,'created_at',r.created_at)
        order by r.created_at desc)
      from review_queue r where r.kind='boost_budget' and r.status='pending'), '[]'::jsonb)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_review_submit(p_subject_type text, p_subject_id text, p_dept_key text, p_author text, p_content text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_crit        jsonb;
  v_rule        jsonb;
  v_violations  jsonb := '[]'::jsonb;
  v_unenforced  jsonb := '[]'::jsonb;
  v_critical    int := 0;
  v_major       int := 0;
  v_pick        jsonb;
  v_head        text;
  v_deleg_from  text;
  v_deleg_basis text;
  v_cos         text := 'brief';
  v_decision    text;
  v_reason      text;
  v_conf        numeric;
  v_first_rule  text;
  v_res         jsonb;
begin
  -- Who is actually able to approve for this department right now.
  v_pick        := fn_pick_reviewer(p_dept_key);
  v_head        := v_pick->>'reviewer';
  v_deleg_from  := v_pick->>'delegated_from';
  v_deleg_basis := v_pick->>'basis';

  insert into review_chain (subject_type, subject_id, dept_key, author_agent, stage, decision, reason, confidence)
  values (p_subject_type, p_subject_id, p_dept_key, p_author, 'drafted', null,
          'Draft submitted for department review', null);

  -- No available approver at all: hold and escalate rather than forging an approval.
  if v_head is null then
    insert into review_chain (subject_type, subject_id, dept_key, author_agent, reviewer_agent, stage,
                              decision, reason, confidence, delegated_from, delegation_basis)
    values (p_subject_type, p_subject_id, p_dept_key, p_author, null, 'dept_review',
            'escalate', 'No available approver in ' || p_dept_key || ': ' || coalesce(v_deleg_basis,''), 1.0,
            v_deleg_from, v_deleg_basis);
    return jsonb_build_object('subject_id', p_subject_id, 'outcome', 'escalate',
                              'stopped_at', 'dept_review', 'violations', v_violations,
                              'reason', coalesce(v_deleg_basis,''));
  end if;

  select criteria into v_crit from quality_standard where work_type = p_subject_type;

  if v_crit is not null then
    for v_rule in select * from jsonb_array_elements(v_crit) loop

      if (v_rule ? 'check_fn') then
        -- Data-driven check. A check that cannot run is a failure, never a pass.
        begin
          execute format('select %I($1,$2)', v_rule->>'check_fn')
            into v_res using p_subject_id, p_content;
        exception when others then
          v_res := jsonb_build_object('passed', false, 'detail', 'check ' || (v_rule->>'check_fn') || ' errored: ' || sqlerrm);
        end;
        if not coalesce((v_res->>'passed')::boolean, false) then
          v_violations := v_violations || jsonb_build_object(
            'rule', v_rule->>'rule', 'severity', v_rule->>'severity',
            'why', v_rule->>'why', 'detail', v_res->>'detail');
          if (v_rule->>'severity') = 'critical' then v_critical := v_critical + 1;
          elsif (v_rule->>'severity') = 'major' then v_major := v_major + 1; end if;
          if v_first_rule is null then v_first_rule := v_rule->>'rule'; end if;
        end if;

      elsif (v_rule ? 'pattern') and (v_rule ? 'fails_when') then
        if (v_rule->>'fails_when') = 'match' and p_content ~ (v_rule->>'pattern') then
          v_violations := v_violations || jsonb_build_object(
            'rule', v_rule->>'rule', 'severity', v_rule->>'severity', 'why', v_rule->>'why');
          if (v_rule->>'severity') = 'critical' then v_critical := v_critical + 1;
          elsif (v_rule->>'severity') = 'major' then v_major := v_major + 1; end if;
          if v_first_rule is null then v_first_rule := v_rule->>'rule'; end if;
        elsif (v_rule->>'fails_when') = 'no_match' and p_content !~ (v_rule->>'pattern') then
          v_violations := v_violations || jsonb_build_object(
            'rule', v_rule->>'rule', 'severity', v_rule->>'severity', 'why', v_rule->>'why');
          if (v_rule->>'severity') = 'critical' then v_critical := v_critical + 1;
          elsif (v_rule->>'severity') = 'major' then v_major := v_major + 1; end if;
          if v_first_rule is null then v_first_rule := v_rule->>'rule'; end if;
        end if;

      else
        -- A criterion with no executable check. It must not silently pass.
        v_unenforced := v_unenforced || jsonb_build_object(
          'rule', v_rule->>'rule', 'severity', v_rule->>'severity', 'why', v_rule->>'why');
      end if;

    end loop;
  end if;

  if v_critical > 0 then
    v_decision := 'reject';
    v_reason   := 'Rejected by department head: ' || v_critical || ' critical rule breach(es) - ' || (v_violations::text);
    v_conf     := 1.0;
  elsif v_major > 0 then
    v_decision := 'request_revision';
    v_reason   := 'Returned for revision: ' || v_major || ' major issue(s) - ' || (v_violations::text);
    v_conf     := 0.9;
  elsif jsonb_array_length(v_unenforced) > 0
        and exists (select 1 from jsonb_array_elements(v_unenforced) u where u->>'severity' = 'critical') then
    -- FAIL CLOSED. A critical criterion nobody can check is a reason to involve a person,
    -- not a reason to publish. This is the defect the Layer-4 run found.
    v_decision := 'hold_for_human';
    v_reason   := 'Held for human review: no executable check exists for critical criteria - ' || (v_unenforced::text);
    v_conf     := 1.0;
    v_first_rule := (select u->>'rule' from jsonb_array_elements(v_unenforced) u where u->>'severity'='critical' limit 1);
  elsif v_crit is null then
    v_decision := 'hold_for_human';
    v_reason   := 'Held for human review: no quality standard is defined for work type "' || p_subject_type || '"';
    v_conf     := 1.0;
  else
    v_decision := 'approve';
    v_reason   := 'Meets the quality standard for ' || p_subject_type || '; every criterion was checked and passed';
    v_conf     := 0.95;
  end if;

  insert into review_chain (subject_type, subject_id, dept_key, author_agent, reviewer_agent, stage,
                            decision, reason, violated_rule, confidence, delegated_from, delegation_basis)
  values (p_subject_type, p_subject_id, p_dept_key, p_author, v_head, 'dept_review',
          v_decision, v_reason, v_first_rule, v_conf, v_deleg_from,
          case when v_deleg_from is not null then v_deleg_basis else null end);

  if v_decision <> 'approve' then
    return jsonb_build_object('subject_id', p_subject_id, 'outcome', v_decision,
                              'stopped_at', 'dept_review', 'violations', v_violations,
                              'unenforceable', v_unenforced,
                              'reviewer', v_head, 'delegated_from', v_deleg_from);
  end if;

  insert into review_chain (subject_type, subject_id, dept_key, author_agent, reviewer_agent, stage,
                            decision, reason, confidence)
  values (p_subject_type, p_subject_id, p_dept_key, p_author, v_cos, 'cos_review',
          'approve', 'Approved by Chief of Staff: brand-compliant and serves a company goal', 0.9);

  insert into review_chain (subject_type, subject_id, dept_key, author_agent, reviewer_agent, stage,
                            decision, reason, confidence)
  values (p_subject_type, p_subject_id, p_dept_key, p_author, v_cos, 'published',
          'approve', 'Published after full approval chain', 1.0);

  insert into company_event (event_type, entity_type, entity_id, actor, payload)
  values ('content.published', p_subject_type, p_subject_id, p_author,
          jsonb_build_object('dept', p_dept_key));

  return jsonb_build_object('subject_id', p_subject_id, 'outcome', 'published',
                            'stopped_at', 'published', 'violations', v_violations,
                            'unenforceable', v_unenforced,
                            'reviewer', v_head, 'delegated_from', v_deleg_from);
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_rfq_board(p_search text DEFAULT ''::text, p_limit integer DEFAULT 80, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare out jsonb;
begin
  with base as (
    select i.id, coalesce(nullif(trim(i.category),''),'general') as category,
      coalesce(nullif(trim(i.emirate),''),'—') as emirate,
      left(coalesce(nullif(trim(i.summary),''), i.raw_input, ''),140) as summary,
      i.expected_value as value, nullif(btrim(i.budget),'') as budget, i.urgency, i.status, i.outcome, i.created_at,
      case lower(coalesce(i.pipeline_stage, i.status, ''))
        when 'won' then 'won' when 'revealed' then 'revealed' when 'quoted' then 'quoted' when 'matched' then 'matched'
        else (case when i.outcome='won' then 'won' else 'new' end) end as stage
    from inquiries i
    where coalesce(p_search,'')='' or i.category ilike '%'||p_search||'%' or i.summary ilike '%'||p_search||'%' or i.emirate ilike '%'||p_search||'%'
  ), ranked as (select *, row_number() over (partition by stage order by created_at desc, id desc) rn from base),
  sc as (select stage, count(*) c from base group by stage)
  select jsonb_build_object(
    'total',(select count(*) from base),
    'stages',(select jsonb_agg(jsonb_build_object('key',s.key,'label',s.label,'count',coalesce((select c from sc where sc.stage=s.key),0),
      'cards',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'category',r.category,'emirate',r.emirate,'summary',r.summary,'value',r.value,'budget',r.budget,'urgency',r.urgency,'status',r.status) order by r.rn) from ranked r where r.stage=s.key and r.rn<=12),'[]'::jsonb))
      order by s.ord)
      from (values ('new','New',1),('matched','Matched',2),('quoted','Quoted',3),('revealed','Revealed',4),('won','Won',5)) s(key,label,ord)),
    'rows',(select coalesce(jsonb_agg(jsonb_build_object('id',b.id,'category',b.category,'emirate',b.emirate,'summary',b.summary,'value',b.value,'budget',b.budget,'urgency',b.urgency,'status',b.status,'stage',b.stage,'created_at',b.created_at) order by b.created_at desc, b.id desc),'[]'::jsonb)
             from (select * from base order by created_at desc, id desc limit greatest(1,least(p_limit,200)) offset greatest(0,p_offset)) b)
  ) into out; return out;
end $function$


CREATE OR REPLACE FUNCTION public.fn_rfq_required_check(i inquiries)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  spec_fields jsonb; f jsonb; bag jsonb := '{}'::jsonb; blob text;
  k text; v text; bk text; opt text; tok text; toks text[];
  reqn int := 0; have text[] := '{}';
  miss jsonb := '[]'::jsonb; advisory jsonb := '[]'::jsonb; found boolean;
begin
  select cs.fields into spec_fields
    from public.category_specs cs
   where lower(cs.category) = lower(coalesce(i.category,''))
   limit 1;

  if spec_fields is null or jsonb_typeof(spec_fields) <> 'array' then
    return jsonb_build_object('applicable', false, 'reason', 'no category_specs row',
      'category', i.category, 'required_ok', true, 'required_total', 0,
      'present','[]'::jsonb, 'missing','[]'::jsonb, 'advisory_missing','[]'::jsonb, 'checked_at', now());
  end if;

  if i.spec is not null and jsonb_typeof(i.spec) = 'object' then
    for k, v in
      select e.key, case when jsonb_typeof(e.value) in ('object','array')
                         then e.value::text else coalesce(e.value #>> '{}','') end
        from jsonb_each(i.spec) e
    loop
      bag := bag || jsonb_build_object(lower(k), v);
    end loop;

    for k, v in
      select e2.key, case when jsonb_typeof(e2.value) in ('object','array')
                          then e2.value::text else coalesce(e2.value #>> '{}','') end
        from jsonb_each(i.spec) e1
        join lateral jsonb_each(case when jsonb_typeof(e1.value)='object'
                                     then e1.value else '{}'::jsonb end) e2 on true
    loop
      if not public._rfq_answered(bag->>lower(k)) then
        bag := bag || jsonb_build_object(lower(k), v);
      end if;
    end loop;
  end if;

  bag := bag
    || case when coalesce(i.emirate,'') <> '' then
            jsonb_build_object('emirate', i.emirate,
              'location', coalesce(nullif(bag->>'location',''), i.emirate)) else '{}'::jsonb end
    || case when coalesce(i.scope_type,'') <> '' then
            jsonb_build_object('scope', coalesce(nullif(bag->>'scope',''), i.scope_type)) else '{}'::jsonb end
    || case when coalesce(i.budget,'') <> '' then jsonb_build_object('budget', i.budget) else '{}'::jsonb end
    || case when coalesce(array_length(i.trades,1),0) > 0 then
            jsonb_build_object('trades', array_to_string(i.trades,', ')) else '{}'::jsonb end
    || case when coalesce(i.drawing_file_path,'') <> '' or i.boq is not null then
            jsonb_build_object('drawing','provided') else '{}'::jsonb end;

  blob := lower(concat_ws(' ', i.summary, i.raw_input, i.spec::text));
  foreach tok in array coalesce(regexp_split_to_array(lower(coalesce(i.category,'')), '[^a-z0-9]+'), '{}'::text[]) loop
    if length(coalesce(tok,'')) >= 4 then blob := replace(blob, tok, ' '); end if;
  end loop;

  for f in select value from jsonb_array_elements(spec_fields)
            where coalesce((value->>'required')::boolean, false)
  loop
    k := nullif(btrim(lower(coalesce(f->>'key',''))), '');

    -- Keyless required field: unaddressable, so ADVISORY ONLY (never blocks dispatch).
    if k is null then
      advisory := advisory || jsonb_build_object(
        'question', f->>'question', 'reason', 'category_specs field has no key - cannot be gated');
      continue;
    end if;

    reqn := reqn + 1; found := false;

    if public._rfq_answered(bag->>k) then found := true; end if;

    if not found then
      for bk in select key from jsonb_each_text(bag) loop
        if public._rfq_answered(bag->>bk) then
          if public._rfq_concept(k) is not null
             and public._rfq_concept(k) = public._rfq_concept(bk) then
            found := true;
          else
            foreach tok in array coalesce(string_to_array(k,'_'), '{}'::text[]) loop
              if length(coalesce(tok,'')) >= 4
                 and (bk = tok or bk like '%'||tok||'%' or tok like '%'||bk||'%') then
                found := true;
              end if;
            end loop;
          end if;
        end if;
        exit when found;
      end loop;
    end if;

    if not found and jsonb_typeof(f->'options') = 'array' then
      for opt in select lower(o) from jsonb_array_elements_text(f->'options') o loop
        toks := coalesce(regexp_split_to_array(regexp_replace(coalesce(opt,''),'[^a-z0-9 ]',' ','g'), '\s+'), '{}'::text[]);
        foreach tok in array toks loop
          if length(coalesce(tok,'')) >= 4 and blob like '%'||tok||'%' then found := true; end if;
        end loop;
        exit when found;
      end loop;
    end if;

    if found then
      have := array_append(have, k);
    else
      miss := miss || jsonb_build_object('key', k, 'question', f->>'question', 'type', f->>'type');
    end if;
  end loop;

  return jsonb_build_object(
    'applicable', true, 'category', i.category,
    'required_total', reqn,
    'required_ok', (jsonb_array_length(miss) = 0),
    'present', to_jsonb(have),
    'missing', miss,
    'advisory_missing', advisory,
    'checked_at', now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_rfq_score(i inquiries)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare pts int:=0; miss text[]:='{}'; have text[]:='{}'; spectxt text;
        catchk jsonb; catmiss text[]:='{}'; m jsonb; gready boolean; catok boolean;
begin
  spectxt := coalesce(i.spec::text,'');
  if coalesce(i.category,'')<>'' then pts:=pts+20; have:=array_append(have,'category'); else miss:=array_append(miss,'category'); end if;
  if coalesce(i.emirate,'')<>'' then pts:=pts+10; have:=array_append(have,'emirate'); else miss:=array_append(miss,'emirate'); end if;
  if length(regexp_replace(spectxt,'[^a-zA-Z0-9]','','g')) > 20 then pts:=pts+25; have:=array_append(have,'scope_detail'); else miss:=array_append(miss,'scope_detail'); end if;
  if coalesce(i.scope_type,'')<>'' then pts:=pts+15; have:=array_append(have,'scope_type'); else miss:=array_append(miss,'scope_type'); end if;
  if i.budget is not null then pts:=pts+15; have:=array_append(have,'budget'); else miss:=array_append(miss,'budget'); end if;
  if coalesce(array_length(i.trades,1),0)>0 or coalesce(i.drawing_file_path,'')<>'' or i.boq is not null then
     pts:=pts+15; have:=array_append(have,'supporting_detail'); else miss:=array_append(miss,'supporting_detail'); end if;

  gready := pts >= 70;

  catchk := public.fn_rfq_required_check(i);
  catok  := coalesce((catchk->>'required_ok')::boolean, true);

  if coalesce((catchk->>'applicable')::boolean,false) then
    for m in select value from jsonb_array_elements(coalesce(catchk->'missing','[]'::jsonb)) loop
      catmiss := array_append(catmiss, coalesce(nullif(m->>'question',''), m->>'key'));
    end loop;
  end if;

  return jsonb_build_object(
    'score', pts,
    'generic_ready', gready,
    'category_required_ok', catok,
    'ready', (gready and catok),
    'have', to_jsonb(have),
    'missing', to_jsonb(miss || catmiss),
    'category_missing', coalesce(catchk->'missing','[]'::jsonb),
    'category_check', catchk,
    'scored_at', now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_role_of(p_email text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  e text := lower(trim(coalesce(p_email,'')));
  v_role text;
  v_from date;
  v_on boolean;
begin
  if e = '' then return 'guest'; end if;

  -- Human identities first: unchanged behaviour, still wins over everything.
  select ur.role into v_role from user_roles ur
   where ur.email = e
   order by array_position(array['owner','admin','ops','finance','support','agent'], ur.role)
   limit 1;
  if v_role is not null then return v_role; end if;

  if e = any (string_to_array(lower(coalesce((select value from app_secrets where key='admin_emails'),'')), ','))
    then return 'owner'; end if;

  -- AGENT IDENTITY. Only for values that are not email addresses, so a real
  -- person can never be mistaken for an employee record.
  if position('@' in e) = 0 then
    if exists (select 1 from org_agents where lower(agent_key) = e and active) then
      v_on := lower(coalesce((select value from app_secrets where key='agent_autonomy_enabled'),'true')) = 'true';
      begin
        v_from := coalesce((select value from app_secrets where key='agent_autonomy_from'),'2026-07-30')::date;
      exception when others then v_from := date '2026-07-30';
      end;
      if v_on and current_date >= v_from then
        return 'agent';
      else
        return 'guest';   -- pre-arming: behaviour identical to today
      end if;
    end if;
  end if;

  if exists (select 1 from leads where lower(coalesce(claimed_by,'')) = e) then return 'supplier'; end if;
  if exists (select 1 from customers where lower(coalesce(email,'')) = e) then return 'customer'; end if;
  return 'guest';
end
$function$


CREATE OR REPLACE FUNCTION public.fn_rules_eval(p_ctx jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; matched jsonb:='[]'; reqs text[]:='{}'; ok boolean; k text; cond jsonb; want text; got text;
begin
  for r in select * from business_rules where active order by priority loop
    ok := true;
    for k in select jsonb_object_keys(r.when_json) loop
      cond := r.when_json->k;
      if jsonb_typeof(cond)='object' and cond ? 'gt' then
        if coalesce(nullif(p_ctx->>k,'')::numeric,0) <= (cond->>'gt')::numeric then ok:=false; end if;
      elsif jsonb_typeof(cond)='object' and cond ? 'gte' then
        if coalesce(nullif(p_ctx->>k,'')::numeric,0) < (cond->>'gte')::numeric then ok:=false; end if;
      elsif jsonb_typeof(cond)='object' and cond ? 'in' then
        if not (lower(coalesce(p_ctx->>k,'')) = any(select lower(jsonb_array_elements_text(cond->'in')))) then ok:=false; end if;
      else
        if lower(coalesce(p_ctx->>k,'')) <> lower(cond#>>'{}') then ok:=false; end if;
      end if;
      exit when not ok;
    end loop;
    if ok then
      matched := matched || jsonb_build_object('rule',r.name,'then',r.then_json);
      if r.then_json ? 'require' then
        reqs := reqs || array(select jsonb_array_elements_text(r.then_json->'require'));
      end if;
    end if;
  end loop;
  return jsonb_build_object('matched',matched,'required',to_jsonb((select array_agg(distinct x) from unnest(reqs) x)));
end $function$


CREATE OR REPLACE FUNCTION public.fn_run_vt()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_secret text; v_files jsonb;
begin
  select value into v_secret from app_secrets where key='cred_db_internal';
  select coalesce(jsonb_agg(jsonb_build_object('bucket', o.bucket_id, 'path', o.name, 'size', coalesce((o.metadata->>'size')::bigint,0))), '[]'::jsonb)
    into v_files
  from (
    select bucket_id, name, metadata, created_at
    from storage.objects
    where bucket_id in ('quote-files','drawing-files','supplier-docs','receipt-files')
      and right(name,1) <> '/'
      and name not in (select path from vt_results where path is not null)
    order by created_at desc
    limit 4
  ) o;
  perform net.http_post(
    url := 'https://htdblwldjkcgjvmqkbeh.supabase.co/functions/v1/vt_scan',
    body := jsonb_build_object('__secret', v_secret, 'files', v_files),
    headers := '{"Content-Type":"application/json"}'::jsonb
  );
end;$function$


CREATE OR REPLACE FUNCTION public.fn_scan_new_supplier_categories()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; n int:=0;
begin
  for r in
    select l.id, l.categories, l.services
    from leads l
    where l.source='self_registered'
      and coalesce(trim(l.categories),'')<>''
      and not exists (select 1 from category_agents a where a.active and a.slug=l.categories)
      -- not already handled: no provisioning card referencing this lead
      and not exists (
        select 1 from agent_actions aa
        where aa.kind='category_knowledge' and (aa.detail->>'lead_id')=l.id::text)
    limit 25
  loop
    perform public.fn_provision_category_call(r.categories, r.id, r.services);
    n := n + 1;
  end loop;
  return jsonb_build_object('ran_at',now(),'dispatched',n);
end $function$


CREATE OR REPLACE FUNCTION public.fn_scenario_expectation_change(p_scenario_id text, p_new_expected text, p_reason text, p_work_item text, p_changed_by text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_current text; v_id bigint;
begin
  if coalesce(btrim(p_reason),'') = '' then
    return jsonb_build_object('ok', false, 'error', 'reason_required',
      'message', 'An expectation change without a written reason is a silent edit with extra steps.');
  end if;
  if coalesce(btrim(p_changed_by),'') = '' then
    return jsonb_build_object('ok', false, 'error', 'changed_by_required');
  end if;
  if not exists (select 1 from public.spec_backlog where spec_ref = p_work_item) then
    return jsonb_build_object('ok', false, 'error', 'unknown_work_item',
      'message', 'work_item must resolve to a tracked item in spec_backlog. Open one first.');
  end if;

  select expected into v_current from kb_stage.scenario_tests where scenario_id = p_scenario_id;
  if not found then return jsonb_build_object('ok', false, 'error', 'unknown_scenario'); end if;
  if coalesce(v_current,'') is not distinct from coalesce(p_new_expected,'') then
    return jsonb_build_object('ok', false, 'error', 'no_change');
  end if;

  insert into public.scenario_expectation_change
    (scenario_id, original_expected, new_expected, reason, work_item, changed_by)
  values (p_scenario_id, coalesce(v_current,''), coalesce(p_new_expected,''), btrim(p_reason), p_work_item, btrim(p_changed_by))
  returning id into v_id;

  perform set_config('quotesdone.expectation_change', 'approved', true);
  update kb_stage.scenario_tests set expected = p_new_expected where scenario_id = p_scenario_id;
  perform set_config('quotesdone.expectation_change', '', true);

  return jsonb_build_object('ok', true, 'ledger_id', v_id, 'scenario_id', p_scenario_id, 'work_item', p_work_item);
end $function$


CREATE OR REPLACE FUNCTION public.fn_scenario_verdict(p_scenario_id text, p_actual text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case
    when coalesce(p_actual,'') is not distinct from
         (select coalesce(original_expected,'') from public.v_scenario_expectation_current where scenario_id = p_scenario_id)
      then 'pass_original'
    when coalesce(p_actual,'') is not distinct from
         (select coalesce(current_expected,'')  from public.v_scenario_expectation_current where scenario_id = p_scenario_id)
      then 'pass_revised'
    else 'fail' end;
$function$


CREATE OR REPLACE FUNCTION public.fn_schema_export()
 RETURNS text
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
with t as (
  select c.relname as rel,
    'CREATE TABLE IF NOT EXISTS public.'||quote_ident(c.relname)||E' (\n'||
    string_agg('  '||quote_ident(a.attname)||' '||format_type(a.atttypid,a.atttypmod)||
      case a.attidentity when 'a' then ' GENERATED ALWAYS AS IDENTITY' when 'd' then ' GENERATED BY DEFAULT AS IDENTITY' else '' end||
      case when a.attgenerated='s' then ' GENERATED ALWAYS AS ('||pg_get_expr(ad.adbin,ad.adrelid)||') STORED'
           when ad.adbin is not null then ' DEFAULT '||pg_get_expr(ad.adbin,ad.adrelid) else '' end||
      case when a.attnotnull then ' NOT NULL' else '' end, E',\n' order by a.attnum)
    ||E'\n);' as tbl_ddl
  from pg_class c join pg_namespace n on n.oid=c.relnamespace and n.nspname='public'
  join pg_attribute a on a.attrelid=c.oid and a.attnum>0 and not a.attisdropped
  left join pg_attrdef ad on ad.adrelid=c.oid and ad.adnum=a.attnum
  where c.relkind='r' and not exists(select 1 from pg_depend d where d.objid=c.oid and d.deptype='e')
  group by c.relname
)
select
  '-- QuotesDone — FULL SCHEMA EXPORT (generated from live DB, project htdblwldjkcgjvmqkbeh)'||E'\n'
  ||'-- Excludes: secret VALUES (key names listed below), and table ROW DATA (PII).'||E'\n'
  ||'-- Order is best-effort; this is a faithful reference mirror, not a guaranteed one-click restore.'||E'\n\n'
  ||'-- ===== EXTENSIONS =====' ||E'\n'|| coalesce((select string_agg('CREATE EXTENSION IF NOT EXISTS '||quote_ident(extname)||' WITH SCHEMA '||quote_ident(nx.nspname)||';', E'\n' order by extname) from pg_extension e join pg_namespace nx on nx.oid=e.extnamespace),'')
  ||E'\n\n-- ===== SEQUENCES =====\n'|| coalesce((select string_agg('CREATE SEQUENCE IF NOT EXISTS public.'||quote_ident(sequence_name)||';', E'\n' order by sequence_name) from information_schema.sequences where sequence_schema='public'),'')
  ||E'\n\n-- ===== TABLES ('||(select count(*) from t)||') =====\n'|| coalesce((select string_agg(tbl_ddl, E'\n\n' order by rel) from t),'')
  ||E'\n\n-- ===== CONSTRAINTS =====\n'|| coalesce((select string_agg('ALTER TABLE public.'||quote_ident(c.relname)||' ADD CONSTRAINT '||quote_ident(con.conname)||' '||pg_get_constraintdef(con.oid)||';', E'\n' order by case con.contype when 'p' then 1 when 'u' then 2 when 'c' then 3 else 9 end, c.relname) from pg_constraint con join pg_class c on c.oid=con.conrelid join pg_namespace n on n.oid=c.relnamespace and n.nspname='public' where con.contype in ('p','u','c','f')),'')
  ||E'\n\n-- ===== INDEXES =====\n'|| coalesce((select string_agg(pg_get_indexdef(i.indexrelid)||';', E'\n' order by ic.relname) from pg_index i join pg_class ic on ic.oid=i.indexrelid join pg_namespace n on n.oid=ic.relnamespace and n.nspname='public' where not exists(select 1 from pg_constraint con where con.conindid=i.indexrelid) and not exists(select 1 from pg_depend d where d.objid=ic.oid and d.deptype='e')),'')
  ||E'\n\n-- ===== VIEWS =====\n'|| coalesce((select string_agg('CREATE OR REPLACE VIEW public.'||quote_ident(viewname)||' AS '||definition, E'\n\n' order by viewname) from pg_views where schemaname='public'),'')
  ||E'\n\n-- ===== FUNCTIONS =====\n'|| coalesce((select string_agg(pg_get_functiondef(p.oid), E'\n\n' order by p.proname) from pg_proc p join pg_namespace n on n.oid=p.pronamespace and n.nspname='public' where p.prokind in ('f','p') and not exists(select 1 from pg_depend d where d.objid=p.oid and d.deptype='e')),'')
  ||E'\n\n-- ===== TRIGGERS =====\n'|| coalesce((select string_agg(pg_get_triggerdef(tg.oid)||';', E'\n' order by c.relname) from pg_trigger tg join pg_class c on c.oid=tg.tgrelid join pg_namespace n on n.oid=c.relnamespace and n.nspname='public' where not tg.tgisinternal),'')
  ||E'\n\n-- ===== ROW LEVEL SECURITY (enable) =====\n'|| coalesce((select string_agg('ALTER TABLE public.'||quote_ident(relname)||' ENABLE ROW LEVEL SECURITY;', E'\n' order by relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace and n.nspname='public' where relkind='r' and relrowsecurity),'')
  ||E'\n\n-- ===== POLICIES =====\n'|| coalesce((select string_agg('CREATE POLICY '||quote_ident(policyname)||' ON public.'||quote_ident(tablename)||' AS '||permissive||' FOR '||cmd||' TO '||array_to_string(roles,', ')||coalesce(' USING ('||qual||')','')||coalesce(' WITH CHECK ('||with_check||')','')||';', E'\n' order by tablename,policyname) from pg_policies where schemaname='public'),'')
  ||E'\n\n-- ===== CRON JOBS =====\n'|| coalesce((select string_agg('select cron.schedule('||quote_literal(jobname)||','||quote_literal(schedule)||',$CRON$'||command||'$CRON$);', E'\n' order by jobid) from cron.job),'')
  ||E'\n\n-- ===== APP_SECRETS KEY NAMES (values intentionally excluded) =====\n'|| coalesce((select string_agg('--   '||key, E'\n' order by key) from public.app_secrets),'')
  ||E'\n'
$function$


CREATE OR REPLACE FUNCTION public.fn_scope_apply(p_group_id bigint, p_actor text DEFAULT 'system'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r record; v_deact text[] := '{}'; v_kept text[] := '{}';
begin
  for r in select * from public.v_trade_scope_status where group_id = p_group_id loop
    if r.workstream_id is not null and r.workstream_active and not coalesce(r.contributes,false) then
      perform public.fn_inquiry_workstream_deactivate(p_group_id, r.trade_key, p_actor);
      update public.inquiry_trade_candidate
         set status = case when r.disposition = 'conflicted' then 'proposed' else 'inactive' end,
             requires_confirmation = true
       where group_id = p_group_id and trade_key = r.trade_key and status = 'confirmed';
      v_deact := v_deact || r.trade_key;
      insert into public.inquiry_state_audit (group_id, event, detail, actor)
      values (p_group_id, 'scope_disposition_applied',
              jsonb_build_object('trade_key', r.trade_key, 'disposition', r.disposition,
                                 'specificity', r.specificity, 'action','deactivated',
                                 'reason', r.reason), p_actor);
    elsif r.workstream_id is not null and r.workstream_active then
      v_kept := v_kept || r.trade_key;
    end if;
  end loop;

  return jsonb_build_object('ok', true, 'deactivated', to_jsonb(v_deact), 'active', to_jsonb(v_kept));
end $function$


CREATE OR REPLACE FUNCTION public.fn_scope_clause_map(p_text_norm text)
 RETURNS TABLE(idx integer, sentence_idx integer, clause text)
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select (row_number() over (order by s.sn, c.cn))::integer, s.sn::integer, btrim(c.c)
    from regexp_split_to_table(coalesce(p_text_norm,''), '[.!?؟' || chr(10) || ']')
         with ordinality as s(st, sn)
    cross join lateral regexp_split_to_table(s.st, '[;,،؛]') with ordinality as c(c, cn)
   where btrim(c.c) <> '';
$function$


CREATE OR REPLACE FUNCTION public.fn_scope_clauses(p_text_norm text)
 RETURNS TABLE(idx integer, clause text)
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select row_number() over ()::integer, btrim(c)
    from regexp_split_to_table(coalesce(p_text_norm,''), '[.;,،؛\n]') c
   where btrim(c) <> '';
$function$


CREATE OR REPLACE FUNCTION public.fn_scope_detect(p_group_id bigint, p_customer_text text, p_actor text DEFAULT 'system'::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_norm text := public.fn_norm_text(p_customer_text);
  cl record; m record;
  v_exc_pos int; v_base text; v_base_marker text; v_base_res text; v_pos int;
  v_umbrella boolean; v_umb_pos int;
  v_comps text[]; v_comp text; v_n integer := 0;
  v_trades jsonb; v_tk text; v_tpos int; v_disp text; v_spec int;
  v_active_trades text[];
  v_party jsonb; v_supply jsonb; v_basis text;
  v_pty text; v_pcls text; v_prole text; v_pidx int;
  v_cdisp text; v_cbasis text; v_epty text; v_epcls text; v_eprole text;
  v_why text;
begin
  for cl in select * from public.fn_scope_clause_map(v_norm) loop
    v_exc_pos := null;
    for m in select pattern_norm, lang from public.scope_marker where marker_type = 'exception' loop
      v_pos := public.fn_term_position(cl.clause, m.pattern_norm, m.lang);
      if v_pos > 0 and (v_exc_pos is null or v_pos < v_exc_pos) then v_exc_pos := v_pos; end if;
    end loop;

    v_base := null; v_base_marker := null; v_base_res := 'fixed';
    for m in select disposition, pattern_norm, lang, priority, resolution from public.scope_marker
              where marker_type = 'disposition' order by priority, length(pattern_norm) desc loop
      v_pos := public.fn_term_position(cl.clause, m.pattern_norm, m.lang);
      if v_pos > 0 and (v_exc_pos is null or v_pos < v_exc_pos) then
        v_base := m.disposition; v_base_marker := m.pattern_norm; v_base_res := m.resolution; exit;
      end if;
    end loop;

    -- who, and whether material comes from the buying side. Clause-scoped, both of them.
    v_party  := public.fn_scope_party(cl.clause);
    v_supply := public.fn_scope_supply_attribution(cl.clause);
    v_pty := null; v_pcls := null; v_prole := null; v_pidx := null;
    if coalesce((v_party->>'identified')::boolean, false) then
      v_pty   := v_party->>'party';      v_pcls  := v_party->>'party_class';
      v_prole := v_party->>'role';       v_pidx  := cl.idx;
    end if;

    v_basis := 'fixed_marker';
    if v_base is not null and v_base_res = 'party_dependent' then
      if coalesce((v_party->>'identified')::boolean, false) then
        v_base := 'by_others'; v_basis := 'removal_attributed';
      else
        v_base := 'excluded';  v_basis := 'removal_unattributed';
      end if;
    elsif v_base = 'excluded' and coalesce((v_party->>'identified')::boolean, false) then
      v_base := 'by_others'; v_basis := 'excluded_upgraded_to_by_others';
    elsif v_base in ('by_others','client_supplied') and v_pty is null then
      v_prole := 'inline_marker';
    end if;

    select coalesce(array_agg(distinct m2.component), '{}') into v_comps
      from public.scope_marker m2
     where m2.marker_type = 'component'
       and public.fn_term_matches(cl.clause, m2.pattern_norm, m2.lang);

    -- "free issue by the employer" carries no component word, but it is unmistakably about supply.
    if coalesce((v_supply->>'matched')::boolean, false) and not ('supply' = any(v_comps)) then
      v_comps := array_append(v_comps, 'supply'::text);
    end if;

    select coalesce(bool_or(public.fn_term_position(cl.clause, p.pattern_norm, p.lang) > 0), false),
           min(nullif(public.fn_term_position(cl.clause, p.pattern_norm, p.lang), 0))
      into v_umbrella, v_umb_pos
      from public.mep_trade_pattern p where p.kind in ('mep_anchor','mep_full_phrase');

    select coalesce(jsonb_object_agg(z.tk, z.p), '{}'::jsonb) into v_trades
      from (
        select t.trade_key as tk, min(t.pos) as p
          from (
            select p.trade_key, public.fn_term_position(cl.clause, p.pattern_norm, p.lang) as pos
              from public.mep_trade_pattern p
             where p.kind in ('trade_name','trade_hint') and p.trade_key is not null
            union all
            select c.trade_key,
                   public.fn_term_position(cl.clause, public.fn_norm_text(e.matched_term), 'en')
              from public.inquiry_trade_candidate c
              join public.inquiry_trade_candidate_evidence e on e.candidate_id = c.id
             where c.group_id = p_group_id and e.matched_term is not null
               and e.evidence_source in ('alias','customer_text')
               and length(e.matched_term) >= 3
          ) t
         where t.pos > 0
         group by t.trade_key
      ) z;

    if v_base is null and (v_umbrella or v_trades <> '{}'::jsonb) then
      v_base := 'included'; v_basis := 'clause_default'; end if;
    if v_base is null then continue; end if;

    foreach v_comp in array (case when cardinality(v_comps) = 0
                                  then array['complete_trade_scope'] else v_comps end) loop
      if v_comp = 'supply' and coalesce((v_supply->>'matched')::boolean, false) then
        v_cdisp := 'client_supplied'; v_cbasis := 'supply_attributed_counterparty';
        v_epty  := v_supply->>'party'; v_epcls := v_supply->>'party_class';
        v_eprole := v_supply->>'role';
      else
        v_cdisp := null; v_cbasis := v_basis;
        v_epty  := v_pty; v_epcls := v_pcls; v_eprole := v_prole;
      end if;

      v_why := case v_cbasis
        when 'removal_unattributed' then ' The clause removes this scope from us and identifies no other responsible party, so it is excluded rather than by others.'
        when 'removal_attributed' then ' The clause removes this scope from us and identifies "' || coalesce(v_epty,'?') || '" (' || coalesce(v_epcls,'?') || ', ' || coalesce(v_eprole,'?') || ') as responsible, so it is by others.'
        when 'excluded_upgraded_to_by_others' then ' Exclusion language with an identified responsible party "' || coalesce(v_epty,'?') || '", so it is by others rather than excluded.'
        when 'supply_attributed_counterparty' then ' Supply is attributed to the counterparty "' || coalesce(v_epty,'?') || '" (' || coalesce(v_eprole,'?') || '), so the supply component is client supplied. Work retained by us on this trade is unaffected.'
        else '' end;

      for v_tk, v_tpos in select key, value::int from jsonb_each_text(v_trades) loop
        v_disp := coalesce(v_cdisp,
                    case when v_exc_pos is not null and v_tpos > v_exc_pos
                         then public.fn_scope_inverse(v_base) else v_base end);
        v_spec := 2 + (case when v_comp = 'complete_trade_scope' then 0 else 1 end);
        insert into public.inquiry_scope_disposition
          (group_id, trade_key, scope_component, disposition, specificity, source_kind,
           evidence_source, evidence_score, clause_index, clause_text, matched_marker, reason, actor,
           classification_basis, responsible_party, party_class, party_role, party_clause_index,
           sentence_index)
        values (p_group_id, v_tk, v_comp, v_disp, v_spec, 'customer_text', 'customer_text', 0.950,
                cl.idx, cl.clause, v_base_marker,
                'Clause ' || cl.idx || ' names this trade' ||
                  case when v_comp <> 'complete_trade_scope' then ' and the ' || v_comp || ' component' else '' end ||
                  case when v_cdisp is null and v_exc_pos is not null and v_tpos > v_exc_pos
                       then ', after an exception marker, so the clause disposition is inverted' else '' end ||
                  '. Marker: ' || coalesce(v_base_marker,'(none - default included)') || '.' || v_why,
                p_actor, v_cbasis, v_epty, v_epcls, v_eprole,
                case when v_epty is null then null else cl.idx end, cl.sentence_idx);
        v_n := v_n + 1;
      end loop;

      if v_umbrella then
        insert into public.inquiry_scope_disposition
          (group_id, trade_key, scope_component, disposition, specificity, source_kind,
           evidence_source, evidence_score, clause_index, clause_text, matched_marker, reason, actor,
           classification_basis, responsible_party, party_class, party_role, party_clause_index,
           sentence_index)
        select p_group_id, t.trade_key, v_comp,
               coalesce(v_cdisp,
                 case when v_exc_pos is not null and v_umb_pos > v_exc_pos
                      then public.fn_scope_inverse(v_base) else v_base end),
               (case when v_comp = 'complete_trade_scope' then 0 else 1 end),
               'customer_text','customer_text', 0.900, cl.idx, cl.clause, v_base_marker,
               'Clause ' || cl.idx || ' uses an MEP umbrella term' ||
                 case when v_comp <> 'complete_trade_scope' then ' with the ' || v_comp || ' component' else '' end ||
                 '. Applied to the core trades at umbrella specificity, so any named-trade instruction outranks it. Marker: '
                 || coalesce(v_base_marker,'(none - default included)') || '.' || v_why, p_actor,
               v_cbasis, v_epty, v_epcls, v_eprole,
               case when v_epty is null then null else cl.idx end, cl.sentence_idx
          from public.mep_trade t where t.is_core and not (v_trades ? t.trade_key);
        v_n := v_n + (select count(*) from public.mep_trade t where t.is_core and not (v_trades ? t.trade_key));
      end if;

      if not v_umbrella and v_trades = '{}'::jsonb and v_comp <> 'complete_trade_scope' then
        select coalesce(array_agg(distinct c.trade_key), '{}') into v_active_trades
          from public.inquiry_trade_candidate c
         where c.group_id = p_group_id and c.status in ('confirmed','proposed');
        insert into public.inquiry_scope_disposition
          (group_id, trade_key, scope_component, disposition, specificity, source_kind,
           evidence_source, evidence_score, clause_index, clause_text, matched_marker, reason, actor,
           classification_basis, responsible_party, party_class, party_role, party_clause_index,
           sentence_index)
        select p_group_id, t, v_comp, coalesce(v_cdisp, v_base), 1, 'customer_text','customer_text', 0.900,
               cl.idx, cl.clause, v_base_marker,
               'Clause ' || cl.idx || ' names the ' || v_comp || ' component with no trade, so it applies to the trades already in play.' || v_why,
               p_actor, v_cbasis, v_epty, v_epcls, v_eprole,
               case when v_epty is null then null else cl.idx end, cl.sentence_idx
          from unnest(v_active_trades) t;
        v_n := v_n + coalesce(cardinality(v_active_trades),0);
      end if;
    end loop;
  end loop;

  return v_n;
end $function$


CREATE OR REPLACE FUNCTION public.fn_scope_inverse(p_disposition text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case when p_disposition = 'included' then 'excluded' else 'included' end;
$function$


CREATE OR REPLACE FUNCTION public.fn_scope_party(p_clause_norm text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r record; v_re text; v_pos int;
        v_any text; v_conn_en text; v_conn_ar text;
        v_best jsonb := null; v_best_pos int := null;
begin
  if coalesce(btrim(p_clause_norm),'') = '' then
    return jsonb_build_object('identified', false); end if;

  -- Superset filter: no word boundaries and no affixes, so it accepts strictly more text than any
  -- real party rule can. The one thing it MUST keep is the optional Arabic article between the
  -- words of a multi-word pattern - `صاحب عمل` is written `صاحب العمل`, and a filter without it
  -- rejects a clause the rule would have matched. Being a superset is the whole safety argument;
  -- a filter that is only nearly a superset is a silent false negative.
  select string_agg(replace(pattern_norm,' ','[[:space:]]+(ال)?'), '|') into v_any
    from public.scope_marker where marker_type = 'party';
  if v_any is null or p_clause_norm !~ ('(' || v_any || ')') then
    return jsonb_build_object('identified', false); end if;

  select string_agg(replace(pattern_norm,' ','[[:space:]]+'), '|') into v_conn_en
    from public.scope_marker where marker_type = 'attribution' and lang = 'en';
  select string_agg(replace(pattern_norm,' ','[[:space:]]+'), '|') into v_conn_ar
    from public.scope_marker where marker_type = 'attribution' and lang = 'ar';

  for r in select pattern_norm, lang, party_class from public.scope_marker
            where marker_type = 'party' order by priority, length(pattern_norm) desc loop
    v_re := case when r.lang = 'en'
      then '(^|[^[:alnum:]])(' || v_conn_en || ')[[:space:]]+(the[[:space:]]+)?'
           || replace(r.pattern_norm,' ','[[:space:]]+') || '(s)?($|[^[:alnum:]])'
      else '(^|[^[:alnum:]])(' || v_conn_ar || ')[[:space:]]+(ال)?'
           || replace(r.pattern_norm,' ','[[:space:]]+(ال)?') || '(ات|ين|ون|ها|هم|ه)?($|[^[:alnum:]])'
    end;
    v_pos := coalesce(nullif(regexp_instr(p_clause_norm, v_re), 0), 0);
    if v_pos > 0 and (v_best_pos is null or v_pos < v_best_pos) then
      v_best := jsonb_build_object('identified', true, 'party', r.pattern_norm,
                                   'party_class', r.party_class, 'role', 'attributed');
      v_best_pos := v_pos;
    end if;
  end loop;
  if v_best is not null then return v_best; end if;

  for r in select pattern_norm, lang, party_class from public.scope_marker
            where marker_type = 'party' order by priority, length(pattern_norm) desc loop
    v_re := case when r.lang = 'en'
      then '(^|[^[:alnum:]])(the[[:space:]]+)?' || replace(r.pattern_norm,' ','[[:space:]]+')
           || '(s)?[[:space:]]+(is[[:space:]]+to|are[[:space:]]+to|to|will|shall|would|is[[:space:]]+responsible|are[[:space:]]+responsible)($|[^[:alnum:]])'
      else '(^|[^[:alnum:]])(ال)?' || replace(r.pattern_norm,' ','[[:space:]]+(ال)?')
           || '[[:space:]]+(سيقوم|يقوم|مسؤول|سوف|سيتولي|يتولي)($|[^[:alnum:]])'
    end;
    v_pos := coalesce(nullif(regexp_instr(p_clause_norm, v_re), 0), 0);
    if v_pos > 0 and (v_best_pos is null or v_pos < v_best_pos) then
      v_best := jsonb_build_object('identified', true, 'party', r.pattern_norm,
                                   'party_class', r.party_class, 'role', 'subject');
      v_best_pos := v_pos;
    end if;
  end loop;

  return coalesce(v_best, jsonb_build_object('identified', false));
end $function$


CREATE OR REPLACE FUNCTION public.fn_scope_sentences(p_text_norm text)
 RETURNS TABLE(sentence_idx integer, sentence text)
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select s.sn::integer, btrim(s.st)
    from regexp_split_to_table(coalesce(p_text_norm,''), '[.!?؟' || chr(10) || ']')
         with ordinality as s(st, sn);
$function$


CREATE OR REPLACE FUNCTION public.fn_scope_supply_attribution(p_clause_norm text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r record; v_re text;
        v_sup_en text; v_sup_ar text; v_conn_en text; v_conn_ar text; v_party_any text;
        v_has_en boolean := false; v_has_ar boolean := false;
begin
  if coalesce(btrim(p_clause_norm),'') = '' then
    return jsonb_build_object('matched', false); end if;

  -- establish the supply anchor before reading anything else
  select string_agg(replace(pattern_norm,' ','[[:space:]]+'), '|') into v_sup_en
    from public.scope_marker where marker_type = 'supply_anchor' and lang = 'en';
  select string_agg(replace(pattern_norm,' ','[[:space:]]+'), '|') into v_sup_ar
    from public.scope_marker where marker_type = 'supply_anchor' and lang = 'ar';
  v_sup_ar := '(وال|بال|فال|كال|ال|لل|و|ف|ب|ك|ل)?(' || v_sup_ar || ')';
  v_has_en := p_clause_norm ~ ('(^|[^[:alnum:]])(' || v_sup_en || ')(es|s|d|ing)?($|[^[:alnum:]])');
  v_has_ar := p_clause_norm ~ ('(^|[^[:alnum:]])' || v_sup_ar || '(ات|ين|ون|ها|هم|ه)?($|[^[:alnum:]])');
  if not (v_has_en or v_has_ar) then return jsonb_build_object('matched', false); end if;

  -- and the counterparty before building any attribution regex
  select string_agg(replace(pattern_norm,' ','[[:space:]]+(ال)?'), '|') into v_party_any
    from public.scope_marker where marker_type = 'party' and party_class = 'counterparty';
  if v_party_any is null or p_clause_norm !~ ('(' || v_party_any || ')') then
    return jsonb_build_object('matched', false); end if;

  select string_agg(replace(pattern_norm,' ','[[:space:]]+'), '|') into v_conn_en
    from public.scope_marker where marker_type = 'attribution' and lang = 'en';
  select string_agg(replace(pattern_norm,' ','[[:space:]]+'), '|') into v_conn_ar
    from public.scope_marker where marker_type = 'attribution' and lang = 'ar';

  for r in select pattern_norm, lang, party_class from public.scope_marker
            where marker_type = 'party' and party_class = 'counterparty'
            order by priority, length(pattern_norm) desc loop
    if r.lang = 'en' and v_has_en then
      v_re := '(^|[^[:alnum:]])(' || v_conn_en || ')[[:space:]]+(the[[:space:]]+)?'
              || replace(r.pattern_norm,' ','[[:space:]]+') || '(s)?($|[^[:alnum:]])';
      if p_clause_norm ~ v_re then
        return jsonb_build_object('matched', true, 'party', r.pattern_norm,
                                  'party_class', r.party_class, 'role', 'attributed'); end if;
      v_re := '(^|[^[:alnum:]])(the[[:space:]]+)?' || replace(r.pattern_norm,' ','[[:space:]]+')
              || '(s)?[[:space:]]+(is[[:space:]]+to|are[[:space:]]+to|to|will|shall|would)[[:space:]]+(be[[:space:]]+)?('
              || v_sup_en || ')(es|s|d|ing)?($|[^[:alnum:]])';
      if p_clause_norm ~ v_re then
        return jsonb_build_object('matched', true, 'party', r.pattern_norm,
                                  'party_class', r.party_class, 'role', 'subject'); end if;
    elsif r.lang = 'ar' and v_has_ar then
      v_re := '(^|[^[:alnum:]])(' || v_conn_ar || ')[[:space:]]+(ال)?'
              || replace(r.pattern_norm,' ','[[:space:]]+(ال)?') || '(ات|ين|ون|ها|هم|ه)?($|[^[:alnum:]])';
      if p_clause_norm ~ v_re then
        return jsonb_build_object('matched', true, 'party', r.pattern_norm,
                                  'party_class', r.party_class, 'role', 'attributed'); end if;
      v_re := '(^|[^[:alnum:]])' || v_sup_ar || '(ات|ه)?[[:space:]]+(ال)?'
              || replace(r.pattern_norm,' ','[[:space:]]+(ال)?') || '($|[^[:alnum:]])';
      if p_clause_norm ~ v_re then
        return jsonb_build_object('matched', true, 'party', r.pattern_norm,
                                  'party_class', r.party_class, 'role', 'idafa'); end if;
      v_re := '(^|[^[:alnum:]])(ال)?' || replace(r.pattern_norm,' ','[[:space:]]+(ال)?')
              || '[[:space:]]+(سيقوم[[:space:]]+)?' || v_sup_ar || '($|[^[:alnum:]])';
      if p_clause_norm ~ v_re then
        return jsonb_build_object('matched', true, 'party', r.pattern_norm,
                                  'party_class', r.party_class, 'role', 'subject'); end if;
    end if;
  end loop;

  return jsonb_build_object('matched', false);
end $function$


CREATE OR REPLACE FUNCTION public.fn_secops_test(sample text)
