CREATE OR REPLACE FUNCTION public.trg_goal_cascade()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if old.active is true and new.active is false then
    update department_objective
       set status='superseded', updated_at=now()
     where goal_key = new.key and status='active';

    insert into org_tasks (dept_key, title, detail, status, tier, needs_founder, action_class)
    select distinct o.dept_key,
           'Re-plan after goal retired: '||new.key,
           'Company goal "'||coalesce(new.goal,new.key)||'" was retired. Objectives serving it are now superseded. Propose replacement objectives that serve an active goal.',
           'proposed','advisory', false, 'coordinate'
      from department_objective o
     where o.goal_key = new.key and o.status='superseded'
       and not exists (select 1 from org_tasks t where t.title='Re-plan after goal retired: '||new.key and t.status<>'done');

    begin
      perform fn_emit_event('goal.retired','company_goals',new.key,'ceo',
                            jsonb_build_object('goal',new.key));
    exception when others then null; end;
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.trg_health_check_agent_threshold()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_total   int;
  v_failed  int;
  v_rate    numeric;
  v_limit   numeric := coalesce(
    (select nullif(value,'')::numeric from app_secrets where key='agent_failure_rate_limit'), 0.10);
begin
  if new.check_kind is distinct from 'agent_runs' then
    return new;
  end if;

  select count(*),
         count(*) filter (where status not in ('ok','success','completed','skipped','warn'))
    into v_total, v_failed
  from agent_runs
  where started_at > now() - interval '1 hour';

  -- No runs at all in an hour is itself a failure: the company has gone quiet.
  if v_total = 0 then
    new.ok := false;
    new.detail := 'NO agent runs at all in the last hour - the company has gone silent, which is worse than a high failure rate.';
    return new;
  end if;

  v_rate := round(v_failed::numeric / v_total, 4);
  new.ok := (v_rate < v_limit);
  new.detail := v_failed || ' of ' || v_total || ' agent runs failed in the last hour ('
             || round(v_rate * 100, 2) || '%); threshold ' || round(v_limit * 100, 2) || '%'
             || case when new.ok then '' else ' - OVER THRESHOLD' end
             || '. [Recomputed by trg_health_check_agent_threshold; the raw producer sets ok=false on any single failure, which can never be true.]';
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.trg_holdout_expectations_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_op = 'DELETE' then
    if coalesce(current_setting('quotesdone.holdout_change', true),'') = 'approved' then return old; end if;
    raise exception 'holdout case % cannot be deleted', old.case_key
      using hint = 'Use the P2-C5 expectation-change controls. A holdout that can be quietly pruned proves nothing.';
  end if;
  if coalesce(current_setting('quotesdone.holdout_change', true),'') = 'approved' then return new; end if;
  if new.expect_active       is distinct from old.expect_active
     or new.expect_dispositions is distinct from old.expect_dispositions
     or new.expect_components   is distinct from old.expect_components
     or new.expect_clarify      is distinct from old.expect_clarify
     or new.expect_conflict     is distinct from old.expect_conflict
     or new.text_en             is distinct from old.text_en
     or new.text_ar             is distinct from old.text_ar then
    raise exception 'holdout case % is frozen; its expectation cannot be edited in place', old.case_key
      using hint = 'Changing an expectation to match the code is how a suite stops being evidence.';
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.trg_holdout_record_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  raise exception 'holdout result of record is immutable: % is not permitted', tg_op
    using hint = 'The first measurement of a holdout happens once. Re-running it later is a regression run, not a new first result.';
end $function$


CREATE OR REPLACE FUNCTION public.trg_ingest_case_lessons()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare les text; key text; n int := 0;
begin
  if NEW.ai_summary is null or jsonb_typeof(NEW.ai_summary->'lessons') <> 'array' then return NEW; end if;
  key := coalesce(public.fn_resolve_cat_agent(NEW.category), '_global');
  for les in select jsonb_array_elements_text(NEW.ai_summary->'lessons') loop
    les := trim(les);
    if length(les) < 12 then continue; end if;
    if not exists (select 1 from agent_knowledge where agent_key=key and content=les) then
      insert into agent_knowledge(agent_key, topic, content, priority)
      values (key, 'Closed-case lesson (RFQ-'||NEW.rfq_id||')', les, 60);
      n := n + 1;
    end if;
  end loop;
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.trg_inquiry_answer_value_domain()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if not public.fn_field_value_allowed(new.field_id, new.value) then
    raise exception 'value %L is not in the allowed domain for field %', new.value, new.field_id
      using hint = 'Allowed values are listed in field_definition.allowed_values.';
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.trg_inquiry_answer_value_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_op = 'DELETE' then
    if coalesce(current_setting('quotesdone.p2c1_teardown', true), '') = 'approved' then
      return old;
    end if;
    raise exception 'inquiry_answer rows are never deleted (id %)', old.id
      using hint = 'Supersede the answer instead. The chain is the history.';
  end if;
  if new.value       is distinct from old.value
     or new.field_id    is distinct from old.field_id
     or new.group_id    is distinct from old.group_id
     or new.precedence  is distinct from old.precedence
     or new.source_kind is distinct from old.source_kind then
    raise exception 'inquiry_answer % is immutable; supersede it instead of editing it', old.id;
  end if;
  if old.superseded_by is not null and new.superseded_by is distinct from old.superseded_by then
    raise exception 'inquiry_answer % is already superseded by %', old.id, old.superseded_by;
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.trg_inquiry_enrich()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare dup int;
begin
  if NEW.urgency is null and NEW.spec is not null and (NEW.spec ? 'urgency') then NEW.urgency := NEW.spec->>'urgency'; end if;
  if NEW.plausibility is null and NEW.spec is not null and (NEW.spec ? 'plausibility') then NEW.plausibility := NEW.spec->'plausibility'; end if;
  if NEW.provenance is null and NEW.spec is not null and (NEW.spec ? 'provenance') then NEW.provenance := NEW.spec->'provenance'; end if;
  select count(*) into dup from inquiries i
    where i.customer_id = NEW.customer_id and i.created_at > now() - interval '30 minutes'
      and coalesce(i.category,'') = coalesce(NEW.category,'')
      and (i.summary = NEW.summary or (length(coalesce(NEW.summary,'')) > 8 and i.summary ilike '%' || left(NEW.summary, 40) || '%'));
  if dup > 0 then
    NEW.plausibility := coalesce(NEW.plausibility, '{}'::jsonb) || jsonb_build_object('possible_duplicate', true);
  end if;
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.trg_inquiry_gate_state_sync()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.state is null then
    new.state := (case when new.passed is true then 'passed'
                       when new.passed is false then 'failed'
                       else 'not_evaluated' end)::public.gate_state;
  end if;
  new.passed := public.fn_gate_state_satisfies(new.state);
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.trg_inquiry_received()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare cemail text;
begin
  -- child sub-RFQs of a combined project do not get their own "received" notice
  if NEW.parent_inquiry_id is not null then return NEW; end if;
  select email into cemail from public.customers where id = NEW.customer_id;
  if cemail is not null then
    insert into public.notifications(type,to_email,to_role,inquiry_id,subject,body,status)
    values('inquiry_received', cemail, 'customer', NEW.id,
      'We have received your request',
      case
        when NEW.scope_type = 'multi' then
          'Thanks — your combined request'||coalesce(' for '||left(NEW.summary,80),'')||' is in. We have split it into separate requests per trade and are matching each to the right specialists'||coalesce(' in '||NEW.emirate,' in the UAE')||'. You will be notified as quotes come in — track everything in the app.'
        when NEW.scope_type = 'turnkey' then
          'Thanks — your combined request'||coalesce(' for '||left(NEW.summary,80),'')||' is in. We are matching it to turnkey fit-out companies that can handle the whole project'||coalesce(' in '||NEW.emirate,' in the UAE')||'. You will be notified as quotes come in — track everything in the app.'
        else
          'Thanks — your request'||coalesce(' for '||left(NEW.summary,80),'')||' is in. We are matching it to relevant '||coalesce(NEW.category,'')||' suppliers in '||coalesce(NEW.emirate,'the UAE')||'. You will be notified as quotes come in — track everything in the app.'
      end,
      'queued');
  end if;
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.trg_kb_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if TG_OP='INSERT' or NEW.content is distinct from OLD.content then
    insert into public.kb_revisions(entry_kind,entry_ref,version,content,status,author,ai_validation)
    values ('agent_knowledge', NEW.agent_key||' :: '||NEW.topic, public._kb_next_ver('agent_knowledge',NEW.agent_key||' :: '||NEW.topic),
